def _resolve_project_model_artifact(artifact_name, preferred_path=None):
    """Resolve a trained model artifact even when this script is copied/moved.

    Search is intentionally bounded to likely project roots.  This avoids the
    silent path breakage that can happen when Path(__file__).parents[...] changes
    after a diagnostic script is downloaded into another directory.
    """
    artifact_name = str(artifact_name)
    candidates = []

    env_path = os.environ.get("TA_MLCA_MODEL_PATH", "").strip()
    if env_path:
        candidates.append(Path(env_path))
    if preferred_path:
        candidates.append(Path(preferred_path))

    script_path = Path(__file__).resolve()
    roots = [Path.cwd(), script_path.parent]
    roots.extend(list(script_path.parents)[:6])
    # Also consider the directory from which the user launched Python as a
    # project root and the common source-package layout.
    seen_roots = set()
    unique_roots = []
    for root in roots:
        try:
            key = str(root.resolve())
        except Exception:
            key = str(root)
        if key not in seen_roots:
            seen_roots.add(key)
            unique_roots.append(root)

    for root in unique_roots:
        candidates.extend([
            root / "data" / "multifire" / "models" / artifact_name,
            root / "forest_fire_simulation" / "data" / "multifire" / "models" / artifact_name,
            root / "models" / artifact_name,
        ])

    seen = set()
    checked = []
    for candidate in candidates:
        try:
            candidate = candidate.expanduser().resolve()
        except Exception:
            candidate = candidate.expanduser()
        key = str(candidate)
        if key in seen:
            continue
        seen.add(key)
        checked.append(key)
        if candidate.is_file():
            return key, checked

    fallback = str(Path(preferred_path).expanduser()) if preferred_path else artifact_name
    return fallback, checked


def _bootstrap_forest_fire_package():
    """Add the project root containing ``forest_fire_simulation`` to sys.path."""
    import sys

    env_root = os.environ.get("FIRE_SIM_PROJECT_ROOT", "").strip()
    script_path = Path(__file__).resolve()
    cwd = Path.cwd().resolve()
    bases = []
    if env_root:
        bases.append(Path(env_root))
    bases.extend([cwd, script_path.parent])
    bases.extend(list(cwd.parents)[:6])
    bases.extend(list(script_path.parents)[:6])

    seen = set()
    checked = []
    for base in bases:
        for root in (base, base / "src", base / "python"):
            try:
                root = root.expanduser().resolve()
            except Exception:
                root = root.expanduser()
            key = str(root)
            if key in seen:
                continue
            seen.add(key)
            checked.append(key)
            if (root / "forest_fire_simulation").is_dir():
                if key not in sys.path:
                    sys.path.insert(0, key)
                return key, checked
    return None, checked


_PROJECT_IMPORT_ROOT, _PROJECT_IMPORT_CANDIDATES = _bootstrap_forest_fire_package()

