def load_temporal_attention_model(path=None):
    """Load the validated causal ConvLSTM parameter model once per process."""
    requested = TEMPORAL_ATTENTION_MODEL_PATH if path is None else path
    resolved, checked = _resolve_project_model_artifact(
        PRIMARY_MODEL_ARTIFACT, preferred_path=requested
    )
    path = resolved
    if not TEMPORAL_ATTENTION_ML:
        return None
    if not temporal_attention_model_is_available(path):
        print("Temporal-attention checkpoint not available.")
        print(f"  requested/resolved path: {path}")
        if checked:
            print("  searched candidate paths:")
            for candidate in checked[:18]:
                print(f"    - {candidate}")
        return None
    key = os.path.abspath(path)
    if key not in _TEMPORAL_ATTENTION_MODEL_CACHE:
        try:
            model = TemporalAttentionParameterModel.load(key)
            _TEMPORAL_ATTENTION_MODEL_CACHE[key] = model
            if model.training_decoder != DECODER_LINK_PROGRESS:
                raise ValueError(
                    "the primary model requires a directed-link-progress "
                    f"checkpoint, got {model.training_decoder!r}"
                )
            architecture = (
                "dual-attention TA-MLCA"
                if model.model_variant == "front_conditioned_dual_attention"
                else "temporal ConvLSTM parameter model"
            )
            print(
                f"Loaded strict-history {architecture} from {key}; "
                f"decoder={model.training_decoder}, "
                f"variant={model.model_variant}, "
                f"validation trust={model.transfer_trust:.4f}, "
                f"history={model.history_steps} frames."
            )
        except (OSError, ValueError, KeyError, RuntimeError) as exc:
            print(
                "Temporal-attention ML disabled: could not load "
                f"{key}: {exc}"
            )
            _TEMPORAL_ATTENTION_MODEL_CACHE[key] = None
    return _TEMPORAL_ATTENTION_MODEL_CACHE[key]


