def local_transition_transfer_scale(model):
    """Return a conservative cross-resolution scale from held-out skill."""
    if model is None:
        return 0.0, 0.0, 300.0
    metadata = getattr(model, "metadata", {}) or {}
    training_resolution = max(
        float(metadata.get("training_cell_resolution_m", 300.0)),
        float(TARGET_RES),
    )
    validation_trust = float(np.clip(
        metadata.get("validation_transfer_trust", 0.0), 0.0, 1.0
    ))
    resolution_ratio = float(np.clip(
        TARGET_RES / training_resolution, 0.05, 1.0
    ))
    return resolution_ratio * validation_trust, validation_trust, training_resolution


def ca_step(state, burn_clock, arrival, fuel, elev, geo, wind, step, rng,
            is_building=None, veg_q=None, veg_crit=None,
            canopy=None, evt_attention=None, canopy_attention=None,
            aspect_fac=None, grow=None, gcol=None,
            moisture_h=None, moisture_f=None, spread_accum=None,
            percolation_factor=None, control_damp=None,
            moisture_spatial=None, directional_progress=None,
            ros_scale=1.0, attention_feedback=None, adaptive_spread_field=None,
            causal_morphing_field=None,
            slope_scale=1.0, spot_prob_scale=1.0, moisture_scale=1.0,
            front_momentum=None,
            spot_stats=None,
            spot_queue=None, burn_duration_steps=None,
            local_transition_model=None,
            local_transition_stats=None,
            normal_ros_model=None,
            normal_ros_stats=None,
            neural_parameter_fields=None,
            ta_mlca_spotting_active=False,
            paired_random_key=None):
    """推进一步。fuel 可在调用间被外部改写(如开隔离带置 0), 火头会据当前 fuel 蔓延。"""
    ny, nx = elev.shape
    paired_rows = None
    paired_cols = None

    def spread_uniform(channel):
        nonlocal paired_rows, paired_cols
        if paired_random_key is None:
            return rng.random((ny, nx))
        if paired_rows is None:
            paired_rows = np.arange(ny, dtype=np.uint64)[:, None]
            paired_cols = np.arange(nx, dtype=np.uint64)[None, :]
        return _keyed_uniform(
            paired_rows, paired_cols, step, channel, paired_random_key, nx
        )

    def spot_uniform(rows, cols, channel):
        if paired_random_key is None:
            return rng.random(len(rows))
        return _keyed_uniform(
            rows, cols, step, channel, paired_random_key, nx
        )

    def spot_normal(rows, cols, channel, scale=1.0):
        if paired_random_key is None:
            return rng.normal(0.0, scale, len(rows))
        return _keyed_normal(
            rows, cols, step, channel, paired_random_key, nx
        ) * np.asarray(scale)

    def spot_lognormal(rows, cols, channel, sigma):
        if paired_random_key is None:
            return rng.lognormal(mean=0.0, sigma=sigma, size=len(rows))
        return np.exp(spot_normal(rows, cols, channel, scale=sigma))

    cell_m = TARGET_RES
    ta_spot_active = bool(
        TA_MLCA_SPOTTING
        and ta_mlca_spotting_active
        and neural_parameter_fields is not None
        and np.asarray(neural_parameter_fields).shape == (4, ny, nx)
    )
    local_transition_residual_scale, local_transition_validation_trust, _ = (
        local_transition_transfer_scale(local_transition_model)
    )
    if local_transition_stats is not None:
        local_transition_stats["effective_scale"] = float(
            local_transition_residual_scale
        )
        local_transition_stats["validation_trust"] = float(
            local_transition_validation_trust
        )
    normal_ros_residual_scale, normal_ros_validation_trust, normal_ros_training_res = (
        normal_ros_transfer_scale(normal_ros_model)
    )
    if normal_ros_stats is not None:
        normal_ros_stats["effective_scale"] = float(normal_ros_residual_scale)
        normal_ros_stats["validation_trust"] = float(normal_ros_validation_trust)
        normal_ros_stats["training_resolution_m"] = float(normal_ros_training_res)
    spd, dfrom = wind.get(step)
    sf = suppress_factor(step)             # Optional global containment factor; defaults to 1.0.
    moisture_scalar = nonlinear_fire_weather_response(
        moisture_factor_for_step(step, moisture_h, moisture_f)
    )
    moisture_scalar = float(np.clip(
        moisture_scalar * max(float(moisture_scale), 1e-6),
        ROTH_MIN_MOISTURE_FACTOR,
        ROTH_MAX_MOISTURE_FACTOR,
    ))
    try:
        ros_scalar = float(np.nanmean(ros_scale))
    except Exception:
        ros_scalar = 1.0
    if not np.isfinite(ros_scalar):
        ros_scalar = 1.0
    spot_budget_scale = float(np.clip(ros_scalar, 0.12, 1.35))
    if spot_budget_scale < 1.0:
        spot_budget_scale = float(spot_budget_scale ** 1.45)
    _activate_due_spot_ignitions(
        spot_queue, state, burn_clock, arrival, step,
        spread_accum=spread_accum,
        directional_progress=directional_progress,
        spot_stats=spot_stats,
        is_building=is_building,
    )
    burning = (state == BURNING)
    fire_before_step = burning | (state == BURNED)
    fire_cells_before_step = int(fire_before_step.sum())
    burning_edge = perimeter_mask(fire_before_step) & burning
    spd, dfrom = apply_fire_induced_wind_feedback(
        spd, dfrom, state, burn_clock, fuel, moisture_scalar,
        is_building=is_building, canopy=canopy,
        burn_duration_steps=burn_duration_steps,
        step=step,
    )
    transport_spd = np.asarray(spd, dtype="float32")
    if CANOPY_MIDFLAME_WIND:
        spd = (
            transport_spd
            * canopy_midflame_wind_factor(canopy, (ny, nx))
        ).astype("float32")
    regional_low_wind = float(low_wind_terrain_weight(
        float(np.nanmean(spd)) if np.isfinite(spd).any() else 0.0
    )) if LOW_WIND_TERRAIN_DOMINANT else 0.0
    normal_ros_regime_weight = (
        0.0 if normal_ros_model is None else
        regional_low_wind if NORMAL_ROS_LOW_WIND_GATE else 1.0
    )
    if normal_ros_stats is not None:
        normal_ros_stats["regime_weight_sum"] = float(
            normal_ros_stats.get("regime_weight_sum", 0.0)
        ) + float(normal_ros_regime_weight)
        normal_ros_stats["regime_weight_steps"] = int(
            normal_ros_stats.get("regime_weight_steps", 0)
        ) + 1
    directional_q, directional_normalization = terrain_flank_direction_layers(
        spd, grow, gcol, cell_m,
        elapsed_h=step * MIN_PER_STEP / 60.0
    )
    toward = (dfrom + 180.0) % 360.0       # 风吹向的方位
    moisture_factor = moisture_scalar
    if moisture_spatial is not None:
        moisture_factor = moisture_scalar * moisture_spatial
    crown_prob, crown_ros_factor, crown_spot_factor, crown_dist_factor, crown_hit_factor = (
        build_crown_intensity_layers(
            fuel, spd, moisture_scalar, grow=grow, gcol=gcol,
            burn_clock=burn_clock, is_building=is_building, canopy=canopy,
            burn_duration_steps=burn_duration_steps,
        )
    )
    front_normal_row, front_normal_col = fire_front_outward_normals(fire_before_step)
    mean_wind_speed = float(np.nanmean(spd)) if np.isfinite(spd).any() else 0.0
    front_normal_activation = 0.0
    if (
        FRONT_NORMAL_PROPAGATION and
        step * MIN_PER_STEP / 60.0 >= FRONT_NORMAL_MIN_ELAPSED_H
    ):
        regional_activation = float(
            1.0 - low_wind_terrain_weight(mean_wind_speed)
        )
        if regional_activation > 0.0:
            fire_area_ha = fire_cells_before_step * TARGET_RES ** 2 / 1e4
            area_activation = float(np.clip(
                (fire_area_ha - FRONT_NORMAL_AREA_START_HA) /
                max(FRONT_NORMAL_AREA_FULL_HA - FRONT_NORMAL_AREA_START_HA, 1e-6),
                0.0,
                1.0,
            ))
            front_normal_activation = area_activation * regional_activation * (
                1.0 - low_wind_terrain_weight(spd)
            )
    maturity = fire_maturity_factor(step, fire_cells_before_step)
    can_ignite = (state == UNBURNED)
    ignite_p = np.zeros((ny, nx), dtype="float32")
    use_directional = (
        DIRECTIONAL_TRAVEL_CA and directional_progress is not None and
        directional_progress.shape[0] >= len(geo)
    )
    normal_ros_factor_field = None
    if (
        normal_ros_model is not None and use_directional and burning_edge.any()
        and normal_ros_regime_weight >= NORMAL_ROS_MIN_REGIME_WEIGHT
    ):
        slope_east = (
            np.asarray(gcol, dtype="float32") / max(float(cell_m), 1e-6)
            if gcol is not None else np.zeros((ny, nx), dtype="float32")
        )
        slope_north = (
            -np.asarray(grow, dtype="float32") / max(float(cell_m), 1e-6)
            if grow is not None else np.zeros((ny, nx), dtype="float32")
        )
        normal_dryness = np.clip(
            (np.asarray(moisture_factor, dtype="float32") - 0.35) / 1.65,
            0.0,
            1.5,
        )
        cover_layer = None if canopy is None else canopy.get("cover_pct")
        height_layer = None if canopy is None else canopy.get("height_m")
        cover_scaled = (
            None if cover_layer is None else
            np.asarray(cover_layer, dtype="float32") / 100.0
        )
        height_scaled = (
            None if height_layer is None else
            np.asarray(height_layer, dtype="float32") / 40.0
        )
        curvature = (
            np.gradient(front_normal_row, axis=0)
            + np.gradient(front_normal_col, axis=1)
        ).astype("float32")
        normal_features, normal_rows, normal_cols = build_normal_ros_feature_rows(
            burning_edge,
            front_normal_row,
            front_normal_col,
            spd,
            toward,
            slope_east,
            slope_north,
            fuel,
            normal_dryness,
            canopy_cover=cover_scaled,
            canopy_height=height_scaled,
            fuel_continuity=percolation_factor,
            curvature=curvature,
            elapsed_hours=step * MIN_PER_STEP / 60.0,
        )
        normal_factors = normal_ros_model.predict_factor(
            normal_features,
            residual_scale=(
                normal_ros_residual_scale * normal_ros_regime_weight
            ),
            preserve_front_median=NORMAL_ROS_PRESERVE_FRONT_MEDIAN,
            shrink_out_of_distribution=True,
            component_mode=NORMAL_ROS_COMPONENT_MODE,
        )
        normal_ros_factor_field = np.ones((ny, nx), dtype="float32")
        normal_ros_factor_field[normal_rows, normal_cols] = normal_factors
    directional_newly = np.zeros((ny, nx), dtype=bool)
    directional_arrival_frac = np.ones((ny, nx), dtype="float32")
    terrain_link_cache = build_neighbor_terrain_cache(
        geo, elev, aspect_fac, grow, gcol
    )

    for link_idx, (dy, dx, dist, bearing, spread_weight) in enumerate(geo):
        if (
            dist > float(CA_NEIGHBOR_RADIUS) + 1e-9 and
            step * MIN_PER_STEP / 60.0 >= float(INITIAL_OUTBREAK_DURATION_H)
        ):
            continue
        src_burning = shift_no_wrap(burning, dy, dx, fill_value=False)  # 该邻居在燃烧
        src_edge = shift_no_wrap(burning_edge, dy, dx, fill_value=False)
        if terrain_link_cache is None:
            src_elev = shift_no_wrap(elev, dy, dx, fill_value=np.nan)
            slope_ang = np.degrees(np.arctan2(elev - src_elev, dist * cell_m))
            terrain_core = None
            low_wind_terrain_core = None
        else:
            slope_ang, terrain_core, low_wind_terrain_core = terrain_link_cache[link_idx]
            src_elev = None
        cos_t = np.cos(np.radians(bearing - toward))
        if ROTHERMEL_VEG_MODEL:
            ros = rothermel_veg_ros(
                fuel, elev, src_elev, dist, cell_m, spd, cos_t, dy, dx,
                aspect_fac, grow, gcol, moisture_factor,
                terrain_core=terrain_core,
                low_wind_terrain_core=low_wind_terrain_core,
                regional_low_wind=regional_low_wind,
                directional_q=directional_q,
                directional_normalization=directional_normalization,
            )
            ros = ros * fire_atmosphere_feedback_factor(
                spd, cos_t, fire_cells_before_step
            )
            if percolation_factor is not None:
                src_perc = shift_no_wrap(percolation_factor, dy, dx, fill_value=0.0)
                ros = ros * np.sqrt(np.maximum(percolation_factor, 0.0) *
                                     np.maximum(src_perc, 0.0))
        else:
            p_slope = slope_ros_factor(slope_ang)
            p_wind = np.exp(C1 * spd) * np.exp(spd * C2 * (cos_t - 1.0))
            fuel_local = fuel
            if LOW_WIND_TERRAIN_DOMINANT:
                terrain_weight = low_wind_terrain_weight(spd)
                residual_wind = 1.0 + LOW_WIND_RESIDUAL_WIND * (
                    np.exp(C1 * np.maximum(spd, 0.0)) - 1.0
                )
                p_wind = (
                    (1.0 - terrain_weight) * p_wind +
                    terrain_weight * residual_wind
                )
                low_wind_slope = slope_ros_factor(
                    slope_ang,
                    LOW_WIND_UPSLOPE_GAIN,
                    LOW_WIND_DOWNSLOPE_A,
                    LOW_WIND_DOWNSLOPE_MIN,
                )
                low_wind_slope = np.exp(
                    LOW_WIND_TERRAIN_EXPONENT * np.log(
                        np.clip(low_wind_slope, 0.25, 4.0)
                    )
                )
                p_slope = (
                    (1.0 - terrain_weight) * p_slope +
                    terrain_weight * low_wind_slope
                )
                fuel_local = low_wind_fuel_response(fuel, terrain_weight)
            ros = R_BASE * fuel_local * p_slope * p_wind
        p_step = np.clip(ros * MIN_PER_STEP / (dist * cell_m), 0.0, 1.0)
        src_building = None
        if is_building is not None:
            src_building = shift_no_wrap(is_building, dy, dx, fill_value=False)
        if WUI_MODEL and is_building is not None and veg_q is not None and veg_crit is not None:
            src_veg_q = shift_no_wrap(veg_q, dy, dx, fill_value=0.0)
            wui_pair = src_building | is_building
            if wui_pair.any():
                p_wui = wui_step_probability(src_building, is_building, src_veg_q,
                                             veg_crit, spd, cos_t, moisture_factor)
                if WUI_LOW_CONNECTIVITY_DAMP and percolation_factor is not None:
                    target_connectivity = np.clip(
                        WUI_LOW_CONNECTIVITY_DAMP_MIN +
                        (1.0 - WUI_LOW_CONNECTIVITY_DAMP_MIN) *
                        np.clip(percolation_factor, 0.0, 1.0),
                        WUI_LOW_CONNECTIVITY_DAMP_MIN,
                        1.0,
                    )
                    p_wui = p_wui * np.where(wui_pair, target_connectivity, 1.0)
                p_step = np.where(wui_pair, p_wui, p_step)
        slope_scale_value = max(float(slope_scale), 1e-6)
        if abs(slope_scale_value - 1.0) > 1e-6:
            signed_slope_signal = np.clip(
                3.0 * np.tan(np.radians(slope_ang)),
                -1.0,
                1.0,
            )
            p_step = p_step * np.exp(
                np.log(slope_scale_value) * signed_slope_signal
            )
        if neural_parameter_fields is not None and TA_MLCA_LOCAL_SPREAD:
            parameter_fields = np.asarray(neural_parameter_fields, dtype="float32")
            if parameter_fields.shape == (4, ny, nx):
                src_log_ros = shift_no_wrap(
                    parameter_fields[0], dy, dx, fill_value=0.0
                )
                src_wind_delta = shift_no_wrap(
                    parameter_fields[1], dy, dx, fill_value=0.0
                )
                src_slope_delta = shift_no_wrap(
                    parameter_fields[2], dy, dx, fill_value=0.0
                )
                activity_logit = parameter_fields[3]
                activity_gate = np.clip(
                    2.0 / (1.0 + np.exp(-activity_logit)), 0.05, 1.0
                )
                pair_log_ros = 0.5 * (parameter_fields[0] + src_log_ros)
                pair_wind_delta = 0.5 * (
                    parameter_fields[1] + src_wind_delta
                )
                pair_slope_delta = 0.5 * (
                    parameter_fields[2] + src_slope_delta
                )
                learned_log_factor = (
                    pair_log_ros
                    + pair_wind_delta * cos_t * np.clip(spd / 15.0, 0.0, 2.0)
                    + pair_slope_delta * np.clip(
                        np.tan(np.radians(slope_ang)), -1.5, 1.5
                    )
                )
                p_step = p_step * np.exp(np.clip(
                    learned_log_factor,
                    -math.log(1.40), math.log(1.40)
                )) * activity_gate
        if dist > np.sqrt(2.0) + 1e-9:
            g = int(np.gcd(abs(int(dy)), abs(int(dx))))
            if g > 1:
                clear_path = np.ones((ny, nx), dtype=bool)
                for k in range(1, g):
                    oy = int(round(dy * k / g))
                    ox = int(round(dx * k / g))
                    mid_burnable = shift_no_wrap(fuel > 0.02, oy, ox, fill_value=False)
                    clear_path &= mid_burnable
                p_step = np.where(clear_path, p_step, 0.0)
        if CROWN_FIRE_MODEL:
            src_crown = shift_no_wrap(crown_prob, dy, dx, fill_value=0.0)
            crown_forward = np.power(np.clip(0.5 + 0.5 * cos_t, 0.0, 1.0),
                                     CROWN_FORWARD_POWER)
            src_crown_ros = 1.0 + CROWN_ROS_GAIN * src_crown * crown_forward
            p_step = p_step * np.where(src_burning, src_crown_ros, 1.0)
        if ATTENTION_CA:
            link_evt_focus = None
            if evt_attention is not None:
                src_evt_focus = shift_no_wrap(evt_attention, dy, dx, fill_value=-1.0)
                link_evt_focus = 0.55 * evt_attention + 0.45 * src_evt_focus
            link_canopy_focus = None
            if canopy_attention is not None:
                src_canopy_focus = shift_no_wrap(canopy_attention, dy, dx, fill_value=-1.0)
                link_canopy_focus = 0.50 * (canopy_attention + src_canopy_focus)
            p_step = p_step * attention_factor_for_link(
                fuel, slope_ang, cos_t, src_edge,
                is_building=is_building,
                src_building=src_building,
                feedback=attention_feedback,
                evt_focus=link_evt_focus,
                canopy_focus=link_canopy_focus,
            )
        normal_alignment = np.zeros((ny, nx), dtype="float32")
        normal_ros_link_factor = 1.0
        if FRONT_NORMAL_PROPAGATION:
            src_normal_row = shift_no_wrap(front_normal_row, dy, dx, fill_value=0.0)
            src_normal_col = shift_no_wrap(front_normal_col, dy, dx, fill_value=0.0)
            normal_alignment = np.clip(
                src_normal_row * (dy / dist) + src_normal_col * (dx / dist),
                0.0,
                1.0,
            )
            raw_normal_factor = (
                FRONT_NORMAL_MIN_FACTOR +
                (FRONT_NORMAL_MAX_FACTOR - FRONT_NORMAL_MIN_FACTOR) *
                np.power(normal_alignment, FRONT_NORMAL_POWER)
            )
            normal_factor = 1.0 + front_normal_activation * (raw_normal_factor - 1.0)
            p_step = p_step * np.where(src_edge, normal_factor, 1.0)
            if normal_ros_factor_field is not None:
                source_normal_ros_factor = shift_no_wrap(
                    normal_ros_factor_field, dy, dx, fill_value=1.0
                )
                normal_ros_link_factor = normal_ros_link_progress_factor(
                    source_normal_ros_factor, normal_alignment, src_edge
                )
        if (
            local_transition_model is not None and
            step * MIN_PER_STEP / 60.0 >= LOCAL_TRANSITION_ML_MIN_ELAPSED_H
        ):
            valid_ml_link = src_burning & can_ignite & (fuel > 0.02)
            if valid_ml_link.any():
                source_fuel_ml = shift_no_wrap(fuel, dy, dx, fill_value=0.0)
                cover_ml = None if canopy is None else canopy.get("cover_pct")
                height_ml = None if canopy is None else canopy.get("height_m")
                ml_features, ml_rows, ml_cols = build_local_link_feature_rows(
                    valid_ml_link,
                    spd,
                    toward,
                    bearing,
                    slope_ang,
                    fuel,
                    source_fuel_ml,
                    moisture_factor=moisture_factor,
                    canopy_cover_pct=cover_ml,
                    canopy_height_m=height_ml,
                    fuel_continuity=percolation_factor,
                    front_normal_alignment=normal_alignment,
                    elapsed_hours=step * MIN_PER_STEP / 60.0,
                )
                ml_factor = local_transition_model.predict_factor(
                    ml_features,
                    preserve_mean_hazard=LOCAL_TRANSITION_ML_PRESERVE_LINK_MEAN,
                    residual_scale=local_transition_residual_scale,
                    shrink_out_of_distribution=True,
                )
                p_step[ml_rows, ml_cols] *= ml_factor
                if local_transition_stats is not None and ml_factor.size:
                    local_transition_stats["link_count"] = int(
                        local_transition_stats.get("link_count", 0)
                    ) + int(ml_factor.size)
                    local_transition_stats["factor_sum"] = float(
                        local_transition_stats.get("factor_sum", 0.0)
                    ) + float(np.sum(ml_factor))
                    local_transition_stats["abs_log_sum"] = float(
                        local_transition_stats.get("abs_log_sum", 0.0)
                    ) + float(np.sum(np.abs(np.log(np.maximum(ml_factor, 1e-6)))))
                    local_transition_stats["factor_min"] = min(
                        float(local_transition_stats.get("factor_min", np.inf)),
                        float(np.min(ml_factor)),
                    )
                    local_transition_stats["factor_max"] = max(
                        float(local_transition_stats.get("factor_max", -np.inf)),
                        float(np.max(ml_factor)),
                    )
        fan_factor = strong_wind_fan_spread_factor(
            spd,
            bearing,
            step * MIN_PER_STEP / 60.0,
            src_edge=src_edge,
        )
        if not np.isscalar(fan_factor) or float(fan_factor) != 1.0:
            p_step = p_step * fan_factor
        momentum_factor = front_momentum_link_factor(
            front_momentum, dy, dx, dist, step, regional_low_wind
        )
        if not np.isscalar(momentum_factor) or float(momentum_factor) != 1.0:
            p_step = p_step * momentum_factor
        morphing_factor = causal_morphing_link_factor(
            causal_morphing_field, dy, dx, dist, step
        )
        if not np.isscalar(morphing_factor) or float(morphing_factor) != 1.0:
            p_step = p_step * morphing_factor
        if control_damp is not None:
            src_damp = shift_no_wrap(control_damp, dy, dx, fill_value=1.0)
            pair_damp = np.sqrt(np.clip(control_damp, 0.0, 1.0) *
                                np.clip(src_damp, 0.0, 1.0))
            p_step = p_step * pair_damp
        p_step = np.clip(p_step * spread_weight * maturity, 0.0, 1.0)
        effective_ros_scale = ros_scale
        if adaptive_spread_field is not None:
            effective_ros_scale = (
                float(ros_scale) * np.asarray(adaptive_spread_field, dtype="float32")
            )
        p_step = _scaled_probability(p_step, effective_ros_scale)
        if use_directional:
            directional_load = (
                DIRECTIONAL_IGNITION_LOAD /
                np.maximum(initial_outbreak_ros_factor(step, cos_t), 1e-6)
            )
            valid_link = src_burning & can_ignite
            link_accum = directional_progress[link_idx]
            link_accum[~valid_link] = 0.0
            if valid_link.any():
                rr, cc = np.where(valid_link)
                prev_vals = link_accum[rr, cc].copy()
                link_travel_factor = (
                    normal_ros_link_factor[rr, cc]
                    if np.ndim(normal_ros_link_factor) else
                    np.full(len(rr), float(normal_ros_link_factor), dtype="float32")
                )
                add_vals = (
                    p_step[rr, cc] * sf * link_travel_factor
                ).astype("float32")
                if normal_ros_stats is not None and normal_ros_factor_field is not None:
                    normal_ros_stats["link_count"] = int(
                        normal_ros_stats.get("link_count", 0)
                    ) + int(len(link_travel_factor))
                    normal_ros_stats["factor_sum"] = float(
                        normal_ros_stats.get("factor_sum", 0.0)
                    ) + float(np.sum(link_travel_factor))
                    normal_ros_stats["abs_log_sum"] = float(
                        normal_ros_stats.get("abs_log_sum", 0.0)
                    ) + float(np.sum(np.abs(np.log(np.maximum(link_travel_factor, 1e-6)))))
                    normal_ros_stats["factor_min"] = min(
                        float(normal_ros_stats.get("factor_min", np.inf)),
                        float(np.min(link_travel_factor)),
                    )
                    normal_ros_stats["factor_max"] = max(
                        float(normal_ros_stats.get("factor_max", -np.inf)),
                        float(np.max(link_travel_factor)),
                    )
                load_vals = (
                    np.full(rr.shape, float(directional_load), dtype="float32")
                    if np.ndim(directional_load) == 0 else
                    np.asarray(directional_load[rr, cc], dtype="float32")
                )
                new_vals = prev_vals + add_vals
                link_accum[rr, cc] = new_vals
                crossed_vals = new_vals >= load_vals
            else:
                rr = cc = np.asarray([], dtype=int)
                add_vals = prev_vals = np.asarray([], dtype="float32")
                load_vals = np.asarray([], dtype="float32")
                crossed_vals = np.asarray([], dtype=bool)
            if crossed_vals.any():
                cr = rr[crossed_vals]
                ccross = cc[crossed_vals]
                frac = np.clip(
                    (load_vals[crossed_vals] - prev_vals[crossed_vals]) /
                    np.maximum(add_vals[crossed_vals], 1e-9),
                    0.0, 1.0
                )
                directional_arrival_frac[cr, ccross] = np.minimum(
                    directional_arrival_frac[cr, ccross], frac.astype("float32")
                )
                directional_newly[cr, ccross] = True
            contrib = np.where(valid_link, p_step * sf, 0.0)
        else:
            contrib = np.where(src_burning, p_step, 0.0)
        ignite_p = 1.0 - (1.0 - ignite_p) * (1.0 - contrib)

    if use_directional:
        low_wind_leak_scale = 1.0 - float(regional_low_wind) * (
            1.0 - float(LOW_WIND_DIRECTIONAL_RANDOM_LEAK_SCALE)
        )
        random_leak = spread_uniform(100) < (
            ignite_p * DIRECTIONAL_RANDOM_LEAK * low_wind_leak_scale
        )
        newly = can_ignite & (directional_newly | random_leak)
        arrival_frac = directional_arrival_frac
        if spread_accum is not None:
            spread_accum[~can_ignite] = 0.0
    elif LEVELSET_ACCUMULATION and spread_accum is not None:
        prev_accum = spread_accum.copy()
        addition = ignite_p * sf
        spread_accum[can_ignite] += addition[can_ignite]
        spread_accum[~can_ignite] = 0.0
        deterministic = spread_accum >= LEVELSET_IGNITION_LOAD
        low_wind_leak_scale = 1.0 - float(regional_low_wind) * (
            1.0 - float(LOW_WIND_DIRECTIONAL_RANDOM_LEAK_SCALE)
        )
        random_leak = spread_uniform(101) < (
            ignite_p * sf * LEVELSET_RANDOM_LEAK * low_wind_leak_scale
        )
        newly = can_ignite & (deterministic | random_leak)
        arrival_frac = np.ones((ny, nx), dtype="float32")
        crossed = newly & deterministic & (addition > 1e-9)
        arrival_frac[crossed] = np.clip(
            (LEVELSET_IGNITION_LOAD - prev_accum[crossed]) / addition[crossed],
            0.0, 1.0
        )
    else:
        newly = can_ignite & (spread_uniform(102) < ignite_p * sf)
        arrival_frac = np.ones((ny, nx), dtype="float32")
    state[newly] = BURNING
    arrival[newly] = (step + arrival_frac[newly]) * MIN_PER_STEP / 60.0
    if spread_accum is not None and newly.any():
        spread_accum[newly] = 0.0
    if directional_progress is not None and newly.any():
        directional_progress[:, newly] = 0.0

    spot_sources = burning.copy()
    if SPOT_EDGE_ONLY:
        spot_sources &= perimeter_mask(fire_before_step)
    if SPOT_SOURCE_MIN_AGE_STEPS > 0:
        spot_sources &= (burn_clock >= SPOT_SOURCE_MIN_AGE_STEPS)
    burn_rc = np.argwhere(spot_sources)
    spot_day = _reporting_day_for_elapsed((step + 1) * MIN_PER_STEP / 60.0)
    if spot_stats is not None and CROWN_FIRE_MODEL:
        crown_sources = spot_sources & (crown_prob > 0.05)
        crown_edges = burning_edge & (crown_prob > 0.05)
        _add_spotting_stats(
            spot_stats, spot_day,
            crown_source_cells=int(np.count_nonzero(crown_sources)),
            crown_edge_cells=int(np.count_nonzero(crown_edges)),
            crown_high_source_cells=int(np.count_nonzero(spot_sources & (crown_prob >= 0.50))),
            crown_source_sum=float(np.sum(crown_prob[spot_sources])) if np.any(spot_sources) else 0.0,
            crown_edge_sum=float(np.sum(crown_prob[burning_edge])) if np.any(burning_edge) else 0.0,
        )
    if spot_stats is not None and len(burn_rc):
        _add_spotting_stats(
            spot_stats, spot_day,
            candidate_sources=int(len(burn_rc)),
            active_source_cells=int(np.count_nonzero(spot_sources)),
        )
    physical_spot_prob = SPOT_PROB * max(float(spot_prob_scale), 0.0)
    if (
        PHYSICAL_FIREBRAND_MODEL
        and len(burn_rc)
        and physical_spot_prob > 0.0
        and sf > 0.0
    ):
        age_factor = min(spotting_age_factor(step), maturity)
        distance_ramp = 0.65 + 0.35 * age_factor
        br = burn_rc[:, 0]
        bc = burn_rc[:, 1]
        local_v = np.nan_to_num(
            spd[br, bc], nan=0.0, posinf=0.0, neginf=0.0
        )
        source_fuel = np.clip(fuel[br, bc], 0.0, 1.5)
        source_factor = np.clip(
            np.power(
                np.maximum(source_fuel, 0.02) / 0.75,
                SPOT_SOURCE_FUEL_POWER,
            ),
            0.35,
            1.65,
        )
        source_intensity = source_fuel * np.clip(
            local_v / max(SPOT_WIND_REF, 1e-6), 0.0, 2.5
        )
        source_factor *= 1.0 + SPOT_INTENSITY_GAIN * source_intensity
        source_crown = (
            np.clip(crown_prob[br, bc], 0.0, 1.0)
            if CROWN_FIRE_MODEL
            else np.zeros(local_v.shape, dtype="float32")
        )
        if CROWN_FIRE_MODEL:
            source_factor *= crown_spot_factor[br, bc]
        if is_building is not None:
            source_factor *= np.where(
                is_building[br, bc], 1.0 + SPOT_WUI_SOURCE_GAIN, 1.0
            )
        source_ml_factor = np.ones(local_v.shape, dtype="float32")
        if FIREBRAND_ML_COUPLING and (
            neural_parameter_fields is not None
            or adaptive_spread_field is not None
        ):
            source_log_ros = np.zeros(local_v.shape, dtype="float32")
            source_wind_delta = np.zeros(local_v.shape, dtype="float32")
            if neural_parameter_fields is not None and not ta_spot_active:
                parameter_fields = np.asarray(
                    neural_parameter_fields, dtype="float32"
                )
                if parameter_fields.shape == (4, ny, nx):
                    source_log_ros = parameter_fields[0, br, bc]
                    source_wind_delta = parameter_fields[1, br, bc]
            source_causal_hazard = np.ones(local_v.shape, dtype="float32")
            if adaptive_spread_field is not None:
                source_causal_hazard = np.asarray(
                    adaptive_spread_field, dtype="float32"
                )[br, bc]
            source_ml_factor = learned_firebrand_factor(
                source_log_ros,
                source_wind_delta,
                local_v,
                causal_hazard_factor=source_causal_hazard,
                role="source",
            )
            source_factor *= source_ml_factor
            if spot_stats is not None:
                _add_spotting_stats(
                    spot_stats,
                    spot_day,
                    ml_source_factor_samples=int(source_ml_factor.size),
                    ml_source_factor_sum=float(np.sum(source_ml_factor)),
                    ml_source_adjusted_cells=int(np.count_nonzero(
                        np.abs(source_ml_factor - 1.0) > 1e-4
                    )),
                )
        source_factor_before_ta = source_factor.copy().astype("float32")
        ta_release_factor = np.ones(local_v.shape, dtype="float32")
        ta_distance_factor = np.ones(local_v.shape, dtype="float32")
        if ta_spot_active:
            ta_release_factor, ta_distance_factor = ta_mlca_spot_source_factors(
                neural_parameter_fields, br, bc, local_v
            )
            source_factor *= ta_release_factor
            if spot_stats is not None:
                _add_spotting_stats(
                    spot_stats,
                    spot_day,
                    ta_source_factor_samples=int(ta_release_factor.size),
                    ta_release_factor_sum=float(np.sum(ta_release_factor)),
                    ta_release_adjusted_cells=int(np.count_nonzero(
                        np.abs(ta_release_factor - 1.0) > 1e-4
                    )),
                    ta_distance_factor_sum=float(np.sum(ta_distance_factor)),
                )
        source_factor = np.clip(
            source_factor, 0.25, SPOT_SOURCE_FACTOR_MAX
        ).astype("float32")
        spot_wind_scale = np.ones(local_v.shape, dtype="float32")
        if LOW_WIND_TERRAIN_DOMINANT:
            spot_wind_scale = np.where(
                local_v < LOW_WIND_THRESHOLD,
                LOW_WIND_RESIDUAL_WIND,
                1.0,
            ).astype("float32")
        release_exposure = (
            sf
            * spot_budget_scale
            * age_factor
            * spot_wind_scale
        )
        launch_probability = firebrand_release_probability(
            physical_spot_prob,
            local_v,
            source_factor,
            source_crown,
            dryness_factor=moisture_scalar,
            exposure_scale=release_exposure,
        )
        launch_mask = spot_uniform(br, bc, 1) < launch_probability
        launch = burn_rc[launch_mask]
        if spot_stats is not None:
            crown_launches = 0
            if CROWN_FIRE_MODEL and len(launch):
                crown_launches = int(np.count_nonzero(
                    source_crown[launch_mask] >= 0.35
                ))
            _add_spotting_stats(
                spot_stats,
                spot_day,
                launched_firebrands=int(len(launch)),
                crown_launched_firebrands=crown_launches,
                release_probability_sum=float(np.sum(launch_probability)),
            )
        if len(launch):
            lr = launch[:, 0]
            lc = launch[:, 1]
            launch_factor = (
                source_factor_before_ta[launch_mask]
                if ta_spot_active else source_factor[launch_mask]
            )
            launch_crown = source_crown[launch_mask]
            launch_ta_distance = (
                ta_distance_factor[launch_mask]
                if ta_spot_active
                else np.ones(len(launch), dtype="float32")
            )
            launch_crown_dist = (
                crown_dist_factor[lr, lc]
                if CROWN_FIRE_MODEL
                else np.ones(len(launch), dtype="float32")
            )
            launch_crown_hit = (
                crown_hit_factor[lr, lc]
                if CROWN_FIRE_MODEL
                else np.ones(len(launch), dtype="float32")
            )
            v_loc = np.nan_to_num(
                transport_spd[lr, lc],
                nan=0.0, posinf=0.0, neginf=0.0
            )
            gust = np.clip(
                spot_lognormal(lr, lc, 10, SPOT_GUST_SIGMA),
                1.0 / SPOT_GUST_MAX,
                SPOT_GUST_MAX,
            )
            source_canopy_height = np.zeros(len(launch), dtype="float32")
            if canopy is not None and isinstance(canopy, dict):
                height_layer = canopy.get("height_m")
                if height_layer is not None:
                    source_canopy_height = np.nan_to_num(
                        np.asarray(height_layer, dtype="float32")[lr, lc],
                        nan=0.0,
                    )
            source_slope_deg = np.zeros(len(launch), dtype="float32")
            if grow is not None and gcol is not None:
                source_slope_deg = np.degrees(np.arctan(
                    np.hypot(grow[lr, lc], gcol[lr, lc])
                    / max(float(cell_m), 1e-6)
                )).astype("float32")
            transport = sample_firebrand_transport(
                v_loc * gust,
                launch_factor,
                launch_crown,
                source_canopy_height,
                source_slope_deg,
                spot_uniform(lr, lc, 2),
                spot_normal(lr, lc, 11),
                spot_normal(lr, lc, 12),
                spot_normal(lr, lc, 13),
                cell_size_m=cell_m,
                maximum_distance_m=FIREBRAND_MAX_DISTANCE_M,
                plume_probability_max=FIREBRAND_PLUME_PROBABILITY_MAX,
                distance_scale=(
                    distance_ramp * SPOT_DIST_K * launch_crown_dist
                    * launch_ta_distance
                ),
            )
            regime = transport["regime"]
            survived = (
                spot_uniform(lr, lc, 3)
                < transport["survival_probability"]
            )
            physical_toward = (
                (dfrom[lr, lc] + 180.0) % 360.0
            ).astype("float32")
            toward = physical_toward
            if ta_spot_active:
                toward, ta_direction_entropy, ta_direction_offset = (
                    ta_mlca_spot_direction_attention(
                        neural_parameter_fields,
                        lr,
                        lc,
                        physical_toward,
                        v_loc,
                        grow=grow,
                        gcol=gcol,
                        cell_size_m=cell_m,
                    )
                )
                if spot_stats is not None:
                    _add_spotting_stats(
                        spot_stats,
                        spot_day,
                        ta_direction_samples=int(len(toward)),
                        ta_direction_entropy_sum=float(np.sum(
                            ta_direction_entropy
                        )),
                        ta_direction_offset_sum_deg=float(np.sum(
                            ta_direction_offset
                        )),
                    )
            ang = np.radians(toward)
            downwind_cells = transport["downwind_m"] / max(cell_m, 1e-6)
            crosswind_cells = transport["crosswind_m"] / max(cell_m, 1e-6)
            tr = np.rint(
                lr
                - np.cos(ang) * downwind_cells
                + np.sin(ang) * crosswind_cells
            ).astype(int)
            tc = np.rint(
                lc
                + np.sin(ang) * downwind_cells
                + np.cos(ang) * crosswind_cells
            ).astype(int)
            ok = (tr >= 0) & (tr < ny) & (tc >= 0) & (tc < nx)
            if spot_stats is not None:
                _add_spotting_stats(
                    spot_stats,
                    spot_day,
                    short_range_launches=int(np.count_nonzero(
                        regime == FIREBRAND_SHORT_RANGE
                    )),
                    long_range_launches=int(np.count_nonzero(
                        regime == FIREBRAND_LONG_RANGE
                    )),
                    plume_range_launches=int(np.count_nonzero(
                        regime == FIREBRAND_PLUME_RANGE
                    )),
                    burned_out_before_landing=int(np.count_nonzero(~survived)),
                    flight_time_sum_min=float(np.sum(
                        transport["flight_time_min"]
                    )),
                    remaining_energy_sum=float(np.sum(
                        transport["remaining_energy"]
                    )),
                )
            source_r = lr[ok]
            source_c = lc[ok]
            tr = tr[ok]
            tc = tc[ok]
            v_target_source = v_loc[ok]
            regime_ok = regime[ok]
            survived_ok = survived[ok]
            distance_m_ok = transport["distance_m"][ok]
            flight_time_ok = transport["flight_time_min"][ok]
            energy_ok = transport["remaining_energy"][ok]
            energy_factor_ok = transport["ignition_energy_factor"][ok]
            crown_ok = launch_crown[ok]
            crown_hit_ok = launch_crown_hit[ok]
            land_ok = state[tr, tc] == UNBURNED
            viable_target = land_ok & survived_ok
            if spot_stats is not None:
                _add_spotting_stats(
                    spot_stats,
                    spot_day,
                    landed_in_domain=int(len(tr)),
                    viable_landings=int(np.count_nonzero(survived_ok)),
                    unburned_targets=int(np.count_nonzero(land_ok)),
                    viable_unburned_targets=int(np.count_nonzero(
                        viable_target
                    )),
                    distance_sum_cells=(
                        float(np.sum(distance_m_ok / max(cell_m, 1e-6)))
                        if len(distance_m_ok)
                        else 0.0
                    ),
                    distance_max_cells=(
                        float(np.max(distance_m_ok / max(cell_m, 1e-6)))
                        if len(distance_m_ok)
                        else 0.0
                    ),
                    plume_range_landed=int(np.count_nonzero(
                        regime_ok == FIREBRAND_PLUME_RANGE
                    )),
                )
            damp = (
                1.0
                if control_damp is None
                else np.clip(control_damp[tr, tc], 0.0, 1.0)
            )
            target_fuel = np.clip(fuel[tr, tc], 0.0, 1.5)
            target_context = np.ones(len(tr), dtype="float32")
            if is_building is not None:
                target_building = is_building[tr, tc]
                target_fuel = np.where(
                    target_building,
                    np.maximum(target_fuel, 0.22),
                    target_fuel,
                )
                target_context *= np.where(
                    target_building, 1.0 + SPOT_WUI_TARGET_GAIN, 1.0
                )
            if percolation_factor is not None:
                target_context *= (
                    1.0
                    + SPOT_TARGET_CLUSTER_GAIN
                    * np.clip(percolation_factor[tr, tc], 0.0, 1.0)
                )
            spot_dryness = np.clip(
                1.0 + SPOT_DRYNESS_GAIN * (moisture_scalar - 1.0),
                0.65,
                1.45,
            )
            target_spatial_damp = np.ones(len(tr), dtype="float32")
            if moisture_spatial is not None:
                target_spatial_damp = np.clip(
                    moisture_spatial[tr, tc],
                    HYDRO_MOISTURE_MIN,
                    MOISTURE_SPATIAL_MAX,
                )
            target_dryness = np.clip(
                spot_dryness * target_spatial_damp, 0.45, 1.60
            )
            target_ml_factor = np.ones(len(tr), dtype="float32")
            local_target_ml_factor = np.ones(len(tr), dtype="float32")
            if FIREBRAND_ML_COUPLING and len(tr) and (
                neural_parameter_fields is not None
                or adaptive_spread_field is not None
                or local_transition_model is not None
            ):
                target_log_ros = np.zeros(len(tr), dtype="float32")
                target_wind_delta = np.zeros(len(tr), dtype="float32")
                if neural_parameter_fields is not None and not ta_spot_active:
                    parameter_fields = np.asarray(
                        neural_parameter_fields, dtype="float32"
                    )
                    if parameter_fields.shape == (4, ny, nx):
                        target_log_ros = parameter_fields[0, tr, tc]
                        target_wind_delta = parameter_fields[1, tr, tc]
                target_causal_hazard = np.ones(len(tr), dtype="float32")
                if adaptive_spread_field is not None:
                    target_causal_hazard = np.asarray(
                        adaptive_spread_field, dtype="float32"
                    )[tr, tc]
                target_ml_factor = learned_firebrand_factor(
                    target_log_ros,
                    target_wind_delta,
                    spd[tr, tc],
                    causal_hazard_factor=target_causal_hazard,
                    role="target",
                )
                if (
                    local_transition_model is not None
                    and local_transition_residual_scale > 0.0
                ):
                    target_cover = (
                        None if canopy is None
                        else canopy.get("cover_pct")
                    )
                    target_height = (
                        None if canopy is None
                        else canopy.get("height_m")
                    )
                    local_features = build_firebrand_link_feature_rows(
                        source_r,
                        source_c,
                        tr,
                        tc,
                        spd,
                        (dfrom + 180.0) % 360.0,
                        elev,
                        fuel,
                        moisture_factor=moisture_factor,
                        canopy_cover_pct=target_cover,
                        canopy_height_m=target_height,
                        fuel_continuity=percolation_factor,
                        elapsed_hours=step * MIN_PER_STEP / 60.0,
                        cell_size_m=cell_m,
                    )
                    local_target_ml_factor = (
                        local_transition_model.predict_factor(
                            local_features,
                            preserve_mean_hazard=False,
                            residual_scale=(
                                local_transition_residual_scale
                                * FIREBRAND_ML_LOCAL_RESIDUAL_SCALE
                            ),
                            shrink_out_of_distribution=True,
                        )
                    )
                    target_ml_factor *= local_target_ml_factor
                target_ml_factor = np.clip(
                    target_ml_factor, 0.68, 1.34
                ).astype("float32")
                if spot_stats is not None:
                    _add_spotting_stats(
                        spot_stats,
                        spot_day,
                        ml_target_factor_samples=int(target_ml_factor.size),
                        ml_target_factor_sum=float(np.sum(target_ml_factor)),
                        ml_target_adjusted_landings=int(np.count_nonzero(
                            np.abs(target_ml_factor - 1.0) > 1e-4
                        )),
                        ml_local_target_factor_sum=float(np.sum(
                            local_target_ml_factor
                        )),
                    )
            ta_target_factor = np.ones(len(tr), dtype="float32")
            if ta_spot_active and len(tr):
                ta_target_factor = ta_mlca_spot_target_factor(
                    neural_parameter_fields, tr, tc, spd[tr, tc]
                )
                if spot_stats is not None:
                    _add_spotting_stats(
                        spot_stats,
                        spot_day,
                        ta_target_factor_samples=int(ta_target_factor.size),
                        ta_target_factor_sum=float(np.sum(ta_target_factor)),
                        ta_target_adjusted_landings=int(np.count_nonzero(
                            np.abs(ta_target_factor - 1.0) > 1e-4
                        )),
                    )
            hit_wind = np.clip(
                1.0
                + SPOT_HIT_WIND_GAIN
                * np.maximum(v_target_source - LOW_WIND_THRESHOLD, 0.0)
                / max(SPOT_WIND_REF - LOW_WIND_THRESHOLD, 1e-6),
                1.0,
                SPOT_HIT_WIND_MAX,
            )
            hit_prob = np.clip(
                SPOT_IGNITE
                * target_fuel
                * target_context
                * damp
                * spot_budget_scale
                * target_dryness
                * hit_wind
                * energy_factor_ok
                * crown_hit_ok
                * target_ml_factor
                * ta_target_factor,
                0.0,
                0.95,
            )
            hit = (
                viable_target
                & (spot_uniform(source_r, source_c, 6) < hit_prob)
            )
            delay_all = firebrand_ignition_delay_minutes(
                flight_time_ok,
                energy_ok,
                target_dryness,
                target_fuel,
                spot_normal(source_r, source_c, 14),
            )
            hit_r = tr[hit]
            hit_c = tc[hit]
            hit_distance_m = distance_m_ok[hit]
            hit_delay_min = delay_all[hit]
            hit_regime = regime_ok[hit]
            hit_source_crown = crown_ok[hit]
            if hit_r.size:
                hit_lin = hit_r.astype(np.int64) * nx + hit_c.astype(np.int64)
                _, hit_unique_idx = np.unique(hit_lin, return_index=True)
                hit_r = hit_r[hit_unique_idx]
                hit_c = hit_c[hit_unique_idx]
                hit_distance_m = hit_distance_m[hit_unique_idx]
                hit_delay_min = hit_delay_min[hit_unique_idx]
                hit_regime = hit_regime[hit_unique_idx]
                hit_source_crown = hit_source_crown[hit_unique_idx]
            if spot_stats is not None:
                hit_building = 0
                if is_building is not None and len(hit_r):
                    hit_building = int(np.count_nonzero(
                        is_building[hit_r, hit_c]
                    ))
                _add_spotting_stats(
                    spot_stats,
                    spot_day,
                    successful_spot_ignitions=int(len(hit_r)),
                    queued_spot_ignitions=int(len(hit_r)),
                    building_spot_ignitions=hit_building,
                    short_range_successful_ignitions=int(np.count_nonzero(
                        hit_regime == FIREBRAND_SHORT_RANGE
                    )),
                    long_range_successful_ignitions=int(np.count_nonzero(
                        hit_regime == FIREBRAND_LONG_RANGE
                    )),
                    plume_range_successful_ignitions=int(np.count_nonzero(
                        hit_regime == FIREBRAND_PLUME_RANGE
                    )),
                    crown_successful_spot_ignitions=int(np.count_nonzero(
                        hit_source_crown >= 0.35
                    )),
                    hit_distance_sum_cells=(
                        float(np.sum(hit_distance_m / max(cell_m, 1e-6)))
                        if len(hit_distance_m)
                        else 0.0
                    ),
                    hit_distance_max_cells=(
                        float(np.max(hit_distance_m / max(cell_m, 1e-6)))
                        if len(hit_distance_m)
                        else 0.0
                    ),
                    ignition_delay_sum_min=(
                        float(np.sum(hit_delay_min))
                        if len(hit_delay_min)
                        else 0.0
                    ),
                )
            _enqueue_spot_ignitions(
                spot_queue,
                step,
                hit_r,
                hit_c,
                delay_min=hit_delay_min,
            )


    burn_clock[burning] += 1
    burn_limit = (
        BURN_STEPS if burn_duration_steps is None else
        np.asarray(burn_duration_steps, dtype="int16")
    )
    state[(state == BURNING) & (burn_clock >= burn_limit)] = BURNED


# ============================================================
# CA 主循环
# ============================================================
def run_ca(elev, fuel, wind, transform, crs, is_building=None, veg_q=None, veg_crit=None,
           seed=SEED, calibrate_daily=None, spot_stats_out=None, spot_stats_png=None,
           max_steps=None):
    ny, nx = elev.shape
    rng = np.random.default_rng(seed)
    code = None
    if FUEL_PATH and os.path.exists(FUEL_PATH):
        code = load_fbfm40_codes(FUEL_PATH, transform, crs, elev.shape)
    canopy = load_canopy_layers(FUEL_PATH, transform, crs, elev.shape)
    evt_codes = load_evt_codes(EVT_PATH, transform, crs, elev.shape)
    if is_building is None and code is not None:
        is_building, veg_q, veg_crit = build_wui_layers(code, evt_codes=evt_codes)
        print(f"WUI paper model enabled: {int(is_building.sum())} building cells.")
    fuel, burn_duration_steps, evt_codes = prepare_evt_fuel_behavior(
        fuel, transform, crs, canopy=canopy, evt_codes=evt_codes
    )
    evt_attention, canopy_attention = build_vegetation_attention_layers(evt_codes, canopy)
    aspect_fac, grow, gcol = build_rothermel_layers(elev)
    moisture_spatial = build_spatial_moisture_modifier(
        elev, aspect_fac, grow, gcol, fbfm_code=code, fuel=fuel
    )
    moisture_h, moisture_f = load_moisture_timeline()
    if ROTHERMEL_VEG_MODEL:
        msg = "Rothermel-like vegetation spread enabled"
        if moisture_h is not None:
            msg += f" with fire-weather ROS factor {float(np.nanmin(moisture_f)):.2f}-{float(np.nanmax(moisture_f)):.2f}"
        print(msg + ".")
    if LOW_WIND_TERRAIN_DOMINANT:
        print(f"Low-wind terrain/fuel dominance enabled below {LOW_WIND_THRESHOLD:.1f} m/s.")
    if moisture_spatial is not None:
        print(f"Spatial fuel-moisture modifier enabled: "
              f"{float(np.nanmin(moisture_spatial)):.2f}-{float(np.nanmax(moisture_spatial)):.2f}.")
    percolation_factor, percolation_stats = build_percolation_layers(fuel, is_building)
    if PERCOLATION_MODEL:
        print("Percolation layer enabled: "
              f"mean density={percolation_stats.get('percolation_mean_density', 0.0):.2f}, "
              f"giant cluster={percolation_stats.get('percolation_giant_frac', 0.0):.2f}, "
              f"near-critical={percolation_stats.get('percolation_near_critical_ha', 0.0):.0f} ha.")
    if CROWN_FIRE_MODEL:
        print("High-intensity/crown-fire source layer enabled: "
              f"wind threshold {CROWN_WIND_THRESHOLD:.1f}-{CROWN_WIND_FULL:.1f} m/s, "
              f"ROS gain <= {CROWN_ROS_GAIN:.2f}, spotting gain <= {CROWN_SPOT_PROB_GAIN:.2f}.")
    if FIRE_INDUCED_WIND_FEEDBACK:
        print("Fire-induced wind feedback proxy enabled: "
              f"convergence <= {FIRE_INDUCED_CONVERGENCE_MAX_MPS:.2f} m/s, "
              f"head-fire boost <= {FIRE_INDUCED_HEADWIND_MAX_MPS:.2f} m/s.")
        _FIRE_INDUCED_WIND_CACHE.clear()

    state = np.full((ny, nx), UNBURNED, dtype=np.int8)
    state[~np.isfinite(elev)] = NONFUEL
    state[fuel <= 0.02] = NONFUEL              # 极低燃料视为不可燃(如水体)
    burn_clock = np.zeros((ny, nx), dtype=np.int16)
    arrival = np.full((ny, nx), np.nan, dtype="float32")   # 着火时刻(小时), 用于画"按天蔓延"

    r0, c0 = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
    r0 = int(np.clip(r0, 1, ny - 2)); c0 = int(np.clip(c0, 1, nx - 2))
    # 用真实起火点。仅当它落在真正不可燃处(水体/范围外)时, 才微调到最近可燃元胞。
    if state[r0, c0] != UNBURNED:
        ys, xs = np.where(state == UNBURNED)
        k = int(np.argmin((ys - r0) ** 2 + (xs - c0) ** 2))
        r0, c0 = int(ys[k]), int(xs[k])
        print("起火点落在水体/范围外, 已微调到最近可燃元胞。")
    # 点一小片(半径 IGNITION_RADIUS)而非单格, 避免单次抽样导致"起火即灭"
    yy, xx = np.ogrid[:ny, :nx]
    seed_disk = ((yy - r0) ** 2 + (xx - c0) ** 2 <= IGNITION_RADIUS ** 2) & (state == UNBURNED)
    state[seed_disk] = BURNING
    arrival[seed_disk] = 0.0
    spread_accum = np.zeros((ny, nx), dtype="float32")
    print(f"起火点(真实) grid=({r0},{c0})  网格 {ny}x{nx}  cell={TARGET_RES:.0f}m")

    geo = neighbor_geometry()
    print(f"CA neighbor radius={CA_NEIGHBOR_RADIUS}, links={len(geo)}, "
          f"second-ring weight={CA_SECOND_RING_WEIGHT:.2f}.")
    directional_progress = make_directional_progress(geo, elev.shape)
    spot_queue = make_spot_queue()
    history, dims, burned_counts = [], [], []
    spot_stats = make_spotting_stats() if spot_stats_out else None
    if calibrate_daily is None:
        calibrate_daily = DAILY_ROLLING_CALIBRATION
    daily_ref_masks, daily_ref_areas = ({}, {})
    daily_ref_new_masks, daily_ref_new_areas = ({}, {})
    if calibrate_daily:
        daily_ref_masks, daily_ref_areas = load_daily_validation_references(transform, crs, elev.shape)
        daily_ref_new_masks = daily_increment_masks(daily_ref_masks)
        daily_ref_new_areas = daily_increment_areas(daily_ref_areas)
        print("Daily rolling ROS calibration enabled (uses daily references, not final perimeter clamp).")
    ros_scale = 1.0
    calibration_records = []
    windows_by_start = {
        int(w["start_step"]): w for w in daily_time_windows()
    } if calibrate_daily else {}

    run_steps = N_STEPS if max_steps is None else max(1, min(N_STEPS, int(max_steps)))
    for step in range(run_steps):
        if calibrate_daily and step in windows_by_start:
            window = windows_by_start[step]
            ros_scale, cal = select_daily_ros_scale(
                state, burn_clock, arrival, fuel, elev, geo, wind,
                window, ros_scale, SEED + 5100 + int(window["day"]) * 41,
                daily_ref_masks=daily_ref_masks,
                daily_ref_new_masks=daily_ref_new_masks,
                daily_ref_areas=daily_ref_areas,
                daily_ref_new_areas=daily_ref_new_areas,
                ign=(r0, c0),
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                canopy=canopy, evt_attention=evt_attention,
                canopy_attention=canopy_attention,
                aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                moisture_h=moisture_h, moisture_f=moisture_f,
                spread_accum=spread_accum,
                percolation_factor=percolation_factor,
                moisture_spatial=moisture_spatial,
                directional_progress=directional_progress,
                burn_duration_steps=burn_duration_steps,
            )
            cal["mode"] = "baseline"
            calibration_records.append(cal)
            print(f"  Day {int(window['day'])}: calibrated ROS scale = {ros_scale:.3f} "
                  f"({cal.get('reason', '')})")
        ca_step(state, burn_clock, arrival, fuel, elev, geo, wind, step, rng,
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                canopy=canopy, evt_attention=evt_attention,
                canopy_attention=canopy_attention,
                aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                moisture_h=moisture_h, moisture_f=moisture_f,
                spread_accum=spread_accum,
                percolation_factor=percolation_factor,
                moisture_spatial=moisture_spatial,
                directional_progress=directional_progress,
                ros_scale=ros_scale,
                spot_stats=spot_stats,
                spot_queue=spot_queue,
                burn_duration_steps=burn_duration_steps)

        fire_any = (state == BURNING) | (state == BURNED)
        if step % 5 == 0 or step == run_steps - 1:
            history.append((step, state.copy()))
            dims.append(box_counting_dimension(perimeter_mask(fire_any)))
            burned_counts.append(int(fire_any.sum()))

        if not (state == BURNING).any() and not has_pending_spot_queue(spot_queue):
            print(f"第 {step} 步火已熄灭。")
            break

    if calibrate_daily:
        write_daily_ros_calibration(calibration_records, DAILY_CALIBRATION_OUT_CSV)
    if spot_stats_out:
        write_spotting_stats(spot_stats, spot_stats_out, spot_stats_png)

    return state, history, dims, burned_counts, (r0, c0), arrival


def arrival_day_index(arrival):
    """Return 1-based reporting day for each burned cell; unburned cells stay NaN."""
    day = np.full(arrival.shape, np.nan, dtype="float32")
    burned = np.isfinite(arrival)
    for window in daily_time_windows():
        unassigned = burned & ~np.isfinite(day)
        in_window = unassigned & (arrival <= float(window["end_h"]) + 1e-9)
        day[in_window] = float(window["day"])
    return day


def daily_time_windows():
    """Return reporting/control windows as CA step and elapsed-hour ranges."""
    total_minutes = int(round(N_STEPS * MIN_PER_STEP))
    sim_start = np.datetime64(SIM_START.replace(" ", "T"))
    sim_end = sim_start + np.timedelta64(total_minutes, "m")
    step_minutes = float(MIN_PER_STEP)

    offset_min = int(round(LOCAL_UTC_OFFSET_HOURS * 60.0))
    windows = []

    def fmt_time(t):
        return str(t.astype("datetime64[m]")).replace("T", " ")

    if DAILY_WINDOW_MODE == "local_calendar":
        current_start_utc = sim_start
        current_end_local = (sim_start + np.timedelta64(offset_min, "m")).astype("datetime64[D]") + np.timedelta64(1, "D")
        day = 1
        while current_start_utc < sim_end:
            current_end_utc = current_end_local - np.timedelta64(offset_min, "m")
            if current_end_utc > sim_end:
                current_end_utc = sim_end
            start_min = int(round((current_start_utc - sim_start) / np.timedelta64(1, "m")))
            end_min = int(round((current_end_utc - sim_start) / np.timedelta64(1, "m")))
            windows.append({
                "day": day,
                "start_step": int(round(start_min / step_minutes)),
                "end_step": int(round(end_min / step_minutes)),
                "start_h": start_min / 60.0,
                "end_h": end_min / 60.0,
                "window_start_utc": fmt_time(current_start_utc),
                "window_end_utc": fmt_time(current_end_utc),
                "window_start_local": fmt_time(current_start_utc + np.timedelta64(offset_min, "m")),
                "window_end_local": fmt_time(current_end_utc + np.timedelta64(offset_min, "m")),
            })
            day += 1
            current_start_utc = current_end_utc
            current_end_local = current_end_local + np.timedelta64(1, "D")
        return windows

    if DAILY_WINDOW_MODE == "utc_calendar":
        current_start_utc = sim_start
        current_end_utc = sim_start.astype("datetime64[D]") + np.timedelta64(1, "D")
        day = 1
        while current_start_utc < sim_end:
            if current_end_utc <= current_start_utc:
                current_end_utc = current_end_utc + np.timedelta64(1, "D")
            if current_end_utc > sim_end:
                current_end_utc = sim_end
            start_min = int(round((current_start_utc - sim_start) / np.timedelta64(1, "m")))
            end_min = int(round((current_end_utc - sim_start) / np.timedelta64(1, "m")))
            windows.append({
                "day": day,
                "start_step": int(round(start_min / step_minutes)),
                "end_step": int(round(end_min / step_minutes)),
                "start_h": start_min / 60.0,
                "end_h": end_min / 60.0,
                "window_start_utc": fmt_time(current_start_utc),
                "window_end_utc": fmt_time(current_end_utc),
                "window_start_local": fmt_time(current_start_utc + np.timedelta64(offset_min, "m")),
                "window_end_local": fmt_time(current_end_utc + np.timedelta64(offset_min, "m")),
            })
            day += 1
            current_start_utc = current_end_utc
            current_end_utc = current_end_utc + np.timedelta64(1, "D")
        return windows

    total_h = total_minutes / 60.0
    n_days = max(1, int(np.ceil(total_h / 24.0)))
    for day in range(1, n_days + 1):
        start_min = int(round((day - 1) * 24.0 * 60.0))
        end_min = min(total_minutes, int(round(day * 24.0 * 60.0)))
        start_utc = sim_start + np.timedelta64(start_min, "m")
        end_utc = sim_start + np.timedelta64(end_min, "m")
        windows.append({
            "day": day,
            "start_step": int(round(start_min / step_minutes)),
            "end_step": int(round(end_min / step_minutes)),
            "start_h": start_min / 60.0,
            "end_h": end_min / 60.0,
            "window_start_utc": fmt_time(start_utc),
            "window_end_utc": fmt_time(end_utc),
            "window_start_local": fmt_time(start_utc + np.timedelta64(offset_min, "m")),
            "window_end_local": fmt_time(end_utc + np.timedelta64(offset_min, "m")),
        })
    return windows


def rolling_reference_time_windows(max_days=ROLLING_REF_MAX_DAYS):
    """Build rolling windows between actual official perimeter observations."""
    if str(ROLLING_REFERENCE_TIME_MODE).lower() != "observation":
        return daily_time_windows()[:max_days]

    import json

    sim_start = np.datetime64(SIM_START.replace(" ", "T"), "m")
    offset_min = int(round(LOCAL_UTC_OFFSET_HOURS * 60.0))
    step_minutes = float(MIN_PER_STEP)
    previous_utc = sim_start
    windows = []

    def fmt_time(value):
        return str(value.astype("datetime64[m]")).replace("T", " ")

    for day in range(1, min(int(max_days), DAILY_REFERENCE_MAX_DAYS) + 1):
        path = Path(OFFICIAL_DAILY_REF_PERIM_DIR) / f"day{day:02d}.geojson"
        if not path.exists():
            break
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
            properties = payload.get("features", [{}])[0].get("properties", {})
            observed_local_text = str(properties.get("observation_time_local", "")).strip()
            if not observed_local_text:
                raise ValueError("missing observation_time_local")
            observed_local = np.datetime64(observed_local_text, "m")
            observed_utc = observed_local - np.timedelta64(offset_min, "m")
        except Exception as exc:
            print(f"Observation-time window fallback for Day {day}: {exc}")
            return daily_time_windows()[:max_days]

        start_min = int(round((previous_utc - sim_start) / np.timedelta64(1, "m")))
        end_min = int(round((observed_utc - sim_start) / np.timedelta64(1, "m")))
        start_step = int(round(start_min / step_minutes))
        end_step = int(round(end_min / step_minutes))
        end_step = max(start_step + 1, end_step)
        windows.append({
            "day": day,
            "start_step": start_step,
            "end_step": end_step,
            "start_h": start_step * step_minutes / 60.0,
            "end_h": end_step * step_minutes / 60.0,
            "window_start_utc": fmt_time(previous_utc),
            "window_end_utc": fmt_time(observed_utc),
            "window_start_local": fmt_time(previous_utc + np.timedelta64(offset_min, "m")),
            "window_end_local": fmt_time(observed_local),
            "observation_aligned": True,
        })
        previous_utc = observed_utc
    return windows


def daily_area_summary(arrival):
    """Summarize new and cumulative burned area for each reporting day."""
    total_h = N_STEPS * MIN_PER_STEP / 60.0
    cell_ha = TARGET_RES ** 2 / 1e4
    rows = []
    prev_cells = 0
    burned = np.isfinite(arrival)
    for window in daily_time_windows():
        day = window["day"]
        start_h = max(0.0, float(window["start_h"]))
        end_h = min(float(window["end_h"]), total_h)
        window_hours = max(0.0, end_h - start_h)
        cumulative_cells = int((burned & (arrival <= end_h + 1e-9)).sum())
        new_cells = cumulative_cells - prev_cells
        new_burned_ha = new_cells * cell_ha
        rows.append({
            "day": day,
            "window_start_utc": window["window_start_utc"],
            "window_end_utc": window["window_end_utc"],
            "window_start_local": window.get("window_start_local", ""),
            "window_end_local": window.get("window_end_local", ""),
            "hours_since_ignition": end_h,
            "window_hours": window_hours,
            "new_cells": new_cells,
            "cumulative_cells": cumulative_cells,
            "new_burned_ha": new_burned_ha,
            "cumulative_burned_ha": cumulative_cells * cell_ha,
            "new_burned_ha_per_hour": new_burned_ha / window_hours if window_hours > 0 else np.nan,
        })
        prev_cells = cumulative_cells
    return rows


def write_daily_area_csv(rows, out_csv):
    import csv
    fields = [
        "day", "window_start_utc", "window_end_utc",
        "window_start_local", "window_end_local", "hours_since_ignition", "window_hours",
        "new_cells", "cumulative_cells", "new_burned_ha", "cumulative_burned_ha",
        "new_burned_ha_per_hour",
    ]
    os.makedirs(os.path.dirname(out_csv) or ".", exist_ok=True)
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)


def print_daily_area(rows):
    print("Daily burned area after spread:")
    print("  Day  UTC window                 local window              hours   new(ha)  ha/hour  cumulative(ha)")
    for row in rows:
        print(f"  {row['day']:>3}  {row['window_start_utc']} -> {row['window_end_utc']}  "
              f"{row.get('window_start_local', '')} -> {row.get('window_end_local', '')}  "
              f"{row['window_hours']:5.1f}  {row['new_burned_ha']:8.0f}  "
              f"{row['new_burned_ha_per_hour']:7.1f}  {row['cumulative_burned_ha']:14.0f}")


def plot_daily_area(rows, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    days = [r["day"] for r in rows]
    new_ha = [r["new_burned_ha"] for r in rows]
    cum_ha = [r["cumulative_burned_ha"] for r in rows]
    fig, ax = plt.subplots(figsize=(9, 5))
    ax.bar(days, new_ha, color="#e2724a", alpha=0.85,
           label="Daily burned-area increment")
    ax.plot(days, cum_ha, "-o", color="#7a1f1f", lw=2,
            label="Cumulative burned area")
    for x, y in zip(days, cum_ha):
        ax.annotate(f"{y:.0f}", (x, y), textcoords="offset points", xytext=(0, 7),
                    ha="center", fontsize=8, fontweight="bold")
    ax.set_xlabel("Reporting day")
    ax.set_ylabel("Burned area (ha)")
    ax.set_title("Daily Burned Area after Fire Spread", fontweight="bold")
    ax.legend()
    ax.grid(alpha=0.3)
    _apply_lettered_bottom_caption(
        fig, [ax], ["daily burned-area increment and cumulative burned area"],
        "Daily Burned Area after Fire Spread",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=140)
    plt.close(fig)
    print("saved", out_png)


def load_fbfm40_codes(lf_path, dst_transform, dst_crs, shape):
    """Load LANDFIRE FBFM40 codes on the simulation grid."""
    from rasterio.warp import reproject, Resampling as WR
    codes = np.full(shape, -9999.0, dtype="float32")
    with rasterio.open(lf_path) as src:
        reproject(source=rasterio.band(src, 4), destination=codes,
                  src_transform=src.transform, src_crs=src.crs,
                  dst_transform=dst_transform, dst_crs=dst_crs,
                  resampling=WR.nearest)
    return codes.astype("int32")


_EVT_ATTRIBUTE_CACHE = {}


def load_evt_codes(path, dst_transform, dst_crs, shape):
    """Align categorical LANDFIRE EVT codes to the CA master grid."""
    if not EVT_FUEL_MODEL or not path or not os.path.exists(path):
        return None
    from rasterio.warp import reproject, Resampling as WR
    codes = np.full(shape, -9999.0, dtype="float32")
    with rasterio.open(path) as src:
        reproject(
            source=rasterio.band(src, 1), destination=codes,
            src_transform=src.transform, src_crs=src.crs,
            src_nodata=src.nodata, dst_nodata=-9999.0,
            dst_transform=dst_transform, dst_crs=dst_crs,
            resampling=WR.mode,
        )
    return codes.astype("int32")


def load_evt_attributes(path=EVT_ATTRIBUTE_CSV):
    """Read the LFPS raster attribute table exported to a stable CSV."""
    key = str(path)
    if key in _EVT_ATTRIBUTE_CACHE:
        return _EVT_ATTRIBUTE_CACHE[key]
    if not path or not os.path.exists(path):
        _EVT_ATTRIBUTE_CACHE[key] = {}
        return {}
    import csv
    rows = {}
    with open(path, newline="", encoding="utf-8") as stream:
        for row in csv.DictReader(stream):
            try:
                rows[int(row["Value"])] = row
            except (KeyError, TypeError, ValueError):
                continue
    _EVT_ATTRIBUTE_CACHE[key] = rows
    return rows


def evt_road_mask(evt_codes, attributes=None):
    """Return LANDFIRE EVT road cells used as nonfuel barriers at CA scale."""
    if evt_codes is None:
        return None
    attributes = load_evt_attributes() if attributes is None else attributes
    road = np.zeros(evt_codes.shape, dtype=bool)
    for value, row in attributes.items():
        name = str(row.get("EVT_NAME", "")).strip().lower()
        if "developed-roads" in name or name.endswith(" roads"):
            road |= evt_codes == int(value)
    return road


def build_evt_behavior_layers(evt_codes, canopy=None, attribute_path=EVT_ATTRIBUTE_CSV):
    """Build bounded vegetation-type ROS and residence-time modifiers.

    EVT identifiers are nominal categories. Modifiers are assigned from the
    attribute-table lifeform and community text, never from code magnitude.
    """
    if evt_codes is None:
        return None, None
    attributes = load_evt_attributes(attribute_path)
    if not attributes:
        return None, None

    flammability = np.ones(evt_codes.shape, dtype="float32")
    residence = np.ones(evt_codes.shape, dtype="float32")
    tree_or_shrub = np.zeros(evt_codes.shape, dtype=bool)
    lifeform_rules = {
        "tree": (0.98, 1.08),
        "shrub": (1.02, 1.05),
        "herb": (1.01, 0.75),
        "sparse": (0.75, 0.65),
        "agriculture": (0.95, 0.80),
        "water": (0.0, 0.0),
        "developed": (1.0, 0.90),
    }
    for value, row in attributes.items():
        selected = evt_codes == int(value)
        if not selected.any():
            continue
        lifeform = str(row.get("EVT_LF", "")).strip().lower()
        name = " ".join((
            str(row.get("EVT_NAME", "")),
            str(row.get("EVT_PHYS", "")),
            str(row.get("EVT_GP_N", "")),
        )).lower()
        if EVT_ROADS_NONFUEL and (
            "developed-roads" in name or " roads " in f" {name} "
        ):
            flammability[selected] = 0.0
            residence[selected] = 0.0
            continue
        flame_factor, residence_factor = lifeform_rules.get(lifeform, (1.0, 1.0))
        if lifeform in ("tree", "shrub"):
            tree_or_shrub[selected] = True
        if "dry-mesic chaparral" in name or "xeric" in name:
            flame_factor *= 1.04
            residence_factor *= 1.08
        elif "chaparral" in name:
            flame_factor *= 1.02
            residence_factor *= 1.05
        elif "coastal scrub" in name:
            flame_factor *= 1.01
            residence_factor *= 0.97
        if any(term in name for term in ("riparian", "wet meadow", "marsh")):
            flame_factor *= 0.75
            residence_factor *= 0.90
        if "ruderal grassland" in name or "ruderal herbaceous" in name:
            flame_factor *= 1.03
            residence_factor *= 0.90
        flammability[selected] = flame_factor
        residence[selected] = residence_factor

    flammability = np.clip(
        flammability, EVT_FLAMMABILITY_MIN, EVT_FLAMMABILITY_MAX
    ).astype("float32")
    flammability[residence <= 0.0] = 0.0
    if canopy is not None:
        cover = np.clip(np.asarray(canopy["cover_pct"], dtype="float32") / 100.0, 0.0, 1.0)
        height = np.clip(np.asarray(canopy["height_m"], dtype="float32") / 25.0, 0.0, 1.0)
        density = np.clip(
            np.asarray(canopy["bulk_density_kg_m3"], dtype="float32") / 0.18,
            0.0, 1.0,
        )
        canopy_residence = 1.0 + 0.06 * cover + 0.04 * height + 0.04 * density
        residence[tree_or_shrub] *= canopy_residence[tree_or_shrub]
    duration_steps = np.rint(BURN_STEPS * residence).astype("int16")
    duration_steps = np.clip(
        duration_steps,
        EVT_BURN_DURATION_MIN_STEPS,
        EVT_BURN_DURATION_MAX_STEPS,
    ).astype("int16")
    duration_steps[flammability <= 0.0] = EVT_BURN_DURATION_MIN_STEPS
    return flammability, duration_steps


def prepare_evt_fuel_behavior(fuel, transform, crs, canopy=None, evt_codes=None):
    """Apply detailed pre-fire vegetation behavior while preserving FBFM40."""
    if evt_codes is None:
        evt_codes = load_evt_codes(EVT_PATH, transform, crs, fuel.shape)
    factor, duration_steps = build_evt_behavior_layers(evt_codes, canopy=canopy)
    if factor is None or duration_steps is None:
        return fuel.copy(), np.full(fuel.shape, BURN_STEPS, dtype="int16"), evt_codes
    adjusted = np.clip(np.asarray(fuel, dtype="float32") * factor, 0.0, 1.3)
    road = evt_road_mask(evt_codes) if EVT_ROADS_NONFUEL else None
    burnable = adjusted > 0.02
    if burnable.any():
        hours = duration_steps[burnable].astype(float) * MIN_PER_STEP / 60.0
        print(
            "LANDFIRE EVT behavior enabled: "
            f"{len(np.unique(evt_codes[evt_codes > 0]))} classes, "
            f"flammability factor {float(np.min(factor[burnable])):.2f}-"
            f"{float(np.max(factor[burnable])):.2f}, "
            f"burn residence {float(np.min(hours)):.2f}-"
            f"{float(np.max(hours)):.2f} h."
        )
    if road is not None:
        print(
            f"EVT roads treated as nonfuel: {int(road.sum())} cells "
            f"({road.sum() * TARGET_RES ** 2 / 1e4:.1f} ha); spotting may cross them."
        )
    return adjusted, duration_steps, evt_codes


def build_vegetation_attention_layers(evt_codes, canopy=None):
    """Encode EVT flammability and canopy structure as centered attention features."""
    factor, _duration = build_evt_behavior_layers(evt_codes, canopy=canopy)
    if factor is None:
        return None, None
    evt_focus = np.clip((factor.astype("float32") - 1.0) / 0.12, -1.0, 1.0)
    evt_focus[factor <= 0.0] = -1.0

    canopy_focus = np.zeros(factor.shape, dtype="float32")
    if canopy is not None:
        cover = np.clip(np.asarray(canopy["cover_pct"], dtype="float32") / 100.0, 0.0, 1.0)
        height = np.clip(np.asarray(canopy["height_m"], dtype="float32") / 25.0, 0.0, 1.0)
        density = np.clip(
            np.asarray(canopy["bulk_density_kg_m3"], dtype="float32") / 0.18,
            0.0, 1.0,
        )
        structure = 0.50 * cover + 0.30 * height + 0.20 * density
        canopy_focus = np.clip((structure - 0.35) / 0.65, -1.0, 1.0).astype("float32")
        canopy_focus[factor <= 0.0] = -1.0
    return evt_focus.astype("float32"), canopy_focus


def build_wui_layers(code, evt_codes=None, evt_attributes=None):
    """Build WUI fields for the paper-based building/vegetation ignition rules."""
    tree = ((code >= 161) & (code <= 165)) | ((code >= 181) & (code <= 189))
    shrub = ((code >= 141) & (code <= 149)) | ((code >= 121) & (code <= 124))
    grass = (code >= 101) & (code <= 109)
    is_building = code == 91
    if evt_codes is not None:
        attributes = load_evt_attributes() if evt_attributes is None else evt_attributes
        road = evt_road_mask(evt_codes, attributes=attributes)
        is_building &= ~road

    veg_q = np.zeros(code.shape, dtype="float32")
    veg_q[grass] = VEGQ_GRASS
    veg_q[shrub] = VEGQ_SHRUB
    veg_q[tree] = VEGQ_TREE

    veg_crit = np.full(code.shape, QCRIT_VEG_OTH, dtype="float32")
    veg_crit[tree] = QCRIT_VEG_TREE
    veg_crit[is_building] = np.inf
    return is_building, veg_q, veg_crit


def build_control_value_maps(code, elev, evt_codes=None):
    """Build per-cell loss maps used by the daily cost function."""
    try:
        from scipy import ndimage
    except Exception:
        ndimage = None

    cell_ha = TARGET_RES ** 2 / 1e4
    forest = ((code >= 161) & (code <= 165)) | ((code >= 181) & (code <= 189))
    shrub = (code >= 141) & (code <= 149)
    grass_shrub = (code >= 121) & (code <= 124)
    grass = (code >= 101) & (code <= 109)
    ag = code == 93
    urban = code == 91
    road = evt_road_mask(evt_codes) if evt_codes is not None else None
    if road is not None:
        urban &= ~road

    asset = np.zeros(code.shape, dtype="float64")
    asset[forest] = COST_FOREST
    asset[shrub] = COST_SHRUB
    asset[grass_shrub] = (COST_SHRUB + COST_GRASS) / 2.0
    asset[grass] = COST_GRASS
    asset[ag] = COST_AG
    asset[urban] = COST_BUILDING

    veg = forest | shrub | grass_shrub | grass | ag
    grow, gcol = np.gradient(np.nan_to_num(elev, nan=0.0))
    slope_tan = np.hypot(grow, gcol) / TARGET_RES
    external = np.zeros(code.shape, dtype="float64")
    external[veg] += COST_CARBON
    external += COST_EROSION * np.clip(slope_tan, 0, 1.5) * veg
    external += COST_SMOKE

    if ndimage is not None:
        near_urban = ndimage.binary_dilation(urban, iterations=max(1, int(300 / TARGET_RES)))
    else:
        near_urban = urban

    value = (asset + external) * cell_ha
    human = COST_HUMAN * near_urban * cell_ha
    cats = {
        "forest": forest,
        "shrub": shrub,
        "grass": grass | grass_shrub,
        "ag": ag,
        "urban": urban,
    }
    return value, human, cats, urban


def cost_breakdown(mask, value, human, cats):
    out = {name: float(value[mask & cat].sum()) for name, cat in cats.items()}
    out["human"] = float(human[mask].sum())
    out["total_loss"] = float(value[mask].sum()) + out["human"]
    return out


def initialize_ca_state(elev, fuel, transform, crs):
    """Create the persistent CA state used by the daily closed loop."""
    ny, nx = elev.shape
    state = np.full((ny, nx), UNBURNED, dtype=np.int8)
    state[~np.isfinite(elev)] = NONFUEL
    state[fuel <= 0.02] = NONFUEL
    burn_clock = np.zeros((ny, nx), dtype=np.int16)
    arrival = np.full((ny, nx), np.nan, dtype="float32")

    r0, c0 = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
    r0 = int(np.clip(r0, 1, ny - 2))
    c0 = int(np.clip(c0, 1, nx - 2))
    if state[r0, c0] != UNBURNED:
        ys, xs = np.where(state == UNBURNED)
        k = int(np.argmin((ys - r0) ** 2 + (xs - c0) ** 2))
        r0, c0 = int(ys[k]), int(xs[k])

    yy, xx = np.ogrid[:ny, :nx]
    seed_disk = ((yy - r0) ** 2 + (xx - c0) ** 2 <= IGNITION_RADIUS ** 2) & (state == UNBURNED)
    state[seed_disk] = BURNING
    arrival[seed_disk] = 0.0
    return state, burn_clock, arrival, (r0, c0)


def load_firms_hotspot_schedule(path, transform, crs, shape):
    """Load incident VIIRS detections into causal CA-step observation bins."""
    import csv
    from datetime import datetime

    schedule = {}
    if not FIRMS_NOWCAST_ASSIMILATION or not path or not os.path.exists(path):
        return schedule
    start = datetime.strptime(str(SIM_START), "%Y-%m-%d %H:%M")
    with open(path, newline="", encoding="utf-8-sig") as stream:
        for row in csv.DictReader(stream):
            try:
                if int(float(row.get("type", 0))) != 0:
                    continue
                confidence = str(row.get("confidence", "")).strip().lower()
                if confidence in {"l", "low"}:
                    continue
                frp = float(row.get("frp", 0.0))
                if not np.isfinite(frp) or frp < float(FIRMS_MIN_FRP_MW):
                    continue
                date_text = str(row["acq_date"]).strip().replace("/", "-")
                parts = date_text.split("-")
                date_text = "-".join(
                    [parts[0], parts[1].zfill(2), parts[2].zfill(2)]
                )
                time_text = str(row["acq_time"]).strip().split(".")[0].zfill(4)
                observed_at = datetime.strptime(
                    f"{date_text} {time_text}", "%Y-%m-%d %H%M"
                )
                elapsed_min = (observed_at - start).total_seconds() / 60.0
                step = int(np.floor(elapsed_min / float(MIN_PER_STEP)))
                if step < 0 or step >= int(N_STEPS):
                    continue
                latitude = float(row["latitude"])
                longitude = float(row["longitude"])
                rr, cc = lonlat_to_rowcol(longitude, latitude, transform, crs)
                rr, cc = int(rr), int(cc)
                if not (0 <= rr < shape[0] and 0 <= cc < shape[1]):
                    continue
                schedule.setdefault(step, []).append({
                    "row": rr,
                    "col": cc,
                    "frp_mw": frp,
                    "observed_at_utc": observed_at.isoformat(timespec="minutes"),
                })
            except (KeyError, TypeError, ValueError):
                continue
    print(
        "FIRMS nowcast observations enabled: "
        f"{sum(len(items) for items in schedule.values())} VIIRS hotspot(s) "
        f"across {len(schedule)} CA step(s)."
    )
    return schedule


def apply_firms_hotspots(state, burn_clock, arrival, active_fuel, step,
                         hotspot_schedule, stats=None):
    """Assimilate VIIRS hotspots at acquisition time without future look-ahead."""
    events = hotspot_schedule.get(int(step), ()) if hotspot_schedule else ()
    if not events:
        return 0
    try:
        from scipy import ndimage
    except Exception:
        ndimage = None

    fire = (state == BURNING) | (state == BURNED)
    distance_to_fire = (
        ndimage.distance_transform_edt(~fire) if ndimage is not None and fire.any()
        else np.zeros(state.shape, dtype="float32")
    )
    max_link_cells = float(FIRMS_MAX_LINK_DISTANCE_M) / max(float(TARGET_RES), 1.0)
    radius = max(0, int(FIRMS_SEED_RADIUS_CELLS))
    elapsed_h = float(step) * float(MIN_PER_STEP) / 60.0
    yy, xx = np.ogrid[:state.shape[0], :state.shape[1]]
    new_cells = 0
    accepted_events = 0
    for event in events:
        rr, cc = int(event["row"]), int(event["col"])
        if fire.any() and float(distance_to_fire[rr, cc]) > max_link_cells:
            continue
        seed = (
            (yy - rr) ** 2 + (xx - cc) ** 2 <= radius ** 2
        ) & (state == UNBURNED) & np.isfinite(active_fuel) & (active_fuel > 0.02)
        count = int(seed.sum())
        if count <= 0:
            continue
        state[seed] = BURNING
        burn_clock[seed] = 0
        existing = arrival[seed]
        arrival[seed] = np.where(
            np.isfinite(existing), np.minimum(existing, elapsed_h), elapsed_h
        )
        fire[seed] = True
        new_cells += count
        accepted_events += 1
    if stats is not None:
        stats["detections_seen"] = int(stats.get("detections_seen", 0)) + len(events)
        stats["detections_accepted"] = int(
            stats.get("detections_accepted", 0)
        ) + accepted_events
        stats["cells_ignited"] = int(stats.get("cells_ignited", 0)) + new_cells
    return new_cells


def firms_hotspot_mask_for_window(hotspot_schedule, start_step, end_step,
                                  shape):
    """Rasterize VIIRS detections already acquired in one nowcast window."""
    mask = np.zeros(shape, dtype=bool)
    count = 0
    for step in range(int(start_step), int(end_step)):
        for event in hotspot_schedule.get(step, ()):
            rr, cc = int(event["row"]), int(event["col"])
            if 0 <= rr < shape[0] and 0 <= cc < shape[1]:
                mask[rr, cc] = True
                count += 1
    return mask, count


def firms_shape_fusion_nowcast(pred_new, previous_fire, hotspot_mask,
                               active_fuel, target_area_ha,
                               radius_cells=None, sigma_cells=None,
                               prediction_weight=None, hotspot_weight=None,
                               density_weight=None,
                               sector_quota_weight=None, sector_count=None,
                               sector_min_hotspots=None,
                               local_support_weight=None, fuel_weight=None,
                               distance_penalty=None, target_scale=None,
                               max_link_distance_m=None,
                               chain_link_distance_m=None, support_mode=None,
                               include_prediction_candidates=True,
                               selection_threshold=None):
    """Fuse a CA forecast with in-window VIIRS support for operational nowcasts.

    The function does not access a perimeter reference. It is intentionally
    separate from strict forecasts because hotspot observations are acquired
    after the forecast window starts.
    """
    predicted = np.asarray(pred_new, dtype=bool)
    previous = np.asarray(previous_fire, dtype=bool)
    # Interior detections confirm already assimilated fire and contain no new
    # information about today's growth. Keeping them biases the support field
    # back into yesterday's perimeter.
    hotspots = np.asarray(hotspot_mask, dtype=bool) & ~previous
    stats = {
        "applied": False,
        "hotspot_count": int(hotspots.sum()),
        "candidate_ha": float(predicted.sum()) * TARGET_RES ** 2 / 1e4,
        "selected_ha": float(predicted.sum()) * TARGET_RES ** 2 / 1e4,
        "target_ha": np.nan,
        "added_ha": 0.0,
        "removed_ha": 0.0,
    }
    threshold_mode = (
        selection_threshold is not None and
        np.isfinite(float(selection_threshold))
    )
    if (
        not hotspots.any() or
        (not threshold_mode and not np.isfinite(target_area_ha))
    ):
        return predicted.copy(), stats
    try:
        from scipy import ndimage
    except Exception:
        return predicted.copy(), stats

    radius = max(1, int(
        FIRMS_SHAPE_RADIUS_CELLS if radius_cells is None else radius_cells
    ))
    sigma = max(0.5, float(
        FIRMS_SHAPE_SIGMA_CELLS if sigma_cells is None else sigma_cells
    ))
    pred_weight = float(
        FIRMS_SHAPE_PREDICTION_WEIGHT
        if prediction_weight is None else prediction_weight
    )
    hot_weight = float(
        FIRMS_SHAPE_HOTSPOT_WEIGHT if hotspot_weight is None else hotspot_weight
    )
    density_mix = float(np.clip(
        FIRMS_SHAPE_DENSITY_WEIGHT if density_weight is None else density_weight,
        0.0,
        1.0,
    ))
    sector_mix = float(np.clip(
        FIRMS_SHAPE_SECTOR_QUOTA_WEIGHT
        if sector_quota_weight is None else sector_quota_weight,
        0.0,
        1.0,
    ))
    sectors = max(4, int(
        FIRMS_SHAPE_SECTORS if sector_count is None else sector_count
    ))
    minimum_sector_hotspots = max(1, int(
        FIRMS_SHAPE_SECTOR_MIN_HOTSPOTS
        if sector_min_hotspots is None else sector_min_hotspots
    ))
    support_weight = float(
        FIRMS_SHAPE_LOCAL_SUPPORT_WEIGHT
        if local_support_weight is None else local_support_weight
    )
    local_fuel_weight = float(
        FIRMS_SHAPE_FUEL_WEIGHT if fuel_weight is None else fuel_weight
    )
    dist_penalty = float(
        FIRMS_SHAPE_DISTANCE_PENALTY
        if distance_penalty is None else distance_penalty
    )
    area_scale = float(
        FIRMS_SHAPE_TARGET_SCALE if target_scale is None else target_scale
    )
    shape_link_distance = max(0.0, float(
        FIRMS_SHAPE_MAX_LINK_DISTANCE_M
        if max_link_distance_m is None else max_link_distance_m
    ))
    chain_link_distance = max(0.0, float(
        FIRMS_SHAPE_CHAIN_LINK_DISTANCE_M
        if chain_link_distance_m is None else chain_link_distance_m
    ))
    shape_support_mode = str(
        FIRMS_SHAPE_SUPPORT_MODE if support_mode is None else support_mode
    ).strip().lower()

    previous_distance = ndimage.distance_transform_edt(~previous).astype("float32")
    initial_link = previous_distance <= (
        shape_link_distance / max(float(TARGET_RES), 1.0)
    )
    connected_hotspots = hotspots & initial_link
    if connected_hotspots.any() and chain_link_distance > 0.0:
        chain_cells = chain_link_distance / max(float(TARGET_RES), 1.0)
        while True:
            distance_to_chain = ndimage.distance_transform_edt(
                ~connected_hotspots
            )
            expanded = hotspots & (distance_to_chain <= chain_cells)
            if int(expanded.sum()) == int(connected_hotspots.sum()):
                break
            connected_hotspots = expanded
    hotspots = connected_hotspots
    stats["hotspot_count"] = int(hotspots.sum())
    if int(hotspots.sum()) < minimum_sector_hotspots:
        sector_mix = 0.0
    if not hotspots.any():
        return predicted.copy(), stats

    burnable = (
        np.isfinite(active_fuel) & (np.asarray(active_fuel, dtype=float) > 0.02) &
        ~previous
    )
    hotspot_distance = ndimage.distance_transform_edt(~hotspots).astype("float32")
    if shape_support_mode in {
        "multiscale_kde", "kde", "multiscale", "hybrid", "density_robust"
    }:
        hotspot_impulse = hotspots.astype("float32")
        fine = ndimage.gaussian_filter(hotspot_impulse, sigma=sigma)
        coarse = ndimage.gaussian_filter(hotspot_impulse, sigma=sigma * 2.0)
        fine_scale = max(float(np.nanpercentile(fine[fine > 0], 99.0)), 1e-9)
        coarse_scale = max(
            float(np.nanpercentile(coarse[coarse > 0], 99.0)), 1e-9
        )
        kde_support = (
            0.68 * np.clip(fine / fine_scale, 0.0, 1.0) +
            0.32 * np.clip(coarse / coarse_scale, 0.0, 1.0)
        ).astype("float32")
        if shape_support_mode in {"hybrid", "density_robust"}:
            # A pure KDE rewards tightly clustered detections and can
            # underweight a broad flank sampled by dispersed VIIRS pixels.
            # Nearest-detection support saturates that sampling-density bias.
            nearest_support = np.exp(-hotspot_distance / sigma).astype("float32")
            hotspot_support = (
                density_mix * kde_support +
                (1.0 - density_mix) * nearest_support
            ).astype("float32")
        else:
            hotspot_support = kde_support
    else:
        hotspot_support = np.exp(-hotspot_distance / sigma).astype("float32")
    predicted_support = ndimage.gaussian_filter(
        predicted.astype("float32"), sigma=max(1.0, sigma * 0.65)
    ).astype("float32")
    hotspot_candidate = hotspot_distance <= float(radius)
    # Only graph-connected detections reach this point. Their local candidate
    # neighborhoods may extend beyond the direct previous-fire distance,
    # allowing a chain of confirmed detections to represent rapid runs.
    candidate_support = hotspot_candidate.copy()
    if bool(include_prediction_candidates):
        candidate_support |= predicted
    candidate = burnable & candidate_support
    if not candidate.any():
        return predicted.copy(), stats

    fuel_scaled = np.clip(np.asarray(active_fuel, dtype="float32"), 0.0, 1.25) / 1.25
    score = (
        pred_weight * predicted.astype("float32") +
        hot_weight * hotspot_support +
        support_weight * predicted_support +
        local_fuel_weight * fuel_scaled -
        dist_penalty * previous_distance
    ).astype("float32")
    cell_ha = TARGET_RES ** 2 / 1e4
    candidate_index = np.flatnonzero(candidate.ravel())
    values = score.ravel()[candidate_index]
    selected = np.zeros(candidate.size, dtype=bool)
    target_cells = None
    if threshold_mode:
        selected[candidate_index[values >= float(selection_threshold)]] = True
    else:
        target_cells = int(round(float(target_area_ha) * area_scale / cell_ha))
        target_cells = int(np.clip(target_cells, 1, int(candidate.sum())))
    if (
        not threshold_mode and sector_mix > 1e-9 and hotspots.any()
    ):
        if previous.any():
            origin_row, origin_col = np.mean(np.argwhere(previous), axis=0)
        else:
            origin_row, origin_col = np.mean(np.argwhere(hotspots), axis=0)
        rows, cols = np.indices(candidate.shape)
        angles = (
            np.arctan2(cols - origin_col, -(rows - origin_row)) + 2.0 * np.pi
        ) % (2.0 * np.pi)
        sector_index = np.floor(
            angles * sectors / (2.0 * np.pi) + 0.5
        ).astype("int16") % sectors
        footprint = burnable & hotspot_candidate
        footprint_mass = np.asarray([
            np.count_nonzero(footprint & (sector_index == sector))
            for sector in range(sectors)
        ], dtype="float64")
        prediction_mass = np.asarray([
            np.count_nonzero(predicted & candidate & (sector_index == sector))
            for sector in range(sectors)
        ], dtype="float64")
        footprint_share = footprint_mass / max(float(footprint_mass.sum()), 1.0)
        prediction_share = prediction_mass / max(float(prediction_mass.sum()), 1.0)
        quota_share = (
            sector_mix * footprint_share +
            (1.0 - sector_mix) * prediction_share
        )
        quota_share /= max(float(quota_share.sum()), 1e-12)
        raw_quota = quota_share * target_cells
        quota = np.floor(raw_quota).astype(int)
        remainder = target_cells - int(quota.sum())
        if remainder > 0:
            fractional_order = np.argsort(-(raw_quota - quota))
            quota[fractional_order[:remainder]] += 1
        for sector in range(sectors):
            sector_candidates = candidate_index[
                sector_index.ravel()[candidate_index] == sector
            ]
            if sector_candidates.size == 0 or quota[sector] <= 0:
                continue
            sector_values = score.ravel()[sector_candidates]
            order = np.argsort(-sector_values, kind="mergesort")
            take = min(int(quota[sector]), int(sector_candidates.size))
            selected[sector_candidates[order[:take]]] = True
        shortfall = target_cells - int(selected.sum())
        if shortfall > 0:
            remaining = candidate_index[~selected[candidate_index]]
            order = np.argsort(-score.ravel()[remaining], kind="mergesort")
            selected[remaining[order[:shortfall]]] = True
    elif not threshold_mode:
        order = np.argsort(-values, kind="mergesort")
        selected[candidate_index[order[:target_cells]]] = True
    selected = selected.reshape(candidate.shape)

    added = selected & ~predicted
    removed = predicted & ~selected
    stats.update({
        "applied": True,
        "candidate_ha": float(candidate.sum()) * cell_ha,
        "selected_ha": float(selected.sum()) * cell_ha,
        "target_ha": (
            float(target_cells) * cell_ha
            if target_cells is not None else np.nan
        ),
        "selection_threshold": (
            float(selection_threshold) if threshold_mode else np.nan
        ),
        "prediction_candidates_included": bool(
            include_prediction_candidates
        ),
        "added_ha": float(added.sum()) * cell_ha,
        "removed_ha": float(removed.sum()) * cell_ha,
    })
    return selected, stats


def line_cells(p0, p1):
    r0, c0 = map(int, p0)
    r1, c1 = map(int, p1)
    dr, dc = abs(r1 - r0), abs(c1 - c0)
    sr = 1 if r0 < r1 else -1
    sc = 1 if c0 < c1 else -1
    err = dr - dc
    out = []
    r, c = r0, c0
    while True:
        out.append((r, c))
        if r == r1 and c == c1:
            break
        e2 = 2 * err
        if e2 > -dc:
            err -= dc
            r += sr
        if e2 < dr:
            err += dr
            c += sc
    return out


def build_firebreak_mask(elev, placeable, center, gdir):
    """Build a ridge-snapped firebreak mask roughly perpendicular to gdir."""
    try:
        from scipy import ndimage
    except Exception:
        ndimage = None

    h, w = elev.shape
    gr, gc = float(gdir[0]), float(gdir[1])
    pr, pc = -gc, gr
    snapped = []
    for t in range(-FIREBREAK_HALF_LEN, FIREBREAK_HALF_LEN + 1):
        br = center[0] + pr * t
        bc = center[1] + pc * t
        best = None
        best_elev = -1e18
        for s in range(-FIREBREAK_SNAP, FIREBREAK_SNAP + 1):
            rr = int(round(br + gr * s))
            cc = int(round(bc + gc * s))
            if 0 <= rr < h and 0 <= cc < w and placeable[rr, cc] and elev[rr, cc] > best_elev:
                best = (rr, cc)
                best_elev = float(elev[rr, cc])
        if best is not None:
            snapped.append(best)

    if len(snapped) < 2:
        return None, 0.0

    cells = []
    for a, b in zip(snapped[:-1], snapped[1:]):
        cells.extend([cell for cell in line_cells(a, b) if placeable[cell]])
    if len(cells) < 2:
        return None, 0.0

    mask = np.zeros((h, w), dtype=bool)
    rr, cc = zip(*cells)
    mask[list(rr), list(cc)] = True
    if ndimage is not None:
        mask = ndimage.binary_dilation(mask, iterations=FIREBREAK_WIDTH_ITERS)
    mask &= placeable

    pts = np.asarray(snapped, dtype=float)
    length_m = float(np.hypot(np.diff(pts[:, 0]), np.diff(pts[:, 1])).sum()) * TARGET_RES
    return mask, length_m


def forecast_next_window_mask(state, burn_clock, arrival, active_fuel, elev, geo, wind,
                              start_step, forecast_steps, rng_seed,
                              is_building=None, veg_q=None, veg_crit=None,
                              canopy=None, evt_attention=None, canopy_attention=None,
                              aspect_fac=None, grow=None, gcol=None,
                              moisture_h=None, moisture_f=None,
                              spread_accum=None, percolation_factor=None,
                              control_damp=None, moisture_spatial=None,
                              directional_progress=None, ros_scale=1.0,
                              slope_scale=1.0, spot_prob_scale=1.0,
                              moisture_scale=1.0,
                              attention_feedback=None, burn_duration_steps=None,
                              front_momentum=None, adaptive_spread_field=None,
                              causal_morphing_field=None,
                              local_transition_model=None,
                              normal_ros_model=None,
                              neural_parameter_fields=None,
                              ta_mlca_spotting_active=False):
    """Run a no-action CA forecast and return cells expected to burn in that window."""
    forecast_steps = int(max(0, forecast_steps))
    empty = np.zeros(state.shape, dtype=bool)
    if forecast_steps == 0 or not (state == BURNING).any():
        return empty

    f_state = state.copy()
    f_burn_clock = burn_clock.copy()
    f_arrival = arrival.copy()
    f_spread_accum = None if spread_accum is None else spread_accum.copy()
    f_directional_progress = (
        make_directional_progress(geo, state.shape)
        if directional_progress is None else directional_progress.copy()
    )
    f_control_damp = None if control_damp is None else control_damp.copy()
    f_spot_queue = make_spot_queue()
    fire_before = (f_state == BURNING) | (f_state == BURNED)
    rng = np.random.default_rng(rng_seed)

    end_step = min(N_STEPS, int(start_step) + forecast_steps)
    for step in range(int(start_step), end_step):
        if not (f_state == BURNING).any() and not has_pending_spot_queue(f_spot_queue):
            break
        ca_step(f_state, f_burn_clock, f_arrival, active_fuel, elev, geo, wind, step, rng,
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                canopy=canopy, evt_attention=evt_attention,
                canopy_attention=canopy_attention,
                aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                moisture_h=moisture_h, moisture_f=moisture_f,
                spread_accum=f_spread_accum,
                percolation_factor=percolation_factor,
                control_damp=f_control_damp,
                moisture_spatial=moisture_spatial,
                directional_progress=f_directional_progress,
                ros_scale=ros_scale,
                slope_scale=slope_scale,
                spot_prob_scale=spot_prob_scale,
                moisture_scale=moisture_scale,
                attention_feedback=attention_feedback,
                adaptive_spread_field=adaptive_spread_field,
                causal_morphing_field=causal_morphing_field,
                front_momentum=front_momentum,
                spot_queue=f_spot_queue,
                burn_duration_steps=burn_duration_steps,
                local_transition_model=local_transition_model,
                normal_ros_model=normal_ros_model,
                neural_parameter_fields=neural_parameter_fields,
                ta_mlca_spotting_active=ta_mlca_spotting_active,
                paired_random_key=int(rng_seed))

    fire_after = (f_state == BURNING) | (f_state == BURNED)
    return fire_after & ~fire_before


def simulate_window_with_scale(state, burn_clock, arrival, active_fuel, elev, geo, wind,
                               start_step, end_step, rng_seed, ros_scale,
                               is_building=None, veg_q=None, veg_crit=None,
                               canopy=None, evt_attention=None, canopy_attention=None,
                               aspect_fac=None, grow=None, gcol=None,
                               moisture_h=None, moisture_f=None,
                               spread_accum=None, percolation_factor=None,
                               control_damp=None, moisture_spatial=None,
                               directional_progress=None, attention_feedback=None,
                               slope_scale=1.0, spot_prob_scale=1.0,
                               moisture_scale=1.0,
                               burn_duration_steps=None,
                               adaptive_spread_field=None,
                               causal_morphing_field=None,
                               front_momentum=None,
                               hotspot_schedule=None,
                               local_transition_model=None,
                               normal_ros_model=None,
                               neural_parameter_fields=None,
                               ta_mlca_spotting_active=False,
                               paired_random_key=None):
    f_state = state.copy()
    f_burn_clock = burn_clock.copy()
    f_arrival = arrival.copy()
    f_spread_accum = None if spread_accum is None else spread_accum.copy()
    f_directional_progress = (
        make_directional_progress(geo, state.shape)
        if directional_progress is None else directional_progress.copy()
    )
    f_control_damp = None if control_damp is None else control_damp.copy()
    f_spot_queue = make_spot_queue()
    rng = np.random.default_rng(rng_seed)
    for step in range(int(start_step), min(N_STEPS, int(end_step))):
        if not FIRMS_SHAPE_FUSION:
            apply_firms_hotspots(
                f_state, f_burn_clock, f_arrival, active_fuel, step,
                hotspot_schedule,
            )
        if not (f_state == BURNING).any() and not has_pending_spot_queue(f_spot_queue):
            break
        ca_step(f_state, f_burn_clock, f_arrival, active_fuel, elev, geo, wind, step, rng,
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                canopy=canopy, evt_attention=evt_attention,
                canopy_attention=canopy_attention,
                aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                moisture_h=moisture_h, moisture_f=moisture_f,
                spread_accum=f_spread_accum,
                percolation_factor=percolation_factor,
                control_damp=f_control_damp,
                moisture_spatial=moisture_spatial,
                directional_progress=f_directional_progress,
                ros_scale=ros_scale,
                slope_scale=slope_scale,
                spot_prob_scale=spot_prob_scale,
                moisture_scale=moisture_scale,
                attention_feedback=attention_feedback,
                adaptive_spread_field=adaptive_spread_field,
                causal_morphing_field=causal_morphing_field,
                front_momentum=front_momentum,
                spot_queue=f_spot_queue,
                burn_duration_steps=burn_duration_steps,
                local_transition_model=local_transition_model,
                normal_ros_model=normal_ros_model,
                neural_parameter_fields=neural_parameter_fields,
                ta_mlca_spotting_active=ta_mlca_spotting_active,
                paired_random_key=paired_random_key)
    return f_state, f_arrival


def _front_bearing_deg(mask, origin):
    rr, cc = np.where(mask)
    if len(rr) == 0:
        return np.nan
    dr = float(np.mean(rr) - origin[0])
    dc = float(np.mean(cc) - origin[1])
    return float(np.degrees(np.arctan2(dc, -dr)) % 360.0)


def _score_metric(scores, key):
    try:
        val = float(scores.get(key, 0.0))
    except Exception:
        return 0.0
    return val if np.isfinite(val) else 0.0


def select_daily_ros_scale(state, burn_clock, arrival, active_fuel, elev, geo, wind,
                           window, current_scale, rng_seed,
                           daily_ref_masks=None, daily_ref_new_masks=None,
                           daily_ref_areas=None, daily_ref_new_areas=None,
                           ign=None, is_building=None, veg_q=None, veg_crit=None,
                           canopy=None, evt_attention=None, canopy_attention=None,
                           aspect_fac=None, grow=None, gcol=None,
                           moisture_h=None, moisture_f=None,
                           spread_accum=None, percolation_factor=None,
                           control_damp=None, moisture_spatial=None,
                           directional_progress=None, burn_duration_steps=None):
    """Choose a per-day ROS scale from short CA forecasts against observed daily perimeters."""
    day = int(window["day"])
    daily_ref_masks = daily_ref_masks or {}
    daily_ref_new_masks = daily_ref_new_masks or {}
    daily_ref_areas = daily_ref_areas or {}
    daily_ref_new_areas = daily_ref_new_areas or {}
    ref_cum = daily_ref_masks.get(day)
    ref_new = daily_ref_new_masks.get(day)
    ref_cum_area = daily_ref_areas.get(day)
    ref_new_area = daily_ref_new_areas.get(day)
    if ref_cum is None and ref_new is None and ref_cum_area is None and ref_new_area is None:
        return float(current_scale), {
            "day": day,
            "selected_ros_scale": float(current_scale),
            "reason": "no daily reference",
        }
    if not (state == BURNING).any():
        return float(current_scale), {
            "day": day,
            "selected_ros_scale": float(current_scale),
            "reason": "no active fire",
        }

    start_step = int(window["start_step"])
    end_step = min(N_STEPS, int(window["end_step"]))
    fire_before = (state == BURNING) | (state == BURNED)
    cell_ha = TARGET_RES ** 2 / 1e4
    rel_scales = np.asarray(DAILY_CALIBRATION_CANDIDATE_SCALES, dtype=float)
    candidates = np.unique(np.round(np.clip(
        float(current_scale) * rel_scales,
        DAILY_CALIBRATION_MIN_SCALE,
        DAILY_CALIBRATION_MAX_SCALE
    ), 4))

    best = None
    for i, scale in enumerate(candidates):
        f_state, _f_arrival = simulate_window_with_scale(
            state, burn_clock, arrival, active_fuel, elev, geo, wind,
            start_step, end_step, rng_seed + i * 17, float(scale),
            is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
            canopy=canopy, evt_attention=evt_attention,
            canopy_attention=canopy_attention,
            aspect_fac=aspect_fac, grow=grow, gcol=gcol,
            moisture_h=moisture_h, moisture_f=moisture_f,
            spread_accum=spread_accum,
            percolation_factor=percolation_factor,
            control_damp=control_damp,
            moisture_spatial=moisture_spatial,
            directional_progress=directional_progress,
            burn_duration_steps=burn_duration_steps,
        )
        fire_after = (f_state == BURNING) | (f_state == BURNED)
        sim_new = fire_after & ~fire_before
        daily_scores = _spatial_scores(sim_new, ref_new) if ref_new is not None else {}
        cum_scores = _spatial_scores(fire_after, ref_cum) if ref_cum is not None else {}
        sim_new_ha = float(sim_new.sum()) * cell_ha
        sim_cum_ha = float(fire_after.sum()) * cell_ha

        if ref_new_area is not None and np.isfinite(ref_new_area) and ref_new_area > 0:
            area_ref = float(ref_new_area)
            area_sim = sim_new_ha
        elif ref_new is not None and ref_new.any():
            area_ref = float(ref_new.sum()) * cell_ha
            area_sim = sim_new_ha
        elif ref_cum_area is not None and np.isfinite(ref_cum_area) and ref_cum_area > 0:
            area_ref = float(ref_cum_area)
            area_sim = sim_cum_ha
        elif ref_cum is not None and ref_cum.any():
            area_ref = float(ref_cum.sum()) * cell_ha
            area_sim = sim_cum_ha
        else:
            area_ref = np.nan
            area_sim = np.nan
        area_penalty = (
            abs(np.log((area_sim + 1e-6) / (area_ref + 1e-6)))
            if np.isfinite(area_ref) and area_ref > 0 and np.isfinite(area_sim)
            else 0.0
        )

        heading_penalty = 0.0
        if ign is not None and ref_new is not None and ref_new.any() and sim_new.any():
            sim_heading = _front_bearing_deg(sim_new, ign)
            ref_heading = _front_bearing_deg(ref_new, ign)
            if np.isfinite(sim_heading) and np.isfinite(ref_heading):
                heading_penalty = abs(_angle_delta_deg(sim_heading, ref_heading)) / 180.0

        score = 0.0
        score += 0.30 * _score_metric(daily_scores, "f1")
        score += 0.16 * _score_metric(daily_scores, "iou")
        score += 0.26 * _score_metric(cum_scores, "f1")
        score += 0.12 * _score_metric(cum_scores, "iou")
        score -= DAILY_CALIBRATION_AREA_WEIGHT * float(area_penalty)
        score -= DAILY_CALIBRATION_HEADING_WEIGHT * float(heading_penalty)
        rec = {
            "day": day,
            "candidate_ros_scale": float(scale),
            "score": float(score),
            "sim_new_ha": sim_new_ha,
            "sim_cumulative_ha": sim_cum_ha,
            "ref_new_ha": float(area_ref) if np.isfinite(area_ref) else np.nan,
            "daily_iou": float(daily_scores.get("iou", np.nan)),
            "daily_f1": float(daily_scores.get("f1", np.nan)),
            "cumulative_iou": float(cum_scores.get("iou", np.nan)),
            "cumulative_f1": float(cum_scores.get("f1", np.nan)),
            "area_penalty": float(area_penalty),
            "heading_penalty": float(heading_penalty),
        }
        if best is None or rec["score"] > best["score"]:
            best = rec

    if best is None:
        return float(current_scale), {
            "day": day,
            "selected_ros_scale": float(current_scale),
            "reason": "no candidate",
        }
    best["selected_ros_scale"] = best["candidate_ros_scale"]
    best["reason"] = "selected by daily perimeter calibration"
    return float(best["selected_ros_scale"]), best


def write_daily_ros_calibration(records, out_csv):
    if not records:
        return
    import csv
    os.makedirs(os.path.dirname(out_csv) or ".", exist_ok=True)
    fields = [
        "mode", "day", "selected_ros_scale", "candidate_ros_scale", "score",
        "sim_new_ha", "sim_cumulative_ha", "ref_new_ha",
        "daily_iou", "daily_f1", "cumulative_iou", "cumulative_f1",
        "area_penalty", "heading_penalty", "reason",
    ]
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(records)
    print("saved", out_csv)


def _front_terrain_fuel_score(observed, active_fuel, elev):
    """Score exterior source cells by sustained fuel and DEM-corridor access."""
    score = np.zeros(observed.shape, dtype="float32")
    if active_fuel is None or elev is None:
        return score
    corridor_strength, corridor_row, corridor_col = build_terrain_corridor_layers(elev)
    lookahead = max(1, int(ASSIMILATION_FRONT_LOOKAHEAD_CELLS))
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dy == 0 and dx == 0:
                continue
            dist = float(np.hypot(dy, dx))
            direction_sum = np.zeros(observed.shape, dtype="float32")
            direction_weight = np.zeros(observed.shape, dtype="float32")
            path_open = np.ones(observed.shape, dtype=bool)
            for distance_cells in range(1, lookahead + 1):
                oy = -dy * distance_cells
                ox = -dx * distance_cells
                target_elev = shift_no_wrap(elev, oy, ox, fill_value=np.nan)
                target_fuel = shift_no_wrap(active_fuel, oy, ox, fill_value=0.0)
                target_outside = shift_no_wrap(~observed, oy, ox, fill_value=False)
                target_corridor = shift_no_wrap(
                    corridor_strength, oy, ox, fill_value=0.0
                )
                target_axis_row = shift_no_wrap(corridor_row, oy, ox, fill_value=0.0)
                target_axis_col = shift_no_wrap(corridor_col, oy, ox, fill_value=0.0)
                path_open &= np.isfinite(target_elev) & (target_fuel > 0.02)
                slope = np.degrees(np.arctan2(
                    target_elev - elev,
                    distance_cells * dist * float(TARGET_RES),
                ))
                axis_alignment = np.power(
                    np.clip(np.abs(
                        target_axis_row * (dy / dist) +
                        target_axis_col * (dx / dist)
                    ), 0.0, 1.0),
                    ASSIMILATION_FRONT_CORRIDOR_ALIGNMENT_POWER,
                )
                corridor_factor = 1.0 + float(ASSIMILATION_FRONT_CORRIDOR_GAIN) * (
                    np.clip(target_corridor, 0.0, 1.0) * axis_alignment
                )
                opportunity = (
                    low_wind_fuel_response(target_fuel, 1.0) *
                    slope_ros_factor(
                        slope,
                        LOW_WIND_UPSLOPE_GAIN,
                        LOW_WIND_DOWNSLOPE_A,
                        LOW_WIND_DOWNSLOPE_MIN,
                    ) *
                    corridor_factor
                )
                valid = path_open & target_outside
                distance_weight = float(np.exp(-(distance_cells - 1) / 5.0))
                direction_sum += np.where(
                    valid, opportunity * distance_weight, 0.0
                ).astype("float32")
                direction_weight += np.where(valid, distance_weight, 0.0).astype(
                    "float32"
                )
            direction_score = np.divide(
                direction_sum,
                np.maximum(direction_weight, 1e-6),
                out=np.zeros_like(direction_sum),
                where=direction_weight > 0.0,
            )
            score = np.maximum(score, direction_score.astype("float32"))
    return score


def _robust_unit_scale(values, mask):
    result = np.zeros(values.shape, dtype="float32")
    sample = np.asarray(values[mask], dtype=float)
    sample = sample[np.isfinite(sample)]
    if not sample.size:
        return result
    lo, hi = np.nanpercentile(sample, [10, 90]) if sample.size > 8 else (
        float(np.nanmin(sample)), float(np.nanmax(sample))
    )
    if hi <= lo + 1e-9:
        result[mask] = 0.5
    else:
        result = np.clip((values - lo) / (hi - lo), 0.0, 1.0).astype("float32")
    return result


def build_reference_front_momentum(observed, previous_observed, active_front,
                                   start_step, forecast_wind_speed=None,
                                   regime_memory=1.0):
    """Extend the last observed growth heading into the next forecast domain."""
    observed = np.asarray(observed, dtype=bool)
    previous = np.zeros_like(observed) if previous_observed is None else (
        np.asarray(previous_observed, dtype=bool) & observed
    )
    active = np.asarray(active_front, dtype=bool) & observed
    empty_stats = {
        "momentum_used": False,
        "momentum_active_cells": int(active.sum()),
        "momentum_mean_strength": 0.0,
        "momentum_mean_bearing_deg": np.nan,
        "momentum_regime_weight": 0.0,
        "stratified_front_used": False,
    }
    if not FRONT_MOMENTUM_MODEL or not previous.any() or not active.any():
        return None, empty_stats
    growth = observed & ~previous
    if not growth.any():
        return None, empty_stats

    try:
        from scipy import ndimage

        distance_from_previous = ndimage.distance_transform_edt(~previous).astype(
            "float32"
        )
        travel = np.where(observed, distance_from_previous, 0.0).astype("float32")
        support = ndimage.gaussian_filter(
            observed.astype("float32"),
            sigma=max(float(FRONT_MOMENTUM_VECTOR_SMOOTH_SIGMA), 0.0),
            mode="nearest",
        )
        travel = ndimage.gaussian_filter(
            travel,
            sigma=max(float(FRONT_MOMENTUM_VECTOR_SMOOTH_SIGMA), 0.0),
            mode="nearest",
        ) / np.maximum(support, 1e-5)
        grad_row, grad_col = np.gradient(travel)
        normal_row, normal_col = fire_front_outward_normals(observed)
        vector_row = 0.72 * grad_row + 0.28 * normal_row
        vector_col = 0.72 * grad_col + 0.28 * normal_col
        outward_dot = vector_row * normal_row + vector_col * normal_col
        vector_row = np.where(outward_dot < 0.0, -vector_row, vector_row)
        vector_col = np.where(outward_dot < 0.0, -vector_col, vector_col)
        vector_norm = np.hypot(vector_row, vector_col)
        fallback = active & (vector_norm < 1e-6)
        vector_row[fallback] = normal_row[fallback]
        vector_col[fallback] = normal_col[fallback]
        vector_norm = np.maximum(np.hypot(vector_row, vector_col), 1e-6)
        vector_row = (vector_row / vector_norm).astype("float32")
        vector_col = (vector_col / vector_norm).astype("float32")

        advance_strength = _robust_unit_scale(distance_from_previous, active)
        edge_strength = np.zeros(observed.shape, dtype="float32")
        edge_strength[active] = 0.35 + 0.65 * advance_strength[active]
        distance_to_front, nearest = ndimage.distance_transform_edt(
            ~active, return_indices=True
        )
        nearest_row, nearest_col = nearest
        decay_cells = max(float(FRONT_MOMENTUM_DISTANCE_DECAY_CELLS), 1e-6)
        field_strength = edge_strength[nearest_row, nearest_col] * np.exp(
            -distance_to_front / decay_cells
        )
        valid = (
            np.isfinite(field_strength) &
            (distance_to_front <= float(FRONT_MOMENTUM_MAX_DISTANCE_CELLS))
        )
        field_strength = np.where(valid, field_strength, 0.0).astype("float32")
        field_row = np.where(
            valid, vector_row[nearest_row, nearest_col], 0.0
        ).astype("float32")
        field_col = np.where(
            valid, vector_col[nearest_row, nearest_col], 0.0
        ).astype("float32")

        weights = edge_strength[active].astype(float)
        mean_row = float(np.average(vector_row[active], weights=weights))
        mean_col = float(np.average(vector_col[active], weights=weights))
        bearing = float(np.degrees(np.arctan2(mean_col, -mean_row)) % 360.0)
        wind_regime_weight = (
            float(low_wind_terrain_weight(forecast_wind_speed))
            if forecast_wind_speed is not None and
            np.isfinite(forecast_wind_speed) else 1.0
        )
        regime_weight = wind_regime_weight * float(np.clip(regime_memory, 0.0, 1.0))
        stats = {
            "momentum_used": True,
            "momentum_active_cells": int(active.sum()),
            "momentum_mean_strength": float(np.mean(edge_strength[active])),
            "momentum_mean_bearing_deg": bearing,
            "momentum_regime_weight": regime_weight,
        }
        return {
            "row": field_row,
            "col": field_col,
            "strength": field_strength,
            "start_step": int(start_step),
            "regime_weight": regime_weight,
        }, stats
    except Exception:
        return None, empty_stats


def front_momentum_link_factor(front_momentum, dy, dx, dist, step,
                               regional_low_wind):
    """Bounded directional persistence from the preceding observed window."""
    if front_momentum is None or not FRONT_MOMENTUM_MODEL:
        return 1.0
    try:
        strength = np.asarray(front_momentum["strength"], dtype="float32")
        row = np.asarray(front_momentum["row"], dtype="float32")
        col = np.asarray(front_momentum["col"], dtype="float32")
        elapsed_h = max(
            0.0,
            (int(step) - int(front_momentum.get("start_step", step))) *
            MIN_PER_STEP / 60.0,
        )
        half_life = max(float(FRONT_MOMENTUM_HALF_LIFE_H), MIN_PER_STEP / 60.0)
        time_decay = float(2.0 ** (-elapsed_h / half_life))
        alignment = np.clip(
            row * (float(dy) / float(dist)) +
            col * (float(dx) / float(dist)),
            -1.0,
            1.0,
        )
        forward = np.power(np.clip(alignment, 0.0, 1.0),
                           FRONT_MOMENTUM_ALIGNMENT_POWER)
        backward = np.power(np.clip(-alignment, 0.0, 1.0),
                            FRONT_MOMENTUM_ALIGNMENT_POWER)
        log_factor = (
            float(FRONT_MOMENTUM_FORWARD_GAIN) * forward -
            float(FRONT_MOMENTUM_BACK_DAMP) * backward
        )
        regime_weight = float(np.clip(
            front_momentum.get("regime_weight", 1.0), 0.0, 1.0
        ))
        factor = np.exp(
            regime_weight * float(regional_low_wind) *
            time_decay * strength * log_factor
        )
        return np.clip(
            factor,
            float(FRONT_MOMENTUM_FACTOR_MIN),
            float(FRONT_MOMENTUM_FACTOR_MAX),
        ).astype("float32")
    except Exception:
        return 1.0


def _select_ranked_front_cells(score, candidates, quantile, min_cells):
    """Select coherent high-score front arcs with stable ties."""
    candidates = np.asarray(candidates, dtype=bool)
    flat_idx = np.flatnonzero(candidates.ravel())
    if flat_idx.size == 0:
        return candidates.copy(), 0.0
    ranked_score = np.asarray(score, dtype="float32")
    sigma = max(float(ASSIMILATION_FRONT_SCORE_SMOOTH_SIGMA), 0.0)
    if sigma > 0.0 and flat_idx.size > max(8, int(min_cells)):
        try:
            from scipy import ndimage

            weight = ndimage.gaussian_filter(
                candidates.astype("float32"), sigma=sigma, mode="nearest"
            )
            smoothed = ndimage.gaussian_filter(
                np.where(candidates, ranked_score, 0.0).astype("float32"),
                sigma=sigma,
                mode="nearest",
            )
            ranked_score = np.where(
                candidates,
                smoothed / np.maximum(weight, 1e-6),
                -np.inf,
            ).astype("float32")
        except Exception:
            pass
    values = ranked_score.ravel()[flat_idx]
    values = np.nan_to_num(values, nan=-np.inf, posinf=1.0, neginf=-np.inf)
    n = int(flat_idx.size)
    target = int(math.ceil((1.0 - float(quantile)) * n))
    target = min(n, max(max(1, int(min_cells)), target))
    order = np.argsort(-values, kind="mergesort")
    chosen = flat_idx[order[:target]]
    leading = np.zeros(candidates.size, dtype=bool)
    leading[chosen] = True
    threshold = float(values[order[target - 1]]) if target > 0 else 0.0
    return leading.reshape(candidates.shape), threshold


def _select_stratified_front_cells(score, candidates, quantile, min_cells,
                                   origin, sector_count=None,
                                   arc_weight=None):
    """Select high-potential cells while retaining spatially diverse front arcs."""
    candidates = np.asarray(candidates, dtype=bool)
    flat_idx = np.flatnonzero(candidates.ravel())
    if flat_idx.size == 0:
        return candidates.copy(), 0.0
    count = int(flat_idx.size)
    target = int(math.ceil((1.0 - float(quantile)) * count))
    target = min(count, max(max(1, int(min_cells)), target))
    sectors = max(4, int(
        ASSIMILATION_STRATIFIED_FRONT_SECTORS
        if sector_count is None else sector_count
    ))
    arc_share = float(np.clip(
        ASSIMILATION_STRATIFIED_FRONT_ARC_WEIGHT
        if arc_weight is None else arc_weight,
        0.0, 1.0,
    ))

    rr, cc = np.unravel_index(flat_idx, candidates.shape)
    bearing = (
        np.degrees(np.arctan2(
            cc.astype(float) - float(origin[1]),
            -(rr.astype(float) - float(origin[0])),
        )) + 360.0
    ) % 360.0
    sector_index = np.floor(bearing / (360.0 / sectors)).astype("int16")
    sector_index = np.clip(sector_index, 0, sectors - 1)
    values = np.asarray(score, dtype="float32").ravel()[flat_idx]
    values = np.nan_to_num(values, nan=-np.inf, posinf=1.0, neginf=-np.inf)
    finite = np.isfinite(values)
    if finite.any():
        lo, hi = np.nanpercentile(values[finite], [10.0, 90.0])
        quality = np.clip(
            (values - lo) / max(float(hi - lo), 1e-6), 0.0, 1.0
        )
    else:
        quality = np.zeros(count, dtype="float32")
    quality = np.nan_to_num(quality, nan=0.0).astype("float32")

    sector_counts = np.bincount(sector_index, minlength=sectors).astype(float)
    sector_quality = np.bincount(
        sector_index, weights=0.10 + 0.90 * quality, minlength=sectors
    ).astype(float)
    arc_mass = sector_counts / max(float(sector_counts.sum()), 1.0)
    quality_mass = sector_quality / max(float(sector_quality.sum()), 1e-9)
    allocation = arc_share * arc_mass + (1.0 - arc_share) * quality_mass
    raw_quota = target * allocation
    quota = np.minimum(
        np.floor(raw_quota).astype(int), sector_counts.astype(int)
    )

    available_sectors = np.flatnonzero(sector_counts > 0)
    if target >= available_sectors.size:
        quota[available_sectors] = np.maximum(quota[available_sectors], 1)
        quota = np.minimum(quota, sector_counts.astype(int))
    remaining = target - int(quota.sum())
    residual = raw_quota - quota
    while remaining > 0:
        eligible = np.flatnonzero(quota < sector_counts)
        if not eligible.size:
            break
        best = int(eligible[np.argmax(residual[eligible])])
        quota[best] += 1
        residual[best] -= 1.0
        remaining -= 1

    selected_local = np.zeros(count, dtype=bool)
    for sector in available_sectors:
        local = np.flatnonzero(sector_index == sector)
        take = min(int(quota[sector]), int(local.size))
        if take <= 0:
            continue
        order = np.argsort(-values[local], kind="mergesort")
        selected_local[local[order[:take]]] = True
    selected_count = int(selected_local.sum())
    if selected_count < target:
        remainder = np.flatnonzero(~selected_local)
        order = np.argsort(-values[remainder], kind="mergesort")
        selected_local[remainder[order[:target - selected_count]]] = True

    leading = np.zeros(candidates.size, dtype=bool)
    leading[flat_idx[selected_local]] = True
    selected_values = values[selected_local]
    threshold = float(np.nanmin(selected_values)) if selected_values.size else 0.0
    return leading.reshape(candidates.shape), threshold


def _select_sector_preserving_front_cells(
    reference_score,
    rerank_score,
    candidates,
    quantile,
    min_cells,
    origin,
    sector_count=None,
):
    """Re-rank front cells without changing physical angular quotas."""
    candidates = np.asarray(candidates, dtype=bool)
    physical, _ = _select_ranked_front_cells(
        reference_score, candidates, quantile, min_cells
    )
    flat_idx = np.flatnonzero(candidates.ravel())
    if not flat_idx.size or not physical.any():
        return physical, 0.0, 0

    sectors = max(4, int(
        ML_ACTIVE_FRONT_SECTORS
        if sector_count is None else sector_count
    ))
    rows, cols = np.unravel_index(flat_idx, candidates.shape)
    bearing = (
        np.degrees(np.arctan2(
            cols.astype(float) - float(origin[1]),
            -(rows.astype(float) - float(origin[0])),
        )) + 360.0
    ) % 360.0
    sector_index = np.floor(
        bearing / (360.0 / sectors)
    ).astype("int16")
    sector_index = np.clip(sector_index, 0, sectors - 1)
    physical_local = physical.ravel()[flat_idx]
    quota = np.bincount(
        sector_index[physical_local], minlength=sectors
    ).astype(int)
    values = np.asarray(rerank_score, dtype="float32").ravel()[flat_idx]
    values = np.nan_to_num(
        values, nan=-np.inf, posinf=1.0, neginf=-np.inf
    )

    selected_local = np.zeros(flat_idx.size, dtype=bool)
    for sector in np.flatnonzero(quota > 0):
        local = np.flatnonzero(sector_index == sector)
        take = min(int(quota[sector]), int(local.size))
        if take <= 0:
            continue
        order = np.argsort(-values[local], kind="mergesort")
        selected_local[local[order[:take]]] = True

    selected = np.zeros(candidates.size, dtype=bool)
    selected[flat_idx[selected_local]] = True
    selected = selected.reshape(candidates.shape)
    selected_values = values[selected_local]
    threshold = (
        float(np.nanmin(selected_values))
        if selected_values.size else 0.0
    )
    changed = int(np.count_nonzero(selected ^ physical))
    return selected, threshold, changed


def _empty_ml_active_front_stats():
    return {
        "enabled": False,
        "model_type": "none",
        "valid_links": 0,
        "scored_edge_cells": 0,
        "mean_opportunity": 0.0,
        "p95_opportunity": 0.0,
        "validation_trust": 0.0,
        "effective_weight": 0.0,
    }


def build_ml_active_front_opportunity(observed, active_fuel, elev,
                                      wind_speed, wind_from,
                                      moisture_factor, local_transition_model,
                                      canopy=None, fuel_continuity=None,
                                      elapsed_hours=0.0):
    """Score outward observed-front links with the grouped multi-fire model."""
    stats = _empty_ml_active_front_stats()
    if (
        not ML_ACTIVE_FRONT_FILTER
        or local_transition_model is None
        or observed is None
    ):
        return None, stats
    fire = np.asarray(observed, dtype=bool)
    fuel = np.asarray(active_fuel, dtype="float32")
    if not fire.any() or fire.shape != fuel.shape:
        return None, stats

    edge = outer_perimeter_mask(fire)
    normal_row, normal_col = fire_front_outward_normals(fire)
    toward = (np.asarray(wind_from, dtype="float32") + 180.0) % 360.0
    speed = np.asarray(wind_speed, dtype="float32")
    cover = None if canopy is None else canopy.get("cover_pct")
    height = None if canopy is None else canopy.get("height_m")
    residual_scale, validation_trust, _training_resolution = (
        local_transition_transfer_scale(local_transition_model)
    )
    maximum = np.zeros(fire.shape, dtype="float32")
    total = np.zeros(fire.shape, dtype="float32")
    count = np.zeros(fire.shape, dtype="int16")
    valid_links = 0

    for dy, dx, dist, bearing, _spread_weight in neighbor_geometry():
        if dist > float(ML_ACTIVE_FRONT_MAX_NEIGHBOR_RADIUS) + 1e-9:
            continue
        source_edge = shift_no_wrap(edge, dy, dx, fill_value=False)
        valid = source_edge & ~fire & np.isfinite(elev) & (fuel > 0.02)
        if not valid.any():
            continue
        source_elev = shift_no_wrap(elev, dy, dx, fill_value=np.nan)
        slope_angle = np.degrees(
            np.arctan2(elev - source_elev, dist * TARGET_RES)
        ).astype("float32")
        source_fuel = shift_no_wrap(fuel, dy, dx, fill_value=0.0)
        source_normal_row = shift_no_wrap(
            normal_row, dy, dx, fill_value=0.0
        )
        source_normal_col = shift_no_wrap(
            normal_col, dy, dx, fill_value=0.0
        )
        normal_alignment = np.clip(
            source_normal_row * (dy / dist)
            + source_normal_col * (dx / dist),
            0.0,
            1.0,
        )
        features, rows, cols = build_local_link_feature_rows(
            valid,
            speed,
            toward,
            bearing,
            slope_angle,
            fuel,
            source_fuel,
            moisture_factor=moisture_factor,
            canopy_cover_pct=cover,
            canopy_height_m=height,
            fuel_continuity=fuel_continuity,
            front_normal_alignment=normal_alignment,
            elapsed_hours=elapsed_hours,
        )
        if not len(rows):
            continue
        logits = np.asarray(physical_prior_logit(features), dtype="float64")
        base_probability = 1.0 / (
            1.0 + np.exp(-np.clip(logits, -20.0, 20.0))
        )
        residual_factor = local_transition_model.predict_factor(
            features,
            preserve_mean_hazard=False,
            residual_scale=residual_scale,
            shrink_out_of_distribution=True,
        )
        probability = 1.0 - np.power(
            1.0 - np.clip(base_probability, 0.0, 1.0),
            np.maximum(residual_factor, 1e-4),
        )
        source_rows = rows - int(dy)
        source_cols = cols - int(dx)
        inside = (
            (source_rows >= 0) & (source_rows < fire.shape[0])
            & (source_cols >= 0) & (source_cols < fire.shape[1])
        )
        source_rows = source_rows[inside]
        source_cols = source_cols[inside]
        probability = probability[inside].astype("float32")
        np.maximum.at(maximum, (source_rows, source_cols), probability)
        np.add.at(total, (source_rows, source_cols), probability)
        np.add.at(count, (source_rows, source_cols), 1)
        valid_links += int(probability.size)

    scored = edge & (count > 0)
    if (
        valid_links < int(ML_ACTIVE_FRONT_MIN_LINKS)
        or np.count_nonzero(scored) < 3
    ):
        return None, stats
    mean = np.zeros(fire.shape, dtype="float32")
    mean[scored] = total[scored] / np.maximum(count[scored], 1)
    opportunity = np.zeros(fire.shape, dtype="float32")
    opportunity[scored] = (
        0.65 * maximum[scored] + 0.35 * mean[scored]
    )
    sigma = max(float(ML_ACTIVE_FRONT_SMOOTH_SIGMA), 0.0)
    if sigma > 0.0:
        try:
            from scipy import ndimage
            support = ndimage.gaussian_filter(
                scored.astype("float32"), sigma=sigma
            )
            smoothed = ndimage.gaussian_filter(opportunity, sigma=sigma)
            opportunity[edge] = (
                smoothed[edge] / np.maximum(support[edge], 1e-6)
            )
        except Exception:
            pass
    opportunity[~edge] = 0.0
    values = opportunity[scored]
    effective_weight = float(
        np.clip(ML_ACTIVE_FRONT_WEIGHT * validation_trust, 0.0, 1.0)
    )
    stats.update({
        "enabled": bool(effective_weight > 1e-6),
        "model_type": "local-transition-link-opportunity",
        "valid_links": valid_links,
        "scored_edge_cells": int(np.count_nonzero(scored)),
        "mean_opportunity": float(np.mean(values)),
        "p95_opportunity": float(np.percentile(values, 95.0)),
        "validation_trust": float(validation_trust),
        "effective_weight": effective_weight,
    })
    return opportunity, stats


def select_reference_active_front(observed, previous_observed, edge=None,
                                  active_fuel=None, elev=None,
                                  forecast_wind_speed=None,
                                  forecast_wind_toward_deg=None,
                                  terrain_weight_cap=None,
                                  observation_feedback=None,
                                  causal_activity_field=None,
                                  causal_barrier_field=None,
                                  learned_activity_field=None,
                                  learned_activity_weight=None,
                                  momentum_memory=1.0):
    """Select leading observed arcs that can seed the next forecast window."""
    observed = np.asarray(observed, dtype=bool)
    edge = outer_perimeter_mask(observed) & observed if edge is None else (
        np.asarray(edge, dtype=bool) & observed
    )
    previous = np.zeros_like(observed) if previous_observed is None else (
        np.asarray(previous_observed, dtype=bool) & observed
    )
    stats = {
        "candidate_cells": int(edge.sum()),
        "active_cells": int(edge.sum()),
        "advance_threshold_cells": 0.0,
        "terrain_dominance": 0.0,
        "forecast_wind_speed_mps": float(forecast_wind_speed)
        if forecast_wind_speed is not None else np.nan,
        "forecast_wind_toward_deg": float(forecast_wind_toward_deg)
        if forecast_wind_toward_deg is not None else np.nan,
        "wind_front_weight": 0.0,
        "feedback_front_weight": 0.0,
        "recessed_front_weight": 0.0,
        "momentum_selection_weight": 0.0,
        "bcaf_activity_weight": 0.0,
        "ml_activity_weight": 0.0,
        "ml_sector_mass_preserved": False,
        "ml_reranked_cells": 0,
        "ml_fixed_budget_applied": False,
        "ml_fixed_budget_cells": 0,
        "bcaf_barrier_penalty": 0.0,
        "bcaf_reactivation_reserve_used": False,
        "reserve_score_mode": "none",
        "reserve_front_fraction": 0.0,
        "reserve_front_cells": 0,
        "stratified_front_used": False,
        "candidate_mode": "edge",
    }
    previous_area_ratio = float(previous.sum()) / max(float(observed.sum()), 1.0)
    if (
        not ASSIMILATION_ACTIVE_FRONT_SELECTION
        or not previous.any()
        or previous_area_ratio < ASSIMILATION_SEED_STAGE_PREVIOUS_AREA_RATIO
    ):
        return edge, stats

    try:
        from scipy import ndimage

        advance_distance = ndimage.distance_transform_edt(~previous)
        advancing = edge & (
            advance_distance > float(ASSIMILATION_STATIONARY_EDGE_CELLS)
        )
        raw_terrain_dominance = 0.0
        if forecast_wind_speed is not None and LOW_WIND_TERRAIN_DOMINANT:
            raw_terrain_dominance = float(low_wind_terrain_weight(forecast_wind_speed))
        terrain_cap = (
            ASSIMILATION_MAX_TERRAIN_WEIGHT
            if terrain_weight_cap is None else terrain_weight_cap
        )
        terrain_dominance = min(
            raw_terrain_dominance,
            float(np.clip(terrain_cap, 0.0, 1.0)),
        )
        wind_front_weight = 0.0
        if (
            forecast_wind_speed is not None and
            forecast_wind_toward_deg is not None and
            np.isfinite(forecast_wind_speed) and
            np.isfinite(forecast_wind_toward_deg)
        ):
            wind_ramp = (
                (float(forecast_wind_speed) - float(ASSIMILATION_WIND_FRONT_MIN_SPEED)) /
                max(
                    float(ASSIMILATION_WIND_FRONT_FULL_SPEED) -
                    float(ASSIMILATION_WIND_FRONT_MIN_SPEED),
                    1e-6,
                )
            )
            wind_front_weight = float(ASSIMILATION_WIND_FRONT_WEIGHT) * float(
                np.clip(wind_ramp, 0.0, 1.0)
            )
        forecast_speed = (
            float(forecast_wind_speed)
            if forecast_wind_speed is not None and np.isfinite(forecast_wind_speed)
            else np.nan
        )
        use_advancing_only = bool(ASSIMILATION_REQUIRE_ADVANCING_EDGE and advancing.any())
        if (
            use_advancing_only and ASSIMILATION_LOW_WIND_FULL_EDGE and
            np.isfinite(forecast_speed) and
            forecast_speed < float(ASSIMILATION_ADVANCING_ONLY_MIN_WIND_MPS)
        ):
            use_advancing_only = False

        # Strong winds preserve head-fire inertia; weak winds let terrain/fuel
        # re-rank the full outer perimeter so side-slope growth is not suppressed.
        if use_advancing_only:
            candidates = advancing
            candidate_mode = "advancing_edge"
        else:
            candidates = edge
            candidate_mode = (
                "full_edge_low_wind"
                if np.isfinite(forecast_speed) and
                forecast_speed < float(ASSIMILATION_ADVANCING_ONLY_MIN_WIND_MPS)
                else "full_edge"
            )
        stats["candidate_cells"] = int(candidates.sum())
        stats["candidate_mode"] = candidate_mode
        stats["terrain_dominance"] = terrain_dominance
        stats["raw_terrain_dominance"] = raw_terrain_dominance
        stats["wind_front_weight"] = wind_front_weight
        if not candidates.any():
            stats["active_cells"] = 0
            return candidates, stats

        advance_score = _robust_unit_scale(advance_distance, candidates)
        terrain_opportunity = _front_terrain_fuel_score(
            observed, active_fuel, elev
        )
        terrain_score = _robust_unit_scale(
            terrain_opportunity, candidates
        )
        base_score = (
            (1.0 - terrain_dominance) * advance_score +
            terrain_dominance * terrain_score
        )
        selection_score = base_score
        momentum_selection_weight = 0.0
        if FRONT_MOMENTUM_MODEL and previous.any():
            low_wind_share = (
                float(low_wind_terrain_weight(forecast_speed))
                if np.isfinite(forecast_speed) else 0.0
            )
            momentum_selection_weight = float(
                ASSIMILATION_MOMENTUM_SELECTION_WEIGHT * low_wind_share *
                np.clip(momentum_memory, 0.0, 1.0)
            )
            selection_score = (
                (1.0 - momentum_selection_weight) * selection_score +
                momentum_selection_weight * advance_score
            )
        stats["momentum_selection_weight"] = momentum_selection_weight
        recessed_front_weight = 0.0
        if (
            np.isfinite(forecast_speed) and
            forecast_speed < float(LOW_WIND_THRESHOLD) and previous.any()
        ):
            pr, pc = np.where(previous)
            center_r = float(np.mean(pr))
            center_c = float(np.mean(pc))
            rr_grid, cc_grid = np.indices(observed.shape, dtype="float32")
            radius = np.hypot(rr_grid - center_r, cc_grid - center_c)
            recessed_score = 1.0 - _robust_unit_scale(radius, candidates)
            recessed_front_weight = float(
                ASSIMILATION_LOW_WIND_RECESSED_FRONT_WEIGHT *
                low_wind_terrain_weight(forecast_speed)
            )
            selection_score = (
                (1.0 - recessed_front_weight) * selection_score +
                recessed_front_weight * recessed_score
            )
        stats["recessed_front_weight"] = recessed_front_weight
        if wind_front_weight > 0.0:
            rr, cc = np.where(candidates)
            if previous.any():
                pr, pc = np.where(previous)
            else:
                pr, pc = np.where(observed)
            center_r = float(np.mean(pr)) if pr.size else float(np.mean(rr))
            center_c = float(np.mean(pc)) if pc.size else float(np.mean(cc))
            outward_bearing = (
                np.degrees(np.arctan2(cc.astype(float) - center_c,
                                      -(rr.astype(float) - center_r))) + 360.0
            ) % 360.0
            alignment = 0.5 * (
                np.cos(np.radians(outward_bearing - float(forecast_wind_toward_deg))) +
                1.0
            )
            wind_score = np.zeros_like(base_score, dtype="float32")
            wind_score[rr, cc] = alignment.astype("float32")
            selection_score = (
                (1.0 - wind_front_weight) * selection_score +
                wind_front_weight * wind_score
            )
        feedback_front_weight = 0.0
        if observation_feedback is not None:
            feedback = np.asarray(observation_feedback, dtype="float32")
            if feedback.shape == observed.shape and np.any(np.abs(feedback[candidates]) > 1e-6):
                feedback_strength = float(np.clip(
                    np.nanmax(np.abs(feedback[candidates])), 0.0, 1.0
                ))
                feedback_front_weight = float(
                    ASSIMILATION_FEEDBACK_FRONT_WEIGHT * feedback_strength
                )
                feedback_score = 0.5 * (np.clip(feedback, -1.0, 1.0) + 1.0)
                selection_score = (
                    (1.0 - feedback_front_weight) * selection_score +
                    feedback_front_weight * feedback_score
                )
        stats["feedback_front_weight"] = feedback_front_weight
        pre_ml_selection_score = selection_score.copy()
        ml_activity_weight = 0.0
        if learned_activity_field is not None:
            learned_activity = np.asarray(
                learned_activity_field, dtype="float32"
            )
            if (
                learned_activity.shape == observed.shape
                and np.any(np.isfinite(learned_activity[candidates]))
            ):
                learned_score = _robust_unit_scale(
                    learned_activity, candidates
                )
                ml_activity_weight = float(np.clip(
                    ML_ACTIVE_FRONT_WEIGHT
                    if learned_activity_weight is None
                    else learned_activity_weight,
                    0.0,
                    1.0,
                ))
                if candidate_mode == "full_edge_low_wind":
                    # When almost the whole edge advanced recently, the
                    # observed progression already identifies active arcs.
                    # Learned ranking becomes useful as the dormant share
                    # grows and the next calm window can reactivate old flanks.
                    stationary_share = 1.0 - (
                        float(np.count_nonzero(advancing))
                        / max(float(np.count_nonzero(edge)), 1.0)
                    )
                    ml_activity_weight *= float(np.clip(
                        stationary_share, 0.0, 1.0
                    ))
                selection_score = (
                    (1.0 - ml_activity_weight) * selection_score
                    + ml_activity_weight * learned_score
                )
        stats["ml_activity_weight"] = ml_activity_weight
        # Dormant arcs must be allowed to reactivate when the next weather
        # regime changes. Preserve the causal terrain/wind score before BCAF
        # history is applied, then use it only for the small reserve front.
        reactivation_score = selection_score.copy()
        bcaf_activity_weight = 0.0
        if causal_activity_field is not None:
            activity = np.asarray(causal_activity_field, dtype="float32")
            if activity.shape == observed.shape:
                activity_score = _robust_unit_scale(activity, candidates)
                bcaf_activity_weight = float(np.clip(
                    BCAF_FRONT_ACTIVITY_WEIGHT, 0.0, 1.0
                ))
                selection_score = (
                    (1.0 - bcaf_activity_weight) * selection_score
                    + bcaf_activity_weight * activity_score
                )
        bcaf_barrier_penalty = 0.0
        if causal_barrier_field is not None:
            barrier_factor = np.asarray(causal_barrier_field, dtype="float32")
            if barrier_factor.shape == observed.shape:
                barrier_strength = np.clip(1.0 - barrier_factor, 0.0, 1.0)
                if np.any(barrier_strength[edge] > 1e-6):
                    bcaf_barrier_penalty = float(max(
                        BCAF_FRONT_BARRIER_PENALTY, 0.0
                    ))
                    selection_score = (
                        selection_score
                        - bcaf_barrier_penalty * barrier_strength
                    )
        stats["bcaf_activity_weight"] = bcaf_activity_weight
        stats["bcaf_barrier_penalty"] = bcaf_barrier_penalty
        minimum = min(
            max(1, int(ASSIMILATION_ACTIVE_FRONT_MIN_CELLS)),
            int(candidates.sum()),
        )
        stratified_front = bool(
            ASSIMILATION_STRATIFIED_FRONT_SELECTION and
            np.isfinite(forecast_speed) and
            forecast_speed < float(ASSIMILATION_STRATIFIED_FRONT_MAX_WIND_MPS)
        )
        preserve_ml_sector_mass = bool(
            ML_ACTIVE_FRONT_PRESERVE_SECTOR_MASS
            and ml_activity_weight > 1e-9
            and causal_activity_field is None
            and causal_barrier_field is None
        )
        if preserve_ml_sector_mass:
            center_points = np.argwhere(
                previous if previous.any() else observed
            )
            origin = (
                float(center_points[:, 0].mean()),
                float(center_points[:, 1].mean()),
            )
            leading, threshold, changed = (
                _select_sector_preserving_front_cells(
                    pre_ml_selection_score,
                    selection_score,
                    candidates,
                    ASSIMILATION_ACTIVE_FRONT_QUANTILE,
                    minimum,
                    origin,
                )
            )
            stats["ml_sector_mass_preserved"] = True
            stats["ml_reranked_cells"] = int(changed)
        elif stratified_front:
            center_points = np.argwhere(previous if previous.any() else observed)
            origin = (
                float(center_points[:, 0].mean()),
                float(center_points[:, 1].mean()),
            )
            leading, threshold = _select_stratified_front_cells(
                selection_score,
                candidates,
                ASSIMILATION_ACTIVE_FRONT_QUANTILE,
                minimum,
                origin,
            )
        else:
            leading, threshold = _select_ranked_front_cells(
                selection_score,
                candidates,
                ASSIMILATION_ACTIVE_FRONT_QUANTILE,
                minimum,
            )
        stats["stratified_front_used"] = stratified_front
        reserve_front = np.zeros_like(leading)
        if candidate_mode == "full_edge_low_wind":
            # These cells are not extra burning time; they are dormant
            # observed arcs selected as uncertain active sources.
            reserve_front = leading & edge & ~advancing
            reserve_cap = max(
                0, int(ASSIMILATION_LOW_WIND_RESERVE_FRONT_MAX_CELLS)
            )
            reserve_count = int(np.count_nonzero(reserve_front))
            if reserve_cap and reserve_count > reserve_cap:
                reserve_flat = np.flatnonzero(reserve_front.ravel())
                reserve_values = np.nan_to_num(
                    selection_score.ravel()[reserve_flat],
                    nan=-np.inf,
                    posinf=1.0,
                    neginf=-np.inf,
                )
                order = np.argsort(-reserve_values, kind="mergesort")
                capped_flat = reserve_flat[order[:reserve_cap]]
                capped = np.zeros(reserve_front.size, dtype=bool)
                capped[capped_flat] = True
                capped = capped.reshape(reserve_front.shape)
                leading &= ~reserve_front
                leading |= capped
                reserve_front = capped
            stats["bcaf_reactivation_reserve_used"] = bool(
                reserve_front.any()
                and BCAF_REACTIVATION_RESERVE
                and causal_activity_field is not None
            )
        if (
            candidate_mode == "advancing_edge" and
            np.isfinite(forecast_speed) and
            forecast_speed < float(ASSIMILATION_ADVANCING_ONLY_MIN_WIND_MPS)
        ):
            stationary = edge & ~candidates
            memory_cutoff = max(
                float(ASSIMILATION_LOW_WIND_RESERVE_MEMORY_CUTOFF), 1e-6
            )
            collapse_strength = float(np.clip(
                (
                    memory_cutoff
                    - float(np.clip(momentum_memory, 0.0, 1.0))
                ) / memory_cutoff,
                0.0,
                1.0,
            ))
            reserve_fraction = float(
                ASSIMILATION_LOW_WIND_RESERVE_FRONT_FRACTION
            )
            if REGIME_REACTIVATION_RESERVE:
                reserve_fraction = float(np.clip(
                    reserve_fraction
                    + float(ASSIMILATION_LOW_WIND_RESERVE_REGIME_GAIN)
                    * collapse_strength
                    * float(low_wind_terrain_weight(forecast_speed)),
                    0.0,
                    0.25,
                ))
            stats["reserve_front_fraction"] = reserve_fraction
            reserve_count = min(
                int(stationary.sum()),
                int(ASSIMILATION_LOW_WIND_RESERVE_FRONT_MAX_CELLS),
                int(math.ceil(
                    reserve_fraction *
                    float(edge.sum())
                )),
            )
            if reserve_count > 0:
                if (
                    BCAF_REACTIVATION_RESERVE
                    and causal_activity_field is not None
                ):
                    reserve_score = reactivation_score
                    reserve_score_mode = "causal_reactivation"
                elif not REGIME_REACTIVATION_RESERVE:
                    reserve_score = selection_score
                    reserve_score_mode = "legacy_causal_score"
                elif (
                    observation_feedback is not None
                    and feedback_front_weight > 1e-9
                ):
                    reserve_score = selection_score
                    reserve_score_mode = "causal_error_feedback"
                else:
                    # ``selection_score`` was normalized only on advancing
                    # candidates, so it is zero on the dormant edge. Re-scale
                    # the physical terrain/fuel opportunity on the stationary
                    # cells themselves before selecting a small reserve.
                    reserve_score = _robust_unit_scale(
                        terrain_opportunity, stationary
                    )
                    reserve_score_mode = "stationary_terrain_fuel"
                stats["reserve_score_mode"] = reserve_score_mode
                stats["bcaf_reactivation_reserve_used"] = bool(
                    reserve_score_mode == "causal_reactivation"
                )
                reserve_quantile = float(np.clip(
                    1.0 - reserve_count / max(float(stationary.sum()), 1.0),
                    0.0,
                    1.0,
                ))
                if stratified_front:
                    reserve_front, _ = _select_stratified_front_cells(
                        reserve_score,
                        stationary,
                        reserve_quantile,
                        reserve_count,
                        origin,
                        sector_count=ASSIMILATION_STRATIFIED_FRONT_SECTORS,
                        arc_weight=0.70,
                    )
                else:
                    reserve_front, _ = _select_ranked_front_cells(
                        reserve_score,
                        stationary,
                        reserve_quantile,
                        reserve_count,
                    )
                leading |= reserve_front
        stats["reserve_front_cells"] = int(reserve_front.sum())
        buffer_cells = max(0, int(ASSIMILATION_ACTIVE_FRONT_BUFFER_CELLS))
        if candidate_mode == "full_edge_low_wind":
            buffer_cells = 0
        if buffer_cells:
            main_front = leading & candidates
            main_front = ndimage.binary_dilation(
                main_front, iterations=buffer_cells
            ) & candidates
            leading = main_front | reserve_front

        if ML_ACTIVE_FRONT_FIXED_BUDGET and ml_activity_weight > 1e-9:
            if stratified_front:
                budget_main, _ = _select_stratified_front_cells(
                    pre_ml_selection_score,
                    candidates,
                    ASSIMILATION_ACTIVE_FRONT_QUANTILE,
                    minimum,
                    origin,
                )
            else:
                budget_main, _ = _select_ranked_front_cells(
                    pre_ml_selection_score,
                    candidates,
                    ASSIMILATION_ACTIVE_FRONT_QUANTILE,
                    minimum,
                )
            if buffer_cells:
                budget_main = ndimage.binary_dilation(
                    budget_main, iterations=buffer_cells
                ) & candidates
            if candidate_mode == "full_edge_low_wind":
                fixed_budget = int(budget_main.sum())
            else:
                fixed_budget = int(
                    budget_main.sum() + reserve_front.sum()
                )
            fixed_budget = min(
                max(fixed_budget, 1),
                int(np.count_nonzero(candidates | reserve_front)),
            )
            current_count = int(leading.sum())
            if current_count > fixed_budget:
                mandatory = reserve_front & leading
                mandatory_flat = np.flatnonzero(mandatory.ravel())
                slots = max(fixed_budget - len(mandatory_flat), 0)
                optional_flat = np.flatnonzero(
                    (leading & ~mandatory).ravel()
                )
                optional_score = np.nan_to_num(
                    selection_score.ravel()[optional_flat],
                    nan=-np.inf,
                )
                keep_optional = optional_flat[
                    np.argsort(
                        -optional_score, kind="mergesort"
                    )[:slots]
                ]
                fixed = np.zeros(leading.size, dtype=bool)
                fixed[mandatory_flat[:fixed_budget]] = True
                fixed[keep_optional] = True
                leading = fixed.reshape(leading.shape)
            elif current_count < fixed_budget:
                missing = fixed_budget - current_count
                available_flat = np.flatnonzero(
                    ((candidates | reserve_front) & ~leading).ravel()
                )
                available_score = np.nan_to_num(
                    selection_score.ravel()[available_flat],
                    nan=-np.inf,
                )
                add = available_flat[
                    np.argsort(
                        -available_score, kind="mergesort"
                    )[:missing]
                ]
                leading.ravel()[add] = True
            stats["ml_fixed_budget_applied"] = True
            stats["ml_fixed_budget_cells"] = fixed_budget

        stats.update({
            "active_cells": int(leading.sum()),
            "advance_threshold_cells": float(threshold),
        })
        return leading, stats
    except Exception:
        advancing = edge & ~previous
        candidates = advancing if advancing.any() else edge
        fallback_score = np.zeros(edge.shape, dtype="float32")
        try:
            if "advance_distance" in locals():
                fallback_score = _robust_unit_scale(advance_distance, candidates)
        except Exception:
            pass
        minimum = min(
            max(1, int(ASSIMILATION_ACTIVE_FRONT_MIN_CELLS)),
            int(candidates.sum()),
        )
        leading, threshold = _select_ranked_front_cells(
            fallback_score,
            candidates,
            ASSIMILATION_ACTIVE_FRONT_QUANTILE,
            minimum,
        )
        stats.update({
            "candidate_cells": int(candidates.sum()),
            "active_cells": int(leading.sum()),
            "advance_threshold_cells": float(threshold),
            "candidate_mode": "fallback_ranked_front",
        })
        return leading, stats


def reconstruct_reference_arrival_times(observed, previous_observed, prior_arrival,
                                        previous_elapsed_h, elapsed_h,
                                        active_fuel=None, elev=None,
                                        forecast_wind_speed=None,
                                        forecast_wind_toward_deg=None,
                                        reference_geometry=None,
                                        previous_reference_geometry=None,
                                        model_arrival_weight=None,
                                        terrain_weight_cap=None,
                                        front_feedback=None,
                                        causal_activity_field=None,
                                        causal_barrier_field=None,
                                        learned_activity_field=None,
                                        learned_activity_weight=None,
                                        momentum_memory=1.0):
    """Interpolate fire-arrival time between two observed cumulative perimeters."""
    observed = np.asarray(observed, dtype=bool)
    previous = np.zeros_like(observed) if previous_observed is None else (
        np.asarray(previous_observed, dtype=bool) & observed
    )
    geometry = observed if reference_geometry is None else np.asarray(
        reference_geometry, dtype=bool
    )
    previous_geometry = previous if previous_reference_geometry is None else (
        np.asarray(previous_reference_geometry, dtype=bool) & geometry
    )
    reconstructed = np.full(observed.shape, np.nan, dtype="float32")
    start_h = float(previous_elapsed_h) if previous_elapsed_h is not None else 0.0
    end_h = float(elapsed_h)
    duration_h = max(end_h - start_h, MIN_PER_STEP / 60.0)

    if previous.any():
        old_valid = previous & np.isfinite(prior_arrival)
        reconstructed[old_valid] = np.minimum(prior_arrival[old_valid], start_h)
        reconstructed[previous & ~old_valid] = start_h
    new_region = observed & ~previous
    if not new_region.any():
        reconstructed[observed & ~np.isfinite(reconstructed)] = end_h
        return reconstructed

    try:
        from scipy import ndimage
        if previous_geometry.any():
            distance_from_previous = ndimage.distance_transform_edt(~previous_geometry)
        else:
            seeds = np.isfinite(prior_arrival) & observed
            distance_from_previous = ndimage.distance_transform_edt(~seeds) if seeds.any() else np.ones(observed.shape)
        distance_to_outer = ndimage.distance_transform_edt(geometry)
        geometric_fraction = distance_from_previous / np.maximum(
            distance_from_previous + distance_to_outer, 1e-6
        )
    except Exception:
        geometric_fraction = np.full(observed.shape, 0.5, dtype="float32")

    fraction = np.clip(geometric_fraction, 0.0, 1.0).astype("float32")
    model_valid = new_region & np.isfinite(prior_arrival)
    if model_valid.any():
        values = np.asarray(prior_arrival[model_valid], dtype=float)
        lo, hi = np.nanpercentile(values, [5, 95]) if values.size > 4 else (
            float(np.nanmin(values)), float(np.nanmax(values))
        )
        if hi > lo + 1e-6:
            model_fraction = np.clip((prior_arrival - lo) / (hi - lo), 0.0, 1.0)
            weight = float(np.clip(
                ASSIMILATION_MODEL_ARRIVAL_WEIGHT
                if model_arrival_weight is None else model_arrival_weight,
                0.0,
                1.0,
            ))
            fraction[model_valid] = (
                weight * model_fraction[model_valid] +
                (1.0 - weight) * fraction[model_valid]
            )
    reconstructed[new_region] = start_h + duration_h * fraction[new_region]

    geometry_edge = outer_perimeter_mask(geometry) & geometry
    edge = geometry_edge & observed
    advancing_edge, _ = select_reference_active_front(
        observed, previous, edge=edge,
        active_fuel=active_fuel, elev=elev,
        forecast_wind_speed=forecast_wind_speed,
        forecast_wind_toward_deg=forecast_wind_toward_deg,
        terrain_weight_cap=terrain_weight_cap,
        observation_feedback=front_feedback,
        causal_activity_field=causal_activity_field,
        causal_barrier_field=causal_barrier_field,
        learned_activity_field=learned_activity_field,
        learned_activity_weight=learned_activity_weight,
        momentum_memory=momentum_memory,
    )
    reconstructed[advancing_edge] = end_h
    reconstructed[observed] = np.clip(reconstructed[observed], 0.0, end_h)
    return reconstructed


def reset_state_to_reference_perimeter(state, burn_clock, arrival, ref_mask, active_fuel,
                                       elev, elapsed_h, spread_accum=None,
                                       directional_progress=None,
                                       previous_ref_mask=None, previous_elapsed_h=None,
                                       return_front_stats=False,
                                       forecast_wind_speed=None,
                                       forecast_wind_toward_deg=None,
                                       burn_duration_steps=None,
                                       model_arrival_weight=None,
                                       terrain_weight_cap=None,
                                       front_feedback=None,
                                       causal_activity_field=None,
                                       causal_barrier_field=None,
                                       learned_activity_field=None,
                                       learned_activity_weight=None,
                                       momentum_memory=1.0):
    """Assimilate an observed perimeter while preserving reconstructed fire age."""
    burnable = np.isfinite(elev) & (active_fuel > 0.02)
    reference_geometry = np.asarray(ref_mask, dtype=bool) & np.isfinite(elev)
    observed = reference_geometry & burnable
    previous_reference_geometry = (
        None if previous_ref_mask is None else
        np.asarray(previous_ref_mask, dtype=bool) & np.isfinite(elev)
    )
    prior_arrival = arrival.copy()
    state[:, :] = np.where(burnable, UNBURNED, NONFUEL).astype(np.int8)
    burn_clock[:, :] = 0
    arrival[:, :] = np.nan
    if not observed.any():
        if spread_accum is not None:
            spread_accum[:, :] = 0.0
        if directional_progress is not None:
            directional_progress[:, :, :] = 0.0
        empty_stats = {
            "candidate_cells": 0,
            "active_cells": 0,
            "observed_edge_cells": 0,
            "advance_threshold_cells": 0.0,
        }
        empty = np.zeros(state.shape, dtype=bool)
        return (empty, empty_stats) if return_front_stats else empty

    geometry_edge = outer_perimeter_mask(reference_geometry) & reference_geometry
    edge = geometry_edge & observed
    local_duration = (
        np.full(observed.shape, BURN_STEPS, dtype="int16")
        if burn_duration_steps is None else
        np.asarray(burn_duration_steps, dtype="int16")
    )
    if ARRIVAL_TIME_ASSIMILATION:
        reconstructed = reconstruct_reference_arrival_times(
            observed, previous_ref_mask, prior_arrival,
            previous_elapsed_h, elapsed_h,
            active_fuel=active_fuel, elev=elev,
            forecast_wind_speed=forecast_wind_speed,
            forecast_wind_toward_deg=forecast_wind_toward_deg,
            reference_geometry=reference_geometry,
            previous_reference_geometry=previous_reference_geometry,
            model_arrival_weight=model_arrival_weight,
            terrain_weight_cap=terrain_weight_cap,
            front_feedback=front_feedback,
            causal_activity_field=causal_activity_field,
            causal_barrier_field=causal_barrier_field,
            learned_activity_field=learned_activity_field,
            learned_activity_weight=learned_activity_weight,
            momentum_memory=momentum_memory,
        )
        arrival[observed] = reconstructed[observed]
        age_steps = local_duration.astype("int32").copy()
        age_steps[observed] = np.floor(
            np.maximum(float(elapsed_h) - reconstructed[observed], 0.0) *
            60.0 / MIN_PER_STEP
        ).astype("int32")
        previous = np.zeros_like(observed) if previous_ref_mask is None else (
            np.asarray(previous_ref_mask, dtype=bool) & observed
        )
        advancing_edge, front_stats = select_reference_active_front(
            observed, previous, edge=edge,
            active_fuel=active_fuel, elev=elev,
            forecast_wind_speed=forecast_wind_speed,
            forecast_wind_toward_deg=forecast_wind_toward_deg,
            terrain_weight_cap=terrain_weight_cap,
            observation_feedback=front_feedback,
            causal_activity_field=causal_activity_field,
            causal_barrier_field=causal_barrier_field,
            learned_activity_field=learned_activity_field,
            learned_activity_weight=learned_activity_weight,
            momentum_memory=momentum_memory,
        )
        recent = age_steps < local_duration
        active_edge = edge & advancing_edge & recent
        recent_edge = edge & recent
        if not active_edge.any() and recent_edge.any():
            edge_arrival = np.where(recent_edge, reconstructed, -np.inf)
            active_edge = recent_edge & (
                edge_arrival >= np.nanmax(edge_arrival) - MIN_PER_STEP / 60.0
            )
        secondary_steps = max(0, min(int(ASSIMILATION_SECONDARY_FRONT_STEPS), BURN_STEPS))
        secondary_edge = np.zeros_like(edge)
        if previous.any() and secondary_steps:
            secondary_edge = edge & ~active_edge
        state[observed] = BURNED
        state[secondary_edge] = BURNING
        state[active_edge] = BURNING
        burn_clock[observed] = local_duration[observed]
        burn_clock[secondary_edge] = np.maximum(
            local_duration[secondary_edge] - secondary_steps, 0
        )
        persistence_steps = max(0, int(ASSIMILATION_FRONT_PERSISTENCE_STEPS))
        # Persistence is zero by default: reconstructed age and the local
        # vegetation/canopy residence time alone determine whether a front lives.
        burn_clock[active_edge] = np.clip(
            age_steps[active_edge] - persistence_steps,
            -persistence_steps,
            local_duration[active_edge] - 1,
        )
        front_stats["secondary_cells"] = int(secondary_edge.sum())
        print(
            "  arrival-time assimilation: "
            f"{int(active_edge.sum())} active front cells / "
            f"{int(edge.sum())} observed edge cells "
            f"({front_stats['candidate_cells']} advancing candidates, "
            f"{front_stats.get('reserve_front_cells', 0)} reserve cells, "
            f"{front_stats.get('secondary_cells', 0)} secondary cells "
            f"x {max(0, int(ASSIMILATION_SECONDARY_FRONT_STEPS))} step(s), "
            f"terrain weight={front_stats.get('terrain_dominance', 0.0):.2f}, "
            f"recessed weight={front_stats.get('recessed_front_weight', 0.0):.2f}, "
            f"feedback weight={front_stats.get('feedback_front_weight', 0.0):.2f}, "
            f"BCAF activity={front_stats.get('bcaf_activity_weight', 0.0):.2f}, "
            f"ML activity={front_stats.get('ml_activity_weight', 0.0):.2f}, "
            f"reserve score={front_stats.get('reserve_score_mode', 'none')}, "
            f"BCAF barrier={front_stats.get('bcaf_barrier_penalty', 0.0):.2f}, "
            f"score threshold={front_stats['advance_threshold_cells']:.2f})"
        )
    else:
        interior = observed & ~edge
        state[interior] = BURNED
        state[edge] = BURNING
        burn_clock[interior] = local_duration[interior]
        burn_clock[edge] = 0
        arrival[observed] = float(elapsed_h)
        front_stats = {
            "candidate_cells": int(edge.sum()),
            "active_cells": int(edge.sum()),
            "secondary_cells": 0,
            "advance_threshold_cells": 0.0,
        }
    if spread_accum is not None:
        spread_accum[:, :] = 0.0
    if directional_progress is not None:
        directional_progress[:, :, :] = 0.0
    front_stats["observed_edge_cells"] = int(edge.sum())
    return (observed, front_stats) if return_front_stats else observed


