def _component_rows(mask, min_area_ha=HOLE_DIAGNOSTIC_MIN_AREA_HA):
    try:
        from scipy import ndimage
    except Exception:
        return []
    labels, nlab = ndimage.label(np.asarray(mask, dtype=bool),
                                 structure=np.ones((3, 3), dtype=np.uint8))
    rows = []
    cell_ha = TARGET_RES ** 2 / 1e4
    for lab in range(1, int(nlab) + 1):
        comp = labels == lab
        area_ha = float(comp.sum()) * cell_ha
        if area_ha < min_area_ha:
            continue
        rr, cc = np.where(comp)
        rows.append({
            "label": lab,
            "mask": comp,
            "area_ha": area_ha,
            "centroid_row": float(rr.mean()) if rr.size else np.nan,
            "centroid_col": float(cc.mean()) if cc.size else np.nan,
        })
    rows.sort(key=lambda r: r["area_ha"], reverse=True)
    return rows


def _classify_unburned_patch(row):
    if row.get("nodata_frac", 0.0) >= 0.35:
        return "nodata_or_water"
    if row.get("firebreak_frac", 0.0) >= 0.20:
        return "control_firebreak"
    if row.get("nonfuel_frac", 0.0) >= 0.50 or row.get("mean_fuel", 1.0) <= 0.08:
        return "nonfuel_or_water_low_fuel"
    if row.get("building_frac", 0.0) >= 0.45:
        return "building_or_urban_wui"
    if row.get("mean_percolation", 1.0) <= 0.25:
        return "low_fuel_connectivity"
    if row.get("p90_slope_deg", 0.0) >= 34.0 and row.get("mean_fuel", 0.0) > 0.20:
        return "steep_terrain_barrier"
    if row.get("mean_slope_deg", 0.0) >= 24.0 and row.get("mean_percolation", 1.0) <= 0.55:
        return "terrain_and_connectivity"
    return "stochastic_or_insufficient_time"


def diagnose_final_unburned_holes(elev, fuel, arrival, ign, real_mask, out_dir,
                                  is_building=None, firebreak_mask=None,
                                  percolation_factor=None, title="Final Unburned Hole Diagnostics"):
    """Diagnose unburned islands inside the simulated and observed final perimeters."""
    try:
        from scipy import ndimage
    except Exception as exc:
        print(f"skip final hole diagnostics: scipy unavailable ({exc})")
        return []
    import csv
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches

    burned = np.isfinite(arrival)
    if not burned.any():
        return []
    if percolation_factor is None:
        percolation_factor, _ = build_percolation_layers(fuel, is_building)
    if percolation_factor is None:
        percolation_factor = np.zeros(elev.shape, dtype="float32")
    if firebreak_mask is None:
        firebreak_mask = np.zeros(elev.shape, dtype=bool)
    if is_building is None:
        is_building = np.zeros(elev.shape, dtype=bool)

    valid = np.isfinite(elev)
    nonfuel = (~valid) | (fuel <= 0.02)
    grow, gcol = np.gradient(np.nan_to_num(elev, nan=float(np.nanmedian(elev[valid])) if valid.any() else 0.0))
    slope_deg = np.degrees(np.arctan(np.hypot(grow, gcol) / TARGET_RES)).astype("float32")
    dist_to_burned = ndimage.distance_transform_edt(~burned) * TARGET_RES

    filled_burned = ndimage.binary_fill_holes(burned)
    sim_internal_holes = filled_burned & ~burned
    ref_unburned = (np.asarray(real_mask, dtype=bool) & ~burned) if real_mask is not None else np.zeros_like(burned)

    patch_specs = [
        ("sim_internal_hole", sim_internal_holes),
        ("reference_unburned_patch", ref_unburned),
    ]
    rows = []
    for patch_type, mask in patch_specs:
        for comp in _component_rows(mask, HOLE_DIAGNOSTIC_MIN_AREA_HA):
            m = comp["mask"]
            vals = {
                "patch_type": patch_type,
                "component_id": int(comp["label"]),
                "area_ha": comp["area_ha"],
                "centroid_row": comp["centroid_row"],
                "centroid_col": comp["centroid_col"],
                "mean_fuel": float(np.nanmean(fuel[m])) if np.any(m) else np.nan,
                "p10_fuel": float(np.nanpercentile(fuel[m], 10)) if np.any(m) else np.nan,
                "nonfuel_frac": float(np.count_nonzero(nonfuel[m]) / max(int(m.sum()), 1)),
                "nodata_frac": float(np.count_nonzero(~valid[m]) / max(int(m.sum()), 1)),
                "building_frac": float(np.count_nonzero(is_building[m]) / max(int(m.sum()), 1)),
                "firebreak_frac": float(np.count_nonzero(firebreak_mask[m]) / max(int(m.sum()), 1)),
                "mean_slope_deg": float(np.nanmean(slope_deg[m])) if np.any(m) else np.nan,
                "p90_slope_deg": float(np.nanpercentile(slope_deg[m], 90)) if np.any(m) else np.nan,
                "mean_percolation": float(np.nanmean(percolation_factor[m])) if np.any(m) else np.nan,
                "p10_percolation": float(np.nanpercentile(percolation_factor[m], 10)) if np.any(m) else np.nan,
                "mean_distance_to_burned_m": float(np.nanmean(dist_to_burned[m])) if np.any(m) else np.nan,
                "max_distance_to_burned_m": float(np.nanmax(dist_to_burned[m])) if np.any(m) else np.nan,
            }
            vals["likely_reason"] = _classify_unburned_patch(vals)
            rows.append(vals)

    rows.sort(key=lambda r: (r["patch_type"], -r["area_ha"]))
    rows = rows[:HOLE_DIAGNOSTIC_MAX_PATCHES]
    os.makedirs(out_dir, exist_ok=True)
    out_csv = os.path.join(out_dir, "final_unburned_hole_diagnostics.csv")
    out_summary_csv = os.path.join(out_dir, "final_unburned_hole_reason_summary.csv")
    fields = [
        "patch_type", "component_id", "likely_reason", "area_ha",
        "centroid_row", "centroid_col", "mean_fuel", "p10_fuel",
        "nonfuel_frac", "nodata_frac", "building_frac", "firebreak_frac",
        "mean_slope_deg", "p90_slope_deg", "mean_percolation", "p10_percolation",
        "mean_distance_to_burned_m", "max_distance_to_burned_m",
    ]
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for row in rows:
            writer.writerow({k: row.get(k, "") for k in fields})

    summary_rows = []
    for reason in sorted({row["likely_reason"] for row in rows}):
        subset = [row for row in rows if row["likely_reason"] == reason]
        area = np.asarray([row["area_ha"] for row in subset], dtype=float)
        weights = np.maximum(area, 1e-9)
        summary_rows.append({
            "likely_reason": reason,
            "patch_count": len(subset),
            "total_area_ha": float(area.sum()) if area.size else 0.0,
            "mean_patch_area_ha": float(area.mean()) if area.size else 0.0,
            "area_weighted_mean_fuel": float(np.average(
                [row["mean_fuel"] for row in subset], weights=weights)) if area.size else np.nan,
            "area_weighted_mean_slope_deg": float(np.average(
                [row["mean_slope_deg"] for row in subset], weights=weights)) if area.size else np.nan,
            "area_weighted_mean_percolation": float(np.average(
                [row["mean_percolation"] for row in subset], weights=weights)) if area.size else np.nan,
            "area_weighted_nonfuel_frac": float(np.average(
                [row["nonfuel_frac"] for row in subset], weights=weights)) if area.size else np.nan,
        })
    summary_rows.sort(key=lambda row: row["total_area_ha"], reverse=True)
    with open(out_summary_csv, "w", newline="", encoding="utf-8") as f:
        summary_fields = [
            "likely_reason", "patch_count", "total_area_ha", "mean_patch_area_ha",
            "area_weighted_mean_fuel", "area_weighted_mean_slope_deg",
            "area_weighted_mean_percolation", "area_weighted_nonfuel_frac",
        ]
        writer = csv.DictWriter(f, fieldnames=summary_fields)
        writer.writeheader()
        for row in summary_rows:
            writer.writerow(row)

    crop_masks = [burned, real_mask, sim_internal_holes, ref_unburned]
    sl = crop_for_daily(elev.shape, crop_masks, ign, pad=66)
    reason_colors = {
        "nodata_or_water": "#2b83ba",
        "control_firebreak": "#00d5ff",
        "nonfuel_or_water_low_fuel": "#ffff8c",
        "building_or_urban_wui": "#fdae61",
        "low_fuel_connectivity": "#66bd63",
        "steep_terrain_barrier": "#d7191c",
        "terrain_and_connectivity": "#abdda4",
        "stochastic_or_insufficient_time": "#984ea3",
    }
    reason_map = np.zeros(elev.shape, dtype=np.int16)
    reasons = list(reason_colors)
    label_maps = {}
    structure = np.ones((3, 3), dtype=np.uint8)
    for patch_type, base_mask in patch_specs:
        label_maps[patch_type], _ = ndimage.label(base_mask, structure=structure)
    for idx, reason in enumerate(reasons, start=1):
        for row in rows:
            if row["likely_reason"] != reason:
                continue
            labels = label_maps.get(row["patch_type"])
            if labels is not None:
                reason_map[labels == int(row["component_id"])] = idx

    fig, axes = plt.subplots(1, 2, figsize=(15.5, 7.8), facecolor="#111111")
    for ax in axes:
        ax.imshow(_dark_hillshade(elev[sl]), interpolation="bilinear")
        ax.axis("off")

    axes[0].imshow(_mask_rgba(burned[sl], "#b2182b", 0.62), interpolation="nearest")
    axes[0].imshow(_mask_rgba(sim_internal_holes[sl], "#ffe34d", 0.92), interpolation="nearest")
    axes[0].contour(burned[sl].astype(float), levels=[0.5], colors="#ffffff", linewidths=1.5)
    _draw_final_perimeter(axes[0], real_mask[sl] if real_mask is not None else None,
                          linewidth=1.6, linestyle="--", alpha=0.9)
    axes[0].plot(ign[1] - sl[1].start, ign[0] - sl[0].start, marker="*",
                 color="#ff2020", mec="white", ms=12)
    axes[0].set_title("Simulated Burned Area with Internal Unburned Patches",
                      color="white", fontweight="bold")

    axes[1].imshow(_mask_rgba(burned[sl], "#b2182b", 0.45), interpolation="nearest")
    for idx, reason in enumerate(reasons, start=1):
        mask = reason_map == idx
        if mask.any():
            axes[1].imshow(_mask_rgba(mask[sl], reason_colors[reason], 0.86), interpolation="nearest")
    _draw_final_perimeter(axes[1], real_mask[sl] if real_mask is not None else None,
                          linewidth=1.6, linestyle="--", alpha=0.9)
    axes[1].contour(burned[sl].astype(float), levels=[0.5], colors="#ffffff", linewidths=1.2)
    axes[1].set_title("Likely Cause Classification", color="white", fontweight="bold")
    handles = [
        mpatches.Patch(color="#b2182b", alpha=0.65, label="Simulated burned area"),
        mpatches.Patch(color="#ffe34d", label="Internal unburned patch"),
    ]
    handles.extend(
        mpatches.Patch(color=color, label=reason.replace("_", " "))
        for reason, color in reason_colors.items()
        if np.any(reason_map == reasons.index(reason) + 1)
    )
    _map_legend(axes[1], handles, loc="lower left", fontsize=7)
    _apply_lettered_bottom_caption(
        fig, axes,
        ["simulated burned area and internal unburned patches",
         "classification of likely causes"],
        title,
    )
    out_png = os.path.join(out_dir, "final_unburned_hole_diagnostics.png")
    fig.savefig(out_png, dpi=150, facecolor=fig.get_facecolor())
    plt.close(fig)

    reason_counts = {}
    for row in rows:
        reason_counts[row["likely_reason"]] = reason_counts.get(row["likely_reason"], 0) + 1
    print("Final unburned-hole diagnostics:")
    for reason, count in sorted(reason_counts.items(), key=lambda kv: (-kv[1], kv[0])):
        print(f"  {reason}: {count} patch(es)")
    print("saved", out_csv)
    print("saved", out_summary_csv)
    print("saved", out_png)
    return rows


def save_png_sequence_gif(frame_paths, out_gif, duration_ms=GIF_FRAME_DURATION_MS):
    frame_paths = [p for p in frame_paths if p and os.path.exists(p)]
    if not frame_paths:
        return False
    try:
        from PIL import Image
    except Exception as exc:
        print(f"skip gif {out_gif}: Pillow not available ({exc})")
        return False

    raw = [Image.open(p).convert("RGB") for p in frame_paths]
    max_w = max(im.width for im in raw)
    max_h = max(im.height for im in raw)
    frames = []
    for im in raw:
        canvas = Image.new("RGB", (max_w, max_h), (22, 23, 25))
        canvas.paste(im, ((max_w - im.width) // 2, (max_h - im.height) // 2))
        frames.append(canvas)
        im.close()
    os.makedirs(os.path.dirname(out_gif) or ".", exist_ok=True)
    frames[0].save(
        out_gif, save_all=True, append_images=frames[1:],
        duration=int(duration_ms), loop=0, optimize=True
    )
    print(f"saved {out_gif} ({len(frames)} frames)")
    return True


def save_control_gifs(spread_frames, control_frames):
    save_png_sequence_gif(spread_frames, CONTROL_SPREAD_GIF)
    save_png_sequence_gif(control_frames, CONTROL_ACTION_GIF)


