            "protected_value_k", "firebreak_effective_benefit_k", "firebreak_benefit_cost_ratio",
            "net_benefit_k", "avoided_by_controls_ha",
            "paired_daily_avoided_ha", "paired_daily_area_reduction_pct",
            "no_control_loss_total_k", "realized_loss_avoided_k",
            "realized_net_benefit_k", "realized_benefit_cost_ratio",
            "cost_per_avoided_ha_k", "firefighter_benefit_proxy_k",
