def plot_control_summary(records):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    days = [r["day"] for r in records]
    new_ha = [r["new_ha"] for r in records]
    no_control_ha = [r.get("no_control_new_ha", np.nan) for r in records]
    reference_ha = [r.get("daily_ref_ha", np.nan) for r in records]
    cum_ha = [r["cum_ha"] for r in records]
    loss = [r["loss_total"] for r in records]
    intervention = [r.get("control_cost_total", r["firebreak_cost"] + DAILY_SUPPRESSION_COST)
                    for r in records]

    fig, axes = plt.subplots(1, 2, figsize=(14, 5))
    x = np.asarray(days, dtype=float)
    width = 0.24
    axes[0].bar(x - width, no_control_ha, width=width, color="#e59632",
                alpha=0.88, label="Paired no-action increment")
    axes[0].bar(x, new_ha, width=width, color="#2585a6", alpha=0.90,
                label="Controlled increment")
    axes[0].bar(x + width, reference_ha, width=width, color="#b04aa8",
                alpha=0.75, label="Observed increment")
    axes[0].plot(days, cum_ha, "-o", color="#7a1f1f",
                 label="Controlled cumulative area")
    axes[0].set_xlabel("Day")
    axes[0].set_ylabel("Burned area (ha)")
    axes[0].set_title("Paired Daily Suppression Effect", fontweight="bold")
    axes[0].legend()
    axes[0].grid(alpha=0.3)

    axes[1].bar(days, loss, color="#b22222", label="Daily fire loss")
    axes[1].bar(days, intervention, bottom=loss, color="#2c7fb8",
                label="Suppression cost")
    axes[1].plot(days, np.cumsum(np.asarray(loss) + np.asarray(intervention)),
                 "-o", color="black", label="Cumulative total cost")
    axes[1].set_xlabel("Day")
    axes[1].set_ylabel("Cost ($k)")
    axes[1].set_title("Daily Fire Loss and Suppression Cost", fontweight="bold")
    axes[1].legend()
    axes[1].grid(alpha=0.3)

    _apply_lettered_bottom_caption(
        fig, axes,
        ["paired no-action, controlled and observed daily burned-area increments",
         "daily fire loss, suppression cost and cumulative total cost"],
        "Cost-Controlled CA Summary",
    )
    out = os.path.join(CONTROL_OUT_DIR, "controlled_summary.png")
    fig.savefig(out, dpi=140)
    plt.close(fig)
    print("saved", out)


def plot_directional_control_objective(records):
    """Plot interpretable diagnostics for the directional control objective."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    if not records:
        return
    days = np.asarray([r["day"] for r in records], dtype=int)
    avoided = np.asarray([
        r.get("directional_objective_expected_avoided_k", 0.0)
        for r in records
    ], dtype=float)
    tail = np.asarray([
        r.get("directional_objective_tail_escape_k", 0.0)
        for r in records
    ], dtype=float)
    net = np.asarray([
        r.get("directional_objective_net_benefit_k", 0.0)
        for r in records
    ], dtype=float)
    hold = np.asarray([
        r.get("directional_objective_mean_hold_probability", np.nan)
        for r in records
    ], dtype=float)
    bearing = np.asarray([
        r.get("directional_objective_bearing_deg", np.nan)
        for r in records
    ], dtype=float)

    fig, axes = plt.subplots(2, 1, figsize=(10.5, 8.0), sharex=True)
    width = 0.24
    axes[0].bar(days - width, avoided, width=width, color="#2585a6",
                label="Expected avoided loss")
    axes[0].bar(days, tail, width=width, color="#d99124",
                label="Escape-risk penalty")
    axes[0].bar(days + width, net, width=width, color="#3f9652",
                label="Net directional benefit")
    axes[0].axhline(0.0, color="black", linewidth=0.8)
    axes[0].set_ylabel("Objective value ($k)")
    axes[0].grid(axis="y", alpha=0.25)
    axes[0].legend(ncol=3, fontsize=9, loc="upper center")

    axes[1].plot(days, hold, "o-", color="#6f42a8", linewidth=2,
                 label="Mean probability of holding")
    axes[1].set_ylim(0.0, 1.0)
    axes[1].set_ylabel("Hold probability")
    axes[1].set_xlabel("Day")
    axes[1].set_xticks(days)
    axes[1].grid(alpha=0.25)
    bearing_axis = axes[1].twinx()
