def _angle_delta_deg(a, b):
    """Signed shortest rotation from b to a in degrees."""
    if not (np.isfinite(a) and np.isfinite(b)):
        return np.nan
    return float((a - b + 180.0) % 360.0 - 180.0)


def collect_wind_correction_diagnostics(wind):
    """Compare background, raw WindNinja, station observations and corrected wind."""
    rows = []
    sim_end = wind.t0 + np.timedelta64(int(round(N_STEPS * MIN_PER_STEP)), "m")

    def correction_inputs(t):
        background = wind._background_wind_at(t)
        station = wind._station_wind_at(t)
        bias = wind._station_bias_at(t)
        bg_speed, bg_dir = background if background is not None else (np.nan, np.nan)
        station_speed, station_dir = station if station is not None else (np.nan, np.nan)
        bias_u = np.asarray(bias["du"], dtype=float) if bias is not None else np.asarray([np.nan])
        bias_v = np.asarray(bias["dv"], dtype=float) if bias is not None else np.asarray([np.nan])
        bias_mag = np.asarray(bias["magnitude"], dtype=float) if bias is not None else np.asarray([np.nan])
        return {
            "background_speed": float(bg_speed),
            "background_dir_from": float(bg_dir),
            "station_speed": float(station_speed),
            "station_dir_from": float(station_dir),
            "bias_u_mps": float(np.nanmean(bias_u)),
            "bias_v_mps": float(np.nanmean(bias_v)),
            "bias_magnitude_mps": float(np.nanmean(bias_mag)),
            "bias_p10_mps": float(np.nanpercentile(bias_mag, 10)),
            "bias_p90_mps": float(np.nanpercentile(bias_mag, 90)),
            "station_count": int(bias.get("station_count", 0)) if bias is not None else 0,
            "correction_weight": float(STATION_CORRECTION_WEIGHT),
            "correction_method": STATION_CORRECTION_METHOD,
        }

    if wind.mode == "wn_timevarying":
        times = [t for t in wind.times if wind.t0 <= t <= sim_end]
        for i, t in enumerate(times, start=1):
            vel_path, ang_path = wind.paths[t]
            raw_speed, raw_dir = wind._clean(*wind._load_to_grid(vel_path, ang_path))
            corr_speed, corr_dir = wind._apply_asos_temporal_correction(raw_speed, raw_dir, t)
            raw = _wind_stats(raw_speed, raw_dir)
            corr = _wind_stats(corr_speed, corr_dir)
            raw_mean = raw["mean_speed"]
            corr_mean = corr["mean_speed"]
            row = {
                "time_utc": str(t).replace("T", " "),
                "raw_mean_speed": raw_mean,
                "raw_p10_speed": raw["p10_speed"],
                "raw_p90_speed": raw["p90_speed"],
                "raw_dir_from": raw["mean_dir_from"],
                "corrected_mean_speed": corr_mean,
                "corrected_p10_speed": corr["p10_speed"],
                "corrected_p90_speed": corr["p90_speed"],
                "corrected_dir_from": corr["mean_dir_from"],
                "speed_scale": float(corr_mean / raw_mean) if raw_mean and np.isfinite(raw_mean) else np.nan,
                "dir_rotation_deg": _angle_delta_deg(corr["mean_dir_from"], raw["mean_dir_from"]),
            }
            row.update(correction_inputs(t))
            rows.append(row)
            if i % 25 == 0 or i == len(times):
                print(f"  wind correction stats {i}/{len(times)}")
        return rows

    sample_steps = np.arange(0, N_STEPS + 1, max(1, int(round(60.0 / MIN_PER_STEP))))
    for step in sample_steps:
        t = wind.t0 + np.timedelta64(int(round(step * MIN_PER_STEP)), "m")
        if wind.mode == "wn_single" and wind.vel is not None and wind.ang is not None:
            raw_speed, raw_dir = wind._clean(wind.vel, wind.ang)
            corr_speed, corr_dir = wind._apply_asos_temporal_correction(raw_speed, raw_dir, t)
        else:
            background = wind._background_wind_at(t)
            if background is None:
                continue
            raw_speed = np.full(wind.shape, float(background[0]), "float32")
            raw_dir = np.full(wind.shape, float(background[1]), "float32")
            corr_speed, corr_dir = wind._apply_station_vector_bias_correction(raw_speed, raw_dir, t)
        raw = _wind_stats(raw_speed, raw_dir)
        corr = _wind_stats(corr_speed, corr_dir)
        row = {
            "time_utc": str(t).replace("T", " "),
            "raw_mean_speed": raw["mean_speed"],
            "raw_p10_speed": raw["p10_speed"],
            "raw_p90_speed": raw["p90_speed"],
            "raw_dir_from": raw["mean_dir_from"],
            "corrected_mean_speed": corr["mean_speed"],
            "corrected_p10_speed": corr["p10_speed"],
            "corrected_p90_speed": corr["p90_speed"],
            "corrected_dir_from": corr["mean_dir_from"],
            "speed_scale": float(corr["mean_speed"] / raw["mean_speed"])
            if raw["mean_speed"] and np.isfinite(raw["mean_speed"]) else np.nan,
            "dir_rotation_deg": _angle_delta_deg(corr["mean_dir_from"], raw["mean_dir_from"]),
        }
        row.update(correction_inputs(t))
        rows.append(row)
    return rows


def plot_wind_correction_diagnostics(wind, out_png, out_csv):
    import csv
    import datetime as dt
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    rows = collect_wind_correction_diagnostics(wind)
    os.makedirs(os.path.dirname(out_png), exist_ok=True)
    fields = [
        "time_utc", "background_speed", "background_dir_from",
        "raw_mean_speed", "raw_p10_speed", "raw_p90_speed", "raw_dir_from",
        "station_speed", "station_dir_from",
        "corrected_mean_speed", "corrected_p10_speed", "corrected_p90_speed",
        "corrected_dir_from", "bias_u_mps", "bias_v_mps", "bias_magnitude_mps",
        "bias_p10_mps", "bias_p90_mps", "station_count",
        "correction_weight", "correction_method", "speed_scale", "dir_rotation_deg",
    ]
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)

    if not rows:
        print("saved", out_csv)
        return

    times = [dt.datetime.fromisoformat(r["time_utc"]) for r in rows]
    raw_speed = np.asarray([r["raw_mean_speed"] for r in rows], dtype=float)
    corr_speed = np.asarray([r["corrected_mean_speed"] for r in rows], dtype=float)
    background_speed = np.asarray([r["background_speed"] for r in rows], dtype=float)
    station_speed = np.asarray([r["station_speed"] for r in rows], dtype=float)
    raw_dir = np.asarray([r["raw_dir_from"] for r in rows], dtype=float)
    corr_dir = np.asarray([r["corrected_dir_from"] for r in rows], dtype=float)
    background_dir = np.asarray([r["background_dir_from"] for r in rows], dtype=float)
    station_dir = np.asarray([r["station_dir_from"] for r in rows], dtype=float)
    bias_magnitude = np.asarray([r["bias_magnitude_mps"] for r in rows], dtype=float)
    rot = np.asarray([r["dir_rotation_deg"] for r in rows], dtype=float)

    fig, axes = plt.subplots(3, 1, figsize=(13, 9), sharex=True)
    axes[0].plot(times, background_speed, color="#756bb1", lw=1.2,
                 label=f"{wind.background_source} background")
    axes[0].plot(times, raw_speed, color="#7f7f7f", lw=1.6,
                 label="Raw WindNinja domain mean")
    axes[0].plot(times, station_speed, color="#08519c", lw=1.4, alpha=0.9,
                 label="Blended station observations")
    axes[0].plot(times, corr_speed, color="#d7301f", lw=2.0,
                 label="Bias-corrected WindNinja field")
    axes[0].set_ylabel("Speed (m/s)")
    axes[0].legend(loc="upper right")
    axes[0].grid(alpha=0.28)

    axes[1].plot(times, background_dir, color="#756bb1", lw=1.1,
                 label=f"{wind.background_source} wind direction (from)")
    axes[1].plot(times, raw_dir, color="#7f7f7f", lw=1.4,
                 label="Raw WindNinja wind direction (from)")
    axes[1].plot(times, corr_dir, color="#d7301f", lw=1.8,
                 label="Corrected wind direction (from)")
    axes[1].plot(times, station_dir, color="#08519c", lw=1.2, alpha=0.9,
                 label="Station-observed wind direction (from)")
    axes[1].set_ylabel("Wind direction (from, deg)")
    axes[1].set_ylim(0, 360)
    axes[1].set_yticks(np.arange(0, 361, 45))
    axes[1].legend(loc="upper right")
    axes[1].grid(alpha=0.28)

    bias_line, = axes[2].plot(times, bias_magnitude, color="#238b45", lw=1.8,
                              label="Applied vector-bias magnitude")
    axes[2].axhline(0.0, color="#444444", lw=0.8, alpha=0.6)
    axes[2].set_ylabel("Vector bias (m/s)")
    axes[2].set_xlabel("UTC time")
    axes[2].grid(alpha=0.28)
    axr = axes[2].twinx()
    rot_line, = axr.plot(times, rot, color="#756bb1", lw=1.4,
                         label="Directional adjustment")
    axr.axhline(0.0, color="#444444", lw=0.8, alpha=0.45)
    axr.set_ylabel("Directional adjustment (deg)")
    axes[2].legend([bias_line, rot_line],
                   [bias_line.get_label(), rot_line.get_label()],
                   loc="upper right")

    fig.autofmt_xdate()
    _apply_lettered_bottom_caption(
        fig, axes,
        ["background, raw WindNinja, station-observed and corrected wind speed",
         "background, raw WindNinja, station-observed and corrected meteorological wind direction",
         "applied station-minus-background vector bias and resulting directional adjustment"],
        "Wind-Field Correction Diagnostics",
    )
    fig.savefig(out_png, dpi=150)
    plt.close(fig)
    print("saved", out_png)
    print("saved", out_csv)


def validate_station_spatial_correction(wind, out_png, out_csv):
    """Leave one station out and verify spatial vector-bias interpolation."""
    import csv
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    members = list(getattr(wind, "station_members", []))
    if len(members) < 2:
        return []
    sim_end = wind.t0 + np.timedelta64(int(round(N_STEPS * MIN_PER_STEP)), "m")
    times = np.arange(wind.t0, sim_end + np.timedelta64(1, "h"), np.timedelta64(1, "h"))
    errors = {member["station"]: [] for member in members}
    smooth_m = max(float(STATION_IDW_SMOOTHING_KM) * 1000.0, 1.0)
    power = max(float(STATION_IDW_POWER), 0.1)

    for t in times:
        background = wind._background_wind_at(t)
        if background is None:
            continue
        bg_u, bg_v = wind._speed_dir_from_to_uv(*background)
        bg_u = float(np.asarray(bg_u)); bg_v = float(np.asarray(bg_v))
        observations = {
            index: wind._member_wind_at(member, t)
            for index, member in enumerate(members)
        }
        for target_index, target in enumerate(members):
            obs = observations.get(target_index)
            if obs is None:
                continue
            residual_u = []
            residual_v = []
            weights = []
            for source_index, source in enumerate(members):
                if source_index == target_index:
                    continue
                source_obs = observations.get(source_index)
                if source_obs is None:
                    continue
                source_u, source_v = wind._speed_dir_from_to_uv(*source_obs)
                distance2 = ((target["x"] - source["x"]) ** 2 +
                             (target["y"] - source["y"]) ** 2)
                weight = float(source.get("reliability", 1.0)) / (
                    (distance2 + smooth_m ** 2) ** (power / 2.0)
                )
                residual_u.append(float(np.asarray(source_u)) - bg_u)
                residual_v.append(float(np.asarray(source_v)) - bg_v)
                weights.append(weight)
            if not weights:
                continue
            weights = np.asarray(weights, dtype=float)
            weights /= np.sum(weights)
            pred_u = bg_u + STATION_CORRECTION_WEIGHT * float(np.dot(weights, residual_u))
            pred_v = bg_v + STATION_CORRECTION_WEIGHT * float(np.dot(weights, residual_v))
            pred_speed, pred_dir = wind._uv_to_speed_dir_from(pred_u, pred_v)
            pred_speed = float(np.asarray(pred_speed)); pred_dir = float(np.asarray(pred_dir))
            obs_u, obs_v = wind._speed_dir_from_to_uv(*obs)
            obs_u = float(np.asarray(obs_u)); obs_v = float(np.asarray(obs_v))
            errors[target["station"]].append({
                "background_speed_error": float(background[0]) - float(obs[0]),
                "corrected_speed_error": pred_speed - float(obs[0]),
                "background_dir_error": _angle_delta_deg(float(background[1]), float(obs[1])),
                "corrected_dir_error": _angle_delta_deg(pred_dir, float(obs[1])),
                "background_uv_error2": (bg_u - obs_u) ** 2 + (bg_v - obs_v) ** 2,
                "corrected_uv_error2": (pred_u - obs_u) ** 2 + (pred_v - obs_v) ** 2,
            })

    rows = []
    for station, values in errors.items():
        if not values:
            continue
        def array(field):
            return np.asarray([item[field] for item in values], dtype=float)
        rows.append({
            "station": station,
            "n": len(values),
            "background_speed_mae_mps": float(np.mean(np.abs(array("background_speed_error")))),
            "corrected_speed_mae_mps": float(np.mean(np.abs(array("corrected_speed_error")))),
            "background_direction_mae_deg": float(np.mean(np.abs(array("background_dir_error")))),
            "corrected_direction_mae_deg": float(np.mean(np.abs(array("corrected_dir_error")))),
            "background_uv_rmse_mps": float(np.sqrt(np.mean(array("background_uv_error2")))),
            "corrected_uv_rmse_mps": float(np.sqrt(np.mean(array("corrected_uv_error2")))),
        })
    if not rows:
        return []
    station_rows = list(rows)
    counts = np.asarray([row["n"] for row in station_rows], dtype=float)
    total_count = int(np.sum(counts))

    def weighted_mean(field):
        values = np.asarray([row[field] for row in station_rows], dtype=float)
        return float(np.average(values, weights=counts))

    def pooled_rmse(field):
        values = np.asarray([row[field] for row in station_rows], dtype=float)
        return float(np.sqrt(np.average(values ** 2, weights=counts)))

    rows.append({
        "station": "ALL",
        "n": total_count,
        "background_speed_mae_mps": weighted_mean("background_speed_mae_mps"),
        "corrected_speed_mae_mps": weighted_mean("corrected_speed_mae_mps"),
        "background_direction_mae_deg": weighted_mean("background_direction_mae_deg"),
        "corrected_direction_mae_deg": weighted_mean("corrected_direction_mae_deg"),
        "background_uv_rmse_mps": pooled_rmse("background_uv_rmse_mps"),
        "corrected_uv_rmse_mps": pooled_rmse("corrected_uv_rmse_mps"),
    })

    fields = list(rows[0].keys())
    os.makedirs(os.path.dirname(out_csv) or ".", exist_ok=True)
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)

    stations = [row["station"] for row in rows]
    x = np.arange(len(rows), dtype=float)
    width = 0.36
    fig, axes = plt.subplots(1, 3, figsize=(14, 4.8), facecolor="white")
    metrics = [
        ("background_speed_mae_mps", "corrected_speed_mae_mps", "Speed MAE (m/s)"),
        ("background_direction_mae_deg", "corrected_direction_mae_deg", "Direction MAE (deg)"),
        ("background_uv_rmse_mps", "corrected_uv_rmse_mps", "Vector RMSE (m/s)"),
    ]
    descriptions = []
    for ax, (background_field, corrected_field, ylabel) in zip(axes, metrics):
        background_values = [row[background_field] for row in rows]
        corrected_values = [row[corrected_field] for row in rows]
        ax.bar(x - width / 2, background_values, width, color="#969696", label="HRRR background")
        ax.bar(
            x + width / 2,
            corrected_values,
            width,
            color="#238b45",
            label="Leave-one-station-out corrected",
        )
        ax.set_xticks(x, stations)
        ax.set_ylabel(ylabel)
        ax.grid(axis="y", alpha=0.25)
        ax.legend(fontsize=8)
        descriptions.append(f"station-wise {ylabel.lower()}")
    _apply_lettered_bottom_caption(
        fig, axes, descriptions,
        "Leave-One-Station-Out Wind-Correction Validation",
    )
    fig.savefig(out_png, dpi=170, bbox_inches="tight")
    plt.close(fig)
    print("saved", out_png)
    print("saved", out_csv)
    return rows


def compute_slope_aspect(elev):
    fill = float(np.nanmedian(elev)) if np.isfinite(elev).any() else 0.0
    z = np.nan_to_num(elev.astype("float32"), nan=fill)
    dz_drow, dz_dcol = np.gradient(z, TARGET_RES, TARGET_RES)
    slope_deg = np.degrees(np.arctan(np.hypot(dz_drow, dz_dcol))).astype("float32")
    aspect_deg = (np.degrees(np.arctan2(-dz_dcol, dz_drow)) % 360.0).astype("float32")
    slope_deg[~np.isfinite(elev)] = np.nan
    aspect_deg[~np.isfinite(elev)] = np.nan
    return slope_deg, aspect_deg


def plot_terrain_maps(elev, ign, real_mask, out_slope, out_aspect, out_combo):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.colors import Normalize, hsv_to_rgb

    os.makedirs(os.path.dirname(out_slope), exist_ok=True)
    slope_deg, aspect_deg = compute_slope_aspect(elev)
    finite_slope = slope_deg[np.isfinite(slope_deg)]
    vmax = float(np.percentile(finite_slope, 98)) if finite_slope.size else 45.0
    vmax = max(vmax, 10.0)

    def decorate(ax):
        ax.plot(ign[1], ign[0], "^", color="#ff2020", ms=8, mec="white", mew=0.7)
        ax.axis("off")

    fig, ax = plt.subplots(figsize=(9, 8), facecolor="#f7f7f7")
    im = ax.imshow(slope_deg, cmap="magma", vmin=0, vmax=vmax, interpolation="nearest")
    decorate(ax)
    ax.set_title("Terrain Slope", fontweight="bold")
    cb = fig.colorbar(im, ax=ax, fraction=0.035, pad=0.015)
    cb.set_label("Slope (degrees)")
    _apply_lettered_bottom_caption(
        fig, [ax], ["terrain slope in degrees"], "Terrain Slope",
    )
    fig.savefig(out_slope, dpi=150)
    plt.close(fig)

    aspect_norm = np.ma.masked_invalid(aspect_deg) / 360.0
    fig, ax = plt.subplots(figsize=(9, 8), facecolor="#f7f7f7")
    im = ax.imshow(aspect_norm, cmap="hsv", vmin=0, vmax=1, interpolation="nearest")
    decorate(ax)
    ax.set_title("Terrain Aspect", fontweight="bold")
    cb = fig.colorbar(im, ax=ax, fraction=0.035, pad=0.015, ticks=np.arange(0, 1.01, 0.125))
    cb.ax.set_yticklabels(["N", "NE", "E", "SE", "S", "SW", "W", "NW", "N"])
    cb.set_label("Downslope aspect")
    _apply_lettered_bottom_caption(
        fig, [ax], ["downslope aspect direction"], "Terrain Aspect",
    )
    fig.savefig(out_aspect, dpi=150)
    plt.close(fig)

    hue = np.nan_to_num(aspect_deg / 360.0, nan=0.0)
    sat = np.clip(slope_deg / max(vmax, 1e-6), 0.15, 1.0)
    val = np.where(np.isfinite(elev), 0.92, 1.0)
    rgb = hsv_to_rgb(np.dstack([hue, sat, val]))

    fig, axes = plt.subplots(1, 2, figsize=(15, 7), facecolor="#f7f7f7")
    im0 = axes[0].imshow(slope_deg, cmap="magma", vmin=0, vmax=vmax, interpolation="nearest")
    decorate(axes[0])
    axes[0].set_title("Slope (degrees)", fontweight="bold")
    cb0 = fig.colorbar(im0, ax=axes[0], fraction=0.035, pad=0.015)
    cb0.set_label("Slope (degrees)")
    axes[1].imshow(rgb, interpolation="nearest")
    decorate(axes[1])
    axes[1].set_title("Aspect with Slope-Dependent Saturation", fontweight="bold")
    aspect_map = plt.cm.ScalarMappable(norm=Normalize(vmin=0, vmax=360), cmap="hsv")
    aspect_map.set_array([])
    cb1 = fig.colorbar(aspect_map, ax=axes[1], fraction=0.035, pad=0.015,
                       ticks=np.arange(0, 361, 45))
    cb1.ax.set_yticklabels(["N", "NE", "E", "SE", "S", "SW", "W", "NW", "N"])
    cb1.set_label("Aspect direction (hue)")

    sat_demo = np.linspace(0.15, 1.0, 256, dtype="float32")[None, :]
    sat_rgb = hsv_to_rgb(np.dstack([
        np.full_like(sat_demo, 0.58),
        sat_demo,
        np.full_like(sat_demo, 0.92),
    ]))
    inset = axes[1].inset_axes([0.035, 0.035, 0.34, 0.045])
    inset.imshow(sat_rgb, aspect="auto", interpolation="nearest")
    inset.set_yticks([])
    inset.set_xticks([0, 255])
    inset.set_xticklabels(["gentle", "steep"], fontsize=7)
    for spine in inset.spines.values():
        spine.set_edgecolor("#222222")
        spine.set_linewidth(0.6)
    axes[1].text(
        0.035, 0.105,
        "Aspect hue; slope saturation",
        transform=axes[1].transAxes,
        ha="left", va="bottom", fontsize=8, color="#222222",
        bbox=dict(facecolor="white", edgecolor="#777777", linewidth=0.5, alpha=0.82, pad=3.0),
    )
    _apply_lettered_bottom_caption(
        fig, axes,
        ["terrain slope in degrees", "downslope aspect with slope-dependent saturation"],
        "Terrain Slope and Aspect",
    )
    fig.savefig(out_combo, dpi=150)
    plt.close(fig)

    print("saved", out_slope)
    print("saved", out_aspect)
    print("saved", out_combo)


def _parse_day_from_text(text):
    import re
    if not text:
        return None
    s = str(text)
    m = re.search(r"(?:day|d)[_\-\s]?(\d{1,2})", s, flags=re.IGNORECASE)
    if m:
        return max(1, int(m.group(1)))
    m = re.search(r"(20\d{2})[-_]?(\d{2})[-_]?(\d{2})", s)
    if m:
        date = np.datetime64(f"{m.group(1)}-{m.group(2)}-{m.group(3)}")
        start_date = np.datetime64(SIM_START.split()[0])
        delta = int((date - start_date) / np.timedelta64(1, "D"))
        return max(1, delta + 1)
    return None


def _daily_reference_dirs():
    dirs = [
        Path(OFFICIAL_DAILY_REF_PERIM_DIR),
        Path(OFFICIAL_DAILY_REF_PERIM_DIR) / "daily_cumulative_geojson",
    ]
    out = []
    seen = set()
    for d in dirs:
        key = str(d.resolve()) if d.exists() else str(d)
        if key not in seen:
            out.append(d)
            seen.add(key)
    return out


def _geojson_reference_properties(path):
    import json
    try:
        with open(path, encoding="utf-8") as f:
            gj = json.load(f)
        if gj.get("features"):
            return gj, (gj["features"][0].get("properties", {}) or {})
        return gj, (gj.get("properties", {}) or {})
    except Exception:
        return None, {}


def _daily_reference_paths(ref_dir):
    import json
    manifest = ref_dir / "daily_reference_manifest.json"
    if manifest.exists():
        try:
            with open(manifest, encoding="utf-8") as f:
                data = json.load(f)
            names = data.get("daily_files", [])
            paths = [ref_dir / str(name) for name in names]
            return [path for path in paths if path.exists()]
        except Exception as exc:
            print(f"daily reference manifest could not be read: {manifest} ({exc})")
    return sorted(list(ref_dir.glob("*.geojson")) + list(ref_dir.glob("*.json")))


def _is_approximate_reference(props):
    if bool(props.get("carried_forward", False)):
        return False
    return (
        bool(props.get("approximate", False)) or
        "image segmentation" in str(props.get("method", "")).lower() or
        "png" in str(props.get("source", "")).lower() or
        str(props.get("geometry_role", "")).lower() == "boundary_only"
    )


def load_daily_validation_references(transform, crs, shape):
    """Load optional daily perimeter GeoJSONs and daily reference area CSV."""
    import csv

    masks = {}
    loaded_sources = {}
    skipped_approx = 0
    for ref_dir in _daily_reference_dirs():
        if not ref_dir.exists():
            continue
        paths = _daily_reference_paths(ref_dir)
        for path in paths:
            gj, props = _geojson_reference_properties(path)
            if _is_approximate_reference(props) and not ALLOW_APPROXIMATE_DAILY_PERIMETERS:
                skipped_approx += 1
                continue
            day = _parse_day_from_text(
                props.get("day") or props.get("date") or
                props.get("time_utc") or props.get("observation_time")
            )
            if day is None:
                day = _parse_day_from_text(path.stem)
            if day is None:
                print(f"skip daily reference perimeter without day: {path}")
                continue
            if int(day) > DAILY_REFERENCE_MAX_DAYS:
                continue
            if int(day) in masks:
                continue
            mask = rasterize_geojson_perimeter(str(path), transform, crs, shape)
            if mask is not None and mask.any():
                masks[int(day)] = mask
                loaded_sources[int(day)] = str(path)

    areas = {}
    if DAILY_REF_AREA_CSV and os.path.exists(DAILY_REF_AREA_CSV):
        def pick(row, names):
            for name in names:
                if name in row and str(row[name]).strip() != "":
                    return row[name]
            return None

        with open(DAILY_REF_AREA_CSV, newline="", encoding="utf-8-sig") as f:
            reader = csv.DictReader(f)
            for idx, row in enumerate(reader, start=1):
                lower = {str(k).strip().lower(): v for k, v in row.items()}
                day = pick(lower, ["day", "burn_day", "day_since_ignition"])
                day = int(float(day)) if day is not None else None
                if day is None:
                    day = _parse_day_from_text(
                        pick(lower, ["date", "time_utc", "window_end_utc"])
                    ) or idx
                if int(day) > DAILY_REFERENCE_MAX_DAYS:
                    continue
                ha = pick(lower, [
                    "ref_cumulative_ha", "cumulative_ha", "cum_ha",
                    "area_ha", "burned_ha", "ha",
                ])
                ac = pick(lower, [
                    "ref_cumulative_acres", "cumulative_acres", "acres",
                    "area_acres", "burned_acres",
                ])
                try:
                    if ha is not None:
                        areas[int(day)] = float(ha)
                    elif ac is not None:
                        areas[int(day)] = float(ac) / 2.47105
                except Exception:
                    continue

    if masks:
        print(f"loaded {len(masks)} daily reference perimeter(s)")
        for day in sorted(loaded_sources):
            print(f"  Day {day}: {loaded_sources[day]}")
    if skipped_approx:
        print(f"skipped {skipped_approx} approximate PNG-derived daily perimeter file(s)")
    if areas:
        print(f"loaded {len(areas)} daily reference area checkpoint(s)")
    return masks, areas


def daily_increment_masks(cumulative_masks):
    """Convert cumulative daily perimeter masks into per-day newly burned masks."""
    if not cumulative_masks:
        return {}
    out = {}
    prev = None
    for day in sorted(cumulative_masks):
        cur = np.asarray(cumulative_masks[day], dtype=bool)
        if prev is None:
            out[int(day)] = cur.copy()
            prev = cur.copy()
        else:
            out[int(day)] = cur & ~prev
            prev |= cur
    return out


def daily_increment_areas(cumulative_areas):
    """Convert cumulative daily reference areas to daily area increments."""
    if not cumulative_areas:
        return {}
    out = {}
    prev = np.nan
    for day in sorted(cumulative_areas):
        cur = float(cumulative_areas[day])
        if np.isfinite(prev):
            out[int(day)] = max(0.0, cur - prev)
        else:
            out[int(day)] = cur
        prev = cur
    return out


def _elapsed_hours_from_local_time(local_time_text):
    if not local_time_text:
        return None, "", ""
    s = str(local_time_text).strip().replace(" ", "T")
    try:
        t_local = np.datetime64(s)
    except Exception:
        return None, "", ""
    offset_min = int(round(LOCAL_UTC_OFFSET_HOURS * 60.0))
    sim_start_utc = np.datetime64(SIM_START.replace(" ", "T"))
    sim_start_local = sim_start_utc + np.timedelta64(offset_min, "m")
    elapsed_h = float((t_local - sim_start_local) / np.timedelta64(1, "m")) / 60.0
    t_utc = t_local - np.timedelta64(offset_min, "m")
    return elapsed_h, str(t_local).replace("T", " "), str(t_utc).replace("T", " ")


def _reporting_day_for_elapsed(elapsed_h):
    for window in daily_time_windows():
        if elapsed_h <= float(window["end_h"]) + 1e-9:
            return int(window["day"])
    return int(daily_time_windows()[-1]["day"]) if daily_time_windows() else 1


SPOTTING_STAT_FIELDS = [
    "candidate_sources", "active_source_cells", "launched_firebrands",
    "landed_in_domain", "unburned_targets", "successful_spot_ignitions",
    "queued_spot_ignitions", "activated_spot_ignitions",
    "blocked_spot_ignitions", "building_spot_ignitions",
    "activated_building_spot_ignitions", "distance_sum_cells",
    "distance_max_cells", "hit_distance_sum_cells", "hit_distance_max_cells",
    "release_probability_sum", "short_range_launches",
    "long_range_launches", "plume_range_launches",
    "burned_out_before_landing", "viable_landings",
    "viable_unburned_targets", "plume_range_landed",
    "short_range_successful_ignitions",
    "long_range_successful_ignitions",
    "plume_range_successful_ignitions",
    "flight_time_sum_min", "remaining_energy_sum",
    "ignition_delay_sum_min",
    "crown_source_cells", "crown_edge_cells", "crown_high_source_cells",
    "crown_source_sum", "crown_edge_sum", "crown_launched_firebrands",
    "crown_successful_spot_ignitions",
    "ml_source_factor_samples", "ml_source_factor_sum",
    "ml_source_adjusted_cells", "ml_target_factor_samples",
    "ml_target_factor_sum", "ml_target_adjusted_landings",
    "ml_local_target_factor_sum",
    "ta_source_factor_samples", "ta_release_factor_sum",
    "ta_release_adjusted_cells", "ta_distance_factor_sum",
    "ta_direction_samples", "ta_direction_entropy_sum",
    "ta_direction_offset_sum_deg", "ta_target_factor_samples",
    "ta_target_factor_sum", "ta_target_adjusted_landings",
]


def make_spotting_stats():
    return {}


def _spotting_day_record(stats, day):
    day = int(day)
    if day not in stats:
        stats[day] = {key: 0.0 for key in SPOTTING_STAT_FIELDS}
    return stats[day]


def _add_spotting_stats(stats, day, **values):
    if stats is None:
        return
    rec = _spotting_day_record(stats, day)
    for key, value in values.items():
        if key not in rec:
            rec[key] = 0.0
        if key.endswith("_max_cells"):
            rec[key] = max(float(rec.get(key, 0.0)), float(value))
        else:
            rec[key] = float(rec.get(key, 0.0)) + float(value)


def spotting_stats_rows(stats):
    rows = []
    days = sorted(set(int(w["day"]) for w in daily_time_windows()) | set(int(k) for k in stats.keys()))
    for day in days:
        rec = dict(_spotting_day_record(stats, day))
        launched = rec.get("launched_firebrands", 0.0)
        landed = rec.get("landed_in_domain", 0.0)
        hits = rec.get("successful_spot_ignitions", 0.0)
        activated = rec.get("activated_spot_ignitions", 0.0)
        crown_sources = rec.get("crown_source_cells", 0.0)
        crown_edges = rec.get("crown_edge_cells", 0.0)
        crown_launches = rec.get("crown_launched_firebrands", 0.0)
        viable_landings = rec.get("viable_landings", 0.0)
        ml_source_samples = rec.get("ml_source_factor_samples", 0.0)
        ml_target_samples = rec.get("ml_target_factor_samples", 0.0)
        rec.update({
            "day": int(day),
            "avg_distance_cells": rec.get("distance_sum_cells", 0.0) / landed if landed > 0 else 0.0,
            "avg_distance_m": rec.get("distance_sum_cells", 0.0) * TARGET_RES / landed if landed > 0 else 0.0,
            "max_distance_m": rec.get("distance_max_cells", 0.0) * TARGET_RES,
            "avg_hit_distance_cells": rec.get("hit_distance_sum_cells", 0.0) / hits if hits > 0 else 0.0,
            "avg_hit_distance_m": rec.get("hit_distance_sum_cells", 0.0) * TARGET_RES / hits if hits > 0 else 0.0,
            "max_hit_distance_m": rec.get("hit_distance_max_cells", 0.0) * TARGET_RES,
            "launch_to_hit_ratio": hits / launched if launched > 0 else 0.0,
            "queued_to_activated_ratio": activated / hits if hits > 0 else 0.0,
            "avg_crown_source_tendency": rec.get("crown_source_sum", 0.0) / crown_sources if crown_sources > 0 else 0.0,
            "avg_crown_edge_tendency": rec.get("crown_edge_sum", 0.0) / crown_edges if crown_edges > 0 else 0.0,
            "crown_launch_fraction": crown_launches / launched if launched > 0 else 0.0,
            "crown_hit_fraction": rec.get("crown_successful_spot_ignitions", 0.0) / hits if hits > 0 else 0.0,
            "firebrand_survival_ratio":
                viable_landings / landed if landed > 0 else 0.0,
            "long_range_launch_fraction": (
                rec.get("long_range_launches", 0.0)
                + rec.get("plume_range_launches", 0.0)
            ) / launched if launched > 0 else 0.0,
            "plume_launch_fraction":
                rec.get("plume_range_launches", 0.0) / launched
                if launched > 0 else 0.0,
            "avg_flight_time_min":
                rec.get("flight_time_sum_min", 0.0) / launched
                if launched > 0 else 0.0,
            "avg_remaining_energy":
                rec.get("remaining_energy_sum", 0.0) / launched
                if launched > 0 else 0.0,
            "avg_ignition_delay_min":
                rec.get("ignition_delay_sum_min", 0.0) / hits
                if hits > 0 else 0.0,
            "ml_firebrand_coupling_used": int(
                ml_source_samples > 0 or ml_target_samples > 0
            ),
            "avg_ml_source_factor":
                rec.get("ml_source_factor_sum", 0.0) / ml_source_samples
                if ml_source_samples > 0 else 1.0,
            "avg_ml_target_factor":
                rec.get("ml_target_factor_sum", 0.0) / ml_target_samples
                if ml_target_samples > 0 else 1.0,
            "avg_ml_local_target_factor":
                rec.get("ml_local_target_factor_sum", 0.0) / ml_target_samples
                if ml_target_samples > 0 else 1.0,
            "ta_mlca_spotting_used": int(
                rec.get("ta_source_factor_samples", 0.0) > 0
                or rec.get("ta_target_factor_samples", 0.0) > 0
                or rec.get("ta_direction_samples", 0.0) > 0
            ),
            "avg_ta_release_factor":
                rec.get("ta_release_factor_sum", 0.0)
                / rec.get("ta_source_factor_samples", 0.0)
                if rec.get("ta_source_factor_samples", 0.0) > 0 else 1.0,
            "avg_ta_distance_factor":
                rec.get("ta_distance_factor_sum", 0.0)
                / rec.get("ta_source_factor_samples", 0.0)
                if rec.get("ta_source_factor_samples", 0.0) > 0 else 1.0,
            "avg_ta_direction_entropy":
                rec.get("ta_direction_entropy_sum", 0.0)
                / rec.get("ta_direction_samples", 0.0)
                if rec.get("ta_direction_samples", 0.0) > 0 else 0.0,
            "avg_ta_direction_offset_deg":
                rec.get("ta_direction_offset_sum_deg", 0.0)
                / rec.get("ta_direction_samples", 0.0)
                if rec.get("ta_direction_samples", 0.0) > 0 else 0.0,
            "avg_ta_target_factor":
                rec.get("ta_target_factor_sum", 0.0)
                / rec.get("ta_target_factor_samples", 0.0)
                if rec.get("ta_target_factor_samples", 0.0) > 0 else 1.0,
        })
        rows.append(rec)
    return rows


def write_spotting_stats(stats, out_csv, out_png=None):
    import csv
    rows = spotting_stats_rows(stats)
    fields = [
        "day", "candidate_sources", "active_source_cells", "launched_firebrands",
        "landed_in_domain", "unburned_targets", "successful_spot_ignitions",
        "queued_spot_ignitions", "activated_spot_ignitions",
        "blocked_spot_ignitions", "building_spot_ignitions",
        "activated_building_spot_ignitions", "launch_to_hit_ratio",
        "queued_to_activated_ratio",
        "avg_distance_cells", "avg_distance_m", "max_distance_m",
        "avg_hit_distance_cells", "avg_hit_distance_m", "max_hit_distance_m",
        "short_range_launches", "long_range_launches",
        "plume_range_launches", "long_range_launch_fraction",
        "plume_launch_fraction", "burned_out_before_landing",
        "viable_landings", "firebrand_survival_ratio",
        "viable_unburned_targets", "plume_range_landed",
        "short_range_successful_ignitions",
        "long_range_successful_ignitions",
        "plume_range_successful_ignitions",
        "avg_flight_time_min", "avg_remaining_energy",
        "avg_ignition_delay_min",
        "crown_source_cells", "crown_edge_cells", "crown_high_source_cells",
        "avg_crown_source_tendency", "avg_crown_edge_tendency",
        "crown_launched_firebrands", "crown_successful_spot_ignitions",
        "crown_launch_fraction", "crown_hit_fraction",
        "ml_firebrand_coupling_used", "avg_ml_source_factor",
        "avg_ml_target_factor", "avg_ml_local_target_factor",
        "ml_source_adjusted_cells", "ml_target_adjusted_landings",
        "ta_mlca_spotting_used", "avg_ta_release_factor",
        "avg_ta_distance_factor", "avg_ta_direction_entropy",
        "avg_ta_direction_offset_deg", "avg_ta_target_factor",
        "ta_release_adjusted_cells", "ta_target_adjusted_landings",
    ]
    os.makedirs(os.path.dirname(out_csv) or ".", exist_ok=True)
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({k: row.get(k, 0.0) for k in fields})
    print("saved", out_csv)
    if out_png:
        plot_spotting_stats(rows, out_png)
    total_launch = sum(r.get("launched_firebrands", 0.0) for r in rows)
    total_hits = sum(r.get("successful_spot_ignitions", 0.0) for r in rows)
    total_activated = sum(r.get("activated_spot_ignitions", 0.0) for r in rows)
    total_blocked = sum(r.get("blocked_spot_ignitions", 0.0) for r in rows)
    total_building = sum(r.get("activated_building_spot_ignitions", 0.0) for r in rows)
    print(
        "Spotting summary: "
        f"{total_launch:.0f} launched firebrands, "
        f"{total_hits:.0f} queued spot ignitions, "
        f"{total_activated:.0f} activated after delay, "
        f"{total_blocked:.0f} blocked before delay "
        f"({total_building:.0f} activated on building cells)."
    )
    return rows


def plot_spotting_stats(rows, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    if not rows:
        return
    days = np.asarray([r["day"] for r in rows], dtype=int)
    launched = np.asarray([r.get("launched_firebrands", 0.0) for r in rows], dtype=float)
    hits = np.asarray([r.get("successful_spot_ignitions", 0.0) for r in rows], dtype=float)
    activated = np.asarray([r.get("activated_spot_ignitions", 0.0) for r in rows], dtype=float)
    avg_hit_m = np.asarray([r.get("avg_hit_distance_m", 0.0) for r in rows], dtype=float)
    max_hit_m = np.asarray([r.get("max_hit_distance_m", 0.0) for r in rows], dtype=float)
    short_launch = np.asarray([r.get("short_range_launches", 0.0) for r in rows], dtype=float)
    long_launch = np.asarray([r.get("long_range_launches", 0.0) for r in rows], dtype=float)
    plume_launch = np.asarray([r.get("plume_range_launches", 0.0) for r in rows], dtype=float)
    survival = np.asarray([r.get("firebrand_survival_ratio", 0.0) for r in rows], dtype=float)
    crown_source = np.asarray([r.get("avg_crown_source_tendency", 0.0) for r in rows], dtype=float)
    crown_launch = np.asarray([r.get("crown_launch_fraction", 0.0) for r in rows], dtype=float)
    crown_hit = np.asarray([r.get("crown_hit_fraction", 0.0) for r in rows], dtype=float)
    ml_source = np.asarray(
        [r.get("avg_ml_source_factor", 1.0) for r in rows], dtype=float
    )
    ml_target = np.asarray(
        [r.get("avg_ml_target_factor", 1.0) for r in rows], dtype=float
    )
    ml_local_target = np.asarray(
        [r.get("avg_ml_local_target_factor", 1.0) for r in rows], dtype=float
    )
    fig, axes = plt.subplots(5, 1, figsize=(10.5, 13.8), sharex=True)
    w = 0.36
    axes[0].bar(days - w / 2, launched, width=w, color="#fdae6b",
                label="Launched firebrands")
    axes[0].bar(days + w / 2, hits, width=w, color="#de2d26",
                label="Queued spot-ignition events")
    axes[0].plot(days, activated, "-o", color="#6a51a3", lw=2.0,
                 label="Spot ignitions activated after transport delay")
    axes[0].set_ylabel("Count")
    axes[0].set_title("Spotting Diagnostics by Reporting Day", fontweight="bold")
    axes[0].legend()
    axes[0].grid(alpha=0.25)
    axes[1].bar(days, short_launch, color="#fdd49e",
                label="Short-range packets")
    axes[1].bar(days, long_launch, bottom=short_launch, color="#fc8d59",
                label="Long-range packets")
    axes[1].bar(days, plume_launch, bottom=short_launch + long_launch,
                color="#7a0177", label="Convective-plume packets")
    axes[1].set_ylabel("Released packets")
    axes[1].legend(fontsize=8)
    axes[1].grid(alpha=0.25)
    axes[2].plot(days, avg_hit_m, "-o", color="#756bb1", lw=2.0,
                 label="Mean successful spotting distance")
    axes[2].plot(days, max_hit_m, "--s", color="#2b8cbe", lw=1.7,
                 label="Maximum successful spotting distance")
    axes[2].set_ylabel("Distance (m)")
    axes[2].legend(fontsize=8)
    axes[2].grid(alpha=0.25)
    axes[3].plot(days, survival, "-d", color="#238b45", lw=1.9,
                 label="Viable landing fraction")
    axes[3].plot(days, crown_source, "-o", color="#b2182b", lw=1.9,
                 label="Mean crown-fire tendency at firebrand sources")
    axes[3].plot(days, crown_launch, "--s", color="#ef8a62", lw=1.6,
                 label="Fraction of firebrands launched from high-intensity sources")
    axes[3].plot(days, crown_hit, ":^", color="#7b3294", lw=1.6,
                 label="Fraction of successful spot ignitions from high-intensity sources")
    axes[3].set_ylabel("Fraction / tendency")
    axes[3].set_ylim(0, 1.02)
    axes[3].legend(fontsize=8)
    axes[3].grid(alpha=0.25)
    axes[4].axhline(1.0, color="#4d4d4d", lw=1.0, ls="--",
                    label="Neutral physical baseline")
    axes[4].plot(days, ml_source, "-o", color="#0072b2", lw=1.8,
                 label="ML source-release factor")
    axes[4].plot(days, ml_target, "-s", color="#d55e00", lw=1.8,
                 label="Combined ML landing-receptivity factor")
    axes[4].plot(days, ml_local_target, ":^", color="#009e73", lw=1.7,
                 label="Local-transition residual at landing")
    axes[4].set_xlabel("Reporting day")
    axes[4].set_ylabel("ML multiplier")
    ml_values = np.concatenate([ml_source, ml_target, ml_local_target])
    finite_ml = ml_values[np.isfinite(ml_values)]
    if finite_ml.size:
        span = max(
            0.03,
            float(np.max(np.abs(finite_ml - 1.0))) * 1.35,
        )
        axes[4].set_ylim(max(0.60, 1.0 - span), min(1.40, 1.0 + span))
    axes[4].legend(fontsize=8)
    axes[4].grid(alpha=0.25)
    _apply_lettered_bottom_caption(
        fig, axes,
        ["launched firebrands, queued spot ignitions and delayed activation",
         "short-, long- and convective-plume transport regimes",
         "mean and maximum successful spotting distance",
         "viable landings and high-intensity source contributions",
         "bounded machine-learning influence on spotting processes"],
        "Spotting Diagnostics by Reporting Day",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=145)
    plt.close(fig)
    print("saved", out_png)


def load_observation_validation_references(transform, crs, shape):
    """Load official progression observation perimeters at their actual timestamps."""
    obs_dir = Path(OFFICIAL_OBS_REF_PERIM_DIR)
    records = []
    if not obs_dir.exists():
        return records
    for path in sorted(obs_dir.glob("obs_*.geojson")):
        gj, props = _geojson_reference_properties(path)
        if _is_approximate_reference(props) and not ALLOW_APPROXIMATE_DAILY_PERIMETERS:
            continue
        elapsed_h, local_time, utc_time = _elapsed_hours_from_local_time(
            props.get("observation_time_local") or props.get("time_local")
        )
        if elapsed_h is None:
            continue
        if elapsed_h < -1e-6 or elapsed_h > (N_STEPS * MIN_PER_STEP / 60.0) + 1e-6:
            continue
        mask = rasterize_geojson_perimeter(str(path), transform, crs, shape)
        if mask is None or not mask.any():
            continue
        try:
            ref_ha = float(props.get("area_ha"))
        except Exception:
            ref_ha = float(mask.sum()) * TARGET_RES ** 2 / 1e4
        records.append({
            "observation_index": int(props.get("observation_index") or len(records) + 1),
            "source_objectid": props.get("source_objectid", ""),
            "observation_time_local": local_time,
            "observation_time_utc": utc_time,
            "elapsed_h": float(elapsed_h),
            "reporting_day": _reporting_day_for_elapsed(float(elapsed_h)),
            "ref_ha": ref_ha,
            "mask": mask,
            "path": str(path),
        })
    if records:
        print(f"loaded {len(records)} observation-time reference perimeter(s)")
    return records


def _empty_boundary_scores():
    return {
        "centroid_error_m": np.nan,
        "boundary_mean_error_m": np.nan,
        "boundary_p95_error_m": np.nan,
        "boundary_hausdorff_m": np.nan,
        "shape_orientation_error_deg": np.nan,
        "shape_linear_scale_ratio": np.nan,
        "shape_log_scale_error": np.nan,
        "shape_elongation_log_error": np.nan,
        "shape_radial_nrmse": np.nan,
    }


def _mask_centroid_rc(mask):
    rr, cc = np.where(mask)
    if len(rr) == 0:
        return None
    return np.array([float(np.mean(rr)), float(np.mean(cc))], dtype=float)


def _mask_shape_descriptor(mask, angular_bins=72):
    """Rotation-aware perimeter descriptor for separating size and shape error."""
    rr, cc = np.where(np.asarray(mask, dtype=bool))
    if rr.size < 8:
        return None
    x = cc.astype(float) - float(np.mean(cc))
    y = -(rr.astype(float) - float(np.mean(rr)))
    coords = np.column_stack([x, y])
    covariance = np.cov(coords, rowvar=False)
    eigenvalues, eigenvectors = np.linalg.eigh(covariance)
    order = np.argsort(eigenvalues)[::-1]
    major = eigenvectors[:, order[0]]
    major_value = max(float(eigenvalues[order[0]]), 1e-12)
    minor_value = max(float(eigenvalues[order[1]]), 1e-12)
    orientation = float(np.degrees(np.arctan2(major[1], major[0])) % 180.0)
    elongation = float(np.sqrt(major_value / minor_value))
    equivalent_radius = float(np.sqrt(rr.size / np.pi))

    radius = np.hypot(x, y)
    relative_angle = (
        np.arctan2(y, x) - np.radians(orientation)
    ) % (2.0 * np.pi)
    bins = max(12, int(angular_bins))
    indices = np.floor(relative_angle / (2.0 * np.pi) * bins).astype(int) % bins
    profile = np.full(bins, np.nan, dtype=float)
    for index in range(bins):
        selected = radius[indices == index]
        if selected.size:
            profile[index] = float(np.max(selected)) / max(equivalent_radius, 1e-9)
    valid = np.flatnonzero(np.isfinite(profile))
    if valid.size < 3:
        return None
    extended_x = np.r_[valid - bins, valid, valid + bins]
    extended_y = np.r_[profile[valid], profile[valid], profile[valid]]
    profile = np.interp(np.arange(bins), extended_x, extended_y)
    return {
        "orientation_deg": orientation,
        "elongation": elongation,
        "equivalent_radius_cells": equivalent_radius,
        "radial_profile": profile,
    }


def _perimeter_shape_scores(sim_mask, ref_mask):
    scores = {
        "shape_orientation_error_deg": np.nan,
        "shape_linear_scale_ratio": np.nan,
        "shape_log_scale_error": np.nan,
        "shape_elongation_log_error": np.nan,
        "shape_radial_nrmse": np.nan,
    }
    sim_desc = _mask_shape_descriptor(sim_mask)
    ref_desc = _mask_shape_descriptor(ref_mask)
    if sim_desc is None or ref_desc is None:
        return scores
    orientation_error = abs(
        (sim_desc["orientation_deg"] - ref_desc["orientation_deg"] + 90.0) %
        180.0 - 90.0
    )
    scale_ratio = (
        sim_desc["equivalent_radius_cells"] /
        max(ref_desc["equivalent_radius_cells"], 1e-9)
    )
    scores.update({
        "shape_orientation_error_deg": float(orientation_error),
        "shape_linear_scale_ratio": float(scale_ratio),
        "shape_log_scale_error": float(abs(np.log(max(scale_ratio, 1e-9)))),
        "shape_elongation_log_error": float(abs(np.log(
            max(sim_desc["elongation"], 1e-9) /
            max(ref_desc["elongation"], 1e-9)
        ))),
        "shape_radial_nrmse": float(np.sqrt(np.mean(np.square(
            sim_desc["radial_profile"] - ref_desc["radial_profile"]
        )))),
    })
    return scores


def _boundary_distance_scores(sim_mask, ref_mask):
    """Boundary-distance validation in meters for paper-grade spatial diagnostics."""
    sim = np.asarray(sim_mask, dtype=bool)
    ref = np.asarray(ref_mask, dtype=bool)
    if not sim.any() or not ref.any():
        return _empty_boundary_scores()

    scores = _empty_boundary_scores()
    c_sim = _mask_centroid_rc(sim)
    c_ref = _mask_centroid_rc(ref)
    if c_sim is not None and c_ref is not None:
        scores["centroid_error_m"] = float(np.linalg.norm(c_sim - c_ref) * TARGET_RES)
    scores.update(_perimeter_shape_scores(sim, ref))

    try:
        from scipy import ndimage
    except Exception:
        return scores

    struct = np.ones((3, 3), dtype=bool)
    sim_boundary = sim & ~ndimage.binary_erosion(sim, structure=struct, border_value=0)
    ref_boundary = ref & ~ndimage.binary_erosion(ref, structure=struct, border_value=0)
    if not sim_boundary.any() or not ref_boundary.any():
        return scores

    dist_to_ref = ndimage.distance_transform_edt(~ref_boundary) * TARGET_RES
    dist_to_sim = ndimage.distance_transform_edt(~sim_boundary) * TARGET_RES
    d_sim_ref = dist_to_ref[sim_boundary]
    d_ref_sim = dist_to_sim[ref_boundary]
    d = np.concatenate([d_sim_ref, d_ref_sim])
    if d.size:
        scores["boundary_mean_error_m"] = float(np.nanmean(d))
        scores["boundary_p95_error_m"] = float(np.nanpercentile(d, 95))
        scores["boundary_hausdorff_m"] = float(max(np.nanmax(d_sim_ref), np.nanmax(d_ref_sim)))
    return scores


def _spatial_scores(sim_mask, ref_mask):
    if ref_mask is None:
        out = {
            "tp_cells": 0, "fp_cells": 0, "fn_cells": 0,
            "iou": np.nan, "f1": np.nan, "precision": np.nan, "recall": np.nan,
        }
        out.update(_empty_boundary_scores())
        return out
    sim = sim_mask.astype(bool)
    ref = ref_mask.astype(bool)
    tp = int((sim & ref).sum())
    fp = int((sim & ~ref).sum())
    fn = int((~sim & ref).sum())
    iou_den = tp + fp + fn
    f1_den = 2 * tp + fp + fn
    out = {
        "tp_cells": tp,
        "fp_cells": fp,
        "fn_cells": fn,
        "iou": tp / iou_den if iou_den else np.nan,
        "f1": 2 * tp / f1_den if f1_den else np.nan,
        "precision": tp / (tp + fp) if (tp + fp) else np.nan,
        "recall": tp / (tp + fn) if (tp + fn) else np.nan,
    }
    out.update(_boundary_distance_scores(sim, ref))
    return out


def _tolerant_spatial_scores(sim_mask, ref_mask,
                             tolerance_m=VALIDATION_SPATIAL_TOLERANCE_M):
    """Score masks with a symmetric positional tolerance; raw scores stay separate."""
    if ref_mask is None:
        return {
            "tolerance_m": float(tolerance_m),
            "iou": np.nan,
            "f1": np.nan,
            "precision": np.nan,
            "recall": np.nan,
        }
    sim = np.asarray(sim_mask, dtype=bool)
    ref = np.asarray(ref_mask, dtype=bool)
    cells = max(0, int(np.ceil(float(tolerance_m) / float(TARGET_RES))))
    try:
        from scipy import ndimage
        sim_near = ndimage.binary_dilation(sim, iterations=cells) if cells else sim
        ref_near = ndimage.binary_dilation(ref, iterations=cells) if cells else ref
    except Exception:
        sim_near = sim
        ref_near = ref
    precision = float((sim & ref_near).sum()) / max(float(sim.sum()), 1.0)
    recall = float((ref & sim_near).sum()) / max(float(ref.sum()), 1.0)
    denominator = precision + recall
    f1 = 2.0 * precision * recall / denominator if denominator > 0.0 else 0.0
    return {
        "tolerance_m": float(tolerance_m),
        "iou": f1 / max(2.0 - f1, 1e-12),
        "f1": f1,
        "precision": precision,
        "recall": recall,
    }


def compute_daily_validation_rows(arrival, real_mask=None, daily_ref_masks=None,
                                  daily_ref_areas=None):
    """Build daily validation metrics from arrival time and optional references."""
    daily_ref_masks = daily_ref_masks or {}
    daily_ref_areas = daily_ref_areas or {}
    daily_ref_new_masks = daily_increment_masks(daily_ref_masks)
    daily_ref_new_areas = daily_increment_areas(daily_ref_areas)
    total_h = N_STEPS * MIN_PER_STEP / 60.0
    cell_ha = TARGET_RES ** 2 / 1e4
    final_area_ha = float(real_mask.sum()) * cell_ha if real_mask is not None else np.nan
    burned = np.isfinite(arrival)
    rows = []
    prev_sim = np.zeros(arrival.shape, dtype=bool)

    for window in daily_time_windows():
        day = window["day"]
        start_h = max(0.0, float(window["start_h"]))
        end_h = min(float(window["end_h"]), total_h)
        window_hours = max(0.0, end_h - start_h)
        sim = burned & (arrival <= end_h + 1e-9)
        sim_new = sim & ~prev_sim
        prev_sim = sim.copy()
        sim_cells = int(sim.sum())
        new_cells = int(sim_new.sum())

        ref_cum_mask = daily_ref_masks.get(day)
        ref_new_mask = daily_ref_new_masks.get(day)
        ref_source = "daily_increment_perimeter" if ref_new_mask is not None else ""
        if not ref_source and day in daily_ref_new_areas:
            ref_source = "daily_increment_area_csv"
        if not ref_source and real_mask is not None:
            ref_source = "final_perimeter_diagnostic"

        daily_scores = _spatial_scores(sim_new, ref_new_mask)
        cum_score_mask = ref_cum_mask
        if cum_score_mask is None and real_mask is not None:
            cum_score_mask = real_mask
        cumulative_scores = _spatial_scores(sim, cum_score_mask)

        daily_ref_area = daily_ref_areas.get(day)
        if daily_ref_area is not None:
            ref_area = float(daily_ref_area)
            area_source = "daily_area_csv"
        elif ref_cum_mask is not None:
            ref_area = float(ref_cum_mask.sum()) * cell_ha
            area_source = "daily_perimeter"
        elif real_mask is not None:
            ref_area = final_area_ha
            area_source = "final_perimeter_area"
        else:
            ref_area = np.nan
            area_source = ""
        if day in daily_ref_new_areas:
            ref_new_area = float(daily_ref_new_areas[day])
            new_area_source = "daily_area_csv_increment"
        elif ref_new_mask is not None:
            ref_new_area = float(ref_new_mask.sum()) * cell_ha
            new_area_source = "daily_perimeter_increment"
        else:
            ref_new_area = np.nan
            new_area_source = ""

        sim_ha = sim_cells * cell_ha
        sim_new_ha = new_cells * cell_ha
        daily_area_error = (
            sim_new_ha - ref_new_area if np.isfinite(ref_new_area) else np.nan
        )
        cumulative_area_error = (
            sim_ha - ref_area if np.isfinite(ref_area) else np.nan
        )
        final_scores = _spatial_scores(sim, real_mask) if real_mask is not None else None
        rows.append({
            "day": day,
            "window_end_utc": window["window_end_utc"],
            "window_end_local": window.get("window_end_local", ""),
            "window_hours": window_hours,
            "sim_new_ha": sim_new_ha,
            "sim_cumulative_ha": sim_ha,
            "ref_source": ref_source or new_area_source or area_source,
            "ref_new_source": new_area_source,
            "ref_new_ha": ref_new_area,
            "ref_cumulative_ha": ref_area,
            "daily_area_error_ha": daily_area_error,
            "daily_area_error_pct": (daily_area_error / ref_new_area * 100.0)
            if np.isfinite(ref_new_area) and ref_new_area > 0 else np.nan,
            "cumulative_area_error_ha": cumulative_area_error,
            "cumulative_area_error_pct": (cumulative_area_error / ref_area * 100.0)
            if np.isfinite(ref_area) and ref_area > 0 else np.nan,
            "area_error_ha": daily_area_error,
            "area_error_pct": (daily_area_error / ref_new_area * 100.0)
            if np.isfinite(ref_new_area) and ref_new_area > 0 else np.nan,
            "iou": daily_scores["iou"],
            "f1": daily_scores["f1"],
            "precision": daily_scores["precision"],
            "recall": daily_scores["recall"],
            "tp_cells": daily_scores["tp_cells"],
            "fp_cells": daily_scores["fp_cells"],
            "fn_cells": daily_scores["fn_cells"],
            "daily_centroid_error_m": daily_scores["centroid_error_m"],
            "daily_boundary_mean_error_m": daily_scores["boundary_mean_error_m"],
            "daily_boundary_p95_error_m": daily_scores["boundary_p95_error_m"],
            "daily_boundary_hausdorff_m": daily_scores["boundary_hausdorff_m"],
            "daily_shape_orientation_error_deg": daily_scores["shape_orientation_error_deg"],
            "daily_shape_linear_scale_ratio": daily_scores["shape_linear_scale_ratio"],
            "daily_shape_log_scale_error": daily_scores["shape_log_scale_error"],
            "daily_shape_elongation_log_error": daily_scores["shape_elongation_log_error"],
            "daily_shape_radial_nrmse": daily_scores["shape_radial_nrmse"],
            "cumulative_iou": cumulative_scores["iou"],
            "cumulative_f1": cumulative_scores["f1"],
            "cumulative_precision": cumulative_scores["precision"],
            "cumulative_recall": cumulative_scores["recall"],
            "cumulative_tp_cells": cumulative_scores["tp_cells"],
            "cumulative_fp_cells": cumulative_scores["fp_cells"],
            "cumulative_fn_cells": cumulative_scores["fn_cells"],
            "cumulative_centroid_error_m": cumulative_scores["centroid_error_m"],
            "cumulative_boundary_mean_error_m": cumulative_scores["boundary_mean_error_m"],
            "cumulative_boundary_p95_error_m": cumulative_scores["boundary_p95_error_m"],
            "cumulative_boundary_hausdorff_m": cumulative_scores["boundary_hausdorff_m"],
            "cumulative_shape_orientation_error_deg": cumulative_scores["shape_orientation_error_deg"],
            "cumulative_shape_linear_scale_ratio": cumulative_scores["shape_linear_scale_ratio"],
            "cumulative_shape_log_scale_error": cumulative_scores["shape_log_scale_error"],
            "cumulative_shape_elongation_log_error": cumulative_scores["shape_elongation_log_error"],
            "cumulative_shape_radial_nrmse": cumulative_scores["shape_radial_nrmse"],
            "inside_final_precision": final_scores["precision"] if final_scores else np.nan,
            "final_coverage": final_scores["recall"] if final_scores else np.nan,
            "final_area_ha": final_area_ha,
        })
    return rows


