def load_paper_records_csv(path):
    """Load a result CSV while preserving text fields and parsing numeric fields."""
    import csv

    records = []
    if not path or not os.path.exists(path):
        return records
    with open(path, newline="", encoding="utf-8-sig") as f:
        for row in csv.DictReader(f):
            parsed = {}
            for key, value in row.items():
                text = "" if value is None else str(value).strip()
                if text == "":
                    parsed[key] = np.nan
                elif text.lower() in ("true", "false"):
                    parsed[key] = text.lower() == "true"
                else:
                    try:
                        parsed[key] = float(text)
                    except ValueError:
                        parsed[key] = text
            if "day" in parsed and np.isfinite(float(parsed["day"])):
                parsed["day"] = int(float(parsed["day"]))
            records.append(parsed)
    return records


def write_paper_daily_metrics(records, out_csv):
    """Write the full day-level validation table used by paper figures."""
    import csv

