        "ref_cumulative_ha", "cumulative_area_error_ha",
        "cumulative_area_error_pct", "daily_iou", "daily_f1",
        "daily_precision", "daily_recall", "daily_tolerance_m",
        "daily_tolerant_iou", "daily_tolerant_f1", "daily_tolerant_precision",
        "daily_tolerant_recall", "cumulative_iou", "cumulative_f1",
        "cumulative_precision", "cumulative_recall", "daily_centroid_error_m",
        "daily_boundary_mean_error_m", "daily_boundary_p95_error_m",
        "daily_boundary_hausdorff_m", "cumulative_centroid_error_m",
        "cumulative_boundary_mean_error_m", "cumulative_boundary_p95_error_m",
        "cumulative_boundary_hausdorff_m", "wind_mean_speed_mps",
        "wind_dir_from_deg", "attention_feedback_used",
