def write_experiment_manifest(mode, records, out_json):
    import json
    import platform
    import sys

    daily_ref_dir = Path(OFFICIAL_DAILY_REF_PERIM_DIR)
    daily_refs = sorted(daily_ref_dir.glob("*.geojson")) if daily_ref_dir.exists() else []
    inputs = {
        "dem": _file_fingerprint(DEM_PATH),
        "fuel": _file_fingerprint(FUEL_PATH),
        "evt": _file_fingerprint(EVT_PATH),
        "evt_attributes": _file_fingerprint(EVT_ATTRIBUTE_CSV),
        "weather": _file_fingerprint(WEATHER_CSV),
        "background_wind": _file_fingerprint(BACKGROUND_WIND_CSV),
        "station_wind": _file_fingerprint(STATION_WIND_CSV) if STATION_WIND_CSV else {"exists": False},
        "station_metadata": _file_fingerprint(ASOS_STATION_META_CSV),
        "final_perimeter": _file_fingerprint(PERIM_PATH),
        "daily_reference_area": _file_fingerprint(DAILY_REF_AREA_CSV),
        "daily_reference_perimeter_count": len(daily_refs),
    }
    manifest = {
        "mode": mode,
        "created_utc": str(np.datetime64("now", "s")),
        "python": sys.version,
        "platform": platform.platform(),
        "config": _experiment_config_snapshot(),
        "inputs": inputs,
        "records": {
            "count": len(records or []),
            "days": [int(r.get("day")) for r in (records or []) if "day" in r],
        },
    }
    os.makedirs(os.path.dirname(out_json) or ".", exist_ok=True)
    with open(out_json, "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
    print("saved", out_json)
    return manifest


def write_paper_package(records, mode, out_dir=PAPER_OUT_DIR,
                        daily_image_dir=None, snapshots=None,
                        elev=None, ign=None):
    """Write compact result tables and reproducibility metadata for a paper."""
    import csv

    if not records:
        return None
    os.makedirs(out_dir, exist_ok=True)
    safe = _safe_mode_name(mode)
    summary_csv = os.path.join(out_dir, f"{safe}_metric_summary.csv")
    summary_md = os.path.join(out_dir, f"{safe}_summary.md")
    dashboard_png = os.path.join(out_dir, f"{safe}_metric_dashboard.png")
    manifest_json = os.path.join(out_dir, f"{safe}_experiment_manifest.json")

    rows = paper_metric_rows(records)
    with open(summary_csv, "w", newline="", encoding="utf-8") as f:
        fields = ["metric", "n", "mean", "median", "min", "max", "rmse"]
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)

    metric_map = {r["metric"]: r for r in rows}
    last = records[-1] if records else {}
    with open(summary_md, "w", encoding="utf-8") as f:
        f.write(f"# Paper Summary: {mode}\n\n")
        f.write("## Core Validation Metrics\n\n")
        for metric in [
            "daily_iou", "daily_f1", "cumulative_iou", "cumulative_f1",
            "daily_area_error_ha", "cumulative_area_error_ha",
            "daily_boundary_p95_error_km", "cumulative_boundary_p95_error_km",
        ]:
            f.write(f"- {metric}: {_display_metric_value(metric_map.get(metric))}\n")
        f.write("\n## Final/Last Record\n\n")
        for key in [
            "day", "sim_new_ha", "sim_cumulative_ha", "ref_new_ha",
            "ref_cumulative_ha", "daily_iou", "daily_f1",
            "cumulative_iou", "cumulative_f1",
            "cumulative_boundary_p95_error_m",
        ]:
            if key in last:
                f.write(f"- {key}: {last.get(key)}\n")
        f.write("\n## Reproducibility\n\n")
        f.write(f"- Manifest: {os.path.basename(manifest_json)}\n")
        f.write(f"- Metric table: {os.path.basename(summary_csv)}\n")
        f.write(f"- Metric dashboard: {os.path.basename(dashboard_png)}\n")

    plot_paper_metric_dashboard(records, dashboard_png, f"Metric Dashboard: {mode}")
    write_experiment_manifest(mode, records, manifest_json)
    extended_figures = generate_extended_paper_figures(
        records, mode, out_dir=out_dir,
        daily_image_dir=daily_image_dir,
        snapshots=snapshots,
        elev=elev, ign=ign,
    )
    print("saved", summary_csv)
    print("saved", summary_md)
    return {
        "summary_csv": summary_csv,
        "summary_md": summary_md,
        "dashboard_png": dashboard_png,
        "manifest_json": manifest_json,
        "extended_figures": extended_figures,
    }


def draw_daily_validation_map(elev, arrival, ign, real_mask, daily_ref_masks, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches
    from matplotlib.colors import ListedColormap

    burned = np.isfinite(arrival)
    daily_new_refs = daily_increment_masks(daily_ref_masks or {})
    masks = [burned, real_mask] + list(daily_new_refs.values())
    sl = crop_for_daily(elev.shape, masks, ign, pad=58)
    day = arrival_day_index(arrival)
    day_crop = np.ma.masked_invalid(day[sl])
    max_day = int(np.nanmax(day)) if np.isfinite(day).any() else 1
    cmap = ListedColormap(_day_colors(max_day))

    fig, ax = plt.subplots(figsize=(13, 8), facecolor="#111111")
    ax.imshow(_dark_hillshade(elev[sl]), interpolation="bilinear")
    im = ax.imshow(day_crop, cmap=cmap, vmin=0.5, vmax=max_day + 0.5,
                   alpha=0.76, interpolation="nearest")
    _draw_final_perimeter(ax, real_mask[sl] if real_mask is not None else None,
                          linewidth=2.6, linestyle="-", alpha=1.0)
    for d, mask in sorted(daily_new_refs.items()):
        ax.contour(mask[sl].astype(float), levels=[0.5], colors=[_day_color(d)],
                   linewidths=1.0, linestyles="--", alpha=0.78)
    ax.plot(ign[1] - sl[1].start, ign[0] - sl[0].start, marker="*",
            ms=15, color="#ff2020", mec="white", mew=0.7)
    _letter_text_halo(
        ax, 0.02, 0.89,
        "Fill colors indicate simulated burn day; the green line is the observed final "
        "perimeter; dashed lines are observed daily-increment boundaries.",
        transform=ax.transAxes, fontsize=13, ha="left", va="top",
        fontweight="bold",
    )
    handles = [
        mpatches.Patch(color=FINAL_PERIMETER_COLOR, label="Observed final perimeter"),
        mpatches.Patch(color="#e41a1c", label="Simulated burn-day fill"),
        mpatches.Patch(color="#ff2020", label="Ignition point"),
    ]
    _map_legend(ax, handles, loc="lower left", fontsize=8)
    cb = fig.colorbar(im, ax=ax, fraction=0.028, pad=0.012,
                      ticks=range(1, max_day + 1))
    cb.set_label("Simulated reporting day")
    ax.axis("off")
    _apply_lettered_bottom_caption(
        fig, [ax],
        ["simulated burn day with observed daily-increment and final perimeters"],
        "Daily Validation Map",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=145)
    plt.close(fig)
    print("saved", out_png)


def run_daily_validation(arrival, elev, ign, transform, crs, real_mask, out_dir,
                         title="Daily Validation"):
    daily_masks, daily_areas = load_daily_validation_references(transform, crs, elev.shape)
    rows = compute_daily_validation_rows(arrival, real_mask, daily_masks, daily_areas)
    out_csv = os.path.join(out_dir, "daily_validation.csv")
    out_png = os.path.join(out_dir, "daily_validation.png")
    out_map = os.path.join(out_dir, "daily_validation_map.png")
    write_daily_validation_csv(rows, out_csv)
    plot_daily_validation(rows, out_png, title=title)
    draw_daily_validation_map(elev, arrival, ign, real_mask, daily_masks, out_map)
    write_daily_calibration_diagnostics(
        rows,
        os.path.join(out_dir, "daily_calibration_diagnostics.csv"),
        os.path.join(out_dir, "daily_calibration_diagnostics.png"),
    )
    print("saved", out_csv)
    obs_refs = load_observation_validation_references(transform, crs, elev.shape)
    if obs_refs:
        obs_rows = compute_observation_validation_rows(arrival, obs_refs, real_mask)
        obs_csv = os.path.join(out_dir, "observation_validation.csv")
        obs_png = os.path.join(out_dir, "observation_validation.png")
        write_observation_validation_csv(obs_rows, obs_csv)
        plot_observation_validation(obs_rows, obs_png, title=title.replace("Daily", "Observation-Time"))
        print("saved", obs_csv)
    write_paper_package(rows, title)
    return rows


class PerturbedWindProvider:
    """Thin wrapper for ensemble member wind uncertainty."""
    def __init__(self, base, speed_scale=1.0, dir_offset_deg=0.0):
        self.base = base
        self.speed_scale = float(speed_scale)
        self.dir_offset_deg = float(dir_offset_deg)
        self.t0 = base.t0
        self.shape = base.shape

    def get(self, step):
        speed, direction = self.base.get(step)
        return (speed * self.speed_scale).astype("float32"), (
            (direction + self.dir_offset_deg) % 360.0
        ).astype("float32")


def plot_ensemble_daily_area(days, cum_area, out_png, ref_area_ha=np.nan):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    p10 = np.nanpercentile(cum_area, 10, axis=0)
    p50 = np.nanpercentile(cum_area, 50, axis=0)
    p90 = np.nanpercentile(cum_area, 90, axis=0)
    mean = np.nanmean(cum_area, axis=0)

    fig, ax = plt.subplots(figsize=(10, 5.4))
    ax.fill_between(days, p10, p90, color="#9ecae1", alpha=0.45,
                    label="P10-P90 ensemble range")
    ax.plot(days, p50, "-o", color="#08519c", lw=2.0, label="Ensemble median")
    ax.plot(days, mean, "--", color="#41ab5d", lw=1.6, label="Ensemble mean")
    if np.isfinite(ref_area_ha):
        ax.axhline(ref_area_ha, color="#d7301f", lw=1.6, ls="--",
                   label="Observed final burned area")
    ax.set_xlabel("Reporting day")
    ax.set_ylabel("Cumulative burned area (ha)")
    ax.set_title("Ensemble Cumulative Burned Area", fontweight="bold")
    ax.legend()
    ax.grid(alpha=0.28)
    _apply_lettered_bottom_caption(
        fig, [ax],
        ["ensemble median, mean, and P10-P90 range of cumulative burned area"],
        "Ensemble Cumulative Burned Area",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=145)
    plt.close(fig)
    print("saved", out_png)


def plot_ensemble_validation(member_daily_rows, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    if not member_daily_rows:
        return
    days = sorted({int(r["day"]) for r in member_daily_rows})

    def day_percentiles(field):
        vals = []
        for day in days:
            arr = np.asarray([
                float(r.get(field, np.nan))
                for r in member_daily_rows if int(r["day"]) == day
            ], dtype=float)
            vals.append((
                float(np.nanpercentile(arr, 10)),
                float(np.nanpercentile(arr, 50)),
                float(np.nanpercentile(arr, 90)),
            ))
        return np.asarray(vals, dtype=float)

    area_err = day_percentiles("area_error_pct")
    final_precision = day_percentiles("inside_final_precision")
    final_coverage = day_percentiles("final_coverage")
    iou = day_percentiles("iou")
    x = np.asarray(days, dtype=int)

    fig, axes = plt.subplots(1, 2, figsize=(14, 5.2))
    axes[0].fill_between(x, area_err[:, 0], area_err[:, 2],
                         color="#fdd0a2", alpha=0.5, label="P10-P90 ensemble range")
    axes[0].plot(x, area_err[:, 1], "-o", color="#e6550d", lw=1.9,
                 label="Median area error")
    axes[0].axhline(0.0, color="#444444", lw=0.9, alpha=0.7)
    axes[0].set_xlabel("Reporting day")
    axes[0].set_ylabel("Daily burned-area increment error (%)")
    axes[0].set_title("Daily Burned-Area Increment Error", fontweight="bold")
    axes[0].legend(fontsize=8)
    axes[0].grid(alpha=0.28)

    for p, color, label in [
        (final_precision, "#238b45", "Precision within observed final perimeter"),
        (final_coverage, "#756bb1", "Coverage of observed final perimeter"),
        (iou, "#08519c", "Daily-increment IoU"),
    ]:
        axes[1].fill_between(x, p[:, 0], p[:, 2], color=color, alpha=0.14)
        axes[1].plot(x, p[:, 1], "-o", color=color, lw=1.7, label=label)
    axes[1].set_xlabel("Reporting day")
    axes[1].set_ylabel("Score")
    axes[1].set_ylim(0, 1.02)
    axes[1].set_title("Daily Spatial Validation", fontweight="bold")
    axes[1].legend(fontsize=8)
    axes[1].grid(alpha=0.28)

    fig.suptitle("Ensemble Daily Validation", fontweight="bold")
    _apply_lettered_bottom_caption(
        fig, axes,
        [
            "ensemble uncertainty in daily burned-area increment error",
            "ensemble uncertainty in spatial-validation scores relative to observed perimeters",
        ],
        "Ensemble Daily Validation",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=145)
    plt.close(fig)
    print("saved", out_png)


def draw_ensemble_probability_map(elev, probability, ign, real_mask, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches

    fire_like = probability > 0.02
    sl = crop_for_daily(elev.shape, [fire_like, real_mask], ign, pad=58)
    prob_crop = np.ma.masked_where(probability[sl] <= 0.0, probability[sl])

    fig, ax = plt.subplots(figsize=(13, 8), facecolor="#111111")
    ax.imshow(_dark_hillshade(elev[sl]), interpolation="bilinear")
    im = ax.imshow(prob_crop, cmap="inferno", vmin=0, vmax=1,
                   alpha=0.82, interpolation="nearest")
    for level, color, lw in [(0.1, "#fee391", 0.9), (0.5, "#fc4e2a", 1.4), (0.9, "#ffffff", 1.3)]:
        if np.nanmax(probability) >= level:
            ax.contour(probability[sl], levels=[level], colors=color,
                       linewidths=lw, alpha=0.9)
    _draw_final_perimeter(ax, real_mask[sl] if real_mask is not None else None,
                          linewidth=2.6, linestyle="--", alpha=1.0)
    ax.plot(ign[1] - sl[1].start, ign[0] - sl[0].start, marker="*",
            ms=15, color="#ff2020", mec="white", mew=0.7)
    _letter_text_halo(
        ax, 0.02, 0.89,
        "Burn probability is the fraction of ensemble members in which a cell burns "
        "by the end of the simulation.",
        transform=ax.transAxes, fontsize=13, ha="left", va="top",
        fontweight="bold",
    )
    handles = [
        mpatches.Patch(color="#fc4e2a", label="50% burn-probability contour"),
        mpatches.Patch(color=FINAL_PERIMETER_COLOR, label="Observed final perimeter"),
        mpatches.Patch(color="#ff2020", label="Ignition point"),
    ]
    _map_legend(ax, handles, loc="lower left", fontsize=8)
    cb = fig.colorbar(im, ax=ax, fraction=0.028, pad=0.012)
    cb.set_label("Burn probability")
    ax.axis("off")
    _apply_lettered_bottom_caption(
        fig, [ax],
        ["ensemble terminal burn probability with 10%, 50%, and 90% contours"],
        "Ensemble Burn Probability",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=145)
    plt.close(fig)
    print("saved", out_png)


def verify_ensemble_probabilities(daily_probability, daily_references, out_dir):
    """Write proper probabilistic scores and reliability diagnostics by day."""
    import csv
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    metric_rows = []
    reliability_rows = []
    thresholds = (0.10, 0.25, 0.50, 0.75, 0.90)
    bins = np.linspace(0.0, 1.0, 11)
    for day in sorted(daily_probability):
        reference = daily_references.get(day)
        if reference is None:
            continue
        probability = np.clip(np.asarray(daily_probability[day], dtype=float), 0.0, 1.0)
        observed = np.asarray(reference, dtype=bool)
        evaluation = observed | (probability >= 0.01)
        try:
            from scipy import ndimage
            evaluation = ndimage.binary_dilation(evaluation, iterations=20)
        except Exception:
            pass
        if not evaluation.any():
            continue
        p = probability[evaluation]
        y = observed[evaluation].astype(float)
        brier = float(np.mean((p - y) ** 2))
        eps = 1e-6
        log_score = float(-np.mean(y * np.log(np.clip(p, eps, 1.0)) +
                                   (1.0 - y) * np.log(np.clip(1.0 - p, eps, 1.0))))
        for threshold in thresholds:
            predicted = probability >= threshold
            scores = _spatial_scores(predicted, observed)
            metric_rows.append({
                "day": int(day),
                "threshold": float(threshold),
                "brier_score": brier,
                "log_score": log_score,
                "iou": scores["iou"],
                "f1": scores["f1"],
                "precision": scores["precision"],
                "recall_coverage": scores["recall"],
                "predicted_area_ha": float(predicted.sum()) * TARGET_RES ** 2 / 1e4,
                "observed_area_ha": float(observed.sum()) * TARGET_RES ** 2 / 1e4,
            })
        bin_index = np.clip(np.digitize(p, bins, right=False) - 1, 0, len(bins) - 2)
        for index in range(len(bins) - 1):
            selected = bin_index == index
            if not selected.any():
                continue
            reliability_rows.append({
                "day": int(day),
                "bin_lower": float(bins[index]),
                "bin_upper": float(bins[index + 1]),
                "forecast_probability_mean": float(np.mean(p[selected])),
                "observed_frequency": float(np.mean(y[selected])),
                "cell_count": int(selected.sum()),
            })

    if not metric_rows:
        return []
    metric_csv = os.path.join(out_dir, "ensemble_probability_metrics.csv")
    reliability_csv = os.path.join(out_dir, "ensemble_reliability.csv")
    with open(metric_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=list(metric_rows[0].keys()))
        writer.writeheader(); writer.writerows(metric_rows)
    with open(reliability_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=list(reliability_rows[0].keys()))
        writer.writeheader(); writer.writerows(reliability_rows)

    half = [row for row in metric_rows if abs(row["threshold"] - 0.5) < 1e-9]
    days = np.asarray([row["day"] for row in half], dtype=int)
    fig, axes = plt.subplots(1, 3, figsize=(14.5, 4.8), facecolor="white")
    axes[0].plot(days, [row["brier_score"] for row in half], "-o", color="#d7301f")
    axes[0].set_xlabel("Reporting day"); axes[0].set_ylabel("Brier score")
    axes[0].grid(alpha=0.25)

    if reliability_rows:
        centers = []
        frequencies = []
        for index in range(len(bins) - 1):
            group = [row for row in reliability_rows if abs(row["bin_lower"] - bins[index]) < 1e-9]
            if not group:
                continue
            counts = np.asarray([row["cell_count"] for row in group], dtype=float)
            centers.append(float(np.average([row["forecast_probability_mean"] for row in group], weights=counts)))
            frequencies.append(float(np.average([row["observed_frequency"] for row in group], weights=counts)))
        axes[1].plot([0, 1], [0, 1], "--", color="#777777",
                     label="Perfect reliability")
        axes[1].plot(centers, frequencies, "-o", color="#08519c",
                     label="Ensemble reliability")
    axes[1].set_xlim(0, 1); axes[1].set_ylim(0, 1)
    axes[1].set_xlabel("Forecast probability"); axes[1].set_ylabel("Observed frequency")
    axes[1].grid(alpha=0.25); axes[1].legend(fontsize=8)

    axes[2].plot(days, [row["recall_coverage"] for row in half], "-o",
                 color="#238b45", label="Coverage of observed burned area")
    axes[2].plot(days, [row["precision"] for row in half], "-s",
                 color="#756bb1", label="Forecast precision")
    axes[2].set_ylim(0, 1.02); axes[2].set_xlabel("Reporting day"); axes[2].set_ylabel("Score")
    axes[2].grid(alpha=0.25); axes[2].legend(fontsize=8)
    _apply_lettered_bottom_caption(
        fig, axes,
        ["daily Brier score", "aggregate reliability diagram",
         "coverage and precision at the 50% burn-probability threshold"],
        "Ensemble Probability Verification",
    )
    out_png = os.path.join(out_dir, "ensemble_probability_verification.png")
    fig.savefig(out_png, dpi=170, bbox_inches="tight")
    plt.close(fig)
    print("saved", metric_csv)
    print("saved", reliability_csv)
    print("saved", out_png)
    return metric_rows


def plot_ensemble_rank_sensitivity(member_rows, out_csv, out_png):
    """Estimate first-pass parameter sensitivity from ensemble Spearman ranks."""
    import csv
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    inputs = ["wind_scale", "wind_dir_offset_deg", "fuel_scale",
              "spot_prob_scale", "spot_dist_scale"]
    outputs = ["final_burned_ha", "final_iou", "final_f1", "final_boundary_p95_error_m"]
    rows = []
    matrix = np.full((len(outputs), len(inputs)), np.nan, dtype=float)
    try:
        from scipy.stats import spearmanr
    except Exception:
        spearmanr = None
    for i, output in enumerate(outputs):
        for j, parameter in enumerate(inputs):
            x = np.asarray([row.get(parameter, np.nan) for row in member_rows], dtype=float)
            y = np.asarray([row.get(output, np.nan) for row in member_rows], dtype=float)
            valid = np.isfinite(x) & np.isfinite(y)
            if valid.sum() >= 4 and np.nanstd(x[valid]) > 0 and np.nanstd(y[valid]) > 0:
                if spearmanr is not None:
                    rho, pvalue = spearmanr(x[valid], y[valid])
                else:
                    rho = np.corrcoef(np.argsort(np.argsort(x[valid])),
                                      np.argsort(np.argsort(y[valid])))[0, 1]
                    pvalue = np.nan
            else:
                rho = pvalue = np.nan
            matrix[i, j] = rho
            rows.append({"parameter": parameter, "output": output,
                         "spearman_rho": rho, "p_value": pvalue,
                         "n": int(valid.sum())})
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
        writer.writeheader(); writer.writerows(rows)
    fig, ax = plt.subplots(figsize=(10, 5.4), facecolor="white")
    im = ax.imshow(matrix, cmap="RdBu_r", vmin=-1, vmax=1, aspect="auto")
    ax.set_xticks(np.arange(len(inputs)), inputs, rotation=25, ha="right")
    ax.set_yticks(np.arange(len(outputs)), outputs)
    for i in range(len(outputs)):
        for j in range(len(inputs)):
            if np.isfinite(matrix[i, j]):
                ax.text(j, i, f"{matrix[i, j]:.2f}", ha="center", va="center",
                        color="white" if abs(matrix[i, j]) > 0.55 else "black")
    fig.colorbar(im, ax=ax, fraction=0.035, pad=0.02, label="Spearman rank correlation")
    _apply_lettered_bottom_caption(
        fig, [ax], ["rank-based sensitivity of final outputs to ensemble perturbations"],
        "Ensemble Parameter Sensitivity",
    )
    fig.savefig(out_png, dpi=170, bbox_inches="tight")
    plt.close(fig)
    print("saved", out_csv)
    print("saved", out_png)
    return rows


def run_ensemble(elev, fuel, wind, transform, crs, real_mask=None,
                 members=ENSEMBLE_MEMBERS):
    import csv
    global SPOT_PROB, SPOT_DIST_K

    members = max(1, int(members))
    os.makedirs(ENSEMBLE_OUT_DIR, exist_ok=True)
    daily_masks, daily_areas = load_daily_validation_references(transform, crs, elev.shape)

    if FUEL_PATH and os.path.exists(FUEL_PATH):
        code = load_fbfm40_codes(FUEL_PATH, transform, crs, elev.shape)
        evt_codes = load_evt_codes(EVT_PATH, transform, crs, elev.shape)
        is_building, veg_q, veg_crit = build_wui_layers(code, evt_codes=evt_codes)
    else:
        is_building = veg_q = veg_crit = None

    prob_sum = np.zeros(elev.shape, dtype="float32")
    probability_days = sorted(daily_masks)[:DAILY_REFERENCE_MAX_DAYS]
    daily_prob_sum = {
        int(day): np.zeros(elev.shape, dtype="float32") for day in probability_days
    }
    window_by_day = {int(window["day"]): window for window in daily_time_windows()}
    member_daily_rows = []
    member_final_rows = []
    cum_by_member = []
    ign = None
    cell_ha = TARGET_RES ** 2 / 1e4
    ref_area_ha = float(real_mask.sum()) * cell_ha if real_mask is not None else np.nan
    base_spot_prob = SPOT_PROB
    base_spot_dist_k = SPOT_DIST_K

    print(f"Running CA ensemble: {members} member(s)")
    for member in range(1, members + 1):
        seed = SEED + 1000 + member
        rng = np.random.default_rng(seed)
        wind_scale = float(np.clip(rng.lognormal(0.0, ENSEMBLE_WIND_SPEED_SIGMA), 0.75, 1.25))
        wind_dir_offset = float(np.clip(rng.normal(0.0, ENSEMBLE_WIND_DIR_SIGMA_DEG), -28.0, 28.0))
        fuel_scale = float(np.clip(rng.lognormal(0.0, ENSEMBLE_FUEL_SCALE_SIGMA), 0.85, 1.15))
        spot_prob_scale = float(np.clip(rng.lognormal(0.0, 0.18), 0.65, 1.55))
        spot_dist_scale = float(np.clip(rng.lognormal(0.0, 0.12), 0.75, 1.35))
        member_fuel = fuel.copy()
        burnable = member_fuel > 0.02
        member_fuel[burnable] = np.clip(member_fuel[burnable] * fuel_scale, 0.0, 1.3)
        member_wind = PerturbedWindProvider(wind, wind_scale, wind_dir_offset)

        print(f"  member {member}/{members}: seed={seed}, wind_scale={wind_scale:.3f}, "
              f"dir_offset={wind_dir_offset:+.1f} deg, fuel_scale={fuel_scale:.3f}, "
              f"spot_prob={spot_prob_scale:.2f}, spot_dist={spot_dist_scale:.2f}")
        SPOT_PROB = base_spot_prob * spot_prob_scale
        SPOT_DIST_K = base_spot_dist_k * spot_dist_scale
        try:
            state, history, dims, burned_counts, ign, arrival = run_ca(
                elev, member_fuel, member_wind, transform, crs,
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                seed=seed,
                calibrate_daily=False,
            )
        finally:
            SPOT_PROB = base_spot_prob
            SPOT_DIST_K = base_spot_dist_k
        burned = np.isfinite(arrival)
        prob_sum += burned.astype("float32")
        for day in probability_days:
            window = window_by_day.get(int(day))
            if window is None:
                continue
            cumulative = burned & (arrival <= float(window["end_h"]) + 1e-9)
            daily_prob_sum[int(day)] += cumulative.astype("float32")

        rows = compute_daily_validation_rows(arrival, real_mask, daily_masks, daily_areas)
        cum_by_member.append([r["sim_cumulative_ha"] for r in rows])
        for row in rows:
            out = dict(row)
            out.update({
                "member": member,
                "seed": seed,
                "wind_scale": wind_scale,
                "wind_dir_offset_deg": wind_dir_offset,
                "fuel_scale": fuel_scale,
                "spot_prob_scale": spot_prob_scale,
                "spot_dist_scale": spot_dist_scale,
            })
            member_daily_rows.append(out)
        final = rows[-1] if rows else {}
        member_final_rows.append({
            "member": member,
            "seed": seed,
            "final_burned_ha": float(burned.sum()) * cell_ha,
            "final_iou": final.get("cumulative_iou", np.nan),
            "final_f1": final.get("cumulative_f1", np.nan),
            "final_centroid_error_m": final.get("cumulative_centroid_error_m", np.nan),
            "final_boundary_p95_error_m": final.get("cumulative_boundary_p95_error_m", np.nan),
            "final_boundary_hausdorff_m": final.get("cumulative_boundary_hausdorff_m", np.nan),
            "inside_final_precision": final.get("inside_final_precision", np.nan),
            "final_coverage": final.get("final_coverage", np.nan),
            "wind_scale": wind_scale,
            "wind_dir_offset_deg": wind_dir_offset,
            "fuel_scale": fuel_scale,
            "spot_prob_scale": spot_prob_scale,
            "spot_dist_scale": spot_dist_scale,
            "fractal_dimension": dims[-1] if dims else np.nan,
        })

    probability = prob_sum / float(members)
    np.save(os.path.join(ENSEMBLE_OUT_DIR, "burn_probability.npy"), probability)
    daily_probability = {
        day: values / float(members) for day, values in daily_prob_sum.items()
    }
    if daily_probability:
        np.savez_compressed(
            os.path.join(ENSEMBLE_OUT_DIR, "daily_burn_probability.npz"),
            **{f"day{day:02d}": values for day, values in daily_probability.items()},
        )

    daily_csv = os.path.join(ENSEMBLE_OUT_DIR, "ensemble_members_daily.csv")
    if member_daily_rows:
        fields = [
            "member", "seed", "day", "window_end_utc", "sim_new_ha",
            "sim_cumulative_ha", "ref_source", "ref_new_ha", "ref_cumulative_ha",
            "area_error_ha", "area_error_pct", "iou", "f1", "precision",
            "recall", "cumulative_iou", "cumulative_f1",
            "cumulative_precision", "cumulative_recall",
            "daily_centroid_error_m", "daily_boundary_mean_error_m",
            "daily_boundary_p95_error_m", "daily_boundary_hausdorff_m",
            "cumulative_centroid_error_m", "cumulative_boundary_mean_error_m",
            "cumulative_boundary_p95_error_m", "cumulative_boundary_hausdorff_m",
            "inside_final_precision", "final_coverage",
            "wind_scale", "wind_dir_offset_deg", "fuel_scale",
            "spot_prob_scale", "spot_dist_scale",
        ]
        with open(daily_csv, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fields)
            writer.writeheader()
            for row in member_daily_rows:
                writer.writerow({k: row.get(k, "") for k in fields})
        print("saved", daily_csv)

    final_csv = os.path.join(ENSEMBLE_OUT_DIR, "ensemble_members_final.csv")
    with open(final_csv, "w", newline="", encoding="utf-8") as f:
        fields = list(member_final_rows[0].keys()) if member_final_rows else []
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        writer.writerows(member_final_rows)
    print("saved", final_csv)

    cum = np.asarray(cum_by_member, dtype=float)
    days = np.arange(1, cum.shape[1] + 1) if cum.size else np.arange(1, 2)
    summary_csv = os.path.join(ENSEMBLE_OUT_DIR, "ensemble_summary.csv")
    with open(summary_csv, "w", newline="", encoding="utf-8") as f:
        fields = ["day", "cum_p10_ha", "cum_median_ha", "cum_mean_ha", "cum_p90_ha"]
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        if cum.size:
            for i, day in enumerate(days):
                writer.writerow({
                    "day": int(day),
                    "cum_p10_ha": float(np.nanpercentile(cum[:, i], 10)),
                    "cum_median_ha": float(np.nanpercentile(cum[:, i], 50)),
                    "cum_mean_ha": float(np.nanmean(cum[:, i])),
                    "cum_p90_ha": float(np.nanpercentile(cum[:, i], 90)),
                })
    print("saved", summary_csv)

    if cum.size:
        plot_ensemble_daily_area(
            days, cum, os.path.join(ENSEMBLE_OUT_DIR, "ensemble_daily_area.png"),
            ref_area_ha=ref_area_ha,
        )
    plot_ensemble_validation(
        member_daily_rows,
        os.path.join(ENSEMBLE_OUT_DIR, "ensemble_daily_validation.png"),
    )
    if ign is None:
        ign = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
    draw_ensemble_probability_map(
        elev, probability, ign, real_mask,
        os.path.join(ENSEMBLE_OUT_DIR, "ensemble_burn_probability.png"),
    )
    verify_ensemble_probabilities(
        daily_probability, daily_masks, ENSEMBLE_OUT_DIR
    )
    plot_ensemble_rank_sensitivity(
        member_final_rows,
        os.path.join(ENSEMBLE_OUT_DIR, "ensemble_rank_sensitivity.csv"),
        os.path.join(ENSEMBLE_OUT_DIR, "ensemble_rank_sensitivity.png"),
    )
    print("saved", os.path.join(ENSEMBLE_OUT_DIR, "burn_probability.npy"))
    return probability, member_final_rows


def wind_scenario_definitions():
    """Deterministic wind-field scenarios for publication-style uncertainty maps."""
    return [
        {
            "name": "raw_windninja",
            "label": "Raw WindNinja without station correction",
            "wind_kind": "windninja",
            "speed_scale": 1.0,
            "dir_offset_deg": 0.0,
            "spot_prob_scale": 1.0,
            "spot_dist_scale": 1.0,
        },
        {
            "name": "station_corrected",
            "label": "Station-corrected WindNinja",
            "wind_kind": "corrected",
            "speed_scale": 1.0,
            "dir_offset_deg": 0.0,
            "spot_prob_scale": 1.0,
            "spot_dist_scale": 1.0,
        },
        *[
            {
                "name": f"dir_{offset:+d}".replace("+", "plus").replace("-", "minus"),
                "label": f"Station-corrected wind direction {offset:+d} deg",
                "wind_kind": "corrected",
                "speed_scale": 1.0,
                "dir_offset_deg": float(offset),
                "spot_prob_scale": 1.0,
                "spot_dist_scale": 1.0,
            }
            for offset in (-45, -30, -15, 15, 30, 45)
        ],
        *[
            {
                "name": f"speed_{int(scale * 100):03d}",
                "label": f"Station-corrected wind speed x{scale:.1f}",
                "wind_kind": "corrected",
                "speed_scale": float(scale),
                "dir_offset_deg": 0.0,
                "spot_prob_scale": 1.0,
                "spot_dist_scale": 1.0,
            }
            for scale in (0.8, 0.9, 1.1, 1.2)
        ],
        {
            "name": "gust_spotting",
            "label": "Strong gust and spotting scenario",
            "wind_kind": "corrected",
            "speed_scale": 1.15,
            "dir_offset_deg": 0.0,
            "spot_prob_scale": 1.65,
            "spot_dist_scale": 1.40,
        },
    ]


def run_wind_scenario_ensemble(elev, fuel, wind, transform, crs, real_mask=None,
                               output_dir=None, max_scenarios=None):
    """Run fixed wind-field scenarios and output terminal/daily burn probability."""
    import csv
    global SPOT_PROB, SPOT_DIST_K

    out_dir = str(output_dir or WIND_SCENARIO_ENSEMBLE_OUT_DIR)
    os.makedirs(out_dir, exist_ok=True)
    scenarios = wind_scenario_definitions()
    if max_scenarios is not None and int(max_scenarios) > 0:
        scenarios = scenarios[:int(max_scenarios)]
    if not scenarios:
        return None, []

    daily_masks, daily_areas = load_daily_validation_references(transform, crs, elev.shape)
    if FUEL_PATH and os.path.exists(FUEL_PATH):
        code = load_fbfm40_codes(FUEL_PATH, transform, crs, elev.shape)
        evt_codes = load_evt_codes(EVT_PATH, transform, crs, elev.shape)
        is_building, veg_q, veg_crit = build_wui_layers(code, evt_codes=evt_codes)
    else:
        is_building = veg_q = veg_crit = None

    probability_days = sorted(daily_masks)[:DAILY_REFERENCE_MAX_DAYS]
    window_by_day = {int(window["day"]): window for window in daily_time_windows()}
    prob_sum = np.zeros(elev.shape, dtype="float32")
    daily_prob_sum = {
        int(day): np.zeros(elev.shape, dtype="float32") for day in probability_days
    }
    cell_ha = TARGET_RES ** 2 / 1e4
    ref_area_ha = float(real_mask.sum()) * cell_ha if real_mask is not None else np.nan
    member_daily_rows = []
    member_final_rows = []
    cum_by_member = []
    base_spot_prob = SPOT_PROB
    base_spot_dist_k = SPOT_DIST_K
    ign = None

    print(f"Running wind-scenario ensemble: {len(scenarios)} scenario(s)")
    for index, scenario in enumerate(scenarios, start=1):
        scenario_name = scenario["name"]
        scenario_seed = SEED + 24000
        scenario_base_wind = _experiment_wind_provider(
            scenario.get("wind_kind", "corrected"),
            transform, crs, elev.shape, wind,
        )
        scenario_wind = PerturbedWindProvider(
            scenario_base_wind,
            speed_scale=float(scenario.get("speed_scale", 1.0)),
            dir_offset_deg=float(scenario.get("dir_offset_deg", 0.0)),
        )
        SPOT_PROB = base_spot_prob * float(scenario.get("spot_prob_scale", 1.0))
        SPOT_DIST_K = base_spot_dist_k * float(scenario.get("spot_dist_scale", 1.0))
        print(
            f"  scenario {index}/{len(scenarios)} {scenario_name}: "
            f"wind={scenario.get('wind_kind')}, speed={scenario.get('speed_scale', 1.0):.2f}, "
            f"dir={scenario.get('dir_offset_deg', 0.0):+.0f}, "
            f"spot_prob={scenario.get('spot_prob_scale', 1.0):.2f}, "
            f"spot_dist={scenario.get('spot_dist_scale', 1.0):.2f}"
        )
        try:
            state, history, dims, burned_counts, ign, arrival = run_ca(
                elev, fuel.copy(), scenario_wind, transform, crs,
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                seed=scenario_seed,
                calibrate_daily=False,
            )
        finally:
            SPOT_PROB = base_spot_prob
            SPOT_DIST_K = base_spot_dist_k

        burned = np.isfinite(arrival)
        prob_sum += burned.astype("float32")
        for day in probability_days:
            window = window_by_day.get(int(day))
            if window is None:
                continue
            cumulative = burned & (arrival <= float(window["end_h"]) + 1e-9)
            daily_prob_sum[int(day)] += cumulative.astype("float32")

        rows = compute_daily_validation_rows(arrival, real_mask, daily_masks, daily_areas)
        cum_by_member.append([r["sim_cumulative_ha"] for r in rows])
        for row in rows:
            out = dict(row)
            out.update({
                "member": index,
                "scenario": scenario_name,
                "scenario_label": scenario["label"],
                "seed": scenario_seed,
                "wind_kind": scenario.get("wind_kind", "corrected"),
                "wind_scale": float(scenario.get("speed_scale", 1.0)),
                "wind_dir_offset_deg": float(scenario.get("dir_offset_deg", 0.0)),
                "fuel_scale": 1.0,
                "spot_prob_scale": float(scenario.get("spot_prob_scale", 1.0)),
                "spot_dist_scale": float(scenario.get("spot_dist_scale", 1.0)),
            })
            member_daily_rows.append(out)
        final = rows[-1] if rows else {}
        member_final_rows.append({
            "member": index,
            "scenario": scenario_name,
            "scenario_label": scenario["label"],
            "seed": scenario_seed,
            "wind_kind": scenario.get("wind_kind", "corrected"),
            "final_burned_ha": float(burned.sum()) * cell_ha,
            "final_iou": final.get("cumulative_iou", np.nan),
            "final_f1": final.get("cumulative_f1", np.nan),
            "final_centroid_error_m": final.get("cumulative_centroid_error_m", np.nan),
            "final_boundary_p95_error_m": final.get("cumulative_boundary_p95_error_m", np.nan),
            "final_boundary_hausdorff_m": final.get("cumulative_boundary_hausdorff_m", np.nan),
            "inside_final_precision": final.get("inside_final_precision", np.nan),
            "final_coverage": final.get("final_coverage", np.nan),
            "wind_scale": float(scenario.get("speed_scale", 1.0)),
            "wind_dir_offset_deg": float(scenario.get("dir_offset_deg", 0.0)),
            "fuel_scale": 1.0,
            "spot_prob_scale": float(scenario.get("spot_prob_scale", 1.0)),
            "spot_dist_scale": float(scenario.get("spot_dist_scale", 1.0)),
            "fractal_dimension": dims[-1] if dims else np.nan,
        })

    scenario_count = float(len(scenarios))
    probability = prob_sum / scenario_count
    np.save(os.path.join(out_dir, "wind_scenario_burn_probability.npy"), probability)
    daily_probability = {
        day: values / scenario_count for day, values in daily_prob_sum.items()
    }
    if daily_probability:
        np.savez_compressed(
            os.path.join(out_dir, "wind_scenario_daily_burn_probability.npz"),
            **{f"day{day:02d}": values for day, values in daily_probability.items()},
        )

    daily_csv = os.path.join(out_dir, "wind_scenario_members_daily.csv")
    if member_daily_rows:
        fields = [
            "member", "scenario", "scenario_label", "seed", "wind_kind",
            "day", "window_end_utc", "sim_new_ha", "sim_cumulative_ha",
            "ref_source", "ref_new_ha", "ref_cumulative_ha",
            "area_error_ha", "area_error_pct", "iou", "f1", "precision",
            "recall", "cumulative_iou", "cumulative_f1",
            "cumulative_precision", "cumulative_recall",
            "daily_centroid_error_m", "daily_boundary_mean_error_m",
            "daily_boundary_p95_error_m", "daily_boundary_hausdorff_m",
            "cumulative_centroid_error_m", "cumulative_boundary_mean_error_m",
            "cumulative_boundary_p95_error_m", "cumulative_boundary_hausdorff_m",
            "inside_final_precision", "final_coverage",
            "wind_scale", "wind_dir_offset_deg", "fuel_scale",
            "spot_prob_scale", "spot_dist_scale",
        ]
        with open(daily_csv, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
            writer.writeheader()
            writer.writerows(member_daily_rows)
        print("saved", daily_csv)

    final_csv = os.path.join(out_dir, "wind_scenario_members_final.csv")
    with open(final_csv, "w", newline="", encoding="utf-8") as f:
        fields = list(member_final_rows[0].keys()) if member_final_rows else []
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        writer.writerows(member_final_rows)
    print("saved", final_csv)

    cum = np.asarray(cum_by_member, dtype=float)
    if cum.size:
        days = np.arange(1, cum.shape[1] + 1)
        plot_ensemble_daily_area(
            days, cum, os.path.join(out_dir, "wind_scenario_daily_area.png"),
            ref_area_ha=ref_area_ha,
        )
    plot_ensemble_validation(
        member_daily_rows,
        os.path.join(out_dir, "wind_scenario_daily_validation.png"),
    )
    if ign is None:
        ign = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
    draw_ensemble_probability_map(
        elev, probability, ign, real_mask,
        os.path.join(out_dir, "wind_scenario_burn_probability.png"),
    )
    verify_ensemble_probabilities(daily_probability, daily_masks, out_dir)
    plot_ensemble_rank_sensitivity(
        member_final_rows,
        os.path.join(out_dir, "wind_scenario_rank_sensitivity.csv"),
        os.path.join(out_dir, "wind_scenario_rank_sensitivity.png"),
    )
    return probability, member_final_rows


def _global_settings_snapshot(keys):
    return {key: globals().get(key) for key in keys}


def _restore_global_settings(snapshot):
    for key, value in snapshot.items():
        globals()[key] = value


def _apply_global_settings(settings):
    for key, value in settings.items():
        globals()[key] = value


