def plot_calibration_search_summary(summary_rows, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    if not summary_rows:
        return
    rows = sorted(summary_rows, key=lambda row: float(row.get("selection_objective", np.inf)))
    labels = [row["variant_label"] for row in rows]
    x = np.arange(len(rows))

    def values(key):
        return np.asarray([float(row.get(key, np.nan)) for row in rows], dtype=float)

    fig, axes = plt.subplots(2, 2, figsize=(14, 8.5), facecolor="white")
    colors = ["#2166ac", "#d6604d", "#1b9e77", "#984ea3", "#e6ab02", "#666666", "#a6761d"]
    bar_colors = [colors[i % len(colors)] for i in range(len(rows))]
    axes[0, 0].bar(x, values("selection_objective"), color=bar_colors)
    axes[0, 0].set_ylabel("Objective, lower is better")
    axes[0, 0].set_xticks(x, labels, rotation=18, ha="right")

    axes[0, 1].bar(x, values("all_mean_tolerant_f1"), color=bar_colors)
    axes[0, 1].set_ylim(0, 1.02)
    axes[0, 1].set_ylabel("Mean tolerant F1")
    axes[0, 1].set_xticks(x, labels, rotation=18, ha="right")

    axes[1, 0].bar(x, values("all_area_rmse_ha"), color=bar_colors)
    axes[1, 0].set_ylabel("Daily area RMSE (ha)")
    axes[1, 0].set_xticks(x, labels, rotation=18, ha="right")

    axes[1, 1].bar(x, values("all_mean_boundary_p95_m") / 1000.0, color=bar_colors)
    axes[1, 1].set_ylabel("Boundary P95 error (km)")
    axes[1, 1].set_xticks(x, labels, rotation=18, ha="right")

    for ax in axes.flat:
        ax.grid(alpha=0.22, axis="y")
    _apply_lettered_bottom_caption(
        fig, axes,
        [
            "multi-objective calibration score combining perimeter overlap, area, centroid and boundary distance",
            "mean 300 m tolerant F1 across tested rolling-reference days",
            "daily burned-area increment RMSE across tested rolling-reference days",
            "mean 95th-percentile perimeter-distance error across tested rolling-reference days",
        ],
        "Calibration Search Summary",
        caption_width=160,
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=170, bbox_inches="tight")
    plt.close(fig)
    print("saved", out_png)


def run_calibration_search(elev, fuel, wind, transform, crs, real_mask=None,
                           max_days=3, final_days=ROLLING_REF_MAX_DAYS,
                           quick=False, output_dir=None, candidate_limit=None):
    """Search calibrated CA settings, then rerun the best candidate with outputs."""
    import json

    run_dir = str(output_dir or CALIBRATION_SEARCH_OUT_DIR)
    os.makedirs(run_dir, exist_ok=True)
    max_days = max(1, min(int(max_days), DAILY_REFERENCE_MAX_DAYS))
    final_days = max(1, min(int(final_days), DAILY_REFERENCE_MAX_DAYS))
    variants = rolling_calibration_candidate_variants(
        quick=quick, limit=candidate_limit
    )
    setting_keys = sorted({
        key for variant in variants for key in variant.get("settings", {})
    })
    backup = _global_settings_snapshot(setting_keys)
    daily_rows = []
    summary_rows = []
    daily_csv = os.path.join(run_dir, "calibration_daily_metrics.csv")
    summary_csv = os.path.join(run_dir, "calibration_summary.csv")
    print("Perimeter-aware calibration search:")
    print(f"  candidates={len(variants)}, search days={max_days}, final days={final_days}")
    try:
        for index, variant in enumerate(variants, start=1):
            _restore_global_settings(backup)
            _apply_global_settings(variant.get("settings", {}))
            seed = SEED + 53000
            print(f"  [{index}/{len(variants)}] {variant['name']}: {variant['label']}")
            records = run_rolling_reference_forecast(
                elev, fuel.copy(), wind, transform, crs, real_mask,
                max_days=max_days, seed=seed, write_outputs=False,
                mode_label=f"Calibration candidate: {variant['label']}",
            )
            for row in records:
                components = rolling_day_objective_components(row)
                daily = {
                    "variant": variant["name"],
                    "variant_label": variant["label"],
                    "day": int(row.get("day", 0)),
                    "objective": components["objective"],
                    "tolerant_f1_loss": components["tolerant_f1_loss"],
                    "exact_f1_loss": components["exact_f1_loss"],
                    "boundary_p95_loss": components["boundary_p95_loss"],
                    "area_log_loss": components["area_log_loss"],
                    "centroid_loss": components["centroid_loss"],
                    "sim_new_ha": row.get("sim_new_ha", np.nan),
                    "ref_new_ha": row.get("ref_new_ha", np.nan),
                    "daily_area_error_pct": row.get("daily_area_error_pct", np.nan),
                    "daily_f1": row.get("daily_f1", np.nan),
                    "daily_tolerant_f1": row.get("daily_tolerant_f1", np.nan),
                    "daily_boundary_p95_error_m": row.get("daily_boundary_p95_error_m", np.nan),
                    "daily_centroid_error_m": row.get("daily_centroid_error_m", np.nan),
                }
                daily_rows.append(daily)
            train_days = tuple(day for day in CALIBRATION_TRAIN_DAYS if day <= max_days)
            validation_days = tuple(
                day for day in range(1, max_days + 1) if day not in train_days
            )
            summary = {
                "variant": variant["name"],
                "variant_label": variant["label"],
                "settings_json": json.dumps(
                    variant.get("settings", {}), ensure_ascii=True, sort_keys=True
                ),
            }
            summary.update(summarize_rolling_objective(records, train_days, "train_"))
            summary.update(summarize_rolling_objective(records, validation_days, "validation_"))
            summary.update(summarize_rolling_objective(records, None, "all_"))
            selection = summary.get("train_objective", np.nan)
            if not np.isfinite(float(selection)):
                selection = summary.get("all_objective", np.nan)
            summary["selection_objective"] = selection
            summary_rows.append(summary)
            _write_experiment_csv(daily_rows, daily_csv)
            _write_experiment_csv(summary_rows, summary_csv)

        summary_rows.sort(key=lambda row: float(row.get("selection_objective", np.inf)))
        for rank, row in enumerate(summary_rows, start=1):
            row["rank"] = rank
        _write_experiment_csv(summary_rows, summary_csv)
        plot_calibration_search_summary(
            summary_rows, os.path.join(run_dir, "calibration_search_summary.png")
        )
        best_name = summary_rows[0]["variant"]
        best_variant = next(item for item in variants if item["name"] == best_name)
        _restore_global_settings(backup)
        _apply_global_settings(best_variant.get("settings", {}))
        best_dir = os.path.join(run_dir, "best_rolling_reference_forecast")
        best_records = run_rolling_reference_forecast(
            elev, fuel.copy(), wind, transform, crs, real_mask,
            max_days=final_days, seed=SEED + 53000,
            output_dir=best_dir, write_outputs=True,
            mode_label=f"Best calibrated CA: {best_variant['label']}",
        )
        best_manifest = {
            "selected_variant": best_variant,
            "search_days": max_days,
            "final_days": final_days,
            "objective_weights": CALIBRATION_OBJECTIVE_WEIGHTS,
            "train_days": list(CALIBRATION_TRAIN_DAYS),
            "best_summary": summary_rows[0],
            "best_output_dir": best_dir,
        }
        with open(os.path.join(run_dir, "best_calibration_manifest.json"),
                  "w", encoding="utf-8") as f:
            json.dump(best_manifest, f, ensure_ascii=True, indent=2)
        print("Best calibration candidate:", best_variant["label"])
        return {
            "daily_rows": daily_rows,
            "summary_rows": summary_rows,
            "best_records": best_records,
            "best_output_dir": best_dir,
        }
    finally:
        _restore_global_settings(backup)


def plot_attention_spatial_evidence(elev, full_diagnostics, no_diagnostics,
                                    ign, real_mask, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.colors import BoundaryNorm, ListedColormap

    full_by_day = {int(item["day"]): item for item in full_diagnostics}
    no_by_day = {int(item["day"]): item for item in no_diagnostics}
    days = [day for day in sorted(set(full_by_day) & set(no_by_day)) if day > 1]
    if not days:
        return
    masks = [real_mask]
    for day in days:
        masks.extend([full_by_day[day]["pred_new"], no_by_day[day]["pred_new"]])
    sl = crop_for_daily(elev.shape, masks, ign, pad=58)
    hill = _dark_hillshade(elev[sl])
    fig, axes = plt.subplots(2, len(days), figsize=(4.2 * len(days), 8.3),
                             facecolor="#111111", squeeze=False)
    difference_cmap = ListedColormap(["#d73027", "#2166ac"])
    difference_norm = BoundaryNorm([-1.5, 0.0, 1.5], difference_cmap.N)
    descriptions = []
    diff_image = None
    feedback_image = None
    for column, day in enumerate(days):
        full = full_by_day[day]
        no_attention = no_by_day[day]
        feedback = full.get("attention_feedback")
        if feedback is None:
            feedback = np.zeros(elev.shape, dtype="float32")
        ax = axes[0, column]
        ax.imshow(hill, interpolation="bilinear")
        feedback_image = ax.imshow(
            np.ma.masked_where(np.abs(feedback[sl]) < 0.02, feedback[sl]),
            cmap="coolwarm", vmin=-1.0, vmax=1.0, alpha=0.82,
            interpolation="nearest",
        )
        if real_mask is not None:
            _draw_final_perimeter(ax, real_mask[sl], linewidth=1.3, alpha=0.75)
        ax.axis("off")
        descriptions.append(f"Day {day} observation-error feedback field")

        difference = (
            full["pred_new"].astype("int8") - no_attention["pred_new"].astype("int8")
        )
        ax = axes[1, column]
        ax.imshow(hill, interpolation="bilinear")
        diff_image = ax.imshow(
            np.ma.masked_equal(difference[sl], 0),
            cmap=difference_cmap, norm=difference_norm, alpha=0.9,
            interpolation="nearest",
        )
        if full.get("ref_new") is not None:
            ax.contour(full["ref_new"][sl].astype(float), levels=[0.5],
                       colors="#ffe34d", linewidths=1.1, alpha=0.9)
        ax.axis("off")
        descriptions.append(
            f"Day {day} change in predicted increment caused by feature gating"
        )

    if feedback_image is not None:
        cax = axes[0, 0].inset_axes([0.14, 0.035, 0.72, 0.035])
        cb = fig.colorbar(feedback_image, cax=cax, orientation="horizontal",
                          ticks=[-1, 0, 1])
        cb.set_label("Observation-error feedback", color="white", labelpad=1)
        cb.ax.set_xticklabels(["Suppress", "Neutral", "Enhance"])
        cb.ax.tick_params(colors="white", labelsize=7, pad=1)
    if diff_image is not None:
        cax = axes[1, 0].inset_axes([0.14, 0.035, 0.72, 0.035])
        cb = fig.colorbar(diff_image, cax=cax, orientation="horizontal", ticks=[-1, 1])
        cb.ax.set_xticklabels(["Without attention", "With attention"])
        cb.ax.tick_params(colors="white", labelsize=7, pad=1)
    ordered_descriptions = []
    for row in range(2):
        for column, day in enumerate(days):
            ordered_descriptions.append(
                f"Day {day} observation-error feedback field" if row == 0 else
                f"Day {day} feature-gating change in predicted burned-area increment"
            )
    _apply_lettered_bottom_caption(
        fig, axes, ordered_descriptions,
        "Spatial Evidence for Environmental Feature Gating and Prior-Window Feedback",
        caption_width=175,
        label_fontsize=9,
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=170, bbox_inches="tight", facecolor=fig.get_facecolor())
    plt.close(fig)
    print("saved", out_png)


def run_paper_experiments(elev, fuel, wind, transform, crs, real_mask=None,
                          suite="attention", replicates=1,
                          max_days=ROLLING_REF_MAX_DAYS, dry_run=False,
                          resume=False, variants=None, output_dir=None):
    """Run paired paper experiments with common random numbers and unified metrics."""
    import copy
    import hashlib
    import importlib.metadata
    import json
    import platform
    import sys
    import time
    from datetime import datetime, timezone

    experiment_started = time.perf_counter()

    requested = str(suite).strip().lower()
    suites = [
        "bcaf", "attention", "wind", "protocol", "mechanism", "suppression", "budget",
        "response", "normal-ros-ml", "multiscale-ml", "parameter-filter",
        "publication-core",
    ] if requested == "all" else [requested]
    definitions = {name: paper_experiment_variants(name) for name in suites}
    requested_variants = {
        item.strip()
        for item in str(variants or "").split(",")
        if item.strip()
    }
    if requested_variants:
        definitions = {
            name: [
                variant for variant in suite_variants
                if variant["name"] in requested_variants
            ]
            for name, suite_variants in definitions.items()
        }
        missing = requested_variants - {
            variant["name"]
            for suite_variants in definitions.values()
            for variant in suite_variants
        }
        if missing:
            raise ValueError(
                "Unknown requested experiment variant(s): " +
                ", ".join(sorted(missing))
            )
    experiment_out_dir = str(output_dir or PAPER_EXPERIMENT_OUT_DIR)
    replicates = max(1, int(replicates))
    max_days = max(1, min(int(max_days), DAILY_REFERENCE_MAX_DAYS))
    print("Paper experiment plan:")
    for name in suites:
        print(f"  {name}:")
        for variant in definitions[name]:
            print(f"    - {variant['name']}: {variant['label']}")
    print(f"  paired replicates={replicates}, reporting days={max_days}")
    if dry_run:
        print("Dry run only; no CA simulations were executed.")
        return {"suites": suites, "definitions": definitions}

    os.makedirs(experiment_out_dir, exist_ok=True)
    setting_keys = sorted({
        key
        for variants in definitions.values()
        for variant in variants
        for key in variant.get("settings", {})
    })
    backup = _global_settings_snapshot(setting_keys)
    daily_masks, daily_areas = load_daily_validation_references(transform, crs, elev.shape)
    experiment_windows = rolling_reference_time_windows(max_days)
    experiment_max_steps = (
        int(experiment_windows[-1]["end_step"]) if experiment_windows else N_STEPS
    )
    all_daily_rows = []
    all_replicate_rows = []
    spatial_diagnostics = {}
    wind_cache = {"corrected": wind}

    try:
        for suite_name in suites:
            suite_dir = os.path.join(experiment_out_dir, suite_name)
            os.makedirs(suite_dir, exist_ok=True)
            daily_path = os.path.join(suite_dir, "daily_metrics.csv")
            suite_daily_rows = _read_experiment_csv(daily_path) if resume else []
            for variant_index, variant in enumerate(definitions[suite_name]):
                _restore_global_settings(backup)
                _apply_global_settings(variant.get("settings", {}))
                wind_kind = variant.get("wind_kind", "corrected")
                if wind_kind not in wind_cache:
                    wind_cache[wind_kind] = _experiment_wind_provider(
                        wind_kind, transform, crs, elev.shape, wind
                    )
                variant_wind = wind_cache[wind_kind]
                for replicate in range(1, replicates + 1):
                    completed_days = {
                        int(float(row.get("day", 0)))
                        for row in suite_daily_rows
                        if row.get("variant") == variant["name"] and
                        int(float(row.get("replicate", 0))) == replicate
                    }
                    if len(completed_days) >= max_days:
                        print(
                            f"[{suite_name}] {variant['name']} replicate {replicate} "
                            "already complete; skipped."
                        )
                        continue
                    if completed_days:
                        suite_daily_rows = [
                            row for row in suite_daily_rows
                            if not (
                                row.get("variant") == variant["name"] and
                                int(float(row.get("replicate", 0))) == replicate
                            )
                        ]
                        print(
                            f"[{suite_name}] {variant['name']} replicate {replicate} "
                            "was incomplete; restarting this paired run."
                        )
                    paired_seed = SEED + 12000 + (replicate - 1) * 1009
                    print(
                        f"[{suite_name}] {variant['name']} replicate "
                        f"{replicate}/{replicates}, seed={paired_seed}"
                    )
                    diagnostics = [] if (
                        suite_name in ("attention", "publication-core") and
                        replicate == 1
                    ) else None
                    run_wind = (
                        copy.deepcopy(variant_wind)
                        if suite_name == "publication-core" else variant_wind
                    )
                    try:
                        import psutil
                        process = psutil.Process()
                        rss_before_mb = (
                            process.memory_info().rss / (1024.0 ** 2)
                        )
                    except (ImportError, OSError):
                        process = None
                        rss_before_mb = np.nan
                    run_started = time.perf_counter()
                    if variant["runner"] == "rolling":
                        raw_rows = run_rolling_reference_forecast(
                            elev, fuel.copy(), run_wind, transform, crs, real_mask,
                            max_days=max_days, seed=paired_seed,
                            write_outputs=False,
                            mode_label=f"{suite_name}: {variant['label']}",
                            diagnostics=diagnostics,
                        )
                    elif variant["runner"] == "rolling-control":
                        raw_rows, _state, _arrival, _firebreak, _ign = run_daily_cost_control(
                            elev, fuel.copy(), run_wind, transform, crs, real_mask,
                            rolling_reference=True,
                            max_days=max_days,
                            seed=paired_seed,
                            write_outputs=False,
                            suppression_enabled=variant.get(
                                "suppression_enabled", True
                            ),
                            daily_budget=variant.get(
                                "daily_budget", CONTROL_DAILY_BUDGET
                            ),
                        )
                    else:
                        _state, _history, _dims, _burned, _ign, arrival = run_ca(
                            elev, fuel.copy(), run_wind, transform, crs,
                            seed=paired_seed, calibrate_daily=False,
                            max_steps=experiment_max_steps,
                        )
                        raw_rows = compute_daily_validation_rows(
                            arrival, real_mask, daily_masks, daily_areas
                        )[:max_days]
                    run_elapsed = time.perf_counter() - run_started
                    rss_after_mb = (
                        process.memory_info().rss / (1024.0 ** 2)
                        if process is not None else np.nan
                    )
                    normalized = [
                        _experiment_daily_record(
                            row, suite_name, variant["name"], variant["label"],
                            replicate, paired_seed, variant["runner"],
                            runtime_seconds=run_elapsed,
                            process_rss_before_mb=rss_before_mb,
                            process_rss_after_mb=rss_after_mb,
                        )
                        for row in raw_rows
                    ]
                    suite_daily_rows.extend(normalized)
                    _write_experiment_csv(suite_daily_rows, daily_path)
                    if diagnostics is not None:
                        spatial_diagnostics[variant["name"]] = diagnostics

            suite_replicate_rows = []
            for variant in definitions[suite_name]:
                for replicate in range(1, replicates + 1):
                    group = [
                        row for row in suite_daily_rows
                        if row.get("variant") == variant["name"] and
                        int(float(row.get("replicate", 0))) == replicate and
                        int(float(row.get("day", 0))) <= max_days
                    ]
                    group.sort(key=lambda row: int(float(row.get("day", 0))))
                    summary = _summarize_experiment_replicate(group)
                    if summary:
                        suite_replicate_rows.append(summary)
            aggregate = _aggregate_experiment_summaries(suite_replicate_rows)
            effects = _paired_experiment_effects(suite_replicate_rows)
            effect_summary = _aggregate_paired_effects(effects)
            daily_effects = _paired_daily_experiment_effects(suite_daily_rows)
            daily_effect_summary = _aggregate_paired_daily_effects(daily_effects)
            _write_experiment_csv(suite_daily_rows, daily_path)
            _write_experiment_csv(
                suite_replicate_rows, os.path.join(suite_dir, "replicate_summary.csv")
            )
            _write_experiment_csv(
                aggregate, os.path.join(suite_dir, "experiment_summary.csv")
            )
            _write_experiment_csv(
                effects, os.path.join(suite_dir, "paired_effects.csv")
            )
            _write_experiment_csv(
                effect_summary,
                os.path.join(suite_dir, "paired_effect_summary.csv"),
            )
            _write_experiment_csv(
                daily_effects,
                os.path.join(suite_dir, "paired_daily_effects.csv"),
            )
            _write_experiment_csv(
                daily_effect_summary,
                os.path.join(suite_dir, "paired_daily_effect_summary.csv"),
            )
            if suite_name in ("suppression", "budget", "response"):
                plot_suppression_experiment_comparison(
                    suite_daily_rows, aggregate,
                    os.path.join(suite_dir, "experiment_comparison.png"),
                    suite_name,
                )
            else:
                plot_paper_experiment_comparison(
                    suite_daily_rows, aggregate,
                    os.path.join(suite_dir, "experiment_comparison.png"), suite_name,
                )
            plot_paired_daily_effects(
                daily_effect_summary,
                os.path.join(suite_dir, "paired_daily_effects.png"),
                suite_name,
            )
            if suite_name == "parameter-filter":
                plot_parameter_filter_experiment(
                    suite_daily_rows,
                    os.path.join(
                        suite_dir,
                        "parameter_posterior_evolution.png",
                    ),
                )
            all_daily_rows.extend(suite_daily_rows)
            all_replicate_rows.extend(suite_replicate_rows)

            if suite_name == "attention":
                full = spatial_diagnostics.get("attention_with_feedback", [])
                no_attention = spatial_diagnostics.get("no_attention", [])
                if full and no_attention:
                    ign = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
                    plot_attention_spatial_evidence(
                        elev, full, no_attention, ign, real_mask,
                        os.path.join(suite_dir, "attention_spatial_evidence.png"),
                    )
                    arrays = {}
                    for variant_name, diagnostics in spatial_diagnostics.items():
                        for item in diagnostics:
                            day = int(item["day"])
                            arrays[f"{variant_name}_day{day:02d}_pred_new"] = item["pred_new"]
                            if item.get("attention_feedback") is not None:
                                arrays[f"{variant_name}_day{day:02d}_feedback"] = item["attention_feedback"]
                    np.savez_compressed(
                        os.path.join(suite_dir, "attention_spatial_evidence.npz"),
                        **arrays,
                    )
            if suite_name == "publication-core":
                arrays = {}
                for variant_name, diagnostics in spatial_diagnostics.items():
                    for item in diagnostics:
                        day = int(item["day"])
                        prefix = f"{variant_name}_day{day:02d}"
                        arrays[f"{prefix}_pred_new"] = item["pred_new"]
                        arrays[f"{prefix}_pred_cum"] = item["pred_cum"]
                        if item.get("ref_new") is not None:
                            arrays[f"{prefix}_ref_new"] = item["ref_new"]
                        if item.get("ref_cum") is not None:
                            arrays[f"{prefix}_ref_cum"] = item["ref_cum"]
                if arrays:
                    np.savez_compressed(
                        os.path.join(
                            suite_dir,
                            "publication_core_spatial_masks_replicate01.npz",
                        ),
                        **arrays,
                    )
    finally:
        _restore_global_settings(backup)

    _write_experiment_csv(
        all_daily_rows, os.path.join(experiment_out_dir, "all_daily_metrics.csv")
    )
    _write_experiment_csv(
        all_replicate_rows,
        os.path.join(experiment_out_dir, "all_replicate_summaries.csv"),
    )
    def file_fingerprint(path):
        path = Path(path)
        if not path.is_file():
            return {
                "path": str(path.resolve()),
                "exists": False,
                "size_bytes": None,
                "sha256": None,
            }
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            while True:
                chunk = stream.read(1024 * 1024)
                if not chunk:
                    break
                digest.update(chunk)
        return {
            "path": str(path.resolve()),
            "exists": True,
            "size_bytes": path.stat().st_size,
            "sha256": digest.hexdigest(),
        }

    package_versions = {}
    for package in (
        "numpy", "scipy", "pandas", "matplotlib", "rasterio",
        "geopandas", "scikit-learn",
    ):
        try:
            package_versions[package] = importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:
            package_versions[package] = "not installed"
    fingerprint_paths = {
        "model_source": Path(__file__),
        "firms_hotspots": Path(FIRMS_HOTSPOT_CSV),
        "fuel_raster": Path(FUEL_PATH),
        "dem_raster": Path(DEM_PATH),
        "evt_raster": Path(EVT_PATH),
        "daily_reference_manifest": (
            Path(OFFICIAL_DAILY_REF_PERIM_DIR) /
            "daily_reference_manifest.json"
        ),
    }
    for day in range(1, max_days + 1):
        fingerprint_paths[f"daily_reference_day_{day}"] = (
            Path(OFFICIAL_DAILY_REF_PERIM_DIR) /
            f"day{day:02d}.geojson"
        )

    def manifest_bool(value):
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes"}
        return bool(value)

    observed_variants = sorted({
        str(row.get("variant", "")) for row in all_daily_rows
        if str(row.get("variant", ""))
    })
    publication_core_expected = {
        variant["name"]
        for variant in paper_experiment_variants("publication-core")
    }
    publication_core_complete = True
    if "publication-core" in suites:
        for variant_name in publication_core_expected:
            for replicate in range(1, replicates + 1):
                completed_days = {
                    int(float(row.get("day", 0)))
                    for row in all_daily_rows
                    if row.get("suite") == "publication-core" and
                    row.get("variant") == variant_name and
                    int(float(row.get("replicate", 0))) == replicate
                }
                if not set(range(1, max_days + 1)).issubset(completed_days):
                    publication_core_complete = False
                    break
            if not publication_core_complete:
                break
    protocol_audit = {
        "current_window_reference_never_used": all(
            not manifest_bool(row.get("current_window_reference_used", False))
            for row in all_daily_rows
        ),
        "strict_rows_do_not_use_current_firms": all(
            not manifest_bool(row.get("current_window_firms_used", False))
            for row in all_daily_rows
            if row.get("evaluation_protocol") ==
            "prequential-one-window-ahead"
        ),
        "nowcast_rows_declared": all(
            row.get("evaluation_protocol") ==
            "sequential-satellite-nowcast"
            for row in all_daily_rows
            if manifest_bool(row.get("current_window_firms_used", False))
        ),
    }
    formal_complete = (
        replicates >= 10 and
        max_days >= DAILY_REFERENCE_MAX_DAYS and
        publication_core_complete and
        all(protocol_audit.values())
    )

    manifest = {
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "suites": suites,
        "replicates": replicates,
        "max_days": max_days,
        "resume": bool(resume),
        "requested_variants": sorted(requested_variants),
        "observed_variants": observed_variants,
        "publication_core_expected_variants": sorted(
            publication_core_expected
        ),
        "publication_core_complete": publication_core_complete,
        "protocol_audit": protocol_audit,
        "output_dir": str(Path(experiment_out_dir).resolve()),
        "run_classification": (
            "palisades_development_formal_candidate"
            if formal_complete
            else "smoke_or_preliminary"
        ),
        "case_study_role": "retrospective_development_case_study",
        "independent_fire_event_validation": False,
        "observation_windows": [
            {
                "day": int(window["day"]),
                "start_utc": window["window_start_utc"],
                "end_utc": window["window_end_utc"],
                "duration_hours": (
                    float(window["end_h"]) - float(window["start_h"])
                ),
            }
            for window in experiment_windows
        ],
        "base_seed": SEED,
        "seed_rule": "SEED + 12000 + (replicate - 1) * 1009; shared across variants",
        "definitions": definitions,
        "primary_metrics": [
            "mean_daily_iou", "daily_area_rmse_ha",
            "mean_daily_boundary_p95_error_km",
            "mean_daily_shape_orientation_error_deg",
            "mean_daily_shape_log_scale_error",
            "mean_daily_shape_elongation_log_error",
            "mean_daily_shape_radial_nrmse",
            "total_avoided_ha", "total_realized_net_benefit_k",
            "aggregate_realized_benefit_cost_ratio",
        ],
        "secondary_metrics": [
            "mean_daily_f1",
            "daily_tolerant_iou",
        ],
        "metric_note": (
            "Binary-mask F1 is a monotonic transform of IoU and is not "
            "treated as independent evidence."
        ),
        "fire_wind_coupling_scope": (
            "bounded fire-induced near-surface wind perturbation proxy; "
            "not a prognostic two-way atmosphere-fire solver"
        ),
        "environment": {
            "python": sys.version,
            "python_executable": sys.executable,
            "platform": platform.platform(),
            "processor": platform.processor(),
            "logical_cpu_count": os.cpu_count(),
            "packages": package_versions,
        },
        "data_and_code_fingerprints": {
            key: file_fingerprint(path)
            for key, path in fingerprint_paths.items()
        },
        "end_to_end_runtime_seconds": (
            time.perf_counter() - experiment_started
        ),
    }
    manifest_path = os.path.join(experiment_out_dir, "experiment_manifest.json")
    with open(manifest_path, "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=True, indent=2)
    print("saved", manifest_path)
    return {
        "daily_rows": all_daily_rows,
        "replicate_rows": all_replicate_rows,
        "manifest": manifest_path,
    }


def run_ablation_study(elev, fuel, wind, transform, crs, real_mask=None):
    """Run expensive mechanism ablations for paper tables."""
    import csv

    os.makedirs(ABLATION_OUT_DIR, exist_ok=True)
    variants = [
        ("full_model", "All currently enabled mechanisms.", {}),
        ("no_spotting", "Disable long-range ember spotting.", {"SPOT_PROB": 0.0}),
        ("no_crown_fire", "Disable high-intensity/crown-fire source layer.", {"CROWN_FIRE_MODEL": False}),
        (
            "no_attention",
            "Disable environmental feature gating and feedback weighting.",
            {"ATTENTION_CA": False},
        ),
        ("no_percolation", "Disable fuel-connectivity percolation factor.", {"PERCOLATION_MODEL": False}),
        ("no_wui", "Disable vegetation-building interface heat-flux model.", {"WUI_MODEL": False}),
        ("no_fire_weather", "Disable time-varying fire-weather ROS factor.", {"FIRE_WEATHER_TIMELINE": False}),
    ]
    keys = sorted({key for _, _, settings in variants for key in settings})
    backup = _global_settings_snapshot(keys)
    daily_masks, daily_areas = load_daily_validation_references(transform, crs, elev.shape)
    rows_out = []

    print("Ablation study (expensive; one full CA run per variant):")
    for idx, (name, description, settings) in enumerate(variants, start=1):
        _restore_global_settings(backup)
        _apply_global_settings(settings)
        print(f"  {idx}/{len(variants)} {name}: {description}")
        state, history, dims, burned_counts, ign, arrival = run_ca(
            elev, fuel.copy(), wind, transform, crs,
            seed=SEED + 5000,
            calibrate_daily=False,
        )
        val_rows = compute_daily_validation_rows(arrival, real_mask, daily_masks, daily_areas)
        final = val_rows[-1] if val_rows else {}
        metric_summary = {r["metric"]: r for r in paper_metric_rows(val_rows)}
        out = {
            "variant": name,
            "description": description,
            "final_burned_ha": final.get("sim_cumulative_ha", np.nan),
            "ref_cumulative_ha": final.get("ref_cumulative_ha", np.nan),
            "final_cumulative_iou": final.get("cumulative_iou", np.nan),
            "final_cumulative_f1": final.get("cumulative_f1", np.nan),
            "final_boundary_p95_error_m": final.get("cumulative_boundary_p95_error_m", np.nan),
            "mean_daily_iou": metric_summary.get("daily_iou", {}).get("mean", np.nan),
            "mean_daily_f1": metric_summary.get("daily_f1", {}).get("mean", np.nan),
            "daily_area_rmse_ha": metric_summary.get("daily_area_error_ha", {}).get("rmse", np.nan),
            "cumulative_area_rmse_ha": metric_summary.get("cumulative_area_error_ha", {}).get("rmse", np.nan),
            "fractal_dimension_final": dims[-1] if dims else np.nan,
            "settings_changed": "; ".join(f"{k}={v}" for k, v in settings.items()) or "none",
        }
        rows_out.append(out)
        write_paper_package(val_rows, f"Ablation {name}")

    _restore_global_settings(backup)
    out_csv = os.path.join(ABLATION_OUT_DIR, "ablation_summary.csv")
    fields = [
        "variant", "description", "final_burned_ha", "ref_cumulative_ha",
        "final_cumulative_iou", "final_cumulative_f1", "final_boundary_p95_error_m",
        "mean_daily_iou", "mean_daily_f1", "daily_area_rmse_ha",
        "cumulative_area_rmse_ha", "fractal_dimension_final", "settings_changed",
    ]
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for row in rows_out:
            writer.writerow(row)
    print("saved", out_csv)
    plot_ablation_summary(rows_out, os.path.join(ABLATION_OUT_DIR, "ablation_summary.png"))
    return rows_out


def plot_ablation_summary(rows, out_png):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    if not rows:
        return
    names = [r["variant"] for r in rows]
    x = np.arange(len(names))
    final_area = np.asarray([r.get("final_burned_ha", np.nan) for r in rows], dtype=float)
    ref_area = np.asarray([r.get("ref_cumulative_ha", np.nan) for r in rows], dtype=float)
    iou = np.asarray([r.get("final_cumulative_iou", np.nan) for r in rows], dtype=float)
    f1 = np.asarray([r.get("final_cumulative_f1", np.nan) for r in rows], dtype=float)
    b95 = np.asarray([r.get("final_boundary_p95_error_m", np.nan) for r in rows], dtype=float) / 1000.0
    rmse = np.asarray([r.get("daily_area_rmse_ha", np.nan) for r in rows], dtype=float)

    fig, axes = plt.subplots(2, 2, figsize=(15, 8.8), facecolor="white")
    axes[0, 0].bar(x, final_area, color="#3182bd", alpha=0.82,
                   label="Simulated final burned area")
    if np.isfinite(ref_area).any():
        axes[0, 0].plot(x, ref_area, "--o", color="#d7301f",
                        label="Observed final burned area")
    axes[0, 0].set_title("Final Area by Mechanism Variant", fontweight="bold")
    axes[0, 0].set_ylabel("Area (ha)")
    axes[0, 0].legend(fontsize=8)

    axes[0, 1].plot(x, iou, "-o", color="#08519c", lw=1.8, label="IoU")
    axes[0, 1].plot(x, f1, "-s", color="#31a354", lw=1.8, label="F1")
    axes[0, 1].set_ylim(0, 1.02)
    axes[0, 1].set_title("Final Spatial Agreement", fontweight="bold")
    axes[0, 1].set_ylabel("Score")
    axes[0, 1].legend(fontsize=8)

    axes[1, 0].bar(x, b95, color="#dd1c77", alpha=0.78)
    axes[1, 0].set_title("Final Boundary P95 Error", fontweight="bold")
    axes[1, 0].set_ylabel("Boundary P95 error (km)")

    axes[1, 1].bar(x, rmse, color="#fdae6b", alpha=0.86)
    axes[1, 1].set_title("Daily Area RMSE", fontweight="bold")
    axes[1, 1].set_ylabel("Daily area RMSE (ha)")

    for ax in axes.flat:
        ax.set_xticks(x)
        ax.set_xticklabels(names, rotation=25, ha="right")
        ax.grid(alpha=0.24)
    fig.suptitle("Ablation Study: Evidence of Mechanism Contributions",
                 fontsize=15, fontweight="bold")
    _apply_lettered_bottom_caption(
        fig, axes,
        [
            "final burned area by mechanism variant",
            "final IoU and F1 by mechanism variant",
            "final boundary P95 error by mechanism variant",
            "daily burned-area RMSE by mechanism variant",
        ],
        "Ablation Study: Mechanism Contribution Evidence",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=150)
    plt.close(fig)
    print("saved", out_png)


def _layer_summary_stats(name, arr, valid=None):
    data = np.asarray(arr, dtype=float)
    mask = np.isfinite(data) if valid is None else (np.asarray(valid, dtype=bool) & np.isfinite(data))
    if not np.any(mask):
        return {"layer": name, "mean": np.nan, "p50": np.nan, "p90": np.nan, "p95": np.nan, "max": np.nan}
    vals = data[mask]
    return {
        "layer": name,
        "mean": float(np.nanmean(vals)),
        "p50": float(np.nanpercentile(vals, 50)),
        "p90": float(np.nanpercentile(vals, 90)),
        "p95": float(np.nanpercentile(vals, 95)),
        "max": float(np.nanmax(vals)),
    }


def plot_mechanism_diagnostic_maps(elev, fuel, wind, transform, crs, ign, real_mask,
                                   out_png, out_csv):
    """Paper-style mechanism maps explaining why the CA spreads where it does."""
    import csv
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    shape = elev.shape
    aspect_fac, grow, gcol = build_rothermel_layers(elev)
    moisture_h, moisture_f = load_moisture_timeline()
    burn_clock_proxy = np.full(shape, max(CROWN_MIN_BURN_AGE_STEPS + 2, 4), dtype=np.int16)

    code = np.zeros(shape, dtype="int32")
    is_building = np.zeros(shape, dtype=bool)
    evt_codes = None
    if FUEL_PATH and os.path.exists(FUEL_PATH):
        try:
            code = load_fbfm40_codes(FUEL_PATH, transform, crs, shape)
            evt_codes = load_evt_codes(EVT_PATH, transform, crs, shape)
            is_building, _, _ = build_wui_layers(code, evt_codes=evt_codes)
        except Exception:
            pass
    canopy = load_canopy_layers(FUEL_PATH, transform, crs, shape)
    fuel, diagnostic_burn_duration, evt_codes = prepare_evt_fuel_behavior(
        fuel, transform, crs, canopy=canopy, evt_codes=evt_codes
    )
    evt_attention, canopy_attention = build_vegetation_attention_layers(evt_codes, canopy)
    if evt_attention is None:
        evt_attention = np.zeros(shape, dtype="float32")
    if canopy_attention is None:
        canopy_attention = np.zeros(shape, dtype="float32")
    vegetation_attention_factor = np.clip(
        1.0 + ATTENTION_GAIN * np.tanh(
            ATTENTION_EVT_WEIGHT * evt_attention +
            ATTENTION_CANOPY_WEIGHT * canopy_attention
        ),
        ATTENTION_MIN_FACTOR,
        ATTENTION_MAX_FACTOR,
    ).astype("float32")

    sample_count = int(min(max(N_STEPS, 1), 36))
    sample_steps = np.unique(np.linspace(0, max(N_STEPS - 1, 0), sample_count).astype(int))
    best_step = int(sample_steps[0]) if sample_steps.size else 0
    best_mean_wind = -1.0
    for step in sample_steps:
        spd, _ = wind.get(int(step))
        mean_w = float(np.nanmean(spd))
        if mean_w > best_mean_wind:
            best_mean_wind = mean_w
            best_step = int(step)

    spd, dfrom = wind.get(best_step)
    moisture_scalar = moisture_factor_for_step(best_step, moisture_h, moisture_f)
    crown, crown_ros, crown_spot, crown_dist, crown_hit = build_crown_intensity_layers(
        fuel, spd, moisture_scalar, grow=grow, gcol=gcol,
        burn_clock=burn_clock_proxy, is_building=is_building, canopy=canopy,
        burn_duration_steps=diagnostic_burn_duration,
    )
    percolation, perc_stats = build_percolation_layers(fuel, is_building)
    if percolation is None:
        percolation = np.zeros(shape, dtype="float32")
    moisture_spatial = build_spatial_moisture_modifier(
        elev, aspect_fac, grow, gcol, fbfm_code=code, fuel=fuel
    )
    if moisture_spatial is None:
        moisture_spatial = np.ones(shape, dtype="float32")
    _, aspect_deg = compute_slope_aspect(elev)

    valid = np.isfinite(elev) & (fuel > 0.02)
    slope_deg = np.degrees(np.arctan(np.hypot(grow, gcol) / TARGET_RES)).astype("float32")
    fuel_norm = np.clip(fuel / max(CROWN_FUEL_FULL, 1e-6), 0.0, 1.0)
    wind_norm = np.clip(np.nan_to_num(spd, nan=0.0) / max(CROWN_WIND_FULL, 1e-6), 0.0, 1.0)
    slope_norm = np.clip(slope_deg / max(CROWN_SLOPE_REF_DEG, 1e-6), 0.0, 1.0)
    spot_potential = np.clip(
        0.36 * wind_norm + 0.24 * fuel_norm + 0.18 * slope_norm +
        0.22 * crown,
        0.0, 1.0,
    )
    spread_potential = np.clip(
        0.24 * wind_norm + 0.22 * fuel_norm + 0.18 * slope_norm +
        0.18 * np.clip(percolation, 0.0, 1.0) + 0.18 * crown,
        0.0, 1.0,
    )

    rows = [
        _layer_summary_stats("fuel_norm", fuel_norm, valid),
        _layer_summary_stats("wind_speed_mps_at_representative_step", spd, valid),
        _layer_summary_stats("slope_deg", slope_deg, valid),
        _layer_summary_stats("aspect_deg", aspect_deg, valid),
        _layer_summary_stats("spatial_moisture_factor", moisture_spatial, valid),
        _layer_summary_stats("percolation_factor", percolation, valid),
        _layer_summary_stats("building_wui", is_building.astype("float32"), np.isfinite(elev)),
        _layer_summary_stats("crown_tendency", crown, valid),
        _layer_summary_stats("spotting_potential", spot_potential, valid),
        _layer_summary_stats("combined_spread_potential", spread_potential, valid),
        _layer_summary_stats("evt_attention_feature", evt_attention, valid),
        _layer_summary_stats("canopy_attention_feature", canopy_attention, valid),
        _layer_summary_stats("vegetation_attention_factor", vegetation_attention_factor, valid),
    ]
    if canopy is not None:
        rows.extend([
            _layer_summary_stats("canopy_cover_pct", canopy["cover_pct"], np.isfinite(elev)),
            _layer_summary_stats("canopy_height_m", canopy["height_m"], np.isfinite(elev)),
            _layer_summary_stats("canopy_base_height_m", canopy["base_height_m"], np.isfinite(elev)),
            _layer_summary_stats("canopy_bulk_density_kg_m3", canopy["bulk_density_kg_m3"], np.isfinite(elev)),
        ])
    for row in rows:
        row["representative_step"] = best_step
        row["representative_hours_since_start"] = best_step * MIN_PER_STEP / 60.0
        row["representative_mean_wind_mps"] = best_mean_wind
        row["moisture_scalar"] = moisture_scalar
        row["percolation_giant_frac"] = perc_stats.get("percolation_giant_frac", np.nan)

    os.makedirs(os.path.dirname(out_csv) or ".", exist_ok=True)
    with open(out_csv, "w", newline="", encoding="utf-8") as f:
        fields = [
            "layer", "mean", "p50", "p90", "p95", "max",
            "representative_step", "representative_hours_since_start",
            "representative_mean_wind_mps", "moisture_scalar",
            "percolation_giant_frac",
        ]
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)

    sl = crop_for_daily(shape, [real_mask, fuel > 0.02, crown > 0.25], ign, pad=70)
    hill = _dark_hillshade(elev[sl])
    panels = [
        ("Normalized fuel factor", fuel_norm, "YlGn", 0.0, 1.0),
        ("Slope", slope_deg, "magma", 0.0, np.nanpercentile(slope_deg[valid], 98) if np.any(valid) else 35.0),
        ("Aspect", aspect_deg, "twilight", 0.0, 360.0),
        (f"Wind speed ({best_step * MIN_PER_STEP / 60.0:.1f} h)", spd, "viridis", 0.0, np.nanpercentile(spd[valid], 98) if np.any(valid) else 1.0),
        ("Spatial moisture factor", moisture_spatial, "BrBG_r", 0.35, 1.20),
        ("Percolation connectivity", percolation, "cividis", 0.0, 1.0),
        ("Building and WUI indicator", is_building.astype("float32"), "Greys", 0.0, 1.0),
        ("High-intensity and crown-fire tendency", crown, "inferno", 0.0, 1.0),
        ("Spotting potential", spot_potential, "plasma", 0.0, 1.0),
        ("EVT attention feature", evt_attention, "RdYlGn", -1.0, 1.0),
        ("Canopy attention feature", canopy_attention, "PuOr", -1.0, 1.0),
        ("Static vegetation attention factor", vegetation_attention_factor,
         "coolwarm", ATTENTION_MIN_FACTOR, ATTENTION_MAX_FACTOR),
    ]
    fig, axes = plt.subplots(3, 4, figsize=(19, 13.2), facecolor="#111111")
    for ax, (title, layer, cmap, vmin, vmax) in zip(axes.flat, panels):
        ax.set_facecolor("#111111")
        ax.imshow(hill, interpolation="bilinear")
        im = ax.imshow(np.ma.masked_where(~np.isfinite(layer[sl]), layer[sl]),
                       cmap=cmap, vmin=vmin, vmax=vmax, alpha=0.78,
                       interpolation="nearest")
        ax.plot(ign[1] - sl[1].start, ign[0] - sl[0].start, marker="*",
                color="#ff2020", mec="white", mew=0.6, ms=10)
        ax.axis("off")
        cb = fig.colorbar(im, ax=ax, fraction=0.035, pad=0.01)
        cb.ax.tick_params(labelsize=7, colors="white")
        cb.outline.set_edgecolor("white")
    _apply_lettered_bottom_caption(
        fig, axes,
        [panel[0] for panel in panels],
        "Mechanism Evidence Maps: CA Drivers and Vegetation-Attention Features",
        caption_width=145,
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=150, facecolor=fig.get_facecolor())
    plt.close(fig)
    print("saved", out_csv)
    print("saved", out_png)


def plot_evt_vegetation_diagnostics(elev, fuel, transform, crs, out_png, out_csv):
    """Plot grouped EVT lifeforms and the resulting dynamic burn residence."""
    import csv
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches
    from matplotlib.colors import ListedColormap

    evt_codes = load_evt_codes(EVT_PATH, transform, crs, elev.shape)
    attributes = load_evt_attributes(EVT_ATTRIBUTE_CSV)
    if evt_codes is None or not attributes:
        print("skip EVT diagnostics: raster or attribute table unavailable")
        return None, None
    canopy = load_canopy_layers(FUEL_PATH, transform, crs, elev.shape)
    factor, duration_steps = build_evt_behavior_layers(evt_codes, canopy=canopy)
    if factor is None or duration_steps is None:
        return None, None

    groups = ["Water", "Developed", "Shrub", "Tree", "Herb", "Agriculture", "Sparse", "Other"]
    colors = ["#3977b7", "#767676", "#d95f02", "#238b45", "#e6ab02", "#a6761d", "#bdbdbd", "#756bb1"]
    group_index = np.full(elev.shape, -1, dtype="int16")
    rows = []
    cell_ha = TARGET_RES ** 2 / 1e4
    for value, row in attributes.items():
        selected = evt_codes == int(value)
        count = int(np.count_nonzero(selected))
        if count == 0:
            continue
        lifeform = str(row.get("EVT_LF", "")).strip().title()
        group = lifeform if lifeform in groups[:-1] else "Other"
        group_index[selected] = groups.index(group)
        burnable = selected & (fuel * factor > 0.02)
        rows.append({
            "evt_code": int(value),
            "evt_name": row.get("EVT_NAME", ""),
            "lifeform": row.get("EVT_LF", ""),
            "physiognomy": row.get("EVT_PHYS", ""),
            "group_name": row.get("EVT_GP_N", ""),
            "cell_count": count,
            "area_ha": count * cell_ha,
            "flammability_factor": float(np.mean(factor[selected])),
            "burn_residence_hours": (
                float(np.mean(duration_steps[burnable])) * MIN_PER_STEP / 60.0
                if burnable.any() else np.nan
            ),
        })
    rows.sort(key=lambda item: item["area_ha"], reverse=True)
    os.makedirs(os.path.dirname(out_csv) or ".", exist_ok=True)
    with open(out_csv, "w", newline="", encoding="utf-8") as stream:
        fields = [
            "evt_code", "evt_name", "lifeform", "physiognomy", "group_name",
            "cell_count", "area_ha", "flammability_factor", "burn_residence_hours",
        ]
        writer = csv.DictWriter(stream, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)

    fig, axes = plt.subplots(1, 2, figsize=(15.5, 8.2))
    fig.patch.set_facecolor("#17191b")
    hill = _dark_hillshade(elev)
    for ax in axes:
        ax.imshow(hill, cmap="gray", vmin=0.0, vmax=1.0)
        ax.axis("off")
    axes[0].imshow(
        np.ma.masked_less(group_index, 0), cmap=ListedColormap(colors),
        vmin=-0.5, vmax=len(groups) - 0.5, alpha=0.83,
    )
    handles = [
        mpatches.Patch(color=color, label=f"{name} EVT lifeform")
        for name, color in zip(groups, colors)
        if np.any(group_index == groups.index(name))
    ]
    _map_legend(axes[0], handles, loc="lower left", fontsize=8)

    residence_h = duration_steps.astype("float32") * MIN_PER_STEP / 60.0
    burnable = fuel * factor > 0.02
    image = axes[1].imshow(
        np.ma.masked_where(~burnable, residence_h), cmap="magma",
        vmin=float(np.nanmin(residence_h[burnable])),
        vmax=float(np.nanmax(residence_h[burnable])), alpha=0.86,
    )
    colorbar = fig.colorbar(image, ax=axes[1], fraction=0.042, pad=0.02)
    colorbar.set_label("Burn residence time (h)", color="white")
    colorbar.ax.tick_params(colors="white")
    _apply_lettered_bottom_caption(
        fig,
        axes,
        [
            "Grouped LANDFIRE 2024 Existing Vegetation Type lifeforms",
            "Per-cell burn residence derived from EVT lifeform, community and canopy",
        ],
        "Detailed Vegetation and Dynamic Burn Residence",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=180, bbox_inches="tight", facecolor=fig.get_facecolor())
    plt.close(fig)
    print("saved", out_png)
    print("saved", out_csv)
    return out_png, out_csv


def run_diagnostics(elev, fuel, wind, transform, crs, real_mask=None):
    os.makedirs(DIAGNOSTIC_OUT_DIR, exist_ok=True)
    load_moisture_timeline()
    r0, c0 = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
    r0 = int(np.clip(r0, 1, elev.shape[0] - 2))
    c0 = int(np.clip(c0, 1, elev.shape[1] - 2))
    if fuel is not None and not (fuel[r0, c0] > 0.02 and np.isfinite(elev[r0, c0])):
        ys, xs = np.where((fuel > 0.02) & np.isfinite(elev))
        if len(ys):
            k = int(np.argmin((ys - r0) ** 2 + (xs - c0) ** 2))
            r0, c0 = int(ys[k]), int(xs[k])
    ign = (r0, c0)

    plot_wind_timeseries(
        wind,
        os.path.join(DIAGNOSTIC_OUT_DIR, "wind_field_timeseries.png"),
        os.path.join(DIAGNOSTIC_OUT_DIR, "wind_field_timeseries.csv"),
    )
    plot_wind_correction_diagnostics(
        wind,
        os.path.join(DIAGNOSTIC_OUT_DIR, "wind_correction_diagnostics.png"),
        os.path.join(DIAGNOSTIC_OUT_DIR, "wind_correction_diagnostics.csv"),
    )
    validate_station_spatial_correction(
        wind,
        os.path.join(DIAGNOSTIC_OUT_DIR, "station_wind_cross_validation.png"),
        os.path.join(DIAGNOSTIC_OUT_DIR, "station_wind_cross_validation.csv"),
    )
    plot_terrain_maps(
        elev, ign, real_mask,
        os.path.join(DIAGNOSTIC_OUT_DIR, "terrain_slope.png"),
        os.path.join(DIAGNOSTIC_OUT_DIR, "terrain_aspect.png"),
        os.path.join(DIAGNOSTIC_OUT_DIR, "terrain_slope_aspect.png"),
    )
    plot_mechanism_diagnostic_maps(
        elev, fuel, wind, transform, crs, ign, real_mask,
        os.path.join(DIAGNOSTIC_OUT_DIR, "mechanism_evidence_maps.png"),
        os.path.join(DIAGNOSTIC_OUT_DIR, "mechanism_evidence_stats.csv"),
    )
    plot_evt_vegetation_diagnostics(
        elev, fuel, transform, crs,
        os.path.join(DIAGNOSTIC_OUT_DIR, "evt_vegetation_and_residence.png"),
        os.path.join(DIAGNOSTIC_OUT_DIR, "evt_vegetation_stats.csv"),
    )


def rethreshold_saved_rolling_particle_outputs(elev, transform, crs):
    """Apply the causal particle decision rule to saved forecasts without rerunning CA."""
    import csv

    probability_path = os.path.join(
        ROLLING_REF_OUT_DIR, "rolling_particle_probability.npz"
    )
    weights_path = os.path.join(
        ROLLING_REF_OUT_DIR, "rolling_particle_weights.csv"
    )
    if not os.path.exists(probability_path) or not os.path.exists(ROLLING_REF_SNAPSHOT_NPZ):
        raise FileNotFoundError(
            "Saved particle probabilities and rolling masks are required; "
            "run rolling-reference first."
        )
    records = load_paper_records_csv(ROLLING_REF_CSV)
    if not records:
        raise FileNotFoundError(f"No rolling records found at {ROLLING_REF_CSV}")
    records_by_day = {int(row["day"]): row for row in records}
    particle_data = np.load(probability_path)
    mask_data = np.load(ROLLING_REF_SNAPSHOT_NPZ)
    days = particle_data["days"].astype(int)
    probabilities = particle_data["probability"].astype("float32")
    prior_weights = particle_data["prior_weights"].astype("float32")
    mask_days = mask_data["days"].astype(int)
    pred_new_stack = mask_data["pred_new"].astype(bool)
    pred_cum_stack = mask_data["pred_cum"].astype(bool)
    ref_new_stack = mask_data["ref_new"].astype(bool)
    ref_cum_stack = mask_data["ref_cum"].astype(bool)
    reference_available = mask_data["reference_available"]
    mask_index = {int(day): index for index, day in enumerate(mask_days)}
    decision_thresholds = []
    changed_days = []
    cell_ha = TARGET_RES ** 2 / 1e4

    # Rebuild the Day 1 pre-window ignition state with the same fuel setup as
    # the full rolling forecast. A threshold-only replay cannot infer these
    # cells after they have once been counted as daily growth.
    initial_fire = np.zeros(elev.shape, dtype=bool)
    try:
        replay_fuel = load_fuel(FUEL_PATH, transform, crs, elev.shape)
        replay_canopy = load_canopy_layers(
            FUEL_PATH, transform, crs, elev.shape
        )
        replay_evt = load_evt_codes(EVT_PATH, transform, crs, elev.shape)
        replay_fuel, _duration, _evt = prepare_evt_fuel_behavior(
            replay_fuel,
            transform,
            crs,
            canopy=replay_canopy,
            evt_codes=replay_evt,
        )
        initial_state, _clock, _arrival, _ignition = initialize_ca_state(
            elev, replay_fuel, transform, crs
        )
        initial_fire = initial_state == BURNING
    except Exception as exc:
        # Retain a deterministic geometric fallback for archived runs whose
        # original LANDFIRE inputs have since been moved.
        r0, c0 = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
        r0 = int(np.clip(r0, 1, elev.shape[0] - 2))
        c0 = int(np.clip(c0, 1, elev.shape[1] - 2))
        yy, xx = np.ogrid[:elev.shape[0], :elev.shape[1]]
        initial_fire = (
            (yy - r0) ** 2 + (xx - c0) ** 2 <= IGNITION_RADIUS ** 2
        ) & np.isfinite(elev)
        print(f"Warning: reconstructed ignition without fuel mask: {exc}")

    for particle_index, day in enumerate(days):
        threshold = rolling_particle_decision_threshold(prior_weights[particle_index])
        decision_thresholds.append(threshold)
        index = mask_index.get(int(day))
        record = records_by_day.get(int(day))
        if index is None or record is None:
            continue
        ref_new = ref_new_stack[index]
        ref_cum = ref_cum_stack[index]
        # Preserve the exact pre-window state stored by the forecast. Deriving
        # this as ref_cum - ref_new loses the ignition seed on Day 1 and can
        # introduce small raster-boundary differences on later days.
        prev_assimilated = pred_cum_stack[index] & ~pred_new_stack[index]
        if particle_index == 0:
            prev_assimilated |= initial_fire
        try:
            area_budget_ha = float(record.get("forecast_area_budget_ha", np.nan))
        except Exception:
            area_budget_ha = np.nan
        try:
            mean_wind_speed = float(
                record.get("forecast_mean_wind_speed_mps", np.nan)
            )
        except Exception:
            mean_wind_speed = np.nan
        pred_new, fusion_stats = causal_budget_particle_mask(
            probabilities[particle_index],
            prev_assimilated,
            threshold,
            area_budget_ha,
            mean_wind_speed,
        )
        pred_cum = prev_assimilated | pred_new
        mask_changed = not (
            np.array_equal(pred_new_stack[index], pred_new) and
            np.array_equal(pred_cum_stack[index], pred_cum)
        )
        pred_new_stack[index] = pred_new
        pred_cum_stack[index] = pred_cum
        if mask_changed:
            changed_days.append(int(day))

        daily = _spatial_scores(pred_new, ref_new)
        tolerant = _tolerant_spatial_scores(pred_new, ref_new)
        cumulative = _spatial_scores(pred_cum, ref_cum)
        sim_new_ha = float(pred_new.sum()) * cell_ha
        sim_cum_ha = float(pred_cum.sum()) * cell_ha
        ref_new_ha = float(ref_new.sum()) * cell_ha
        ref_cum_ha = float(ref_cum.sum()) * cell_ha
        record.update({
            "sim_new_ha": sim_new_ha,
            "sim_cumulative_ha": sim_cum_ha,
            "daily_area_error_ha": sim_new_ha - ref_new_ha,
            "daily_area_error_pct": (sim_new_ha - ref_new_ha) / ref_new_ha * 100.0,
            "cumulative_area_error_ha": sim_cum_ha - ref_cum_ha,
            "cumulative_area_error_pct": (sim_cum_ha - ref_cum_ha) / ref_cum_ha * 100.0,
            "particle_threshold": threshold,
            "particle_budget_fusion_applied": bool(fusion_stats["applied"]),
            "particle_budget_core_ha": float(fusion_stats["core_ha"]),
            "particle_budget_added_ha": float(fusion_stats["added_ha"]),
            "particle_budget_selected_ha": float(fusion_stats["selected_ha"]),
            "particle_budget_candidate_ha": float(fusion_stats["candidate_ha"]),
            "particle_budget_blend": float(fusion_stats["blend"]),
            "daily_iou": daily["iou"],
            "daily_f1": daily["f1"],
            "daily_precision": daily["precision"],
            "daily_recall": daily["recall"],
            "daily_tolerance_m": tolerant["tolerance_m"],
            "daily_tolerant_iou": tolerant["iou"],
            "daily_tolerant_f1": tolerant["f1"],
            "daily_tolerant_precision": tolerant["precision"],
            "daily_tolerant_recall": tolerant["recall"],
            "daily_centroid_error_m": daily["centroid_error_m"],
            "daily_boundary_mean_error_m": daily["boundary_mean_error_m"],
            "daily_boundary_p95_error_m": daily["boundary_p95_error_m"],
            "daily_boundary_hausdorff_m": daily["boundary_hausdorff_m"],
            "cumulative_iou": cumulative["iou"],
            "cumulative_f1": cumulative["f1"],
            "cumulative_precision": cumulative["precision"],
            "cumulative_recall": cumulative["recall"],
            "cumulative_centroid_error_m": cumulative["centroid_error_m"],
            "cumulative_boundary_mean_error_m": cumulative["boundary_mean_error_m"],
            "cumulative_boundary_p95_error_m": cumulative["boundary_p95_error_m"],
            "cumulative_boundary_hausdorff_m": cumulative["boundary_hausdorff_m"],
        })

    # Metrics and schema may change even when the selected masks are identical.
    # Always persist the recomputed CSV, while avoiding needless NPZ rewrites.
    with open(ROLLING_REF_CSV, "w", newline="", encoding="utf-8") as f:
        fieldnames = []
        for record in records:
            for key in record:
                if key not in fieldnames:
                    fieldnames.append(key)
        writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(records)
    if changed_days:
        np.savez_compressed(
            ROLLING_REF_SNAPSHOT_NPZ,
            days=mask_days,
            pred_new=pred_new_stack,
            pred_cum=pred_cum_stack,
            ref_new=ref_new_stack,
            ref_cum=ref_cum_stack,
            reference_available=reference_available,
        )

    with open(weights_path, newline="", encoding="utf-8") as f:
        particle_rows = list(csv.DictReader(f))
    r0, c0 = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
    ign = (
        int(np.clip(r0, 1, elev.shape[0] - 2)),
        int(np.clip(c0, 1, elev.shape[1] - 2)),
    )
    probability_snapshots = [
        {
            "day": int(day),
            "probability": probabilities[index],
            "prior_weights": prior_weights[index],
            "decision_threshold": float(decision_thresholds[index]),
        }
        for index, day in enumerate(days)
    ]
    daily_ref_masks = {
        int(day): ref_cum_stack[index] for index, day in enumerate(mask_days)
    }
    write_rolling_particle_filter_outputs(
        particle_rows, probability_snapshots, elev, ign,
        daily_ref_masks, ROLLING_REF_OUT_DIR,
    )
    generate_paper_figures_from_existing(elev, transform, crs)
    print(
        "Applied causal particle threshold and budget fusion; changed day(s): " +
        (", ".join(map(str, changed_days)) if changed_days else "none")
    )


def generate_paper_figures_from_existing(
    elev, transform, crs, source_dir=None
):
    """Rebuild paper figures from saved CSV/masks without rerunning the CA."""
    source_dir = str(ROLLING_REF_OUT_DIR if source_dir is None else source_dir)
    source_csv = os.path.join(source_dir, "rolling_reference_forecast.csv")
    source_snapshots = os.path.join(
        source_dir, "rolling_reference_daily_masks.npz"
    )
    records = load_paper_records_csv(source_csv)
    if not records:
        raise FileNotFoundError(
            f"No rolling-reference records found at {source_csv}; "
            "run rolling-reference first."
        )
    snapshots = load_rolling_reference_snapshots(source_snapshots)
    r0, c0 = lonlat_to_rowcol(*IGNITION_LONLAT, transform, crs)
    ign = (
        int(np.clip(r0, 1, elev.shape[0] - 2)),
        int(np.clip(c0, 1, elev.shape[1] - 2)),
    )
    if snapshots:
        records_by_day = {int(row["day"]): row for row in records}
        is_building = None
        if FUEL_PATH and os.path.exists(FUEL_PATH):
            try:
                code = load_fbfm40_codes(FUEL_PATH, transform, crs, elev.shape)
                evt_codes = load_evt_codes(EVT_PATH, transform, crs, elev.shape)
                is_building, _, _ = build_wui_layers(code, evt_codes=evt_codes)
            except Exception:
                is_building = None
        previous_reference = None
        for index, item in enumerate(snapshots):
            day = int(item["day"])
            if index == 0:
                previous_reference = item["pred_cum"] & ~item["pred_new"]
            record = records_by_day.get(day)
            if record is None:
                continue
            draw_rolling_reference_day(
                elev, previous_reference, item["pred_new"], item["pred_cum"],
                item.get("ref_new"), item.get("ref_cum"), ign, record,
                os.path.join(
                    source_dir,
                    f"day{day:02d}_rolling_reference_forecast.png",
                ),
                is_building=is_building,
            )
            if item.get("ref_cum") is not None:
                previous_reference = item["ref_cum"]
    return write_paper_package(
        records, "Rolling Reference Forecast",
        daily_image_dir=source_dir,
        snapshots=snapshots,
        elev=elev,
        ign=ign,
    )


def run_daily_cost_control(elev, fuel, wind, transform, crs, real_mask=None,
                           rolling_reference=False, max_days=None, seed=None,
                           write_outputs=True, suppression_enabled=True,
                           daily_budget=None):
    """Run cost-based suppression, optionally as causal one-day rolling forecasts.

    In rolling mode, Day 1 starts from the ignition state and each later day
    starts from the previous observed perimeter.  The current day's perimeter
    is withheld until scoring and can only affect the following day.
    """
    run_seed = SEED if seed is None else int(seed)
    run_budget = (
        CONTROL_DAILY_BUDGET if daily_budget is None else max(0.0, float(daily_budget))
    )
    if not suppression_enabled:
        run_budget = 0.0
    if write_outputs:
        os.makedirs(CONTROL_OUT_DIR, exist_ok=True)
    rng = np.random.default_rng(run_seed)
    state, burn_clock, arrival, ign = initialize_ca_state(elev, fuel, transform, crs)
    active_fuel = fuel.copy()
    active_fuel[state == NONFUEL] = 0.0

    if FUEL_PATH and os.path.exists(FUEL_PATH):
        code = load_fbfm40_codes(FUEL_PATH, transform, crs, elev.shape)
    else:
        code = np.zeros(elev.shape, dtype="int32")
    canopy = load_canopy_layers(FUEL_PATH, transform, crs, elev.shape)
    evt_codes = load_evt_codes(EVT_PATH, transform, crs, elev.shape)
    is_building, veg_q, veg_crit = build_wui_layers(code, evt_codes=evt_codes)
    print(f"WUI paper model enabled: {int(is_building.sum())} building cells.")
    active_fuel, burn_duration_steps, evt_codes = prepare_evt_fuel_behavior(
        active_fuel, transform, crs, canopy=canopy, evt_codes=evt_codes
    )
    evt_attention, canopy_attention = build_vegetation_attention_layers(evt_codes, canopy)
    active_fuel[state == NONFUEL] = 0.0
    base_active_fuel = active_fuel.copy()
    value, human, cats, is_urban = build_control_value_maps(
        code, elev, evt_codes=evt_codes
    )
    aspect_fac, grow, gcol = build_rothermel_layers(elev)
    moisture_spatial = build_spatial_moisture_modifier(
        elev, aspect_fac, grow, gcol, fbfm_code=code, fuel=fuel
    )
    moisture_h, moisture_f = load_moisture_timeline()
    if ROTHERMEL_VEG_MODEL:
        msg = "Rothermel-like vegetation spread enabled"
        if moisture_h is not None:
            msg += f" with fire-weather ROS factor {float(np.nanmin(moisture_f)):.2f}-{float(np.nanmax(moisture_f)):.2f}"
        print(msg + ".")
    if LOW_WIND_TERRAIN_DOMINANT:
        print(f"Low-wind terrain/fuel dominance enabled below {LOW_WIND_THRESHOLD:.1f} m/s.")
    if moisture_spatial is not None:
        print(f"Spatial fuel-moisture modifier enabled: "
              f"{float(np.nanmin(moisture_spatial)):.2f}-{float(np.nanmax(moisture_spatial)):.2f}.")
    if CROWN_FIRE_MODEL:
        print("High-intensity/crown-fire source layer enabled for control forecasts and spread.")
    if FIRE_INDUCED_WIND_FEEDBACK:
        _FIRE_INDUCED_WIND_CACHE.clear()

    geo = neighbor_geometry()
    print(f"CA neighbor radius={CA_NEIGHBOR_RADIUS}, links={len(geo)}, "
          f"second-ring weight={CA_SECOND_RING_WEIGHT:.2f}.")
    directional_progress = make_directional_progress(geo, elev.shape)
    run_days = CONTROL_MAX_DAYS if max_days is None else max(1, int(max_days))
    daily_windows = (
        rolling_reference_time_windows(run_days)
        if rolling_reference else daily_time_windows()[:run_days]
    )
    start_time = np.datetime64(SIM_START.replace(" ", "T"))
    prev_fire = np.zeros(elev.shape, dtype=bool)
    firebreak_cum = np.zeros(elev.shape, dtype=bool)
    spread_accum = np.zeros(elev.shape, dtype="float32")
    control_damp = np.ones(elev.shape, dtype="float32")
    ros_scale = 1.0
    calibration_records = []
    records = []
    spread_frames = []
    control_frames = []
    gif_frame_dir = os.path.join(CONTROL_OUT_DIR, "_gif_frames")
    spot_stats = make_spotting_stats()
    spot_queue = make_spot_queue()
    initial_reference = (state == BURNING) | (state == BURNED)
    previous_reference_cum = initial_reference.copy()
    previous_reference_elapsed_h = 0.0
    attention_feedback = None
    adaptive_global_log = 0.0
    adaptive_sector_log = np.zeros(
        max(4, int(AUTOREGRESSIVE_SECTORS)), dtype="float32"
    )
    adaptive_spread_field = None
    front_momentum = None
    if write_outputs and GIF_LEGACY_MAP_FRAMES:
        os.makedirs(gif_frame_dir, exist_ok=True)
    daily_ref_masks, daily_ref_areas = load_daily_validation_references(transform, crs, elev.shape)
    daily_ref_new_masks = daily_increment_masks(daily_ref_masks)
    daily_ref_new_areas = daily_increment_areas(daily_ref_areas)

    protocol_label = (
        "causal rolling-reference cost control"
        if rolling_reference else "continuous cost-control scenario"
    )
    print(f"Cost-driven daily control loop ({protocol_label}):")
    if rolling_reference:
        print("  Current-day observations are withheld; each next day is initialized "
              "from the previous observed perimeter.")
        if DAILY_ROLLING_CALIBRATION:
            print("  Same-day ROS calibration is disabled in rolling-control mode "
                  "to prevent observation leakage.")
    if USE_GLOBAL_CONTAINMENT:
        print("Global containment term enabled: spread probabilities are time-damped.")
    else:
        print("Global containment term disabled: actions use no-action CA forecasts, not a hindsight clamp.")
    print(f"Sub-daily control cadence: first response after "
          f"{CONTROL_INITIAL_ATTACK_DELAY_HOURS:.1f} h, then every "
          f"{CONTROL_DECISION_HOURS:.1f} h; forecast horizon "
          f"{CONTROL_FORECAST_HOURS:.1f} h.")
    print(f"  Suppression enabled={suppression_enabled}; daily action budget "
          f"${run_budget:.0f}k.")
    print("  Day  hours  new(ha)  ha/hour  cumulative(ha)  no-action->controlled(ha)  avoided(ha)  loss($k)  action")

    for window in daily_windows:
        day = int(window["day"])
        init_source = (
            "ignition-only prediction"
            if day == 1 else (
                f"observed Day {day - 1} perimeter"
                if rolling_reference else "previous controlled state"
            )
        )
        day_random_seed = int(run_seed + day * 100003)
        day_rng = np.random.default_rng(day_random_seed)
        start_step = int(window["start_step"])
        end_step = min(N_STEPS, int(window["end_step"]))
        if start_step >= N_STEPS:
            break
        cell_ha = TARGET_RES ** 2 / 1e4
        if DAILY_ROLLING_CALIBRATION and not rolling_reference:
            day_perc_factor, _day_perc_stats = build_percolation_layers(active_fuel, is_building)
            ros_scale, cal = select_daily_ros_scale(
                state, burn_clock, arrival, active_fuel, elev, geo, wind,
                window, ros_scale, run_seed + 7100 + day * 43,
                daily_ref_masks=daily_ref_masks,
                daily_ref_new_masks=daily_ref_new_masks,
                daily_ref_areas=daily_ref_areas,
                daily_ref_new_areas=daily_ref_new_areas,
                ign=ign,
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                canopy=canopy, evt_attention=evt_attention,
                canopy_attention=canopy_attention,
                aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                moisture_h=moisture_h, moisture_f=moisture_f,
                spread_accum=spread_accum,
                percolation_factor=day_perc_factor,
                control_damp=control_damp,
                moisture_spatial=moisture_spatial,
                directional_progress=directional_progress,
                burn_duration_steps=burn_duration_steps,
            )
            cal["mode"] = "control"
            calibration_records.append(cal)
            print(f"  Day {day}: calibrated ROS scale = {ros_scale:.3f} "
                  f"({cal.get('reason', '')})")

        # Paired full-window no-action forecast.  It starts from exactly the
        # same state and random key as the controlled run, so differences are
        # attributable to suppression rather than a different random stream.
        day_percolation, _ = build_percolation_layers(active_fuel, is_building)
        no_control_state, no_control_arrival = simulate_window_with_scale(
            state, burn_clock, arrival, active_fuel, elev, geo, wind,
            start_step, end_step, day_random_seed, ros_scale,
            is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
            canopy=canopy, evt_attention=evt_attention,
            canopy_attention=canopy_attention,
            aspect_fac=aspect_fac, grow=grow, gcol=gcol,
            moisture_h=moisture_h, moisture_f=moisture_f,
            spread_accum=spread_accum,
            percolation_factor=day_percolation,
            control_damp=control_damp,
            moisture_spatial=moisture_spatial,
            directional_progress=directional_progress,
            attention_feedback=attention_feedback,
            burn_duration_steps=burn_duration_steps,
            adaptive_spread_field=adaptive_spread_field,
            front_momentum=front_momentum,
            paired_random_key=day_random_seed,
        )
        no_control_cum = (
            (no_control_state == BURNING) | (no_control_state == BURNED)
        )
        no_control_new = no_control_cum & ~prev_fire
        firebreak_before = firebreak_cum.copy()
        firebreak_new = np.zeros(elev.shape, dtype=bool)
        firefighter_mask = np.zeros(elev.shape, dtype=bool)
        heli_mask = np.zeros(elev.shape, dtype=bool)
        forecast_ha_total = 0.0
        forecast_after_total = 0.0
        avoided_ha_total = 0.0
        firebreak_cost_total = 0.0
        firebreak_len_m_total = 0.0
        firebreak_effective_benefit_total = 0.0
        protected_value_total = 0.0
        protected_area_total = 0.0
        net_benefit_total = 0.0
        firefighter_cost_total = 0.0
        firefighter_ha_total = 0.0
        firefighter_extinguished_total = 0.0
        firefighter_threatened_building_mask = np.zeros(elev.shape, dtype=bool)
        firefighter_active_building_mask = np.zeros(elev.shape, dtype=bool)
        firefighter_benefit_total = 0.0
        helicopter_cost_total = 0.0
        helicopter_ha_total = 0.0
        helicopter_active_total = 0.0
        helicopter_wetline_total = 0.0
        helicopter_head_total = 0.0
        helicopter_building_front_mask = np.zeros(elev.shape, dtype=bool)
        helicopter_benefit_total = 0.0
        directional_expected_avoided_total = 0.0
        directional_tail_escape_total = 0.0
        directional_net_benefit_total = 0.0
        directional_hold_probabilities = []
        directional_control_bearings = []
        rollout_risk_before_total = 0.0
        rollout_risk_after_total = 0.0
        rollout_net_benefit_total = 0.0
        rollout_accepted_count = 0
        rollout_rejected_count = 0
        action_reasons = []
        firefighter_reasons = []
        helicopter_reasons = []
        control_decision_elapsed_hours = []
        sub_decisions = 0
        percolation_stats = {}
        percolation_factor = None

        decision_steps = max(1, int(round(CONTROL_DECISION_HOURS * 60.0 / MIN_PER_STEP)))
        incident_elapsed_h = start_step * MIN_PER_STEP / 60.0
        first_wait_h = max(
            MIN_PER_STEP / 60.0,
            CONTROL_INITIAL_ATTACK_DELAY_HOURS - incident_elapsed_h,
        )
        first_decision_steps = max(
            1, int(round(first_wait_h * 60.0 / MIN_PER_STEP))
        )
        resource_release_steps = sorted({
            int(round(hours * 60.0 / MIN_PER_STEP))
            for hours in (
                FIREFIGHTER_MOBILIZATION_HOURS,
                HELI_MOBILIZATION_HOURS,
                FIREBREAK_MOBILIZATION_HOURS,
            )
            if hours > CONTROL_INITIAL_ATTACK_DELAY_HOURS
        })
        sub_start = start_step
        prev_interval_fire = (state == BURNING) | (state == BURNED)

        # The paired no-action trajectory has already been evaluated above.
        # Reuse it for the rolling no-suppression baseline instead of spending
        # a second CA rollout on an identical state and random field.
        if not suppression_enabled and rolling_reference:
            state[:] = no_control_state
            arrival[:] = no_control_arrival
            sub_start = end_step

        while sub_start < end_step:
            interval_steps = first_decision_steps if sub_decisions == 0 else decision_steps
            sub_end = min(end_step, sub_start + interval_steps)
            if sub_decisions > 0:
                for release_step in resource_release_steps:
                    if sub_start < release_step < sub_end:
                        sub_end = release_step
                        break
            percolation_factor, percolation_stats = build_percolation_layers(active_fuel, is_building)
            if PERCOLATION_MODEL and day == 1 and sub_start == start_step:
                print("Percolation layer enabled: "
                      f"critical density={PERCOLATION_PC:.2f}, "
                      f"mean density={percolation_stats.get('percolation_mean_density', 0.0):.2f}, "
                      f"giant cluster={percolation_stats.get('percolation_giant_frac', 0.0):.2f}.")

            for step in range(sub_start, sub_end):
                if not (state == BURNING).any() and not has_pending_spot_queue(spot_queue):
                    break
                ca_step(state, burn_clock, arrival, active_fuel, elev, geo, wind, step, day_rng,
                        is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                        canopy=canopy, evt_attention=evt_attention,
                        canopy_attention=canopy_attention,
                        aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                        moisture_h=moisture_h, moisture_f=moisture_f,
                        spread_accum=spread_accum,
                        percolation_factor=percolation_factor,
                        control_damp=control_damp,
                        moisture_spatial=moisture_spatial,
                        directional_progress=directional_progress,
                        ros_scale=ros_scale,
                        attention_feedback=attention_feedback,
                        adaptive_spread_field=adaptive_spread_field,
                        front_momentum=front_momentum,
                        spot_stats=spot_stats,
                        spot_queue=spot_queue,
                        burn_duration_steps=burn_duration_steps,
                        paired_random_key=day_random_seed)

            fire_now = (state == BURNING) | (state == BURNED)
            new_interval = fire_now & ~prev_interval_fire
            recover_control_damp(control_damp)
            forecast_limit_step = end_step if rolling_reference else N_STEPS
            forecast_steps = min(
                int(round(CONTROL_FORECAST_HOURS * 60.0 / MIN_PER_STEP)),
                max(0, forecast_limit_step - sub_end)
            )
            if rolling_reference and forecast_steps <= 0:
                # An action chosen at the observation cutoff cannot influence
                # this one-day forecast and would be discarded by assimilation.
                prev_interval_fire = fire_now.copy()
                sub_start = sub_end
                continue
            control_decision_elapsed_hours.append(
                sub_end * MIN_PER_STEP / 60.0
            )
            forecast_seed = run_seed + 10000 + day * 100 + sub_decisions
            forecast_new = forecast_next_window_mask(
                state, burn_clock, arrival, active_fuel, elev, geo, wind,
                sub_end, forecast_steps, forecast_seed,
                is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                canopy=canopy, evt_attention=evt_attention,
                canopy_attention=canopy_attention,
                aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                moisture_h=moisture_h, moisture_f=moisture_f,
                spread_accum=spread_accum,
                percolation_factor=percolation_factor,
                control_damp=control_damp,
                moisture_spatial=moisture_spatial,
                directional_progress=directional_progress,
                ros_scale=ros_scale,
                attention_feedback=attention_feedback,
                burn_duration_steps=burn_duration_steps,
                adaptive_spread_field=adaptive_spread_field,
                front_momentum=front_momentum,
            )

            control_array_snapshot = (
                state.copy(),
                burn_clock.copy(),
                active_fuel.copy(),
                control_damp.copy(),
                spread_accum.copy(),
                firebreak_cum.copy(),
            )
            control_mask_snapshot = (
                firebreak_new.copy(),
                firefighter_mask.copy(),
                heli_mask.copy(),
                firefighter_threatened_building_mask.copy(),
                firefighter_active_building_mask.copy(),
                helicopter_building_front_mask.copy(),
            )
            control_metric_snapshot = (
                firebreak_cost_total,
                firebreak_len_m_total,
                firebreak_effective_benefit_total,
                protected_value_total,
                protected_area_total,
                net_benefit_total,
                firefighter_cost_total,
                firefighter_ha_total,
                firefighter_extinguished_total,
                firefighter_benefit_total,
                helicopter_cost_total,
                helicopter_ha_total,
                helicopter_active_total,
                helicopter_wetline_total,
                helicopter_head_total,
                helicopter_benefit_total,
                directional_expected_avoided_total,
                directional_tail_escape_total,
                directional_net_benefit_total,
            )
            control_list_lengths = (
                len(directional_hold_probabilities),
                len(directional_control_bearings),
                len(action_reasons),
                len(firefighter_reasons),
                len(helicopter_reasons),
            )
            action_cost_before = (
                firebreak_cost_total + firefighter_cost_total + helicopter_cost_total
            )
            directional_undo = []
            incident_elapsed_h = sub_end * MIN_PER_STEP / 60.0

            if suppression_enabled and incident_elapsed_h >= FIREBREAK_MOBILIZATION_HOURS:
                action = choose_daily_firebreak(
                    state, new_interval, value, human, elev, wind, sub_end,
                    firebreak_cum, is_urban, active_fuel,
                    forecast_new=forecast_new,
                    budget_remaining=run_budget - (
                        firebreak_cost_total + firefighter_cost_total + helicopter_cost_total
                    ),
                    length_remaining_km=max(
                        0.0,
                        FIREBREAK_MAX_DAILY_LENGTH_KM - firebreak_len_m_total / 1000.0,
                    ),
                    area_remaining_ha=max(
                        0.0,
                        FIREBREAK_MAX_DAILY_AREA_HA - float(firebreak_new.sum()) * cell_ha,
                    ),
                )
            else:
                action = {
                    "placed": False,
                    "reason": (
                        "suppression disabled" if not suppression_enabled else
                        f"firebreak resource not available before {FIREBREAK_MOBILIZATION_HOURS:.1f} h"
                    ),
                }
            sub_firebreak = np.zeros(elev.shape, dtype=bool)
            if action.get("placed", False):
                sub_firebreak = action["mask"] & (state == UNBURNED)
                if sub_firebreak.any():
                    firebreak_cum |= sub_firebreak
                    firebreak_new |= sub_firebreak
                    active_fuel[sub_firebreak] = 0.0
                    state[sub_firebreak] = NONFUEL
                    spread_accum[sub_firebreak] = 0.0
                    directional_undo.append((
                        sub_firebreak.copy(),
                        directional_progress[:, sub_firebreak].copy(),
                    ))
                    directional_progress[:, sub_firebreak] = 0.0
                    control_damp[sub_firebreak] = 1.0
                    firebreak_cost_total += float(action.get("build_cost", 0.0))
                    firebreak_len_m_total += float(action.get("length_m", 0.0))
                    firebreak_effective_benefit_total += float(action.get("effective_benefit", 0.0))
                    protected_value_total += float(action.get("protected_value", 0.0))
                    protected_area_total += float(action.get("protected_area_ha", 0.0))
                    net_benefit_total += float(action.get("net", 0.0))
                    directional_expected_avoided_total += float(
                        action.get("expected_avoided_loss", 0.0)
                    )
                    directional_tail_escape_total += float(
                        action.get("tail_escape_penalty", 0.0)
                    )
                    directional_net_benefit_total += float(action.get("net", 0.0))
                    if np.isfinite(action.get("hold_probability", np.nan)):
                        directional_hold_probabilities.append(
                            float(action["hold_probability"])
                        )
                    if np.isfinite(action.get("bearing", np.nan)):
                        directional_control_bearings.append(float(action["bearing"]))
                    action_reasons.append(f"{sub_decisions + 1}: firebreak")
                else:
                    action_reasons.append(f"{sub_decisions + 1}: selected line overlapped burned/nonfuel cells")
            else:
                action_reasons.append(f"{sub_decisions + 1}: {action.get('reason', 'no action')}")

            if suppression_enabled and incident_elapsed_h >= FIREFIGHTER_MOBILIZATION_HOURS:
                firefighter = apply_firefighter_response(
                    state, burn_clock, new_interval, is_building, is_urban, active_fuel,
                    control_damp, spread_accum, value, human,
                    budget_remaining=run_budget - (
                        firebreak_cost_total + firefighter_cost_total + helicopter_cost_total
                    ),
                    forecast_new=forecast_new,
                    wind=wind,
                    step=sub_end,
                )
            else:
                firefighter = {
                    "placed": False,
                    "reason": (
                        "suppression disabled" if not suppression_enabled else
                        f"ground resources not available before {FIREFIGHTER_MOBILIZATION_HOURS:.1f} h"
                    ),
                    "mask": np.zeros(elev.shape, dtype=bool),
                }
            sub_firefighter = firefighter.get("mask", np.zeros(elev.shape, dtype=bool))
            if firefighter.get("placed", False):
                firefighter_mask |= sub_firefighter
                if sub_firefighter.any():
                    directional_progress[:, sub_firefighter] *= FIREFIGHTER_ACCUM_REDUCTION
                firefighter_ha_total += float(firefighter.get("area_ha", 0.0))
                firefighter_extinguished_total += float(firefighter.get("extinguished_ha", 0.0))
                if firefighter.get("threatened_building_mask") is not None:
                    firefighter_threatened_building_mask |= firefighter["threatened_building_mask"]
                if firefighter.get("active_building_mask") is not None:
                    firefighter_active_building_mask |= firefighter["active_building_mask"]
                firefighter_cost_total += float(firefighter.get("cost", 0.0))
                firefighter_benefit_total += float(firefighter.get("benefit_proxy", 0.0))
                directional_expected_avoided_total += float(
                    firefighter.get("expected_avoided_loss", 0.0)
                )
                directional_tail_escape_total += float(
                    firefighter.get("tail_escape_penalty", 0.0)
                )
                directional_net_benefit_total += (
                    float(firefighter.get("expected_avoided_loss", 0.0)) -
                    float(firefighter.get("tail_escape_penalty", 0.0)) -
                    float(firefighter.get("cost", 0.0))
                )
                if np.isfinite(firefighter.get("hold_probability", np.nan)):
                    directional_hold_probabilities.append(
                        float(firefighter["hold_probability"])
                    )
                firefighter_reasons.append(
                    f"{sub_decisions + 1}: {firefighter.get('reason', 'ground response')}"
                )
            else:
                firefighter_reasons.append(f"{sub_decisions + 1}: {firefighter.get('reason', '')}")

            if suppression_enabled and incident_elapsed_h >= HELI_MOBILIZATION_HOURS:
                helicopter = choose_helicopter_drop(
                    forecast_new, state, active_fuel, value, human, wind, sub_end,
                    budget_remaining=run_budget - (
                        firebreak_cost_total + firefighter_cost_total + helicopter_cost_total
                    ),
                    already_treated=(firebreak_cum | firefighter_mask),
                    is_building=is_building,
                )
            else:
                helicopter = {
                    "placed": False,
                    "reason": (
                        "suppression disabled" if not suppression_enabled else
                        f"aviation resource not available before {HELI_MOBILIZATION_HOURS:.1f} h"
                    ),
                }
            sub_heli = np.zeros(elev.shape, dtype=bool)
            if helicopter.get("placed", False):
                sub_heli = helicopter["mask"] & ((state == UNBURNED) | (state == BURNING))
                if sub_heli.any():
                    heli_mask |= sub_heli
                    actual_ha = float(sub_heli.sum()) * cell_ha
                    helicopter["area_ha"] = actual_ha
                    helicopter["cost"] = HELI_MOBILIZATION_COST + actual_ha * HELI_COST_PER_HA
                    helicopter["active_ha"] = float((sub_heli & (state == BURNING)).sum()) * cell_ha
                    helicopter["wetline_ha"] = float((sub_heli & (state == UNBURNED)).sum()) * cell_ha
                    helicopter["head_front_ha"] = min(float(helicopter.get("head_front_ha", 0.0)), actual_ha)
                    control_damp[sub_heli] = np.minimum(control_damp[sub_heli], HELI_DAMP_FACTOR)
                    spread_accum[sub_heli & (state == UNBURNED)] *= HELI_ACCUM_REDUCTION
                    directional_undo.append((
                        sub_heli.copy(),
                        directional_progress[:, sub_heli].copy(),
                    ))
                    directional_progress[:, sub_heli] *= HELI_ACCUM_REDUCTION
                    helicopter_ha_total += actual_ha
                    helicopter_active_total += float(helicopter.get("active_ha", 0.0))
                    helicopter_wetline_total += float(helicopter.get("wetline_ha", 0.0))
                    helicopter_head_total += float(helicopter.get("head_front_ha", 0.0))
                    if helicopter.get("building_front_mask") is not None:
                        helicopter_building_front_mask |= helicopter["building_front_mask"]
                    helicopter_cost_total += float(helicopter.get("cost", 0.0))
                    helicopter_benefit_total += float(helicopter.get("benefit_proxy", 0.0))
                    directional_expected_avoided_total += float(
                        helicopter.get("expected_avoided_loss", 0.0)
                    )
                    directional_tail_escape_total += float(
                        helicopter.get("tail_escape_penalty", 0.0)
                    )
                    directional_net_benefit_total += (
                        float(helicopter.get("expected_avoided_loss", 0.0)) -
                        float(helicopter.get("tail_escape_penalty", 0.0)) -
                        float(helicopter.get("cost", 0.0))
                    )
                    if np.isfinite(helicopter.get("hold_probability", np.nan)):
                        directional_hold_probabilities.append(
                            float(helicopter["hold_probability"])
                        )
                    helicopter_reasons.append(f"{sub_decisions + 1}: heli")
                else:
                    helicopter_reasons.append(f"{sub_decisions + 1}: selected drop overlapped burned/nonfuel cells")
            else:
                helicopter_reasons.append(f"{sub_decisions + 1}: {helicopter.get('reason', '')}")

            forecast_after_control = np.zeros(elev.shape, dtype=bool)
            if EVALUATE_CONTROL_EFFECT and forecast_steps > 0:
                # Use common random numbers with forecast_new so the avoided-area
                # diagnostic reflects actions instead of stochastic forecast noise.
                effect_steps = forecast_steps
                post_control_percolation, _ = build_percolation_layers(
                    active_fuel, is_building
                )
                forecast_after_control = forecast_next_window_mask(
                    state, burn_clock, arrival, active_fuel, elev, geo, wind,
                    sub_end, effect_steps, forecast_seed,
                    is_building=is_building, veg_q=veg_q, veg_crit=veg_crit,
                    canopy=canopy, evt_attention=evt_attention,
                    canopy_attention=canopy_attention,
                    aspect_fac=aspect_fac, grow=grow, gcol=gcol,
                    moisture_h=moisture_h, moisture_f=moisture_f,
                    spread_accum=spread_accum,
                    percolation_factor=post_control_percolation,
                    control_damp=control_damp,
                    moisture_spatial=moisture_spatial,
                    directional_progress=directional_progress,
                    ros_scale=ros_scale,
                    attention_feedback=attention_feedback,
                    burn_duration_steps=burn_duration_steps,
                    adaptive_spread_field=adaptive_spread_field,
                    front_momentum=front_momentum,
                )
            action_cost_after = (
                firebreak_cost_total + firefighter_cost_total + helicopter_cost_total
            )
            incremental_action_cost = max(
                0.0, action_cost_after - action_cost_before
            )
            selected_portfolio = incremental_action_cost > 1e-9
            rollout = evaluate_control_rollout(
                control_array_snapshot[0],
                forecast_new,
                forecast_after_control,
                value,
                human,
                wind,
                sub_end,
                control_array_snapshot[2],
                incremental_action_cost,
            )
            rollout_risk_before_total += rollout["risk_before"]
            rollout_risk_after_total += rollout["risk_after"]
            rollout_net_benefit_total += rollout["net_benefit"]
            if selected_portfolio and not rollout["accepted"]:
                (
                    state_before_action,
                    burn_clock_before_action,
                    fuel_before_action,
                    damp_before_action,
                    accum_before_action,
                    firebreak_before_action,
                ) = control_array_snapshot
                state[:] = state_before_action
                burn_clock[:] = burn_clock_before_action
                active_fuel[:] = fuel_before_action
                control_damp[:] = damp_before_action
                spread_accum[:] = accum_before_action
                firebreak_cum[:] = firebreak_before_action
                for undo_mask, undo_values in reversed(directional_undo):
                    directional_progress[:, undo_mask] = undo_values
                (
                    firebreak_new_before_action,
                    firefighter_mask_before_action,
                    heli_mask_before_action,
                    firefighter_threat_before_action,
                    firefighter_active_before_action,
                    helicopter_front_before_action,
                ) = control_mask_snapshot
                firebreak_new[:] = firebreak_new_before_action
                firefighter_mask[:] = firefighter_mask_before_action
                heli_mask[:] = heli_mask_before_action
                firefighter_threatened_building_mask[:] = firefighter_threat_before_action
                firefighter_active_building_mask[:] = firefighter_active_before_action
                helicopter_building_front_mask[:] = helicopter_front_before_action
                (
                    firebreak_cost_total,
                    firebreak_len_m_total,
                    firebreak_effective_benefit_total,
                    protected_value_total,
                    protected_area_total,
                    net_benefit_total,
                    firefighter_cost_total,
                    firefighter_ha_total,
                    firefighter_extinguished_total,
                    firefighter_benefit_total,
                    helicopter_cost_total,
                    helicopter_ha_total,
                    helicopter_active_total,
                    helicopter_wetline_total,
                    helicopter_head_total,
                    helicopter_benefit_total,
                    directional_expected_avoided_total,
                    directional_tail_escape_total,
                    directional_net_benefit_total,
                ) = control_metric_snapshot
                (
                    hold_len,
                    bearing_len,
                    action_len,
                    firefighter_reason_len,
                    helicopter_reason_len,
                ) = control_list_lengths
                del directional_hold_probabilities[hold_len:]
                del directional_control_bearings[bearing_len:]
                del action_reasons[action_len:]
                del firefighter_reasons[firefighter_reason_len:]
                del helicopter_reasons[helicopter_reason_len:]
                reason_parts = []
                if not rollout["area_constraint_ok"]:
                    reason_parts.append("forecast area increased")
                if rollout["net_benefit"] <= 0.0:
                    reason_parts.append("forecast net risk did not improve")
                reason = " and ".join(reason_parts) or "rollout acceptance failed"
                action_reasons.append(
                    f"{sub_decisions + 1}: portfolio rejected ({reason})"
                )
                forecast_after_control = forecast_new.copy()
                rollout_rejected_count += 1
            elif selected_portfolio:
                rollout_accepted_count += 1
            forecast_ha = float(forecast_new.sum()) * cell_ha
            forecast_after_ha = float(forecast_after_control.sum()) * cell_ha
            forecast_ha_total += forecast_ha
            forecast_after_total += forecast_after_ha
            avoided_ha_total += max(0.0, forecast_ha - forecast_after_ha)
            sub_decisions += 1
            prev_interval_fire = fire_now.copy()
            sub_start = sub_end
            if not (state == BURNING).any() and day > 1:
                break

        fire_now = (state == BURNING) | (state == BURNED)
        new_today = fire_now & ~prev_fire
        loss = cost_breakdown(new_today, value, human, cats)
        no_control_loss = cost_breakdown(no_control_new, value, human, cats)
        daily_ref_mask = daily_ref_new_masks.get(day)
        daily_ref_cum_mask = daily_ref_masks.get(day)
        daily_scores = _spatial_scores(new_today, daily_ref_mask)
        no_control_daily_scores = _spatial_scores(no_control_new, daily_ref_mask)
        cumulative_scores = _spatial_scores(fire_now, daily_ref_cum_mask)
        no_control_cumulative_scores = _spatial_scores(
            no_control_cum, daily_ref_cum_mask
        )
        daily_ref_ha = float(daily_ref_mask.sum()) * cell_ha if daily_ref_mask is not None else np.nan
        daily_ref_cumulative_ha = (
            float(daily_ref_cum_mask.sum()) * cell_ha
            if daily_ref_cum_mask is not None else np.nan
        )
        control_union = firebreak_new | firefighter_mask | heli_mask
        suppression_union = firefighter_mask | heli_mask
        frame_wind = wind_snapshot_for_frame(
            wind, max(start_step, end_step - 1),
            focus_mask=(new_today | fire_now)
        )
        window_hours = max(0.0, float(window["end_h"]) - float(window["start_h"]))
        new_today_ha = float(new_today.sum()) * cell_ha
        no_control_new_ha = float(no_control_new.sum()) * cell_ha
        no_control_cum_ha = float(no_control_cum.sum()) * cell_ha
        daily_avoided_ha = no_control_new_ha - new_today_ha
        prevented_mask = no_control_new & ~new_today
        displaced_mask = new_today & ~no_control_new
        realized_loss_avoided = float(no_control_loss["total_loss"] - loss["total_loss"])

        fixed_suppression_cost = DAILY_SUPPRESSION_COST if suppression_enabled else 0.0
        total_control_cost = (
            fixed_suppression_cost + firebreak_cost_total +
            firefighter_cost_total + helicopter_cost_total
        )
        realized_benefit_cost_ratio = (
            max(0.0, realized_loss_avoided) / total_control_cost
            if total_control_cost > 1e-9 else np.nan
        )
        record = {
            "day": day,
            "day_random_seed": day_random_seed,
            "suppression_enabled": bool(suppression_enabled),
            "evaluation_protocol": protocol_label,
            "init_source": init_source,
            "forecast_cutoff_utc": window["window_start_utc"],
            "current_window_reference_used": False,
            "assimilated_after_day": bool(
                rolling_reference and daily_ref_cum_mask is not None and
                day < len(daily_windows)
            ),
            "window_start_utc": window["window_start_utc"],
            "window_end_utc": window["window_end_utc"],
            "window_start_local": window.get("window_start_local", ""),
            "window_end_local": window.get("window_end_local", ""),
            "window_hours": window_hours,
            "ros_scale": ros_scale,
            "new_ha": new_today_ha,
            "new_ha_per_hour": new_today_ha / window_hours if window_hours > 0 else np.nan,
            "cum_ha": float(fire_now.sum()) * cell_ha,
            "no_control_new_ha": no_control_new_ha,
            "no_control_cumulative_ha": no_control_cum_ha,
            "daily_avoided_ha": daily_avoided_ha,
            "daily_area_reduction_pct": (
                100.0 * daily_avoided_ha / no_control_new_ha
                if no_control_new_ha > 1e-9 else 0.0
            ),
            "prevented_ha": float(prevented_mask.sum()) * cell_ha,
            "displaced_ha": float(displaced_mask.sum()) * cell_ha,
            "no_control_loss_total": float(no_control_loss["total_loss"]),
            "realized_loss_avoided_k": realized_loss_avoided,
            "realized_net_benefit_k": realized_loss_avoided - total_control_cost,
            "realized_benefit_cost_ratio": realized_benefit_cost_ratio,
            "daily_ref_ha": daily_ref_ha,
            "no_control_daily_iou": no_control_daily_scores["iou"],
            "no_control_daily_f1": no_control_daily_scores["f1"],
            "controlled_daily_iou_delta": (
                daily_scores["iou"] - no_control_daily_scores["iou"]
                if np.isfinite(daily_scores["iou"]) and
                np.isfinite(no_control_daily_scores["iou"]) else np.nan
            ),
            "daily_ref_cumulative_ha": daily_ref_cumulative_ha,
            "daily_iou": daily_scores["iou"],
            "daily_f1": daily_scores["f1"],
            "daily_precision": daily_scores["precision"],
            "daily_recall": daily_scores["recall"],
            "daily_centroid_error_m": daily_scores["centroid_error_m"],
            "daily_boundary_mean_error_m": daily_scores["boundary_mean_error_m"],
            "daily_boundary_p95_error_m": daily_scores["boundary_p95_error_m"],
            "daily_boundary_hausdorff_m": daily_scores["boundary_hausdorff_m"],
            "daily_shape_orientation_error_deg": daily_scores["shape_orientation_error_deg"],
            "daily_shape_linear_scale_ratio": daily_scores["shape_linear_scale_ratio"],
            "daily_shape_log_scale_error": daily_scores["shape_log_scale_error"],
            "daily_shape_elongation_log_error": daily_scores["shape_elongation_log_error"],
            "daily_shape_radial_nrmse": daily_scores["shape_radial_nrmse"],
            "cumulative_iou": cumulative_scores["iou"],
            "cumulative_f1": cumulative_scores["f1"],
            "cumulative_precision": cumulative_scores["precision"],
            "cumulative_recall": cumulative_scores["recall"],
            "cumulative_centroid_error_m": cumulative_scores["centroid_error_m"],
            "cumulative_boundary_mean_error_m": cumulative_scores["boundary_mean_error_m"],
            "cumulative_boundary_p95_error_m": cumulative_scores["boundary_p95_error_m"],
            "cumulative_boundary_hausdorff_m": cumulative_scores["boundary_hausdorff_m"],
            "cumulative_shape_orientation_error_deg": cumulative_scores["shape_orientation_error_deg"],
            "cumulative_shape_linear_scale_ratio": cumulative_scores["shape_linear_scale_ratio"],
            "cumulative_shape_log_scale_error": cumulative_scores["shape_log_scale_error"],
            "cumulative_shape_elongation_log_error": cumulative_scores["shape_elongation_log_error"],
            "cumulative_shape_radial_nrmse": cumulative_scores["shape_radial_nrmse"],
            "no_control_cumulative_iou": no_control_cumulative_scores["iou"],
            "no_control_cumulative_f1": no_control_cumulative_scores["f1"],
            "forecast_ha": forecast_ha_total,
            "forecast_after_control_ha": forecast_after_total,
            "avoided_by_controls_ha": avoided_ha_total,
            "control_effect_ratio": avoided_ha_total / max(forecast_ha_total, 1e-9),
            "treated_control_ha": float(control_union.sum()) * cell_ha,
            "suppression_treated_ha": float(suppression_union.sum()) * cell_ha,
            "loss": loss,
            "loss_total": loss["total_loss"],
            "control_decisions": sub_decisions,
            "control_decision_hours": CONTROL_DECISION_HOURS,
            "control_initial_attack_delay_hours": CONTROL_INITIAL_ATTACK_DELAY_HOURS,
            "control_decision_elapsed_hours": ";".join(
                f"{hours:.2f}" for hours in control_decision_elapsed_hours
            ),
            "firebreak_placed": bool(firebreak_new.any()),
            "firebreak_km": firebreak_len_m_total / 1000.0,
            "firebreak_ha": float(firebreak_new.sum()) * cell_ha,
            "firebreak_cost": firebreak_cost_total,
            "firebreak_effective_benefit": firebreak_effective_benefit_total,
            "firebreak_benefit_cost_ratio": firebreak_effective_benefit_total / max(firebreak_cost_total, 1e-9),
            "protected_value": protected_value_total,
            "protected_area_ha": protected_area_total,
            "firebreak_repeat_frac": 0.0,
            "firebreak_spacing_penalty": 1.0,
            "net_benefit": net_benefit_total,
            "action_reason": "; ".join(action_reasons) if action_reasons else "no action",
            "firefighter_placed": bool(firefighter_mask.any()),
            "firefighter_ha": firefighter_ha_total,
            "firefighter_extinguished_ha": firefighter_extinguished_total,
            "firefighter_threatened_building_ha": (
                float(firefighter_threatened_building_mask.sum()) * cell_ha
            ),
            "firefighter_active_building_ha": (
                float(firefighter_active_building_mask.sum()) * cell_ha
            ),
            "firefighter_cost": firefighter_cost_total,
            "firefighter_benefit_proxy": firefighter_benefit_total,
            "firefighter_benefit_cost_ratio": firefighter_benefit_total / max(firefighter_cost_total, 1e-9),
            "firefighter_reason": "; ".join([r for r in firefighter_reasons if r]),
            "helicopter_placed": bool(heli_mask.any()),
            "helicopter_ha": helicopter_ha_total,
            "helicopter_active_ha": helicopter_active_total,
            "helicopter_wetline_ha": helicopter_wetline_total,
            "helicopter_head_front_ha": helicopter_head_total,
            "helicopter_building_front_ha": (
                float(helicopter_building_front_mask.sum()) * cell_ha
            ),
            "helicopter_cost": helicopter_cost_total,
            "helicopter_benefit_proxy": helicopter_benefit_total,
            "helicopter_benefit_cost_ratio": helicopter_benefit_total / max(helicopter_cost_total, 1e-9),
            "helicopter_reason": "; ".join([r for r in helicopter_reasons if r]),
            "control_cost_total": total_control_cost,
            "fixed_suppression_cost_k": fixed_suppression_cost,
            "control_budget_k": run_budget,
            "control_budget_used_k": firebreak_cost_total + firefighter_cost_total + helicopter_cost_total,
            "control_budget_remaining_k": max(
                0.0,
                run_budget - (firebreak_cost_total + firefighter_cost_total + helicopter_cost_total),
            ),
            "directional_objective_expected_avoided_k": directional_expected_avoided_total,
            "directional_objective_tail_escape_k": directional_tail_escape_total,
            "directional_objective_net_benefit_k": directional_net_benefit_total,
            "directional_objective_mean_hold_probability": (
                float(np.mean(directional_hold_probabilities))
                if directional_hold_probabilities else np.nan
            ),
            "directional_objective_bearing_deg": (
                _circular_mean_deg(np.asarray(directional_control_bearings, dtype=float))
                if directional_control_bearings else np.nan
            ),
            "control_rollout_risk_before_k": rollout_risk_before_total,
            "control_rollout_candidate_risk_after_k": rollout_risk_after_total,
            "control_rollout_candidate_net_benefit_k": rollout_net_benefit_total,
            "control_rollout_accepted": rollout_accepted_count,
            "control_rollout_rejected": rollout_rejected_count,
            "percolation": percolation_stats,
        }
        record.update(frame_wind)
        records.append(record)

        if write_outputs:
            spread_png = os.path.join(CONTROL_OUT_DIR, f"day{day:02d}_spread_after_burn.png")
            control_png = os.path.join(CONTROL_OUT_DIR, f"day{day:02d}_control_action.png")
            draw_daily_spread(elev, prev_fire, new_today, fire_now, firebreak_before,
                              ign, real_mask, record, spread_png, is_building=is_building,
                              daily_ref_mask=daily_ref_mask,
                              no_control_cum=no_control_cum)
            draw_daily_control(elev, fire_now, firebreak_before, firebreak_new, value, human,
                               ign, real_mask, record, control_png, is_building=is_building,
                               firefighter_mask=firefighter_mask, heli_mask=heli_mask,
                               daily_ref_mask=daily_ref_mask)
            if GIF_LEGACY_MAP_FRAMES:
                spread_gif_png = os.path.join(gif_frame_dir, f"day{day:02d}_spread_after_burn.png")
                control_gif_png = os.path.join(gif_frame_dir, f"day{day:02d}_control_action.png")
                draw_daily_spread(elev, prev_fire, new_today, fire_now, firebreak_before,
                              ign, real_mask, record, spread_gif_png, is_building=is_building,
                              daily_ref_mask=daily_ref_mask,
                              crop_context_mask=real_mask,
                              no_control_cum=no_control_cum)
                draw_daily_control(elev, fire_now, firebreak_before, firebreak_new, value, human,
                               ign, real_mask, record, control_gif_png, is_building=is_building,
                               firefighter_mask=firefighter_mask, heli_mask=heli_mask,
                               daily_ref_mask=daily_ref_mask,
                               crop_context_mask=real_mask)
                spread_frames.append(spread_gif_png)
                control_frames.append(control_gif_png)
            else:
                spread_frames.append(spread_png)
                control_frames.append(control_png)

        actions = []
        if record["firebreak_placed"]:
            actions.append(f"firebreak {record['firebreak_km']:.1f} km")
        if record["firefighter_placed"]:
            actions.append(f"crews {record['firefighter_ha']:.0f} ha")
        if record["helicopter_placed"]:
            actions.append(f"heli {record['helicopter_ha']:.0f} ha")
        action_text = "; ".join(actions) if actions else record["action_reason"]
        print(f"  {day:>3}  {record['window_hours']:5.1f}  {record['new_ha']:7.0f}  "
              f"{record['new_ha_per_hour']:7.1f}  {record['cum_ha']:14.0f}  "
              f"{record['no_control_new_ha']:7.0f}->{record['new_ha']:<7.0f}  "
              f"{record['daily_avoided_ha']:10.0f}  {record['loss_total']:8.0f}  {action_text}")

        if rolling_reference and daily_ref_cum_mask is not None and day < len(daily_windows):
            next_window = daily_windows[day]
            next_wind_speed = estimate_window_mean_wind_speed(wind, next_window)
            next_wind_toward = estimate_window_mean_wind_toward(wind, next_window)
            current_fire_potential = estimate_window_fire_potential(
                wind, window, moisture_h, moisture_f
            )
            next_fire_potential = estimate_window_fire_potential(
                wind, next_window, moisture_h, moisture_f
            )
            next_regime_memory = forecast_regime_memory(
                estimate_window_mean_wind_speed(wind, window),
                next_wind_speed,
                current_fire_potential,
                next_fire_potential,
            )
            next_feedback = build_attention_feedback(
                no_control_new, no_control_cum,
                daily_ref_mask, daily_ref_cum_mask,
            )
            next_correction = build_autoregressive_spread_correction(
                no_control_new, daily_ref_mask, ign,
                previous_global_log=adaptive_global_log,
                previous_sector_log=adaptive_sector_log,
            )
            adaptive_global_log = (
                float(next_correction["global_log"]) * next_regime_memory
            )
            ros_scale = float(np.clip(
                np.exp(adaptive_global_log),
                AUTOREGRESSIVE_GLOBAL_MIN,
                AUTOREGRESSIVE_GLOBAL_MAX,
            ))
            adaptive_sector_log = (
                np.asarray(next_correction["sector_log"], dtype="float32") *
                next_regime_memory
            ).astype("float32")
            adaptive_sector_factors = np.clip(
                np.exp(adaptive_sector_log),
                AUTOREGRESSIVE_SECTOR_MIN,
                AUTOREGRESSIVE_SECTOR_MAX,
            ).astype("float32")
            adaptive_spread_field = sector_spread_scale_field(
                elev.shape, ign, adaptive_sector_factors
            )
            if next_feedback is not None:
                next_feedback = (
                    next_feedback * next_regime_memory
                ).astype("float32")

            # Daily controls are counterfactual.  Restore the environmental
            # fuel field before assimilating the real previous-day perimeter;
            # otherwise a simulated line would leak into the next observed
            # initial condition.
            active_fuel[:] = base_active_fuel
            control_damp[:] = 1.0
            firebreak_cum[:] = False
            assimilated_cum, front_stats = reset_state_to_reference_perimeter(
                state, burn_clock, arrival, daily_ref_cum_mask,
                active_fuel, elev, float(window["end_h"]),
                spread_accum=spread_accum,
                directional_progress=directional_progress,
                previous_ref_mask=previous_reference_cum,
                previous_elapsed_h=previous_reference_elapsed_h,
                return_front_stats=True,
                forecast_wind_speed=next_wind_speed,
                forecast_wind_toward_deg=next_wind_toward,
                burn_duration_steps=burn_duration_steps,
                model_arrival_weight=(
                    0.0 if next_regime_memory <= 1e-9 else
                    ASSIMILATION_MODEL_ARRIVAL_WEIGHT
                ),
                terrain_weight_cap=float(np.clip(
                    ASSIMILATION_MAX_TERRAIN_WEIGHT +
                    ASSIMILATION_REGIME_TERRAIN_GAIN * (1.0 - next_regime_memory),
                    0.0,
                    1.0,
                )),
                front_feedback=next_feedback,
                momentum_memory=next_regime_memory,
            )
            front_momentum, momentum_stats = build_reference_front_momentum(
                daily_ref_cum_mask,
                previous_reference_cum,
                state == BURNING,
                int(next_window["start_step"]),
                forecast_wind_speed=next_wind_speed,
                regime_memory=next_regime_memory,
            )
            front_stats.update(momentum_stats)
            previous_reference_cum = daily_ref_cum_mask.copy()
            previous_reference_elapsed_h = float(window["end_h"])
            attention_feedback = next_feedback
            prev_fire = assimilated_cum.copy()
            spot_queue = make_spot_queue()
            if FIRE_INDUCED_WIND_FEEDBACK:
                _FIRE_INDUCED_WIND_CACHE.clear()
            print(
                f"  -> Day {day + 1} initialized causally from observed Day {day}; "
                f"ROS scale={ros_scale:.3f}, active front="
                f"{front_stats.get('active_cells', 0)} cells."
            )
        else:
            prev_fire = fire_now.copy()
        if not (state == BURNING).any() and day > 1:
            break

    if write_outputs:
        write_daily_ros_calibration(
            calibration_records,
            os.path.join(CONTROL_OUT_DIR, "daily_ros_calibration.csv")
        )
        write_control_csv(records)
        write_paper_package(records, "Cost-Controlled CA")
        write_spotting_stats(
            spot_stats,
            os.path.join(CONTROL_OUT_DIR, "spotting_stats.csv"),
            os.path.join(CONTROL_OUT_DIR, "spotting_stats.png"),
        )
        save_control_gifs(spread_frames, control_frames)
        draw_control_story_map(
            elev, arrival, firebreak_cum, ign, real_mask, is_building, records,
            os.path.join(CONTROL_OUT_DIR, "controlled_story_map.png")
        )
        draw_final_predicted_perimeter_map(
            elev, arrival, ign, real_mask,
            os.path.join(CONTROL_OUT_DIR, "final_predicted_perimeter.png"),
            records=records,
            firebreak_mask=firebreak_cum,
            is_building=is_building,
            title="Final Simulated Perimeter - Cost-Controlled CA",
            subtitle=(
                "Fill colors indicate simulated burn day after suppression; "
                "the white/yellow line is the final simulated perimeter."
            )
        )
        diagnose_final_unburned_holes(
            elev, active_fuel, arrival, ign, real_mask, CONTROL_OUT_DIR,
            is_building=is_building,
            firebreak_mask=firebreak_cum,
            title="Final Unburned Hole Diagnostics - Cost-Controlled CA",
        )
        plot_control_summary(records)
        plot_directional_control_objective(records)
        plot_perimeter_shape_diagnostics(
            records, os.path.join(CONTROL_OUT_DIR, "perimeter_shape_diagnostics.png")
        )
        run_daily_validation(
            arrival, elev, ign, transform, crs, real_mask, CONTROL_OUT_DIR,
            title="Daily Validation - Cost-Controlled CA",
        )
        print("saved", CONTROL_AREA_CSV)
        print("saved", CONTROL_COST_CSV)
    return records, state, arrival, firebreak_cum, ign


