# 可视化
# ============================================================
def visualize(elev, fuel, state, history, dims, burned, ign, arrival, out_png,
              real_mask=None, daily_stats=None):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    fig = plt.figure(figsize=(16, 9))
    gs = fig.add_gridspec(2, 3, hspace=0.3, wspace=0.22)
    panel_axes = []

    # 顶部(横跨三列): 按天"到达时间"图 —— 直接展示燃烧顺序, 对标真实蔓延图
    ax = fig.add_subplot(gs[0, :])
    panel_axes.append(ax)
    day = arrival_day_index(arrival)
    day_m = np.ma.masked_invalid(day)
    ndays = int(np.nanmax(day)) if np.isfinite(day).any() else 1
    ax.imshow(elev, cmap="gray", alpha=0.5)
    cmap = plt.get_cmap("turbo", ndays)
    im = ax.imshow(day_m, cmap=cmap, alpha=0.85, vmin=0.5, vmax=ndays + 0.5,
                   interpolation="nearest")
    _draw_final_perimeter(ax, real_mask, linewidth=2.8, linestyle="-", alpha=1.0)
    ax.plot(ign[1], ign[0], "w*", ms=18, markeredgecolor="k", markeredgewidth=1.2)
    ax.annotate("N", xy=(0.04, 0.96), xycoords="axes fraction", color="w",
                fontsize=13, fontweight="bold", ha="center", va="top")
    ax.annotate("", xy=(0.04, 0.86), xytext=(0.04, 0.74), xycoords="axes fraction",
                arrowprops=dict(arrowstyle="-|>", color="w", lw=2))
    ax.set_title("Simulated Burn Arrival Day and Observed Final Perimeter",
                 fontweight="bold")
    ax.axis("off")
    cb = fig.colorbar(im, ax=ax, fraction=0.022, pad=0.01,
                      ticks=range(1, ndays + 1))
    cb.set_label("Reporting day")

    # 分形燃料场
    ax = fig.add_subplot(gs[1, 0])
    panel_axes.append(ax)
    im = ax.imshow(fuel, cmap="YlGn")
    ax.set_title("LANDFIRE-Derived Fuel Factor", fontweight="bold")
    ax.axis("off"); fig.colorbar(im, ax=ax, fraction=0.046)

    # 分形维数随时间
    ax = fig.add_subplot(gs[1, 1])
    panel_axes.append(ax)
    steps = [h[0] for h in history]
    ax.plot(steps, dims, "o-", color="#7a1f1f")
    ax.set_xlabel("CA step"); ax.set_ylabel("Box-counting D")
    ax.set_title("Fire-Perimeter Fractal Dimension", fontweight="bold")
    ax.grid(alpha=0.3)

    # 按天烧毁面积
    ax = fig.add_subplot(gs[1, 2])
    panel_axes.append(ax)
    if daily_stats:
        days = [r["day"] for r in daily_stats]
        new_ha = [r["new_burned_ha"] for r in daily_stats]
        cum_ha = [r["cumulative_burned_ha"] for r in daily_stats]
        ax.bar(days, new_ha, color="#e2724a", alpha=0.85,
               label="Daily burned-area increment")
        ax.plot(days, cum_ha, "o-", color="#7a1f1f",
                label="Cumulative burned area")
        ax.set_xlabel("Reporting day")
        ax.legend(fontsize=8)
    else:
        area_ha = np.array(burned) * (TARGET_RES**2) / 1e4
        ax.plot(steps, area_ha, "s-", color="#e8820f")
        ax.set_xlabel("CA step")
    ax.set_ylabel("Burned area (ha)")
    ax.set_title("Daily and Cumulative Burned Area", fontweight="bold")
    ax.grid(alpha=0.3)

    fig.suptitle("Cellular-Automaton Fire-Spread Simulation - Palisades",
                 fontsize=15, fontweight="bold")
    _apply_lettered_bottom_caption(
        fig, panel_axes,
        [
            "simulated fire arrival day and observed final perimeter",
            "LANDFIRE-derived fuel factor used by the CA model",
            "fire-perimeter box-counting fractal dimension",
            "daily burned-area increment and cumulative burned area",
        ],
        "Cellular-Automaton Fire Spread - Palisades",
    )
    os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
    fig.savefig(out_png, dpi=140, bbox_inches="tight")
    print("saved", out_png)


def _int_arg(argv, names, default):
    for name in names:
        if name in argv:
            i = argv.index(name)
            if i + 1 < len(argv):
                try:
                    return int(argv[i + 1])
                except Exception:
                    return default
        prefix = name + "="
        for item in argv:
            if item.startswith(prefix):
                try:
                    return int(item.split("=", 1)[1])
                except Exception:
                    return default
    return default


def _string_arg(argv, names, default):
    for name in names:
        if name in argv:
            index = argv.index(name)
            if index + 1 < len(argv):
                return str(argv[index + 1])
        prefix = name + "="
        for item in argv:
            if item.startswith(prefix):
                return str(item.split("=", 1)[1])
    return default


def _float_arg(argv, names, default):
    for name in names:
        if name in argv:
            index = argv.index(name)
            if index + 1 < len(argv):
                try:
                    return float(argv[index + 1])
                except Exception:
                    return default
        prefix = name + "="
        for item in argv:
            if item.startswith(prefix):
                try:
                    return float(item.split("=", 1)[1])
                except Exception:
                    return default
    return default


